// Define the data structure to represent a 5G NR UE context
typedef struct {
    int ue_id;
    char *measurement_reports;
    int num_qos_flows;
    struct qos_flow **qos_flows;
} ue_context_t;

// Define the data structure to represent a QoS flow
typedef struct {
    int qos_id;
    char *qos_policy;
} qos_flow_t;

// Define the data structure to represent the collection of UE contexts
typedef struct {
    ue_context_t **ue_contexts;
    int num_ue_contexts;
} ue_context_collection_t;

// Define the function to initialize and manage the collection of UE contexts
void init_ue_context_collection(ue_context_collection_t *collection) {
    // Initialize the collection with an empty array of UE contexts
    collection->ue_contexts = NULL;
    collection->num_ue_contexts = 0;
}

// Define the function to add a new UE context to the collection
void add_ue_context(ue_context_collection_t *collection, int ue_id) {
    // Check if the UE ID already exists in the collection
    for (int i = 0; i < collection->num_ue_contexts; i++) {
        if (collection->ue_contexts[i]->ue_id == ue_id) {
            return;
        }
    }

    // Allocate memory for the new UE context and add it to the collection
    ue_context_t *new_ue_context = malloc(sizeof(ue_context_t));
    new_ue_context->ue_id = ue_id;
    new_ue_context->measurement_reports = NULL;
    new_ue_context->num_qos_flows = 0;
    new_ue_context->qos_flows = NULL;
    collection->ue_contexts = realloc(collection->ue_contexts, (collection->num_ue_contexts + 1) * sizeof(ue_context_t));
    collection->ue_contexts[collection->num_ue_contexts++] = new_ue_context;
}

// Define the function to update an existing UE context in the collection
void update_ue_context(ue_context_collection_t *collection, int ue_id) {
    // Find the index of the UE context with the given UE ID
    for (int i = 0; i < collection->num_ue_contexts; i++) {
        if (collection->ue_contexts[i]->ue_id == ue_id) {
            return;
        }
    }

    // Update the UE context with the new measurement reports and QoS flows
    for (int i = 0; i < collection->num_ue_contexts; i++) {
        if (collection->ue_contexts[i]->ue_id == ue_id) {
            free(collection->ue_contexts[i]->measurement_reports);
            collection->ue_contexts[i]->measurement_reports = NULL;
            for (int j = 0; j < collection->ue_contexts[i]->num_qos_flows; j++) {
                free(collection->ue_contexts[i]->qos_flows[j]);
            }
            collection->ue_contexts[i]->num_qos_flows = 0;
        }
    }
}

// Define the function to retrieve a UE context from the collection based on its UE ID
ue_context_t *get_ue_context(ue_context_collection_t *collection, int ue_id) {
    // Find the index of the UE context with the given UE ID
    for (int i = 0; i < collection->num_ue_contexts; i++) {
        if (collection->ue_contexts[i]->ue_id == ue_id) {
            return collection->ue_contexts[i];
        }
    }

    // Return NULL if the UE context is not found
    return NULL;
}

// Define the function to free the memory of a UE context
void free_ue_context(ue_context_t *ue_context) {
    // Free the memory of the measurement reports and QoS flows
    free(ue_context->measurement_reports);
    for (int i = 0; i < ue_context->num_qos_flows; i++) {
        free(ue_context->qos_flows[i]);
    }
}

