void free_ue_context_collection(ue_context_collection_t *collection) {
    // Free the memory of each UE context in the collection
    for (int i = 0; i < collection->num_ue_contexts; i++) {
        free_ue_context(collection->ue_contexts[i]);
    }

    // Free the memory of the array of UE contexts
    free(collection->ue_contexts);
}

