    if (key_array == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize key array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_array[i] = rand() % 100;
    }
}

// Function to set the value of each record's int field to a random value within a specified range
void set_random_values(int *offset_array, int *key_array, int num_records, int lower_bound, int upper_bound) {
    // Set the value of each record's int field to a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % (upper_bound - lower_bound + 1) + lower_bound;
