// Function to ensure thread safety by using appropriate synchronization mechanisms
void ensure_thread_safety(int *offset_array, int *key_array, int num_records) {
    // Use a mutex to protect the memory allocation and deallocation functions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Allocate memory for offset array
    offset_array = (int *)malloc(num_records * sizeof(int));
    if (offset_array == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize offset array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 100;
    }

    // Allocate memory for key array
    key_array = (int *)malloc(num_records * sizeof(int));
    if (key_array == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize key array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key_array[i] = rand() % 100;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to report the current memory usage statistics
void report_memory_usage(int *offset_array, int *key_array, int num_records) {
    // Calculate total allocated memory
    size_t total_allocated = 0;
    for (int i = 0; i < num_records; i++) {
        total_allocated += sizeof(offset_array[i]) + sizeof(key_array[i]);
    }

    // Calculate free memory
    size_t free_memory = 0;
    struct sysinfo info;
    sysinfo(&info);
    free_memory = info.freeram * info.mem_unit;

    // Calculate memory pool utilization
    size_t memory_pool_utilization = total_allocated / (total_allocated + free_memory);

    printf("Memory usage statistics:\n");
    printf("Total allocated memory: %zu bytes\n", total_allocated);
    printf("Free memory: %zu bytes\n", free_memory);
    printf("Memory pool utilization: %.2f%%\n", memory_pool_utilization * 100);
}

// Function to clear all allocated resources and reset the memory pool
void clear_resources(int *offset_array, int *key_array) {
    // Use a mutex to protect the memory allocation and deallocation functions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Deallocate memory for offset array
    free(offset_array);

    // Deallocate memory for key array
    free(key_array);

    pthread_mutex_unlock(&mutex);
}

