#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Define the maximum number of files that can be processed simultaneously
#define MAX_FILES 1024

// Define the maximum size of a file in bytes
#define MAX_FILE_SIZE (1 * 1024 * 1024) // 1 MB

// Define the buffer size for reading files
#define BUFFER_SIZE 4096

// Define the number of threads to use for processing files
#define NUM_THREADS 8

// Define the command line options
#define OPTION_HELP "--help"
#define OPTION_COUNT "--count"
#define OPTION_CHARACTERS "--characters"
#define OPTION_OUTPUT "--output"

// Define the error codes
#define ERROR_FILE_NOT_FOUND 1
#define ERROR_INVALID_ARGUMENTS 2
#define ERROR_IO_ERROR 3

// Define the logging levels
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2

// Define the logging function
void log(int level, const char* message) {
    if (level == LOG_LEVEL_INFO) {
        printf("[INFO] %s\n", message);
    } else if (level == LOG_LEVEL_WARNING) {
        printf("[WARNING] %s\n", message);
    } else if (level == LOG_LEVEL_ERROR) {
        printf("[ERROR] %s\n", message);
    }
}

// Define the file processing function
void processFile(const char* filename, int lineCount, int characterCount) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        log(LOG_LEVEL_ERROR, "Error opening file %s", filename);
        return;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        if (strlen(buffer) > 0 && buffer[strlen(buffer) - 1] == '\n') {
            lineCount++;
            characterCount += strlen(buffer);
        } else {
            characterCount += strlen(buffer);
        }
    }

    fclose(file);
}

// Define the main function
int main(int argc, char** argv) {
    // Check for command line options
    if (argc == 1) {
        log(LOG_LEVEL_INFO, "Usage: %s [options] <file>...", argv[0]);
        return 0;
    }

    // Parse the command line options
    int optionCount = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_HELP) == 0) {
            log(LOG_LEVEL_INFO, "Usage: %s [options] <file>...", argv[0]);
            return 0;
        } else if (strcmp(argv[i], OPTION_COUNT) == 0) {
            optionCount++;
        } else if (strcmp(argv[i], OPTION_CHARACTERS) == 0) {
            optionCount++;
        } else if (strcmp(argv[i], OPTION_OUTPUT) == 0) {
            i++;
            if (i < argc && strlen(argv[i]) > 0) {
                log(LOG_LEVEL_INFO, "Redirecting output to %s", argv[i]);
            } else {
                log(LOG_LEVEL_ERROR, "Invalid argument for --output");
                return ERROR_INVALID_ARGUMENTS;
            }
        } else {
            // Check if the file exists and is readable
            FILE* file = fopen(argv[i], "r");
            if (file == NULL) {
                log(LOG_LEVEL_ERROR, "Error opening file %s", argv[i]);
                return ERROR_FILE_NOT_FOUND;
            } else {
                fclose(file);
            }
        }
    }

    // Check if the correct number of options were specified
    if (optionCount != 1) {
        log(LOG_LEVEL_ERROR, "Invalid number of options specified");
        return ERROR_INVALID_ARGUMENTS;
    }

    // Initialize the output file
    FILE* outputFile = NULL;
    if (strcmp(argv[argc - 1], OPTION_OUTPUT) == 0) {
        outputFile = fopen(argv[argc - 2], "w");
        if (outputFile == NULL) {
            log(LOG_LEVEL_ERROR, "Error opening file %s", argv[argc - 2]);
            return ERROR_FILE_NOT_FOUND;
        }
    }

    // Initialize the thread pool
    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, processFile, argv[i])) {
            log(LOG_LEVEL_ERROR, "Error creating thread %d", i);
            return ERROR_IO_ERROR;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_join(threads[i], NULL)) {
            log(LOG_LEVEL_ERROR, "Error joining thread %d", i);
            return ERROR_IO_ERROR;
        }
    }

    // Print the results to the output file
    int lineCount = 0;
    int characterCount = 0;
    for (int i = 1; i < argc - 1; i++) {
        FILE* file = fopen(argv[i], "r");
        if (file == NULL) {
            log(LOG_LEVEL_ERROR, "Error opening file %s", argv[i]);
            return ERROR_FILE_NOT_FOUND;
        }

        char buffer[BUFFER_SIZE];
        while (fgets(buffer, BUFFER_SIZE, file)) {
            if (strlen(buffer) > 0 && buffer[strlen(buffer) - 1] == '\n') {
                lineCount++;
                characterCount += strlen(buffer);
            } else {
                characterCount += strlen(buffer);
            }
        }

        fclose(file);
    }

    if (outputFile != NULL) {
        fprintf(outputFile, "%d\n", lineCount);
        fprintf(outputFile, "%d\n", characterCount);
        fclose(outputFile);
    } else {
        printf("%d\n", lineCount);
        printf("%d\n", characterCount);
    }

    return 0;
}
