use std::env;
use std::fs;
use std::path::PathBuf;

fn create_directory_and_set_env_var(dir_name: &str) -> Result<(), String> {
    let mut env_var = env::var("DIR_NAME").unwrap();
    if env_var.is_empty() {
        // Create directory and set environment variable
        let dir_path = PathBuf::from(dir_name);
        fs::create_dir(&dir_path).map_err(|e| format!("Error creating directory: {}", e))?;
        env_var = dir_path.to_str().unwrap();
    }
    env::set_var("DIR_NAME", &env_var);
    Ok(())
}
