import java.io.File;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.logging.Logger;

public class MoSTState {
    private static final Logger LOGGER = Logger.getLogger(MoSTState.class.getName());

    public static MoSTState loadStateOrRecycleTheme() {
        try (ObjectInputStream ois = new ObjectInputStream(new File("state.dat"))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            } else {
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.log(Level.WARNING, "Failed to load state", e);
            return null;
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    LOGGER.log(Level.SEVERE, "Failed to close ObjectInputStream", e);
                }
            }
        }
    }
}
```
