// JavaScript function to refresh dialog fields
function refreshDialogFields(resourceId, url, arrayOfFieldNames, shouldValidate) {
  // Use AngularJS's $window service to communicate with the parent window
  var $window = angular.element($document).injector().get('$window');

  // Iterate over each dialog field in the application
  angular.forEach(arrayOfFieldNames, function(fieldName) {
    // Check if the field's name matches any entry in the arrayOfFieldNames array
    var match = $window.document.querySelector('[name="' + fieldName + '"]');

    // If a match is found, send a message to the parent window containing the field's name
    if (match) {
      $window.postMessage(fieldName, url);
    }
  });

  // Update the corresponding dialog field with the result upon receiving a successful response from the parent window
  $window.addEventListener('message', function(event) {
    var data = event.data;

    if (shouldValidate && !validateField(data)) {
      return;
    }

    // Update the dialog field with the result
    angular.element($document).injector().get('$scope').$apply(function() {
      $window.document.querySelector('[name="' + data + '"]').value = data;
    });
  });
}

// C++ function to insert a string after another string in a forward list of strings
void insertStringAfter(std::forward_list<std::string>& forwardList, const std::string& targetString, const std::string& newString) {
  // Search for the first occurrence of the target string in the forward list
  auto it = std::find(forwardList.begin(), forwardList.end(), targetString);

  // If the target string is not present in the list, append the new string to the end of the list
  if (it == forwardList.end()) {
    forwardList.push_back(newString);
