// File management tool with dynamic C function generation and execution

const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');

class FileManager {
  constructor() {
    this.files = [];
    this.fileMap = new Map();
  }

  addFile(filename) {
    const file = {
      name: filename,
      extension: path.extname(filename),
      suffix: '',
      type: null,
    };

    // Check if file exists and is executable
    try {
      fs.accessSync(file.name);
      file.type = 'executable';
    } catch (err) {
      file.type = 'unavailable';
    }

    this.files.push(file);
    this.fileMap.set(filename, file);
  }

  removeFile(filename) {
    const index = this.files.findIndex((f) => f.name === filename);
    if (index !== -1) {
      this.files.splice(index, 1);
      this.fileMap.delete(filename);
    }
  }

  getFile(filename) {
    return this.fileMap.get(filename);
  }

  executeFiles() {
    const files = this.files;
    let sequence = [];

    // Generate execution sequence based on file dependencies
    for (const file of files) {
      if (file.type === 'executable') {
        sequence.push(file);
      } else {
        const deps = this.getDependencies(file.name);
        if (deps.length > 0) {
          sequence = sequence.concat(deps);
        }
      }
    }

    // Execute files in sequence, handling errors and discrepancies
    for (const file of sequence) {
      try {
        exec(`${file.name} ${file.suffix}`);
      } catch (err) {
        console.error(err);
      }
    }
  }

  getDependencies(filename) {
    const deps = [];
    for (const file of this.files) {
      if (file.type === 'executable' && file.name !== filename) {
        const dep = this.getFile(file.name);
        if (dep && dep.suffix > 0) {
          deps.push(dep);
        }
      }
    }
    return deps;
  }
}

// Example usage
const fileManager = new FileManager();
fileManager.addFile('file1.txt');
fileManager.addFile('file2.txt');
fileManager.addFile('file3.txt');
fileManager.executeFiles();
