import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class SessionTracker {
    private static final Logger LOGGER = Logger.getLogger(SessionTracker.class.getName());

    // Concurrent data structure to store user sessions
    private final ConcurrentHashMap<String, AtomicInteger> sessionCounts = new ConcurrentHashMap<>();

    // Time window for tracking concurrent sessions (in milliseconds)
    private long timeWindow;

    public SessionTracker(long timeWindow) {
        this.timeWindow = timeWindow;
    }

    /**
     * Processes a stream of user sessions in real-time, returning the maximum number of concurrent sessions for each user over the specified time window.
     * @param sessionStream Stream of user sessions represented as maps containing user IDs and timestamps
     * @return Map of user IDs to maximum number of concurrent sessions over the specified time window
     */
    public Map<String, Integer> processSessions(Stream<Map<String, Object>> sessionStream) {
        // Initialize map to store user IDs and their corresponding maximum concurrent session counts
        Map<String, Integer> maxSessionCounts = new HashMap<>();

        // Iterate over the stream of sessions and update the concurrent session count for each user
        sessionStream.forEach(session -> {
            String userId = (String) session.get("userId");
            long timestamp = (long) session.get("timestamp");

            // Check if the current session is within the time window
            if (timestamp > System.currentTimeMillis() - timeWindow) {
                // Increment the concurrent session count for the user
                AtomicInteger sessionCount = sessionCounts.computeIfAbsent(userId, k -> new AtomicInteger());
                sessionCount.incrementAndGet();
            }
        });

        // Iterate over the map of user IDs and their corresponding concurrent session counts
        // to calculate the maximum number of concurrent sessions for each user over the time window
        sessionCounts.forEach((userId, sessionCount) -> {
            int maxSessionCount = 0;
            long startTime = System.currentTimeMillis() - timeWindow;
            long endTime = System.currentTimeMillis();

            // Iterate over the sessions for the user and calculate the maximum concurrent session count within the time window
            sessionStream.filter(session -> {
                String userId2 = (String) session.get("userId");
                long timestamp = (long) session.get("timestamp");
                return userId2.equals(userId) && timestamp >= startTime && timestamp <= endTime;
            }).forEach(session -> {
                int concurrentSessionCount = (int) session.get("concurrentSessionCount");
                if (concurrentSessionCount > maxSessionCount) {
                    maxSessionCount = concurrentSessionCount;
                }
            });

            // Add the maximum number of concurrent sessions for the user to the map
            maxSessionCounts.put(userId, maxSessionCount);
        });

        return maxSessionCounts;
    }
}
