    // Production-specific configuration settings
}

// Handle external data sources for dynamic settings
$externalData = getenv('EXTERNAL_DATA');
if ($externalData) {
    $data = json_decode(file_get_contents($externalData), true);
    foreach ($data as $key => $value) {
        putenv("$key=$value");
    }
}

// Caching mechanism to minimize configuration file reads
$cacheFilePath = __DIR__ . "/config/cache.json";
if (file_exists($cacheFilePath)) {
    $cache = json_decode(file_get_contents($cacheFilePath), true);
    if ($cache['env'] === $env) {
        foreach ($cache['data'] as $key => $value) {
            putenv("$key=$value");
        }
    } else {
        // Update cache file with new environment data
        $cache['env'] = $env;
        $cache['data'] = $config;
        file_put_contents($cacheFilePath, json_encode($cache));
    }
} else {
    // Create cache file for new environment
    $cache = [
        'env' => $env,
        'data' => $config
    ];
    file_put_contents($cacheFilePath, json_encode($cache));
}

// Integration with CI/CD pipeline
