// HTTP client library in Rust

use std::collections::HashMap;
use std::time::Duration;
use std::sync::{Arc, Mutex};
use reqwest::blocking::Client;
use log::{info, warn, error};

struct HttpClient {
    client: Client,
    headers: HashMap<String, String>,
    timeout: Duration,
    retries: u32,
}

impl HttpClient {
    fn new(headers: HashMap<String, String>, timeout: Duration, retries: u32) -> Self {
        let client = Client::builder()
            .timeout(timeout)
            .build()
            .unwrap();

        Self {
            client,
            headers,
            timeout,
            retries,
        }
    }

    fn execute(&self, request: &str) -> Result<String, String> {
        let mut response = self.client.execute(request).await?;

        if response.status().is_success() {
            Ok(response.text().await?)
        } else {
            Err(format!("Request failed with status code: {}", response.status()))
        }
    }
}

struct HttpClientBuilder {
    headers: HashMap<String, String>,
    timeout: Duration,
    retries: u32,
}

impl HttpClientBuilder {
    fn new() -> Self {
        Self {
            headers: HashMap::new(),
            timeout: Duration::from_secs(10),
            retries: 3,
        }
    }

    fn with_headers(mut self, headers: HashMap<String, String>) -> Self {
        self.headers = headers;
        self
    }

    fn with_timeout(mut self, timeout: Duration) -> Self {
        self.timeout = timeout;
        self
    }

    fn with_retries(mut self, retries: u32) -> Self {
        self.retries = retries;
        self
    }

    fn build(self) -> HttpClient {
        let client = Client::builder()
            .timeout(self.timeout)
            .build()
            .unwrap();

        HttpClient {
            client,
            headers: self.headers,
            timeout: self.timeout,
            retries: self.retries,
        }
    }
}
```
This code defines a `HttpClient` struct that encapsulates the `reqwest::blocking::Client` and provides methods for building and executing HTTP requests. The `HttpClientBuilder` is used to construct instances of `HttpClient`.

