function updatePatientInformation($patientId, $newDemographics, $newMedicalHistory, $newInsuranceInfo) {
    // 1. Fetch latest insurance policies and patient consent status from external APIs
    try {
        $insurancePolicies = fetchLatestInsurancePolicies($patientId);
        $consentStatus = fetchPatientConsentStatus($patientId);
    } catch (Exception $e) {
        // Handle API call failures gracefully
        return "Error: Failed to fetch latest insurance policies and patient consent status. Please try again later.";
    }

    // 2. Update related tables in a transaction
    $db = new PDO('mysql:host=localhost;dbname=healthcare', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    $db->beginTransaction();

    try {
        // Update patient demographics table
        $stmt = $db->prepare("UPDATE patient_demographics SET first_name=:firstName, last_name=:lastName, gender=:gender WHERE patient_id=:patientId");
        $stmt->bindParam(':firstName', $newDemographics['firstName']);
        $stmt->bindParam(':lastName', $newDemographics['lastName']);
        $stmt->bindParam(':gender', $newDemographics['gender']);
        $stmt->bindParam(':patientId', $patientId);
        $stmt->execute();

        // Update patient medical history table
        $stmt = $db->prepare("UPDATE patient_medical_history SET condition=:condition, treatment=:treatment WHERE patient_id=:patientId");
        $stmt->bindParam(':condition', $newMedicalHistory['condition']);
        $stmt->bindParam(':treatment', $newMedicalHistory['treatment']);
        $stmt->bindParam(':patientId', $patientId);
        $stmt->execute();

        // Update patient insurance information table
        $stmt = $db->prepare("UPDATE patient_insurance_info SET insurance_policy=:insurancePolicy, consent_status=:consentStatus WHERE patient_id=:patientId");
        $stmt->bindParam(':insurancePolicy', $insurancePolicies['policy']);
        $stmt->bindParam(':consentStatus', $consentStatus);
        $stmt->bindParam(':patientId', $patientId);
        $stmt->execute();
    } catch (Exception $e) {
        // Handle database errors gracefully
        $db->rollBack();
        return "Error: Failed to update patient information. Please try again later.";
    }

    // 3. Commit transaction and log changes
    $db->commit();
    $log = new Logger('healthcare');
    $log->info("Patient ID {$patientId} updated with new demographics, medical history, and insurance information.");

    // 4. Send notifications to third-party applications
    try {
        sendNotifications($patientId);
    } catch (Exception $e) {
        // Handle failed integrations gracefully
        return "Error: Failed to send notifications to third-party applications. Please try again later.";
    }

    // 5. Return success message
    return "Success: Patient information updated successfully.";
}

