class FileAndHashUtil {
    private $randomStringLength = 16;
    private $hashingAlgorithm = 'bcrypt';
    private $fileReadDirectory = '/path/to/directory';

    public function generateRandomString($length = null) {
        if ($length === null) {
            $length = $this->randomStringLength;
        }

        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $charactersLength = strlen($characters);
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, $charactersLength - 1)];
        }

        return $randomString;
    }

    public function hashPassword($password) {
        if (!is_string($password)) {
            throw new InvalidArgumentException('Password must be a string');
        }

        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function readFileAsync($filePath) {
        if (!file_exists($filePath)) {
            throw new RuntimeException("File does not exist: $filePath");
        }

        if (!is_readable($filePath)) {
            throw new RuntimeException("File is not readable: $filePath");
        }

        return file_get_contents($filePath);
    }
}
```
