using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private readonly Dictionary<string, (int min, int max)> _integerRanges = new Dictionary<string, (int min, int max)>();
        private readonly Dictionary<string, (double mean, double stdDev)> _gaussianRanges = new Dictionary<string, (double mean, double stdDev)>();

        public void AddIntegerRange(string name, int min, int max)
        {
            if (_integerRanges.ContainsKey(name))
                throw new ArgumentException($"An integer range with the name '{name}' already exists.");

            _integerRanges[name] = (min, max);
        }

        public void AddGaussianRange(string name, double mean, double stdDev)
        {
            if (_gaussianRanges.ContainsKey(name))
                throw new ArgumentException($"A Gaussian range with the name '{name}' already exists.");

            _gaussianRanges[name] = (mean, stdDev);
        }

        public int GenerateIntegerValue(string name)
        {
            if (!_integerRanges.ContainsKey(name))
                throw new ArgumentException($"No integer range with the name '{name}' exists.");

            var range = _integerRanges[name];
            return Random.Next(range.min, range.max + 1);
        }

        public double GenerateGaussianValue(string name)
        {
            if (!_gaussianRanges.ContainsKey(name))
                throw new ArgumentException($"No Gaussian range with the name '{name}' exists.");

            var range = _gaussianRanges[name];
            return Random.NextGaussian(range.mean, range.stdDev);
        }

        public override string ToString()
        {
            var sb = new StringBuilder();
            sb.AppendLine("Integer Ranges:");
            foreach (var range in _integerRanges)
            {
                sb.AppendLine($"  - {range.Key}: [{range.Value.min}, {range.Value.max}]");
            }

            sb.AppendLine("Gaussian Ranges:");
            foreach (var range in _gaussianRanges)
            {
                sb.AppendLine($"  - {range.Key}: mean={range.Value.mean}, stdDev={range.Value.stdDev}");
            }

            return sb.ToString();
        }
    }
}
