function reduceAsync(arr, initialValue, reductionCallback, completionCallback) {
  // Initialize a queue to manage asynchronous tasks
  const taskQueue = [];

  // Initialize a counter to track the number of concurrent operations
  let concurrentOps = 0;

  // Iterate over the array and perform the reduction asynchronously
  for (let i = 0; i < arr.length; i++) {
    const currentValue = arr[i];

    // Check if there are any pending tasks in the queue
    if (taskQueue.length > 0) {
      // If there are pending tasks, wait for them to complete before adding a new task
      Promise.all(taskQueue).then(() => {
        // Add a new task to the queue and increment the counter
        taskQueue.push(reductionCallback(currentValue, initialValue));
        concurrentOps++;

        // Check if the number of concurrent operations has reached the limit
        if (concurrentOps >= 5) {
          // If the limit has been reached, wait for a task to complete before adding a new one
          Promise.race(taskQueue).then(() => {
            // Add a new task to the queue and decrement the counter
            taskQueue.push(reductionCallback(currentValue, initialValue));
            concurrentOps--;
          });
        }
      });
    } else {
      // If there are no pending tasks, add a new task directly to the queue
      taskQueue.push(reductionCallback(currentValue, initialValue));
      concurrentOps++;
    }
  }

  // Wait for all tasks in the queue to complete before resolving the promise
  Promise.all(taskQueue).then(() => {
    // If a completion callback was provided, call it with the final result
    if (completionCallback) {
      completionCallback(initialValue);
    }
  });
}
