// Define a struct to represent a node in the DOM tree
struct Node {
    char* name;
    struct Node* parent;
    struct Node* children;
};

// Define a function to traverse the DOM tree and collect matching elements
void traverseDOM(struct Node* root, const char* selector, size_t budget) {
    // Check if the current node matches the selector
    if (root->name && strcmp(root->name, selector) == 0) {
        // Add the current node to the result array
        struct Node** result = malloc(sizeof(struct Node*) * (budget + 1));
        result[budget] = root;
        budget++;
    }

    // Recursively traverse the children of the current node
    if (root->children) {
        for (int i = 0; i < root->children->length; i++) {
            struct Node* child = root->children[i];
            traverseDOM(child, selector, budget);
        }
    }
}
