#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_SECTIONS 100
#define MAX_SETTINGS 50
#define DEFAULT_CONFIG_DIR "/etc/config"
#define THEME_CACHE_ROOT "/theme-cache"

typedef struct {
    char *name;
    int num_settings;
    Setting settings[MAX_SETTINGS];
} Section;

typedef struct {
    char *key;
    char *value;
} Setting;

int main(int argc, char **argv) {
    // Check if a default configuration directory is set
    if (getenv("CONFIG_DIR") == NULL) {
        setenv("CONFIG_DIR", DEFAULT_CONFIG_DIR, 1);
    }

    // Initialize the theme cache root directory
    char *theme_cache_root = getenv("THEME_CACHE_ROOT");
    if (theme_cache_root == NULL) {
        theme_cache_root = THEME_CACHE_ROOT;
    }

    // Open the configuration files and read their contents
    int num_files = argc - 1;
    char **file_names = &argv[1];
    Section *sections[num_files];
    for (int i = 0; i < num_files; i++) {
        sections[i] = read_config_file(file_names[i]);
    }

    // Process the configuration files and generate a unified configuration file
    char *unified_config_file = process_config_files(sections, num_files);

    // Write the unified configuration file to disk
    write_config_file(unified_config_file, "unified-config.txt");

    // Clean up memory allocated for the sections and settings
    for (int i = 0; i < num_files; i++) {
        free_section(sections[i]);
    }

    return 0;
}

Section *read_config_file(char *file_name) {
    // Open the configuration file and read its contents
    int fd = open(file_name, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    char *buffer = malloc(sizeof(char) * 4096);
    int bytes_read = read(fd, buffer, 4096);
    if (bytes_read == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    // Parse the configuration file and extract the sections and settings
    Section *sections = malloc(sizeof(Section) * MAX_SECTIONS);
    int num_sections = 0;
    char *section_name = NULL;
    for (int i = 0; i < bytes_read; i++) {
        if (buffer[i] == '[' && buffer[i+1] != ' ') {
            section_name = &buffer[i+1];
            while (buffer[i+1] != ']') {
                i++;
            }
            i++;
        } else if (section_name != NULL) {
            Setting *settings = malloc(sizeof(Setting) * MAX_SETTINGS);
            int num_settings = 0;
            while (buffer[i] != '\n' && buffer[i+1] != '[' && buffer[i+2] != '=') {
                if (buffer[i] == '=' && buffer[i+1] == ' ') {
                    settings[num_settings].key = &buffer[i-1];
                    while (buffer[i] != '\n' && buffer[i+1] != '[' && buffer[i+2] != '=') {
                        i++;
                    }
                    settings[num_settings].value = &buffer[i+1];
                    num_settings++;
                }
            }
            sections[num_sections].name = section_name;
            sections[num_sections].num_settings = num_settings;
            sections[num_sections].settings = settings;
            num_sections++;
        }
    }

    // Close the configuration file and return the sections and settings
    close(fd);
    return sections;
}

void free_section(Section *section) {
    for (int i = 0; i < section->num_settings; i++) {
        free(section->settings[i].key);
        free(section->settings[i].value);
    }
    free(section->settings);
}

char *process_config_files(Section **sections, int num_files) {
    // Allocate memory for the unified configuration file
    char *unified_config = malloc(sizeof(char) * 4096);
    int offset = 0;

    // Iterate over each section and setting in each file
    for (int i = 0; i < num_files; i++) {
        Section *section = sections[i];
        for (int j = 0; j < section->num_settings; j++) {
            Setting *setting = &section->settings[j];
            // Check if the setting is already present in the unified configuration file
            int found = 0;
            for (int k = 0; k < num_files && !found; k++) {
                Section *other_section = sections[k];
                for (int l = 0; l < other_section->num_settings && !found; l++) {
                    Setting *other_setting = &other_section->settings[l];
                    if (strcmp(setting->key, other_setting->key) == 0) {
                        found = 1;
                    }
                }
            }
            // If the setting is not present in any file, add it to the unified configuration file
            if (!found) {
                int len = strlen(setting->key);
                memcpy(&unified_config[offset], setting->key, len);
                offset += len;
                unified_config[offset++] = '=';
                len = strlen(setting->value);
                memcpy(&unified_config[offset], setting->value, len);
                offset += len;
                unified_config[offset++] = '\n';
            }
        }
    }

    // Return the unified configuration file
    return unified_config;
}

void write_config_file(char *unified_config, char *file_name) {
    // Open the output file and write the unified configuration to it
    int fd = open(file_name, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    write(fd, unified_config, strlen(unified_config));

    // Close the output file
    close(fd);
}
```']

