using System;
using System.Text;
using System.Security.Cryptography;
using System.Net.Sockets;
using System.Threading;

public static class Base64Decoder
{
    private const int MAX_RETRY_COUNT = 3;
    private const int RETRY_DELAY_MS = 1000;

    public static string DecodeAndProcessMessage(string encodedMessage, byte[] authenticationTag, Configuration configuration)
    {
        // Validate input parameters
        if (encodedMessage == null || encodedMessage.Length == 0)
            throw new ArgumentException("Invalid encoded message", nameof(encodedMessage));
        if (authenticationTag == null || authenticationTag.Length == 0)
            throw new ArgumentException("Invalid authentication tag", nameof(authenticationTag));
        if (configuration == null)
            throw new ArgumentNullException(nameof(configuration));

        // Initialize variables
        string decodedMessage = null;
        int retryCount = 0;

        // Retry mechanism for failed authentication attempts due to transient network issues
        while (retryCount < MAX_RETRY_COUNT)
        {
            try
            {
                // Decode the Base64-encoded message
                byte[] decodedBytes = Convert.FromBase64String(encodedMessage);

                // Verify the authentication tag
                if (!VerifyAuthenticationTag(decodedBytes, authenticationTag))
                    throw new InvalidOperationException("Invalid authentication tag");

                // Decrypt the message using Triple DES
                decodedMessage = DecryptTripleDes(decodedBytes, configuration.Key, configuration.IV);

                // Log successful processing of the message
                LogEvent(configuration.LoggingService, "Success", "Decoded and processed message");

                break;
            }
            catch (Exception ex) when (ex is InvalidOperationException || ex is SocketException)
            {
                // Log failed authentication attempt or network issue
                LogEvent(configuration.LoggingService, "Error", $"Failed to decode and process message: {ex.Message}");

                // Increment retry count and wait for a short period before retrying
                retryCount++;
                Thread.Sleep(RETRY_DELAY_MS);
            }
        }

        return decodedMessage;
    }

    private static bool VerifyAuthenticationTag(byte[] decodedBytes, byte[] authenticationTag)
    {
        // Calculate the HMAC-SHA256 hash of the decoded message using the provided key and initialization vector (IV)
        byte[] calculatedAuthenticationTag = CalculateHmacSha256Hash(decodedBytes, configuration.Key, configuration.IV);

        // Compare the calculated authentication tag with the provided one
        return calculatedAuthenticationTag.SequenceEqual(authenticationTag);
    }

    private static string DecryptTripleDes(byte[] decodedBytes, byte[] key, byte[] iv)
    {
        // Create a new instance of the Triple DES algorithm using the provided key and initialization vector (IV)
        TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider();
        tripleDes.Key = key;
        tripleDes.IV = iv;

        // Decrypt the message using the Triple DES algorithm
        byte[] decryptedBytes = tripleDes.CreateDecryptor().TransformFinalBlock(decodedBytes, 0, decodedBytes.Length);

        // Return the decrypted message as a string
        return Encoding.UTF8.GetString(decryptedBytes);
    }

    private static void LogEvent(ILoggingService loggingService, string severityLevel, string errorMessage)
    {
        // Create a new log event with the provided severity level and error message
        LogEvent logEvent = new LogEvent();
        logEvent.SeverityLevel = severityLevel;
        logEvent.ErrorMessage = errorMessage;

        // Add the log event to the logging service
        loggingService.AddLogEvent(logEvent);
    }
}
```
