using System;
using System.Security.Cryptography;
using System.Text;
using System.Xml;

namespace DataEncryptionService
{
    public class EncryptionService
    {
        private readonly string _key;
        private readonly string _iv;

        public EncryptionService(string key, string iv)
        {
            if (string.IsNullOrEmpty(key))
                throw new ArgumentException("Key cannot be null or empty", nameof(key));

            if (string.IsNullOrEmpty(iv))
                throw new ArgumentException("IV cannot be null or empty", nameof(iv));

            _key = key;
            _iv = iv;
        }

        public string Encrypt(string plainText)
        {
            if (string.IsNullOrEmpty(plainText))
                throw new ArgumentException("Plain text cannot be null or empty", nameof(plainText));

            var aesCbc = new AesCryptoServiceProvider();
            aesCbc.Key = Encoding.UTF8.GetBytes(_key);
            aesCbc.IV = Encoding.UTF8.GetBytes(_iv);

            using (var encryptor = aesCbc.CreateEncryptor())
            {
                var plainTextBytes = Encoding.UTF8.GetBytes(plainText);
                var cipherTextBytes = encryptor.TransformFinalBlock(plainTextBytes, 0, plainTextBytes.Length);
                return Convert.ToBase64String(cipherTextBytes);
            }
        }

        public string Decrypt(string cipherText)
        {
            if (string.IsNullOrEmpty(cipherText))
                throw new ArgumentException("Cipher text cannot be null or empty", nameof(cipherText));

            var aesCbc = new AesCryptoServiceProvider();
            aesCbc.Key = Encoding.UTF8.GetBytes(_key);
            aesCbc.IV = Encoding.UTF8.GetBytes(_iv);

            using (var decryptor = aesCbc.CreateDecryptor())
            {
                var cipherTextBytes = Convert.FromBase64String(cipherText);
                var plainTextBytes = decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length);
                return Encoding.UTF8.GetString(plainTextBytes);
            }
        }
    }
}
