const os = require('os');
const child_process = require('child_process');
const diskusage = require('diskusage');
const networkInterface = require('network-interface');

async function healthCheck() {
  try {
    // Get CPU usage
    const cpuUsage = await getCpuUsage();

    // Get memory usage
    const memoryUsage = await getMemoryUsage();

    // Get disk space usage
    const diskSpaceUsage = await getDiskSpaceUsage();

    // Get network interface status
    const networkInterfaceStatus = await getNetworkInterfaceStatus();

    // Get specified system command output
    const systemCommandOutput = await getSystemCommandOutput();

    return {
      cpuUsage,
      memoryUsage,
      diskSpaceUsage,
      networkInterfaceStatus,
      systemCommandOutput,
    };
  } catch (error) {
    console.log(`Error occurred during health check: ${error}`);
    return null;
  }
}

async function getCpuUsage() {
  try {
    const cpuUsage = await os.cpuUsage();
    return cpuUsage;
  } catch (error) {
    console.log(`Error occurred while retrieving CPU usage: ${error}`);
    return null;
  }
}

async function getMemoryUsage() {
  try {
    const memoryUsage = await os.totalmem();
    return memoryUsage;
  } catch (error) {
    console.log(`Error occurred while retrieving memory usage: ${error}`);
    return null;
  }
}

async function getDiskSpaceUsage() {
  try {
    const diskSpaceUsage = await diskusage('/');
    return diskSpaceUsage;
  } catch (error) {
    console.log(`Error occurred while retrieving disk space usage: ${error}`);
    return null;
  }
}

async function getNetworkInterfaceStatus() {
  try {
    const networkInterfaceStatus = await networkInterface.getStatus();
    return networkInterfaceStatus;
  } catch (error) {
    console.log(`Error occurred while retrieving network interface status: ${error}`);
    return null;
  }
}

async function getSystemCommandOutput() {
  try {
    const systemCommandOutput = await child_process.exec('command');
    return systemCommandOutput;
  } catch (error) {
    console.log(`Error occurred while retrieving system command output: ${error}`);
    return null;
  }
}
```
