use std::env;
use std::fs::File;
use std::io::prelude::*;
use std::path::PathBuf;
use std::time::Instant;
use tokio::sync::mpsc::channel;
use tokio::task::JoinHandle;

struct Task {
    id: usize,
    start_time: Instant,
}

impl Task {
    fn new(id: usize) -> Self {
        Self {
            id,
            start_time: Instant::now(),
        }
    }

    fn execute(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Implement the task logic here
        Ok(())
    }
}

struct LogEntry {
    timestamp: Instant,
    task_id: usize,
    duration: Duration,
    result: Result<(), Box<dyn std::error::Error>>,
}

impl LogEntry {
    fn new(task_id: usize, result: Result<(), Box<dyn std::error::Error>>) -> Self {
        let timestamp = Instant::now();
        let duration = timestamp.duration_since(Instant::now());
        Self {
            timestamp,
            task_id,
            duration,
            result,
        }
    }
}

struct LogFile {
    file: File,
    size: u64,
}

impl LogFile {
    fn new(file: File) -> Self {
        Self { file, size: 0 }
    }

    fn write(&mut self, entry: &LogEntry) -> Result<(), Box<dyn std::error::Error>> {
        let mut writer = BufWriter::new(&self.file);
        writer.write_all(format!("{}\n", entry).as_bytes())?;
        self.size += 1;
        Ok(())
    }
}

struct TaskManager {
    tasks: Vec<Task>,
    log_file: LogFile,
}

impl TaskManager {
    fn new() -> Self {
        let file = File::create("log.txt")?;
        let log_file = LogFile::new(file);
        Self {
            tasks: Vec::new(),
            log_file,
        }
    }

    fn add_task(&mut self, task: Task) -> Result<(), Box<dyn std::error::Error>> {
        self.tasks.push(task);
        Ok(())
    }

    fn execute_tasks(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        for task in &self.tasks {
            let start = Instant::now();
            task.execute()?;
            let end = Instant::now();
            let duration = end.duration_since(start);
            self.log_file.write(&LogEntry::new(task.id, Ok(())))?;
        }
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} [task_id]", args[0]);
        return Ok(());
    }

    let task_id = &args[1];
    let mut manager = TaskManager::new();
    manager.add_task(Task::new(task_id.parse()?))?;
    manager.execute_tasks()?;
    Ok(())
}
```
