#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure for records
typedef struct {
    int key;
} record_t;

// Define a function to allocate memory for an array of 'record' structures
void *allocate_records(size_t num_records) {
    // Allocate memory for the array of records
    void *records = malloc(num_records * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record with a random integer value within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        ((record_t *)records)[i].key = rand() % 100 + 1;
    }

    return records;
}

// Define a function to deallocate memory for an array of 'record' structures
void deallocate_records(void *records) {
    // Check if the input pointer is NULL
    if (!records) {
        fprintf(stderr, "Error: Invalid input pointer\n");
        return;
    }

    // Deallocate memory for the array of records
    free(records);
}

// Define a function to find and print the largest integer in an array of 'record' structures
void find_largest_integer(record_t *records, size_t num_records) {
    // Check if the input pointer is NULL
    if (!records) {
        fprintf(stderr, "Error: Invalid input pointer\n");
        return;
    }

    // Initialize variables to keep track of the largest integer and its index
    int largest_integer = 0;
    size_t largest_index = 0;

    // Iterate over each record in the array
    for (size_t i = 0; i < num_records; i++) {
        // Check if the current integer is larger than the previous largest integer
        if (((record_t *)records)[i].key > largest_integer) {
            largest_integer = ((record_t *)records)[i].key;
            largest_index = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d\n", largest_integer);
    printf("Index of largest integer: %zu\n", largest_index);
}

// Define a function to clear all allocated resources and reset the memory pool
void clear_resources() {
    // Check if any resources have been allocated
