// Initialize and manage the network entities hash table
void initializeAndManageNetworkEntities() {
    // Create a new hash table for storing network entities
    network_entities = HashTable_create(50);

    // Initialize the hash table with default values
    HashTable_init(network_entities, 100, NULL);
}

// Add a new network entity to the hash table
void addNetworkEntity(int id, char *status, int resource_allocations[10]) {
    // Create a new network entity structure
    NetworkEntity *entity = malloc(sizeof(NetworkEntity));
    entity->id = id;
    strcpy(entity->status, status);
    memcpy(entity->resource_allocations, resource_allocations, 10 * sizeof(int));

    // Add the new network entity to the hash table
    HashTable_put(network_entities, &entity->id, sizeof(int), entity, sizeof(NetworkEntity));
}

// Update an existing network entity in the hash table
void updateNetworkEntity(int id, char *status, int resource_allocations[10]) {
    // Get the existing network entity from the hash table
    NetworkEntity *entity = HashTable_get(network_entities, &id, sizeof(int));

    // Update the status and resource allocations of the network entity
    strcpy(entity->status, status);
    memcpy(entity->resource_allocations, resource_allocations, 10 * sizeof(int));
}

// Retrieve a network entity from the hash table based on its identifier
NetworkEntity *getNetworkEntity(int id) {
    // Get the network entity from the hash table
    NetworkEntity *entity = HashTable_get(network_entities, &id, sizeof(int));

    // Return the network entity if it exists, otherwise return NULL
    return (entity != NULL) ? entity : NULL;
}

// Delete a network entity from the hash table based on its identifier
void deleteNetworkEntity(int id) {
    // Get the existing network entity from the hash table
    NetworkEntity *entity = HashTable_get(network_entities, &id, sizeof(int));

    // If the network entity exists, delete it from the hash table
    if (entity != NULL) {
        HashTable_delete(network_entities, &entity->id, sizeof(int), entity);
    }
}

// Encrypt a message using AES or Camellia block cipher
void encryptMessage(char *message, int key_length, char *key, char *iv) {
    // Create an EVP context for the encryption operation
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Set the cipher and key length for the encryption operation
    EVP_EncryptInit(ctx, EVP_aes_128_cbc(), key, iv);

    // Encrypt the message using the AES or Camellia block cipher
    int len = strlen(message);
    char *encrypted_message = malloc((len + 1) * sizeof(char));
    EVP_EncryptUpdate(ctx, encrypted_message, &len, message, len);

    // Free the EVP context and return the encrypted message
    EVP_CIPHER_CTX_free(ctx);
    return encrypted_message;
}

// Decrypt a message using AES or Camellia block cipher
void decryptMessage(char *encrypted_message, int key_length, char *key, char *iv) {
    // Create an EVP context for the decryption operation
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Set the cipher and key length for the decryption operation
    EVP_DecryptInit(ctx, EVP_aes_128_cbc(), key, iv);

    // Decrypt the encrypted message using the AES or Camellia block cipher
    int len = strlen(encrypted_message);
    char *decrypted_message = malloc((len + 1) * sizeof(char));
    EVP_DecryptUpdate(ctx, decrypted_message, &len, encrypted_message, len);

    // Free the EVP context and return the decrypted message
    EVP_CIPHER_CTX_free(ctx);
    return decrypted_message;
}

// Compute a digest using MD5 or SHA1
void computeDigest(char *message, int key_length, char *key) {
    // Create an EVP context for the digest operation
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();

    // Set the digest algorithm and key length for the digest operation
    EVP_DigestInit(ctx, EVP_md5());

    // Compute the digest of the message using the MD5 or SHA1 algorithm
    int len = strlen(message);
    char *digest = malloc((EVP_MD_size(EVP_md5()) + 1) * sizeof(char));
    EVP_DigestUpdate(ctx, message, len);
    EVP_DigestFinal(ctx, digest, &len);

    // Free the EVP context and return the digest
    EVP_MD_CTX_free(ctx);
    return digest;
}

// Sign a message using RSA with SHA1
void signMessage(char *message, int key_length, char *key) {
    // Create an EVP context for the signing operation
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();

    // Set the digest algorithm and key length for the signing operation
    EVP_DigestInit(ctx, EVP_sha1());

    // Sign the message using the RSA with SHA1 algorithm
    int len = strlen(message);
    char *signature = malloc((EVP_PKEY_size(key) + 1) * sizeof(char));
    EVP_SignUpdate(ctx, message, len);
    EVP_SignFinal(ctx, signature, &len, key);

    // Free the EVP context and return the signature
    EVP_MD_CTX_free(ctx);
    return signature;
}

// Verify a signature using RSA with SHA1
int verifySignature(char *message, int key_length, char *key, char *signature) {
    // Create an EVP context for the verification operation
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();

    // Set the digest algorithm and key length for the verification operation
    EVP_DigestInit(ctx, EVP_sha1());

    // Verify the signature using the RSA with SHA1 algorithm
    int len = strlen(message);
    int result = EVP_VerifyUpdate(ctx, message, len);
    if (result == 0) {
        result = EVP_VerifyFinal(ctx, signature, key);
    }

    // Free the EVP context and return the verification result
    EVP_MD_CTX_free(ctx);
    return result;
}
