    private static final int MAX_RANDOM_VALUE = 1000;

    private AtomicInteger nextKey = new AtomicInteger(0);
    private ReentrantLock lock = new ReentrantLock();

    public void establishConnection(int numKeys) {
        // Dynamically allocate memory for arrays of 'long' offsets and 'int' keys
        long[] offsets = new long[numKeys];
        int[] keys = new int[numKeys];

        // Initialize each key with a random value within the specified range
        for (int i = 0; i < numKeys; i++) {
