            totalAllocatedMemory += offsets[i];
            freeMemory += keys[i];
            poolUtilization += ExternalManager.getPoolUtilization(keys[i]);
        }

        // Log memory usage statistics
        System.out.println("Total allocated memory: " + totalAllocatedMemory);
        System.out.println("Free memory: " + freeMemory);
        System.out.println("Pool utilization: " + poolUtilization);
    }

    private class Record {
        private int key;
        private long offset;

        public Record(int key) {
            this.key = key;
            this.offset = allocateMemory();
        }

        public long getOffset() {
            return offset;
        }

        private long allocateMemory() {
            // Allocate memory for the 'record' structure containing a single 'int' value
            long[] memoryBlock = new long[1];

            // Register the allocated memory block with the external manager
