import java.util.concurrent.Semaphore;
import java.util.logging.Logger;

public class DisjointPairs {
    private static final Logger LOGGER = Logger.getLogger(DisjointPairs.class.getName());

    public static Tuple<Integer, Long> findDisjointPairs(List<Integer> dataset) {
        // Initialize semaphore for managing concurrency
        Semaphore semaphore = new Semaphore(1);

        // Implement Union-Find data structure using a hash map
        Map<Integer, Integer> parentMap = new HashMap<>();
        for (int i = 0; i < dataset.size(); i++) {
            parentMap.put(i, i);
        }

        // Iterate over the dataset and find disjoint pairs
        int disjointPairsCount = 0;
        long totalTimeMilliseconds = 0L;
        for (int i = 0; i < dataset.size(); i++) {
            int element1 = dataset.get(i);
            semaphore.acquireUninterruptibly();
            try {
                // Find the root of the tree for element1
                int root1 = findRoot(parentMap, element1);

                // Iterate over the remaining elements and find disjoint pairs
                for (int j = i + 1; j < dataset.size(); j++) {
                    int element2 = dataset.get(j);
                    int root2 = findRoot(parentMap, element2);
                    if (root1 != root2) {
                        disjointPairsCount++;
                        totalTimeMilliseconds += calculateTimeMilliseconds(element1, element2);
                    }
                }
            } finally {
                semaphore.release();
            }
        }

        // Clean up semaphore after use
        semaphore.close();

        return new Tuple<>(disjointPairsCount, totalTimeMilliseconds / disjointPairsCount);
    }

    private static int findRoot(Map<Integer, Integer> parentMap, int element) {
        // Find the root of the tree for element
        while (parentMap.containsKey(element)) {
            element = parentMap.get(element);
        }
        return element;
    }

