    $this->characterSet = $characterSet;
    $this->outputDirectory = $outputDirectory;
  }

  public function executeCommand() {
    // Fork and wait system calls to execute the command in the background
    $pid = pcntl_fork();
    if ($pid == -1) {
      return 0;
    } elseif ($pid) {
      // Parent process waits for the child process to finish
      pcntl_wait($status);
      return 1;
    } else {
      // Child process executes the command
      exec($this->command, $output);
      return 1;
    }
  }

  public function generateRandomString() {
    $length = strlen($this->characterSet);
    $randomString = '';
    for ($i = 0; $i < $this->length; $i++) {
      $randomString .= $this->characterSet[rand(0, $length - 1)];
    }
    return $randomString;
  }

  public function processFile($filePath) {
    // Read the file synchronously using file_get_contents
    $fileContents = file_get_contents($filePath);
    if ($fileContents === false) {
      throw new Exception("Error reading file: {$filePath}");
    }

    // Process each line of the file using array_map
    $processedLines = array_map(function($line) {
      return $this->transformLine($line);
    }, explode("\n", $fileContents));

    // Write the processed lines to a new file in the output directory
    $outputFilePath = "{$this->outputDirectory}/processed-{$this->generateRandomString()}.txt";
    if (!file_put_contents($outputFilePath, implode("\n", $processedLines))) {
      throw new Exception("Error writing to file: {$outputFilePath}");
    }
  }

  public function transformLine($line) {
    // Implement the transformation function here
    return $line;
  }
}
