        {
            _mean = mean;
            _stdDev = stdDev;
            _gaussianDistribution = true;
        }

        public int GenerateRandomInteger()
        {
            if (_inclusiveBounds)
            {
                return new Random().Next(_minInt, _maxInt + 1);
            }
            else
            {
                return new Random().Next(_minInt, _maxInt);
            }
        }

        public double GenerateRandomDouble()
        {
            if (_gaussianDistribution)
            {
                return new GaussianDistribution(_mean, _stdDev).Next();
            }
            else
            {
                return new Random().NextDouble();
            }
        }

