}

// Function to process a log entry and update the summary report
void processLogEntry(LogEntry *entry) {
    // Create a new report entry if it doesn't exist yet
    ReportEntry *report_entry = NULL;
    if (strcmp(entry->hostname, "") == 0) {
        report_entry = malloc(sizeof(ReportEntry));
        strcpy(report_entry->hostname, entry->hostname);
        report_entry->frequency = 1;
        report_entry->average_latency = (double)entry->latency / report_entry->frequency;
    } else {
