        for (int i = 0; i < num_report_entries; i++) {
            if (strcmp(report_entries[i].hostname, entry->hostname) == 0) {
                report_entry = &report_entries[i];
                report_entry->frequency++;
                report_entry->average_latency = ((double)report_entry->average_latency * (report_entry->frequency - 1)) + entry->latency;
                break;
            }
        }
    }
}

