// Define a function to traverse the DOM and return an object containing arrays of matched elements for each CSS selector
function traverseDOM(selectors) {
    // Create an empty object to store the results
    var results = {};

    // Loop through each CSS selector and find all matching elements in the DOM
    selectors.forEach(function(selector) {
        // Use the querySelectorAll method to find all elements that match the current selector
        var matches = document.querySelectorAll(selector);

        // Add the matched elements to the results object for this selector
        results[selector] = Array.from(matches);
    });

    // Return the results object
    return results;
}

// Define a function to debounce the traverseDOM function to optimize performance when it is called frequently
function debouncedTraverseDOM(selectors) {
    // Create a variable to store the last time the function was called
    var lastCallTime = 0;

    // Return a new function that will only call the original function if enough time has passed since the last call
    return function() {
        // Get the current time in milliseconds
        var now = Date.now();

        // If enough time has passed since the last call, call the original function and update the last call time
        if (now - lastCallTime > 100) {
            traverseDOM(selectors);
            lastCallTime = now;
        }
    };
}
