void process_and_analyze_data() {
    // Initialize arrays for offset, keys, and records
    long *offset_array = malloc(sizeof(long) * 1000);
    int *key_array = malloc(sizeof(int) * 1000);
    Record *record_array = malloc(sizeof(Record) * 1000);

    // Initialize linked list of records
    Record *head = NULL;
    for (int i = 0; i < 1000; i++) {
        head = malloc(sizeof(Record));
        head->key = -1;
        head->offset = -1;
        head->next = NULL;
    }

    // Set random values for each record's int field
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        Record *record = malloc(sizeof(Record));
        record->key = rand() % 1000;
        record->offset = rand() % 1000;
        head = insert_node(head, record);
    }

    // Read input data from simulated stream and update linked list
    int input[1000];
    for (int i = 0; i < 1000; i++) {
        scanf("%d", &input[i]);
        Record *record = find_node(head, input[i]);
        if (record != NULL) {
            record->offset += input[i];
        } else {
            Record *new_record = malloc(sizeof(Record));
            new_record->key = input[i];
            new_record->offset = input[i];
            head = insert_node(head, new_record);
        }
    }

    // Find and print largest integer in both linked list and input array
    int max_value = -1;
    for (int i = 0; i < 1000; i++) {
        if (max_value < input[i]) {
            max_value = input[i];
        }
        Record *record = find_node(head, input[i]);
        if (record != NULL) {
            if (max_value < record->offset) {
                max_value = record->offset;
            }
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Free dynamically allocated memory
    free(offset_array);
    free(key_array);
    free(record_array);
}

// Insert node into linked list
Record *insert_node(Record *head, Record *new_record) {
    if (head == NULL) {
        head = new_record;
    } else {
        Record *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    return head;
}

// Find node in linked list with given key
Record *find_node(Record *head, int key) {
    if (head == NULL) {
        return NULL;
    } else {
        Record *current = head;
        while (current != NULL) {
            if (current->key == key) {
                return current;
            }
            current = current->next;
        }
        return NULL;
    }
}
