    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Allocate memory for the data structure
    struct Data *data = malloc(sizeof(struct Data));
    if (data == NULL) {
        printf("Error: unable to allocate memory for data structure\n");
        fclose(file);
        return;
    }

    // Initialize the count and numbers array
    data->count = 0;
    data->numbers = malloc(5000 * sizeof(float));
    if (data->numbers == NULL) {
        printf("Error: unable to allocate memory for number array\n");
        free(data);
        fclose(file);
        return;
    }

    // Read the file and process each line
    char line[1024];
    while (fgets(line, sizeof(line), file) != NULL) {
        float number = strtof(line, NULL);
        if (!isfinite(number)) {
            printf("Error: invalid number in file %s\n", filename);
            free(data->numbers);
            free(data);
            fclose(file);
            return;
        }
        if (number < -1000000.0f || number > 1000000.0f) {
            printf("Error: number out of range in file %s\n", filename);
            free(data->numbers);
            free(data);
            fclose(file);
            return;
        }
        data->numbers[data->count++] = number;
        if (data->count == 5000) {
            printf("Error: too many numbers in file %s\n", filename);
            free(data->numbers);
            free(data);
            fclose(file);
            return;
        }
    }

    // Close the file and print the results
    fclose(file);
    printf("Smallest number: %f\n", findSmallestNumber(data));
    printf("Median: %f\n", calculateMedian(data));

    // Free the allocated memory
    free(data->numbers);
    free(data);
}

// Function to find the smallest number in the array
float findSmallestNumber(struct Data *data) {
    float smallest = INFINITY;
    for (int i = 0; i < data->count; i++) {
        if (data->numbers[i] < smallest) {
            smallest = data->numbers[i];
        }
    }
    return smallest;
}

// Function to calculate the median of all numbers
float calculateMedian(struct Data *data) {
    float median = 0.0f;
    if (data->count == 0) {
        return median;
    } else if (data->count % 2 == 0) {
        median = (data->numbers[data->count / 2 - 1] + data->numbers[data->count / 2]) / 2.0f;
    } else {
        median = data->numbers[data->count / 2];
    }
    return median;
}

int main() {
    processFile("numbers.txt");
    return 0;
}
