void* process_file(void* args) {
    // Cast the arguments to the correct type
    char* filename = (char*)args;

    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        printf("Error opening file %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    // Read the file line by line and process each line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Split the line into fields using the specified delimiter
        char** fields = strsplit(line, DEFAULT_DELIMITER);
        if (!fields) {
            printf("Error splitting line %d in file %s\n", line_number, filename);
            continue;
        }

        // Compute the average of the last two numerical fields
        double num1 = atof(fields[0]);
        double num2 = atof(fields[1]);
        if (isnan(num1) || isnan(num2)) {
            printf("Error converting field %d in line %d in file %s\n", 0, line_number, filename);
            continue;
        }
        double average = (num1 + num2) / 2.0;

        // Store the processed data in a structured CSV format
        ProcessedData* data = malloc(sizeof(ProcessedData));
        if (!data) {
            printf("Error allocating memory for processed data\n");
            return NULL;
        }
        data->filename = filename;
        data->line_number = line_number;
        data->average = average;

