        if (!outfp) {
            printf("Error opening output file: %s\n", strerror(errno));
            return NULL;
        }
        fprintf(outfp, "%s,%d,%f\n", filename, line_number, average);
        fclose(outfp);
    }

    // Clean up memory
    free(line);
    strsplit_free(fields);
    return NULL;
}

// Define a function to split a string into an array of substrings using the specified delimiter
char** strsplit(const char* str, const char delim) {
    // Count the number of fields in the string
    int count = 0;
    for (const char* p = str; *p != '\0'; ++p) {
        if (*p == delim) {
            ++count;
        }
    }

    // Allocate memory for the array of substrings
    char** fields = malloc(sizeof(char*) * (count + 1));
    if (!fields) {
        printf("Error allocating memory for field array\n");
        return NULL;
    }

    // Split the string into an array of substrings using the specified delimiter
    int i = 0;
    char* p = (char*)str;
    while (*p != '\0') {
        if (*p == delim) {
            *p = '\0';
            fields[i++] = p + 1;
        }
        ++p;
    }
    fields[count] = NULL;

    return fields;
}

// Define a function to free the memory allocated by strsplit()
void strsplit_free(char** fields) {
    if (fields) {
        for (int i = 0; fields[i]; ++i) {
            free(fields[i]);
        }
        free(fields);
    }
}

