        return 1;
    }

    // Initialize variables for processing files concurrently
    pthread_t* threads = malloc(sizeof(pthread_t) * MAX_CONCURRENT_THREADS);
    if (!threads) {
        printf("Error allocating memory for thread array\n");
        return 1;
    }
    int num_threads = 0;

    // Loop over the input directories and process each file concurrently
    for (int i = 1; i < argc; ++i) {
        DIR* dirp = opendir(argv[i]);
        if (!dirp) {
            printf("Error opening directory %s: %s\n", argv[i], strerror(errno));
            continue;
        }

        struct dirent* entry;
        while ((entry = readdir(dirp)) != NULL) {
            // Skip non-text files and hidden files
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0 || entry->d_type != DT_REG) {
                continue;
            }

            // Create a thread to process the file
            if (num_threads < MAX_CONCURRENT_THREADS) {
                char* filename = malloc(strlen(argv[i]) + strlen(entry->d_name) + 1);
                sprintf(filename, "%s/%s", argv[i], entry->d_name);
                pthread_create(&threads[num_threads++], NULL, process_file, filename);
            } else {
                printf("Maximum number of threads reached\n");
            }
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up memory
    free(threads);

    return 0;
}
