// C function for modifying a filename based on its length and adding a timestamp if necessary
int modify_filename(char* filename, char* filetype) {
    // Check if the filename is empty or contains only whitespace
    if (strlen(filename) == 0 || strspn(filename, " \t\r\n") == strlen(filename)) {
        return -1; // Return error code
    }

    // Get the original filename and extension
    char* orig_filename = strtok(filename, ".");
    char* ext = strtok(NULL, ".");

    // Calculate the new filename length based on the original filename length
    int new_len = strlen(orig_filename) + 10; // Add 10 digits for the timestamp

    // Check if the new filename length exceeds the maximum allowed length
