int init_aes_cbc(const char *password, aes_cbc_ctx **ctx) {
    // Allocate memory for the cipher context structure
    *ctx = (aes_cbc_ctx *)malloc(sizeof(aes_cbc_ctx));
    if (*ctx == NULL) {
        printf("Error: Failed to allocate memory for AES-256-CBC cipher context\n");
        return -1;
