    // Initialize the cipher context structure with a null pointer
    (*ctx)->ctx = NULL;

    // Derive the encryption key from the password using a robust hashing algorithm
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char *)password, strlen(password), 1, (*ctx)->key, (*ctx)->iv);

