    printf("Free memory: %zu bytes\n", pool->capacity - pool->used);
    printf("Pool utilization: %.2f%%\n", (double)pool->used / pool->capacity * 100);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

