// Define a function to read and validate the configuration file
int readConfigFile(const char *filename, ConfigData *data) {
    // Open the configuration file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open configuration file");
        return -1;
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(sizeof(char) * 4096);
    ssize_t bytes_read = read(fd, buffer, 4096);
    if (bytes_read == -1) {
        perror("Failed to read configuration file");
        close(fd);
        return -1;
    }

    // Close the file descriptor
    close(fd);

    // Parse the contents of the buffer into an array of integers
    char *token = strtok(buffer, " ");
    while (token != NULL) {
        int integer = atoi(token);
        if (integer == 0 && errno == EINVAL) {
            perror("Failed to parse integer");
            free(buffer);
            return -1;
        }
        data->integers[data->count++] = integer;
        token = strtok(NULL, " ");
    }

    // Free the buffer memory
    free(buffer);

    // Find and print the largest integer in the array
    int largest = findLargestInteger(data->integers, data->count);
    printf("The largest integer is %d\n", largest);

    return 0;
}

