        printf("Failed to open HR database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }
    char *sql = "SELECT name, city, address FROM employees WHERE supervisorId = ?";
    sqlite3_stmt *stmt = NULL;
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Failed to prepare SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }
    rc = sqlite3_bind_int(stmt, 1, ueId);
    if (rc != SQLITE_OK) {
        printf("Failed to bind parameter: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        printf("No rows returned from query\n");
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return;
    }
    char *name = (char*)sqlite3_column_text(stmt, 0);
    char *city = (char*)sqlite3_column_text(stmt, 1);
    char *address = (char*)sqlite3_column_text(stmt, 2);
    printf("Employee details: name=%s, city=%s, address=%s\n", name, city, address);
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    // Log the executed SQL query and its results for auditing purposes
    char *logMessage = malloc(strlen(sql) + strlen(name) + strlen(city) + strlen(address) + 100);
    sprintf(logMessage, "Executed SQL query: %s\nResults: name=%s, city=%s, address=%s", sql, name, city, address);
    printf("%s\n", logMessage);
    free(logMessage);

    // Process the UE context and employee data
    processUEContextAndEmployeeData(ueContext, name, city, address);
}

