#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <json-c/json.h>

// Structure to represent an entry in the collection
typedef struct {
    char* key;
    size_t length;
    double value;
} Entry;

// Function to initialize the collection from multiple data sources
void initCollection(Entry** entries, int numEntries, const char* primaryCSVFile, const char* jsonConfigFile) {
    // Open the primary CSV file and read it line by line
    FILE* csvFile = fopen(primaryCSVFile, "r");
    if (csvFile == NULL) {
        printf("Error: unable to open primary CSV file\n");
        return;
    }

    // Read each line of the CSV file and parse it into an Entry structure
    while (!feof(csvFile)) {
        char* line = malloc(1024 * sizeof(char));
        fgets(line, 1024, csvFile);
        if (strlen(line) > 0) {
            // Parse the line into an Entry structure
            Entry* entry = parseEntry(line);
            if (entry != NULL) {
                // Add the entry to the collection
                entries[numEntries++] = entry;
            }
        }
    }

    // If a JSON configuration file is provided, read it and apply custom parsing rules
    if (jsonConfigFile != NULL) {
        json_object* configJSON = json_object_from_file(jsonConfigFile);
        if (configJSON == NULL) {
            printf("Error: unable to open JSON configuration file\n");
            return;
        }

        // Iterate over the entries in the collection and apply custom parsing rules as needed
        for (int i = 0; i < numEntries; i++) {
            Entry* entry = &entries[i];
            json_object* keyJSON = json_object_get_object(configJSON, entry->key);
            if (keyJSON != NULL) {
                // Apply custom parsing rules for this entry
                parseEntryCustom(entry, keyJSON);
            }
        }
    }

    // Close the primary CSV file
    fclose(csvFile);
}

// Function to calculate the average of all 'double' values in the collection
void calcAverage(Entry** entries, int numEntries, double* average, size_t* total) {
    *total = 0;
    *average = 0.0;
    for (int i = 0; i < numEntries; i++) {
        Entry* entry = &entries[i];
        if (entry->length >= MIN_LENGTH && entry->length <= MAX_LENGTH) {
            *total += 1;
            *average += entry->value;
        }
    }
    if (*total > 0) {
        *average /= *total;
    }
}

// Function to parse an Entry structure from a CSV line
Entry* parseEntry(char* line) {
    // Parse the line into key, length, and value fields
    char* token = strtok(line, ",");
    if (token == NULL) {
        return NULL;
    }
    char* key = malloc((strlen(token) + 1) * sizeof(char));
    strcpy(key, token);

    token = strtok(NULL, ",");
    if (token == NULL) {
        free(key);
        return NULL;
    }
    size_t length = atoi(token);

    token = strtok(NULL, ",");
    if (token == NULL) {
        free(key);
        return NULL;
    }
    double value = atof(token);

    // Create a new Entry structure and return it
    Entry* entry = malloc(sizeof(Entry));
    entry->key = key;
    entry->length = length;
    entry->value = value;
    return entry;
}

// Function to apply custom parsing rules for an Entry structure
void parseEntryCustom(Entry* entry, json_object* keyJSON) {
    // Check if the JSON object has a "custom" field and apply custom parsing rules as needed
    json_object* customJSON = json_object_get_object(keyJSON, "custom");
    if (customJSON != NULL) {
        // Apply custom parsing rules for this entry
        // ...
    }
}
