unsigned long hash(data_point* point) {
    // Implement a simple hash function that takes the address of the data point as input and returns an unsigned long value
    return (unsigned long)(point->value * 1000000 + (int)point->string[0]);
}

// Define a memory pool manager to optimize memory usage and reduce fragmentation
typedef struct {
    void* blocks; // Pointer to the start of the memory block array
    size_t size; // Size of the memory block array in bytes
    size_t used; // Number of bytes currently used in the memory pool
} mempool_manager;

// Define a function to allocate and initialize an array of data points
data_point* allocate_data_points(size_t num_points, double lower_bound, double upper_bound) {
    // Validate input parameters to ensure they fall within acceptable bounds
    if (num_points == 0 || lower_bound >= upper_bound) {
        return NULL;
    }

    // Allocate memory for the array of data points and initialize each element with a random double value within the specified range
    data_point* points = malloc(sizeof(data_point) * num_points);
    if (points == NULL) {
        return NULL;
    }
    srand((unsigned int)time(NULL)); // Initialize the random number generator with the current time
    for (size_t i = 0; i < num_points; i++) {
        points[i].value = lower_bound + ((double)rand() / RAND_MAX) * (upper_bound - lower_bound);
        points[i].string = malloc(10 * sizeof(char)); // Allocate memory for the string pointer
        if (points[i].string == NULL) {
            free(points);
            return NULL;
        }
    }

    // Initialize the custom hash function and memory pool manager
    mempool_manager* manager = malloc(sizeof(mempool_manager));
    if (manager == NULL) {
        free(points);
        return NULL;
    }
    manager->blocks = points;
    manager->size = sizeof(data_point) * num_points;
    manager->used = 0;

    // Set the value of each data point's double field to a random floating-point number within the specified range
    for (size_t i = 0; i < num_points; i++) {
        points[i].value = lower_bound + ((double)rand() / RAND_MAX) * (upper_bound - lower_bound);
    }

    // Return the initialized array of data points and memory pool manager
    return points;
}

// Define a function to free all allocated resources
void free_data_points(data_point* points, mempool_manager* manager) {
    // Free any allocated memory blocks within the memory pool
    for (size_t i = 0; i < manager->used; i++) {
        free(manager->blocks[i].string);
    }
    free(manager->blocks);
    free(manager);
}

// Define a function to report the current memory usage statistics
void report_memory_usage(mempool_manager* manager) {
    // Print the total allocated memory, free memory, and memory pool utilization
    printf("Total allocated memory: %zu bytes\n", manager->size);
    printf("Free memory: %zu bytes\n", manager->size - manager->used);
    printf("Memory pool utilization: %.2f%%\n", (double)manager->used / manager->size * 100.0);
}
