// Define the record structure
typedef struct {
    int value;
    char *data;
} record_t;

// Define the linked list node structure
typedef struct node {
    record_t *record;
    struct node *next;
} node_t;

// Define the linked list structure
typedef struct {
    node_t *head;
    node_t *tail;
} linked_list_t;

void initializeRecords(const char *label, void (*f)(record_t *), const char *module, int max_length) {
    // Allocate memory for the offset array
    long *offsets = malloc(sizeof(long) * 3);
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the key array
    int *keys = malloc(sizeof(int) * 3);
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for the record array
    record_t **records = malloc(sizeof(record_t *) * 3);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the linked list
    linked_list_t *linked_list = malloc(sizeof(linked_list_t));
    if (linked_list == NULL) {
        printf("Error: Failed to allocate memory for linked list\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    linked_list->head = NULL;
    linked_list->tail = NULL;

    // Generate random values for the record fields
    srand(time(NULL));
    for (int i = 0; i < 3; i++) {
        records[i] = malloc(sizeof(record_t));
        if (records[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        records[i]->value = rand() % max_length + 1;
        records[i]->data = malloc(sizeof(char) * (records[i]->value + 1));
        if (records[i]->data == NULL) {
            printf("Error: Failed to allocate memory for record %d data\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        memset(records[i]->data, 0, records[i]->value + 1);
    }

    // Initialize the linked list nodes
    for (int i = 0; i < 3; i++) {
        node_t *node = malloc(sizeof(node_t));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for linked list node %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        node->record = records[i];
        node->next = NULL;
        if (linked_list->tail == NULL) {
            linked_list->head = node;
        } else {
            linked_list->tail->next = node;
        }
        linked_list->tail = node;
    }

    // Run the tests
    for (int i = 0; i < 3; i++) {
        printf("Running test %d: %s\n", i, label);
        blueslip.reset();
        f(records[i]);
        if (blueslip.has_error()) {
            printf("Error: Test %d failed with error: %s\n", i, blueslip.get_error());
        } else {
            printf("Success: Test %d passed\n", i);
        }
    }

    // Clean up memory
    free(offsets);
    free(keys);
    for (int i = 0; i < 3; i++) {
        free(records[i]->data);
        free(records[i]);
    }
    free(records);
    free(linked_list);
}
