    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_keys; i++) {
        key_arr[i] = rand() % max_size + 1;
    }

    // Allocate memory for the offset array
    offset_arr = (long*)malloc(num_keys * sizeof(long));
    if (!offset_arr) {
        printf("Failed to allocate memory for offset array\n");
