#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the task structure
typedef struct {
    char* name;
    int priority;
    time_t deadline;
} Task;

// Define the memory pool configuration parameters
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
#define MEMORY_POOL_RESIZE_FREQUENCY 5 // Resize every 5 tasks
#define MAX_TASK_NAME_LENGTH 64

// Define the task cache configuration parameters
#define TASK_CACHE_SIZE 1024
#define TASK_CACHE_RESERVE_RATIO 0.25 // Reserve 25% of the memory pool for caching

// Define the locking mechanism for thread safety
pthread_mutex_t task_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the task list data structure
Task* task_list = NULL;
size_t task_list_size = 0;
size_t task_list_capacity = 0;

// Define the memory pool for dynamic allocation
void* memory_pool = NULL;
size_t memory_pool_size = MEMORY_POOL_SIZE;
size_t memory_pool_used = 0;

// Define the task cache for frequently used tasks
Task* task_cache[TASK_CACHE_SIZE];
size_t task_cache_count = 0;

// Function to allocate a new task structure
Task* alloc_task(const char* name, int priority, time_t deadline) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Check if there is enough memory in the pool to allocate a new task
    if (memory_pool_used + sizeof(Task) > memory_pool_size) {
        // Release the lock and return NULL if there is no more memory available
        pthread_mutex_unlock(&task_list_lock);
        return NULL;
    }

    // Allocate a new task structure from the pool
    Task* task = (Task*)memory_pool + memory_pool_used;
    memory_pool_used += sizeof(Task);

    // Initialize the task structure with the given parameters
    task->name = strdup(name);
    task->priority = priority;
    task->deadline = deadline;

    // Release the lock and return the allocated task structure
    pthread_mutex_unlock(&task_list_lock);
    return task;
}

// Function to deallocate a task structure
void free_task(Task* task) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Check if the given task is in the cache
    size_t i;
    for (i = 0; i < TASK_CACHE_SIZE; ++i) {
        if (task == task_cache[i]) {
            break;
        }
    }

    // If the given task is in the cache, move it to the end of the cache
    if (i < TASK_CACHE_SIZE) {
        Task* tmp = task_cache[i];
        task_cache[i] = task_cache[TASK_CACHE_SIZE - 1];
        task_cache[TASK_CACHE_SIZE - 1] = tmp;
    } else {
        // Otherwise, deallocate the task structure from the pool
        memory_pool_used -= sizeof(Task);
        free(task->name);
        free(task);
    }

    // Release the lock and return
    pthread_mutex_unlock(&task_list_lock);
}

// Function to add a new task to the list
void add_task(const char* name, int priority, time_t deadline) {
    // Allocate a new task structure from the pool
    Task* task = alloc_task(name, priority, deadline);

    // Check if there is enough memory in the cache to store the new task
    if (task_cache_count < TASK_CACHE_SIZE) {
        // Add the new task to the cache
        task_cache[task_cache_count++] = task;
    } else {
        // Otherwise, add the new task to the list
        task->next = task_list;
        task_list = task;
        ++task_list_size;
    }
}

// Function to remove a task from the list
void remove_task(Task* task) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Check if the given task is in the cache
    size_t i;
    for (i = 0; i < TASK_CACHE_SIZE; ++i) {
        if (task == task_cache[i]) {
            break;
        }
    }

    // If the given task is in the cache, remove it from the cache
    if (i < TASK_CACHE_SIZE) {
        Task* tmp = task_cache[i];
        task_cache[i] = task_cache[TASK_CACHE_SIZE - 1];
        task_cache[TASK_CACHE_SIZE - 1] = NULL;
        --task_cache_count;
    } else {
        // Otherwise, remove the task from the list
        Task** prev = &task_list;
        while (*prev != NULL && *prev != task) {
            prev = &(*prev)->next;
        }
        if (*prev == NULL) {
            fprintf(stderr, "Task not found in list\n");
        } else {
            *prev = task->next;
            --task_list_size;
        }
    }

    // Release the lock and return
    pthread_mutex_unlock(&task_list_lock);
}

// Function to clear all allocated resources and reset the memory pool
void clear_resources() {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Release all allocated tasks in the cache
    size_t i;
    for (i = 0; i < TASK_CACHE_SIZE; ++i) {
        if (task_cache[i] != NULL) {
            free(task_cache[i]->name);
            free(task_cache[i]);
        }
    }
    task_cache_count = 0;

    // Release all allocated tasks in the list
    Task* task = task_list;
    while (task != NULL) {
        Task* next = task->next;
        free(task->name);
        free(task);
        task = next;
    }
    task_list_size = 0;

    // Release the memory pool and reset its size
    if (memory_pool != NULL) {
        free(memory_pool);
    }
    memory_pool_size = MEMORY_POOL_SIZE;
    memory_pool_used = 0;

    // Release the lock and return
    pthread_mutex_unlock(&task_list_lock);
}

// Function to export the memory pool state to a binary format for backup or recovery purposes
void export_memory_pool(FILE* file) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Write the memory pool size and used size to the file
    fwrite(&memory_pool_size, sizeof(size_t), 1, file);
    fwrite(&memory_pool_used, sizeof(size_t), 1, file);

    // Write the memory pool data to the file
    fwrite(memory_pool, memory_pool_used, 1, file);

    // Release the lock and return
    pthread_mutex_unlock(&task_list_lock);
}

// Function to import the memory pool state from a binary format for backup or recovery purposes
void import_memory_pool(FILE* file) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&task_list_lock);

    // Read the memory pool size and used size from the file
    fread(&memory_pool_size, sizeof(size_t), 1, file);
    fread(&memory_pool_used, sizeof(size_t), 1, file);

    // Allocate a new memory pool with the imported size
    if (memory_pool != NULL) {
        free(memory_pool);
    }
    memory_pool = malloc(memory_pool_size);

    // Read the memory pool data from the file
    fread(memory_pool, memory_pool_used, 1, file);

    // Release the lock and return
    pthread_mutex_unlock(&task_list_lock);
}
