#define MAX_LOG_ENTRIES 100000
#define MIN_LATENCY 0
#define MAX_LATENCY 10000
#define AVG_LATENCY (MIN_LATENCY + MAX_LATENCY) / 2
#define LATENCY_STDDEV (MAX_LATENCY - MIN_LATENCY) / sqrt(12)
#define CONCURRENT_CHECKS 50
#define CHECK_TIMEOUT 30 // seconds
#define MEMORY_THRESHOLD 80 // percent
#define CPU_THRESHOLD 90 // percent

// Define data structures for the program
