    int num_log_entries = 0;
    pthread_t threads[CONCURRENT_CHECKS];
    int thread_count = 0;
    time_t start_time, end_time;
    double total_latency = 0;
    double min_latency = MAX_LATENCY;
    double max_latency = MIN_LATENCY;
    int success_count = 0;
    int failure_count = 0;

