    FILE* fp = fopen("hostnames.txt", "r");
    if (fp == NULL) {
        printf("Error: unable to open hostnames file\n");
        return 1;
    }
    while (fgets(hosts[num_hosts].hostname, sizeof(hosts[num_hosts].hostname), fp) != NULL) {
        num_hosts++;
    }
    fclose(fp);

    // Load the log entries from a file
