        pthread_create(&threads[thread_count], NULL, checkHost, &hosts[i].hostname);
        thread_count++;
    }

    // Wait for the checks to complete and update the monitoring system
    while (thread_count > 0) {
        if (time(NULL) >= end_time) {
            printf("Error: timeout exceeded\n");
            return 1;
        }
        pthread_join(threads[--thread_count], NULL);
        total_latency += hosts[i].latency;
        if (hosts[i].latency < min_latency) {
            min_latency = hosts[i].latency;
        }
        if (hosts[i].latency > max_latency) {
            max_latency = hosts[i].latency;
        }
        if (hosts[i].success) {
            success_count++;
        } else {
            failure_count++;
        }
    }

    // Generate the report
    generateReport(hosts, num_hosts);

    return 0;
}

void* checkHost(void* hostname) {
    char* host = (char*)hostname;
    int sockfd;
    struct sockaddr_in serv_addr;
    struct hostent* server;
    time_t start_time, end_time;
    double latency;
    int success = 0;

    // Initialize the socket and connect to the server
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        printf("Error: unable to create socket\n");
        return NULL;
    }
    server = gethostbyname(host);
    if (server == NULL) {
        printf("Error: unable to resolve hostname\n");
        close(sockfd);
        return NULL;
    }
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);
    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        printf("Error: unable to connect to host\n");
        close(sockfd);
        return NULL;
    }

    // Send a request and receive the response
    char* request = "GET / HTTP/1.1\r\nHost: www.example.com\r\nConnection: close\r\n\r\n";
    send(sockfd, request, strlen(request), 0);
    char buffer[4096];
    int bytes_received = recv(sockfd, buffer, sizeof(buffer), 0);
    if (bytes_received < 0) {
        printf("Error: unable to receive response\n");
        close(sockfd);
        return NULL;
    }

    // Calculate the latency and update the monitoring system
    start_time = time(NULL);
    end_time = start_time + CHECK_TIMEOUT;
    while (time(NULL) < end_time && bytes_received > 0) {
        bytes_received = recv(sockfd, buffer, sizeof(buffer), 0);
    }
    latency = difftime(time(NULL), start_time);
    close(sockfd);

    // Update the host information and return
    HostInfo* host = (HostInfo*)malloc(sizeof(HostInfo));
    strcpy(host->hostname, hostname);
    host->latency = latency;
    if (bytes_received > 0) {
        host->success = 1;
    } else {
        host->success = 0;
    }
    return host;
}

int parseLogEntry(char* log_entry, LogEntry* entry) {
    // Parse the log entry and extract the timestamp and latency
    char* token = strtok(log_entry, " ");
    if (token == NULL) {
        printf("Error: unable to parse log entry\n");
        return 1;
    }
    entry->timestamp = atoi(token);
    token = strtok(NULL, " ");
    if (token == NULL) {
        printf("Error: unable to parse log entry\n");
        return 1;
    }
    entry->latency = atoi(token);

    // Return success
    return 0;
}

double calculateLatency(LogEntry* entry) {
    // Calculate the latency based on the log entry
    double latency = (double)entry->latency / 1000.0;
    return latency;
}

void generateReport(HostInfo* hosts, int num_hosts) {
    // Generate a report of the network health monitoring results
    printf("Network Health Monitoring Report\n");
    printf("-------------------------------\n");
    printf("Total number of hostnames: %d\n", num_hosts);
    printf("Total number of log entries: %d\n", MAX_LOG_ENTRIES);
    printf("Minimum latency: %.2f ms\n", MIN_LATENCY);
    printf("Maximum latency: %.2f ms\n", MAX_LATENCY);
    printf("Average latency: %.2f ms\n", AVG_LATENCY);
    printf("Standard deviation of latency: %.2f ms\n", LATENCY_STDDEV);
    printf("Number of successful checks: %d\n", success_count);
    printf("Number of failed checks: %d\n", failure_count);
    printf("Total check time: %.2f seconds\n", total_latency);
}
