// Define a function to revert to a previous configuration version
void revert_config() {
    // Acquire the semaphore to ensure exclusive access to the shared memory region
    sem_t* semaphore = sem_open("config", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        fprintf(stderr, "Failed to create semaphore\n");
        return;
    }
    void* shared_memory = mmap(NULL, sizeof(struct Config), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
