double median(double* arr, int size) {
    // Sort the array in ascending order
    qsort(arr, size, sizeof(double), compare);

    // Calculate the median as the middle value if the array size is odd, or the average of the two middle values if the array size is even
    if (size % 2 == 0) {
        return (arr[size / 2 - 1] + arr[size / 2]) / 2.0;
    } else {
        return arr[size / 2];
    }
}

