    // Define the variables for tracking the number of processed numbers and the time elapsed
    int num_processed = 0;
    double start_time = clock();

    // Read the numbers from the distributed data stream
    while (num_processed < MAX_ARRAY_SIZE) {
        // Check if the semaphore has been decremented, indicating that a thread is waiting for processing to complete
        if (sem_trywait(sem) == -1) {
            handle_semaphore_decrement_error();
        }

        // Read the next number from the data stream
        double num;
        scanf("%lf", &num);

        // Check if the number is within the allowed range and not a NaN value
        if (num >= MIN_VALUE && num <= MAX_VALUE && !isnan(num)) {
            // Store the number in the array
            arr[num_processed] = num;
            num_processed++;
        } else {
            // Log the error and continue processing
            fprintf(stderr, "Invalid input. Continuing processing.\n");
        }

        // Check if the time elapsed exceeds the allowed limit
        double end_time = clock();
        if (end_time - start_time > 60) {
            handle_input_exceeded_limit();
        }
    }

