    print_smallest(arr, num_processed);

    // Calculate and print the median of all numbers in the array
    print_median(arr, num_processed);

    // Release the semaphore for concurrent thread operations
    if (sem_close(sem) == -1) {
        handle_semaphore_release_error();
    }

    // Free the memory allocated to store the array
    free(arr);

    return 0;
}
