#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Custom memory pool allocator
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used;     // Used memory in the pool
    void* blocks[]; // Array of memory blocks
};

// Data structure for storing data points
struct DataPoint {
    double value;
    char* string;
};

// Custom hash function for mapping data points to memory blocks
size_t hash(const struct DataPoint* point) {
    size_t seed = 0;
    const unsigned char* ptr = (const unsigned char*)point;
    while (*ptr != '\0') {
        seed ^= *ptr++;
    }
    return seed;
}

// Thread-safe memory pool manager
struct MemoryPoolManager {
    pthread_mutex_t lock; // Mutex for synchronizing access to the pool
    struct MemoryPool* pool; // Pointer to the memory pool
};

// Initialize a new memory pool with the given capacity
void initMemoryPool(struct MemoryPoolManager* manager, size_t capacity) {
    manager->pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    manager->pool->capacity = capacity;
    manager->pool->used = 0;
    manager->pool->blocks = (void**)calloc(capacity, sizeof(void*));
}

// Allocate a new memory block from the pool
void* allocateMemoryBlock(struct MemoryPoolManager* manager, size_t size) {
    pthread_mutex_lock(&manager->lock);
    void* block = NULL;
    if (manager->pool->used + size <= manager->pool->capacity) {
        block = &manager->pool->blocks[manager->pool->used];
        manager->pool->used += size;
    }
    pthread_mutex_unlock(&manager->lock);
    return block;
}

// Deallocate a memory block from the pool
void deallocateMemoryBlock(struct MemoryPoolManager* manager, void* block) {
    pthread_mutex_lock(&manager->lock);
    size_t index = (size_t)(block - &manager->pool->blocks[0]);
    if (index < manager->pool->used) {
        memset(block, 0, sizeof(void*));
        manager->pool->used -= sizeof(void*);
    }
    pthread_mutex_unlock(&manager->lock);
}

// Safely release all allocated resources
void releaseResources(struct MemoryPoolManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->pool->used; ++i) {
        deallocateMemoryBlock(manager, &manager->pool->blocks[i]);
    }
    free(manager->pool);
    pthread_mutex_unlock(&manager->lock);
}

// Function to safely release all allocated resources
void releaseResources(struct MemoryPoolManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->pool->used; ++i) {
        deallocateMemoryBlock(manager, &manager->pool->blocks[i]);
    }
    free(manager->pool);
    pthread_mutex_unlock(&manager->lock);
}

// Thread-safe mechanism for interacting with the external memory pool manager
void* allocateMemory(struct MemoryPoolManager* manager, size_t size) {
    return allocateMemoryBlock(manager, size);
}

void deallocateMemory(struct MemoryPoolManager* manager, void* block) {
    deallocateMemoryBlock(manager, block);
}

// Non-blocking mechanism to report memory usage statistics
void getMemoryUsageStats(struct MemoryPoolManager* manager, size_t* total, size_t* free, double* utilization) {
    pthread_mutex_lock(&manager->lock);
    *total = manager->pool->capacity;
    *free = manager->pool->used;
    *utilization = (double)*total / (double)*free;
    pthread_mutex_unlock(&manager->lock);
}

// Main function for demonstrating the use of the memory pool allocator and hash function
int main() {
    struct MemoryPoolManager manager;
    initMemoryPool(&manager, 1024 * 1024); // Initialize a new memory pool with capacity 1 MB

    // Allocate an array for double precision floating-point numbers
    size_t num_doubles = 1000;
    double* doubles = (double*)allocateMemory(&manager, sizeof(double) * num_doubles);
    if (!doubles) {
        printf("Failed to allocate memory for doubles\n");
        return -1;
    }

    // Allocate an array for char strings
    size_t num_strings = 500;
    char** strings = (char**)allocateMemory(&manager, sizeof(char*) * num_strings);
    if (!strings) {
        printf("Failed to allocate memory for strings\n");
        return -1;
    }

    // Initialize the data points array
    struct DataPoint* data_points = (struct DataPoint*)allocateMemory(&manager, sizeof(struct DataPoint) * num_doubles);
    if (!data_points) {
        printf("Failed to allocate memory for data points\n");
        return -1;
    }

    // Populate the data points array with random floating-point numbers and strings
    srand(time(NULL));
    for (size_t i = 0; i < num_doubles; ++i) {
        doubles[i] = (double)(rand() % 1000) / 100.0;
        char* string = (char*)allocateMemory(&manager, sizeof(char) * 256);
        if (!string) {
            printf("Failed to allocate memory for string\n");
            return -1;
        }
        snprintf(string, 256, "String %d", i);
        data_points[i].value = doubles[i];
        data_points[i].string = string;
    }

    // Print the memory usage statistics
    size_t total, free;
    double utilization;
    getMemoryUsageStats(&manager, &total, &free, &utilization);
    printf("Total memory: %zu\n", total);
    printf("Free memory: %zu\n", free);
    printf("Utilization: %.2f%%\n", utilization * 100.0);

    // Safely release all allocated resources
    releaseResources(&manager);

    return 0;
}
```
This code demonstrates the use of a custom memory pool allocator and hash function for managing dynamic memory allocation in a production-ready environment. The `MemoryPool` struct is used to store the memory pool, which consists of an array of memory blocks and a counter for the number of used blocks. The `allocateMemoryBlock` function is used to allocate a new memory block from the pool, while the `deallocateMemoryBlock` function is used to deallocate a memory block. The `releaseResources` function safely releases all allocated resources by deallocating each memory block and freeing the memory pool.

The `DataPoint` struct is used to store data points that contain a double precision floating-point number and a char string pointer. The `hash` function is used to map data points efficiently to memory blocks within the pool, optimizing for both lookup speed and memory coalescing. The `allocateMemory` function is used to safely allocate memory for the data points array, while the `deallocateMemory` function is used to deallocate the memory when it is no longer needed.

The `getMemoryUsageStats` function is used to report memory usage statistics, including total allocated memory, free memory, and pool utilization. This function uses a mutex to ensure thread safety while accessing the memory pool. The `main` function demonstrates the use of the memory pool allocator and hash function by allocating an array for double precision floating-point numbers, an array for char strings, and an array for data points. It then populates the data points array with random floating-point numbers and strings, prints the memory usage statistics, and safely releases all allocated resources when it is no longer needed.']

