void set_theme(const char* passphrase, const int num_themes) {
    // Initialize error code and cipher context
    ERR_load_crypto_strings();
    EVP_CIPHER_CTX *ctx;
    int ret = 0;

    // Derive encryption key from user-provided passphrase
    unsigned char key[32];
    unsigned char iv[16];
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)passphrase, strlen(passphrase), 1, key, iv);

    // Allocate memory for offset and key arrays
    long* offsets = malloc(num_themes * sizeof(long));
    int* keys = malloc(num_themes * sizeof(int));

    // Populate offset and key arrays with pseudo-random values within a specified range
    for (int i = 0; i < num_themes; i++) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 256;
    }

    // Allocate memory for theme record array
    theme_record* themes = malloc(num_themes * sizeof(theme_record));

    // Populate each record's color index with a pseudo-random value within a specified range
    for (int i = 0; i < num_themes; i++) {
        themes[i].color_index = rand() % 256;
    }

    // Initialize cipher context and set IV
    ctx = EVP_CIPHER_CTX_new();
    ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        ERR_print_errors_fp(stderr);
        return;
    }

    // Set theme bitmap to null when no longer needed
    void* theme_bitmap = NULL;

    // Interact seamlessly with existing graphical framework
    while (1) {
        // Check if a new theme is requested
        if (theme_bitmap == NULL) {
            // Allocate memory for the new theme bitmap and set it to null
            theme_bitmap = malloc(sizeof(void*));
            *(void**)theme_bitmap = NULL;
        }

        // Check if a theme is being recycled
        if (theme_bitmap != NULL && *(void**)theme_bitmap == NULL) {
            // Free the old theme bitmap and set it to null
            free(*(void**)theme_bitmap);
            *(void**)theme_bitmap = NULL;
        }

        // Check if a new theme is being set
        if (theme_bitmap != NULL && *(void**)theme_bitmap == NULL) {
            // Allocate memory for the new theme bitmap and set it to null
            *(void**)theme_bitmap = malloc(sizeof(void*));
            *(void**)theme_bitmap = NULL;
        }

        // Check if a theme is being recycled
        if (theme_bitmap != NULL && *(void**)theme_bitmap == NULL) {
            // Free the old theme bitmap and set it to null
            free(*(void**)theme_bitmap);
            *(void**)theme_bitmap = NULL;
        }
    }

    // Cleanup function to disable and free cipher context
    void cleanup() {
        EVP_CIPHER_CTX_free(ctx);
    }
}
