#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the size of the float array and char string array
#define FLOAT_ARRAY_SIZE 1024
#define STRING_ARRAY_SIZE 512

// Define the maximum size of a single block in the memory pool
#define MAX_BLOCK_SIZE (FLOAT_ARRAY_SIZE * sizeof(float) + STRING_ARRAY_SIZE * sizeof(char))

// Define the minimum size of a single block in the memory pool
#define MIN_BLOCK_SIZE 16

// Define the number of blocks to allocate at once when growing the pool
#define ALLOCATION_UNIT 16

// Define the maximum number of threads that can access the memory pool simultaneously
#define MAX_THREADS 32

// Define the synchronization mechanism for accessing the memory pool
pthread_mutex_t mempool_lock;

// Define the memory pool structure
struct mempool {
    // The head of the linked list of free blocks
    struct block *head;
    // The tail of the linked list of free blocks
    struct block *tail;
    // The number of free blocks in the pool
    size_t num_free_blocks;
    // The total size of the memory pool
    size_t total_size;
};

// Define the block structure for the linked list of free blocks
struct block {
    // The next block in the linked list
    struct block *next;
    // The previous block in the linked list
    struct block *prev;
    // The size of the block
    size_t size;
};

// Define the function to allocate memory from the memory pool
void* mempool_alloc(size_t size) {
    // Check if the requested size is valid
    if (size > MAX_BLOCK_SIZE || size < MIN_BLOCK_SIZE) {
        return NULL;
    }

    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&mempool_lock);

    // Find a free block that is large enough to hold the requested size
    struct block *block = mempool->head;
    while (block != NULL && block->size < size) {
        block = block->next;
    }

    // If no suitable block was found, allocate a new one
    if (block == NULL) {
        // Allocate a new block of the requested size
        struct block *new_block = malloc(size);
        if (new_block == NULL) {
            pthread_mutex_unlock(&mempool_lock);
            return NULL;
        }

        // Add the new block to the linked list of free blocks
        new_block->next = mempool->head;
        new_block->prev = NULL;
        if (mempool->head != NULL) {
            mempool->head->prev = new_block;
        }
        mempool->head = new_block;
        mempool->num_free_blocks++;
    } else {
        // Remove the block from the linked list of free blocks
        if (block->next != NULL) {
            block->next->prev = block->prev;
        }
        if (block->prev != NULL) {
            block->prev->next = block->next;
        } else {
            mempool->head = block->next;
        }
        mempool->num_free_blocks--;
    }

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&mempool_lock);

    // Return a pointer to the allocated block
    return (void*)((char*)block + sizeof(struct block));
}

// Define the function to deallocate memory from the memory pool
void mempool_dealloc(void *ptr) {
    // Check if the requested pointer is valid
    if (ptr == NULL || ptr < (void*)mempool || ptr > (void*)(mempool + 1)) {
        return;
    }

    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&mempool_lock);

    // Find the block that contains the requested pointer
    struct block *block = mempool->head;
    while (block != NULL && (char*)ptr < (char*)block + sizeof(struct block)) {
        block = block->next;
    }

    // If the requested pointer is not found, return
    if (block == NULL) {
        pthread_mutex_unlock(&mempool_lock);
        return;
    }

    // Add the block to the linked list of free blocks
    block->next = mempool->head;
    block->prev = NULL;
    if (mempool->head != NULL) {
        mempool->head->prev = block;
    }
    mempool->head = block;
    mempool->num_free_blocks++;

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&mempool_lock);
}

// Define the function to grow the memory pool by a specified number of blocks
void mempool_grow(size_t num_blocks) {
    // Check if the requested number of blocks is valid
    if (num_blocks == 0 || num_blocks > MAX_BLOCK_SIZE / sizeof(struct block)) {
        return;
    }

    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&mempool_lock);

    // Allocate a new block of memory for the requested number of blocks
    struct block *new_block = malloc(num_blocks * sizeof(struct block));
    if (new_block == NULL) {
        pthread_mutex_unlock(&mempool_lock);
        return;
    }

    // Add the new block to the linked list of free blocks
    new_block->next = mempool->head;
    new_block->prev = NULL;
    if (mempool->head != NULL) {
        mempool->head->prev = new_block;
    }
    mempool->head = new_block;
    mempool->num_free_blocks += num_blocks;

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&mempool_lock);
}

// Define the function to shrink the memory pool by a specified number of blocks
void mempool_shrink(size_t num_blocks) {
    // Check if the requested number of blocks is valid
    if (num_blocks == 0 || num_blocks > mempool->num_free_blocks) {
        return;
    }

    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&mempool_lock);

    // Remove the requested number of blocks from the linked list of free blocks
    struct block *block = mempool->head;
    for (size_t i = 0; i < num_blocks; i++) {
        if (block == NULL) {
            break;
        }
        block = block->next;
    }
    if (block != NULL) {
        // Remove the block from the linked list of free blocks
        if (block->next != NULL) {
            block->next->prev = block->prev;
        }
        if (block->prev != NULL) {
            block->prev->next = block->next;
        } else {
            mempool->head = block->next;
        }
        mempool->num_free_blocks -= num_blocks;
    }

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&mempool_lock);
}

// Define the function to reset the memory pool and clear all allocated resources
void mempool_reset() {
    // Lock the memory pool to prevent concurrent access
    pthread_mutex_lock(&mempool_lock);

    // Free all blocks in the linked list of free blocks
    struct block *block = mempool->head;
    while (block != NULL) {
        struct block *next = block->next;
        free(block);
        block = next;
    }
    mempool->head = NULL;
    mempool->num_free_blocks = 0;

    // Unlock the memory pool to allow other threads to access it
    pthread_mutex_unlock(&mempool_lock);
}
