}

// Insert a record into the data structure by its key
int insert_record(int key, record_t *record) {
    pthread_mutex_lock(&mempool_manager_mutex);

    // Check if there is enough free memory to allocate the record
    if (mempool_manager.free_memory < sizeof(record_key_t)) {
        printf("Error: Not enough free memory to insert record\n");
        pthread_mutex_unlock(&mempool_manager_mutex);
        return -1;
    }

    // Allocate a new record key structure from the free memory pool
    record_key_t *new_record_key = (record_key_t *)allocate_memory(sizeof(record_key_t));
    if (!new_record_key) {
        printf("Error: Failed to allocate memory for new record key\n");
        pthread_mutex_unlock(&mempool_manager_mutex);
        return -1;
    }

    // Initialize the new record key structure
    new_record_key->key = key;
    new_record_key->record = record;

    // Insert the new record key into the data structure
    record_keys[key] = *new_record_key;

    pthread_mutex_unlock(&mempool_manager_mutex);

    return 0;
}

// Delete a record from the data structure by its key
int delete_record(int key) {
    pthread_mutex_lock(&mempool_manager_mutex);

    // Check if the record exists in the data structure
    if (!record_keys[key]) {
        printf("Error: Record with key %d does not exist\n", key);
        pthread_mutex_unlock(&mempool_manager_mutex);
        return -1;
    }

    // Free the record key structure
    free(record_keys[key]);

    // Remove the record from the data structure
    record_keys[key] = NULL;

    pthread_mutex_unlock(&mempool_manager_mutex);

    return 0;
}

// Look up a record in the data structure by its key
record_t *lookup_record(int key) {
    pthread_mutex_lock(&mempool_manager_mutex);

    // Check if the record exists in the data structure
    if (!record_keys[key]) {
        printf("Error: Record with key %d does not exist\n", key);
        pthread_mutex_unlock(&mempool_manager_mutex);
        return NULL;
    }

    // Return the record pointer
    record_t *record = record_keys[key]->record;

    pthread_mutex_unlock(&mempool_manager_mutex);

    return record;
}

