    pthread_mutex_lock(&mempool_manager_mutex);

    // Free the records array
    free(records);

    // Reset the total allocated memory, free memory, and utilization statistics
    mempool_manager.total_allocated = 0;
    mempool_manager.free_memory = 0;
    mempool_manager.utilization = 0.0;

    pthread_mutex_unlock(&mempool_manager_mutex);
}
