void init_data_structures(int num_records, int min_value, int max_value, int str_len) {
    // Allocate memory for data structures
    data_structures *ds = malloc(sizeof(data_structures) * num_records);
    if (ds == NULL) {
        printf("Error: Failed to allocate memory for data structures\n");
        return;
    }

    // Initialize arrays of offsets, keys, and timestamps
    long *offsets = malloc(sizeof(long) * num_records);
    int *keys = malloc(sizeof(int) * num_records);
    time_t *timestamps = malloc(sizeof(time_t) * num_records);
    if (offsets == NULL || keys == NULL || timestamps == NULL) {
        printf("Error: Failed to allocate memory for arrays\n");
        free(ds);
        return;
    }

    // Initialize records and strings
    for (int i = 0; i < num_records; i++) {
        ds[i].rec.value = min_value + rand() % (max_value - min_value + 1);
        ds[i].field.str = malloc(sizeof(char) * str_len);
        if (ds[i].field.str == NULL) {
            printf("Error: Failed to allocate memory for string\n");
            free(offsets);
            free(keys);
            free(timestamps);
            free(ds);
            return;
        }
        srand((unsigned int)time(NULL));
        for (int j = 0; j < str_len; j++) {
            ds[i].field.str[j] = rand() % ('Z' - 'A') + 'A';
        }
    }

    // Initialize offsets, keys, and timestamps
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(data_structures);
        keys[i] = rand() % 1000000;
        timestamps[i] = time(NULL);
    }

    // Free memory if error occurs during initialization
    if (offsets == NULL || keys == NULL || timestamps == NULL) {
        printf("Error: Failed to initialize arrays\n");
        free(ds);
        return;
    }

    // Set data structures
    ds->offsets = offsets;
    ds->keys = keys;
    ds->timestamps = timestamps;

    // Print initialized data structures
    printf("Initialized data structures:\n");
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: offset=%ld, key=%d, value=%d, string=%s, timestamp=%lu\n", i, offsets[i], keys[i], ds[i].rec.value, ds[i].field.str, timestamps[i]);
    }
}

// Define function to free memory for data structures
void free_data_structures(data_structures *ds) {
    // Free arrays of offsets, keys, and timestamps
    free(ds->offsets);
    free(ds->keys);
    free(ds->timestamps);

    // Free records and strings
    for (int i = 0; i < num_records; i++) {
        free(ds[i].field.str);
    }

    // Free data structures
    free(ds);
}
