        free(array->elements);
    }
    free(pipeline->arrays);
}

// Function to perform arithmetic operations on the data
void perform_operation(pipeline_t *pipeline, operation_info_t *op) {
    // Perform the specified operation on the data
    switch (op->op) {
        case ADD:
            for (size_t i = 0; i < pipeline->num_arrays; i++) {
                array_t *array = &pipeline->arrays[i];
                size_t num_elements = array->num_elements;
                for (size_t j = 0; j < num_elements; j++) {
                    element_t *element = &array->elements[j];
                    element->value += op->index;
                }
            }
            break;
        case SUBTRACT:
            for (size_t i = 0; i < pipeline->num_arrays; i++) {
                array_t *array = &pipeline->arrays[i];
                size_t num_elements = array->num_elements;
                for (size_t j = 0; j < num_elements; j++) {
                    element_t *element = &array->elements[j];
                    element->value -= op->index;
                }
            }
            break;
        case MULTIPLY:
            for (size_t i = 0; i < pipeline->num_arrays; i++) {
                array_t *array = &pipeline->arrays[i];
                size_t num_elements = array->num_elements;
                for (size_t j = 0; j < num_elements; j++) {
                    element_t *element = &array->elements[j];
                    element->value *= op->index;
                }
            }
            break;
        case DIVIDE:
            for (size_t i = 0; i < pipeline->num_arrays; i++) {
                array_t *array = &pipeline->arrays[i];
                size_t num_elements = array->num_elements;
                for (size_t j = 0; j < num_elements; j++) {
                    element_t *element = &array->elements[j];
                    if (op->index == 0) {
                        // Handle division by zero gracefully
                        continue;
                    }
                    element->value /= op->index;
                }
            }
            break;
    }
}

