data_point* allocate_data_points(size_t num_points, size_t string_length) {
    // Allocate memory for the data points
    data_point* data = (data_point*)malloc(num_points * sizeof(data_point));
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for data points\n");
        return NULL;
