void populate_data_points(data_point* data, size_t num_points, double lower_bound, double upper_bound) {
    // Generate random floating-point numbers within the specified range
    for (size_t i = 0; i < num_points; i++) {
        data[i].value = lower_bound + ((double)rand() / RAND_MAX) * (upper_bound - lower_bound);
    }
}

// Define a function to clear all allocated resources and reset the memory pool
