// Define a struct to represent a record in the collection
typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

// Define a struct to hold the collection and its metadata
typedef struct Collection {
    Record* head;
    size_t count;
    size_t capacity;
} Collection;

// Function to create a new record with a unique key
Record* create_record(int key, long offset) {
    // Check if the key is already in use
    for (Record* current = head; current != NULL; current = current->next) {
        if (current->key == key) {
            // If the key is already in use, retry generating a new key
            return create_record(key + 1, offset);
        }
    }

    // Allocate memory for the record
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return NULL;
    }

    // Initialize the record fields
    record->key = key;
    record->offset = offset;
    record->next = NULL;

    return record;
}

// Function to insert a new record into the collection
void insert_record(Collection* collection, int key, long offset) {
    // Create a new record with a unique key
    Record* record = create_record(key, offset);
    if (record == NULL) {
        fprintf(stderr, "Failed to create record\n");
        return;
    }

    // Insert the record into the collection
    if (collection->head == NULL) {
        collection->head = record;
    } else {
        Record* current = collection->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }

    // Increment the count of records in the collection
    collection->count++;
}

// Function to retrieve a record from the collection by key
Record* get_record(Collection* collection, int key) {
    for (Record* current = collection->head; current != NULL; current = current->next) {
        if (current->key == key) {
            return current;
        }
    }

    return NULL;
}

// Function to delete a record from the collection by key
void delete_record(Collection* collection, int key) {
    Record* previous = NULL;
    for (Record* current = collection->head; current != NULL; current = current->next) {
        if (current->key == key) {
            // Remove the record from the list
            if (previous == NULL) {
                collection->head = current->next;
            } else {
                previous->next = current->next;
            }

            // Decrement the count of records in the collection
            collection->count--;

            // Free the memory allocated for the record
            free(current);

            return;
        }

        previous = current;
    }
}

// Function to report the number of retries due to duplicate keys
int get_num_retries() {
    return num_retries;
}

// Main function for testing the collection
