    if (collection == NULL) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        return 1;
    }

    // Initialize the collection
    collection->head = NULL;
    collection->count = 0;
    collection->capacity = 0;

    // Test insertion and retrieval of records
    insert_record(collection, 1, 10);
    Record* record = get_record(collection, 1);
    assert(record != NULL && record->key == 1 && record->offset == 10);

    // Test deletion of a record by key
    delete_record(collection, 1);
    record = get_record(collection, 1);
    assert(record == NULL);

    // Test insertion and retrieval of multiple records with duplicate keys
    for (int i = 0; i < 10; i++) {
        insert_record(collection, i, i * 10);
    }
    for (int i = 0; i < 10; i++) {
        record = get_record(collection, i);
        assert(record != NULL && record->key == i && record->offset == i * 10);
    }

    // Test the number of retries due to duplicate keys
    insert_record(collection, 1, 10);
    num_retries = get_num_retries();
    assert(num_retries == 1);

    free(collection);
    return 0;
}
