void network_health_checks(char **hostnames, size_t num_hostnames) {
    // Initialize variables for tracking latency and error counts
    double total_latency = 0;
    int error_count = 0;

    // Loop through each hostname and perform a network health check
    for (size_t i = 0; i < num_hostnames; i++) {
        // Initialize variables for tracking latency and error counts for this hostname
        double host_latency = 0;
        int host_error_count = 0;

        // Perform a network health check on the current hostname
        struct addrinfo *result, *rp;
        int sfd;
        char s[INET6_ADDRSTRLEN];
        if (getaddrinfo(hostnames[i], NULL, NULL, &result) == 0) {
            for (rp = result; rp != NULL; rp = rp->ai_next) {
                sfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
                if (sfd == -1) {
                    continue;
                }

                // Connect to the hostname and measure latency
                struct timeval start, end;
                gettimeofday(&start, NULL);
                if (connect(sfd, rp->ai_addr, rp->ai_addrlen) == -1) {
                    close(sfd);
                    continue;
                }
                gettimeofday(&end, NULL);
                close(sfd);

                // Calculate the latency for this hostname
                double latency = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;
                host_latency += latency;
            }
        } else {
            // Handle error for getaddrinfo()
            perror("getaddrinfo");
            continue;
        }

        // Update the total latency and error count for this hostname
        total_latency += host_latency / num_hostnames;
        error_count += host_error_count;
    }

    // Print the summary report of network health checks
    printf("Network Health Checks Summary\n");
    printf("Total Latency: %.2f ms\n", total_latency);
    printf("Error Count: %d\n", error_count);
