// Define a structure to represent a transaction
typedef struct {
    double value;
    unsigned int id;
    bool status;
} transaction_t;

// Define a hash table to store transactions
typedef struct {
    transaction_t **table;
    size_t capacity;
    size_t count;
} hash_table_t;

// Initialize the hash table with a given capacity
void init_hash_table(hash_table_t *ht, size_t capacity) {
    ht->table = malloc(capacity * sizeof(transaction_t*));
    if (!ht->table) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        exit(1);
    }
    ht->capacity = capacity;
    ht->count = 0;
}

// Insert a transaction into the hash table
void insert_transaction(hash_table_t *ht, transaction_t *tx) {
    // Generate a unique ID for the transaction
    tx->id = generate_unique_id();

    // Check if there is a collision with an existing transaction
    size_t index = hash_function(tx->id);
    while (ht->table[index] != NULL && ht->table[index]->id == tx->id) {
        // Handle collisions by retrying with a new ID
        tx->id = generate_unique_id();
        index = hash_function(tx->id);
    }

    // Insert the transaction into the hash table
    ht->table[index] = tx;
    ht->count++;
}

// Look up a transaction in the hash table by ID
transaction_t *lookup_transaction(hash_table_t *ht, unsigned int id) {
    size_t index = hash_function(id);
    while (ht->table[index] != NULL && ht->table[index]->id != id) {
        index++;
        if (index == ht->capacity) {
            index = 0;
        }
    }
    return ht->table[index];
}

// Generate a unique ID for a transaction
unsigned int generate_unique_id() {
    // Implement a simple algorithm to generate a unique ID
    static unsigned int id = 1;
    return id++;
}

// Hash function to map IDs to indices in the hash table
size_t hash_function(unsigned int id) {
    // Implement a simple hash function that takes the least significant bits of the ID
    return id % ht->capacity;
}

// Clean up the hash table and release all resources
void cleanup_hash_table(hash_table_t *ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        free(ht->table[i]);
    }
    free(ht->table);
}
