typedef struct rb_node {
    Record *record;
    struct rb_node *left, *right;
    int color;
} RBNode;

// Define a red-black tree structure
typedef struct {
    RBNode *root;
    pthread_mutex_t mutex;
} RBTree;

// Function to generate a new key for a duplicate record
int generateNewKey(Record *record) {
    int newKey = 0;
    while (1) {
        // Generate a random number between 1 and 1000
        newKey = rand() % 1000 + 1;
        // Check if the new key is already in use
        if (!findRecord(newKey)) {
            break;
        }
    }
    return newKey;
}

// Function to insert a record into the collection
void insertRecord(int key, long offset) {
    pthread_mutex_lock(&tree->mutex);
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        // Handle allocation failure gracefully
        printf("Error: Failed to allocate memory for record\n");
        return;
    }
    record->key = key;
    record->offset = offset;
    RBNode *node = tree->root;
    while (1) {
        if (node == NULL) {
            // Insert the new record as a leaf node
            node = malloc(sizeof(RBNode));
            if (node == NULL) {
                // Handle allocation failure gracefully
                printf("Error: Failed to allocate memory for RBNode\n");
                return;
            }
            node->record = record;
            node->left = node->right = NULL;
            node->color = 0;
            tree->root = node;
            break;
        } else if (node->record->key == key) {
            // Handle duplicate keys by generating a new key and retrying
            int newKey = generateNewKey(record);
            record->key = newKey;
            insertRecord(newKey, offset);
            break;
        } else if (node->record->key > key) {
            // Insert the new record in the left subtree
            node->left = malloc(sizeof(RBNode));
            if (node->left == NULL) {
                // Handle allocation failure gracefully
                printf("Error: Failed to allocate memory for RBNode\n");
                return;
            }
            node->left->record = record;
            node->left->left = node->left->right = NULL;
            node->left->color = 0;
            break;
        } else {
            // Insert the new record in the right subtree
            node->right = malloc(sizeof(RBNode));
            if (node->right == NULL) {
                // Handle allocation failure gracefully
                printf("Error: Failed to allocate memory for RBNode\n");
                return;
            }
            node->right->record = record;
            node->right->left = node->right->right = NULL;
            node->right->color = 0;
            break;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Function to find a record in the collection by key
Record *findRecord(int key) {
    pthread_mutex_lock(&tree->mutex);
    RBNode *node = tree->root;
    while (1) {
        if (node == NULL) {
            break;
        } else if (node->record->key == key) {
            Record *record = node->record;
            pthread_mutex_unlock(&tree->mutex);
            return record;
        } else if (node->record->key > key) {
            node = node->left;
        } else {
            node = node->right;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
    return NULL;
}

// Function to delete a record from the collection by key
void deleteRecord(int key) {
    pthread_mutex_lock(&tree->mutex);
    RBNode *node = tree->root;
    while (1) {
        if (node == NULL) {
            break;
        } else if (node->record->key == key) {
            // Delete the record from the tree
            if (node->left != NULL && node->right != NULL) {
                // Replace the node with its inorder successor
                RBNode *successor = node->right;
                while (successor->left != NULL) {
                    successor = successor->left;
                }
                node->record->key = successor->record->key;
                node->record->offset = successor->record->offset;
            } else if (node->left == NULL && node->right == NULL) {
                // Delete the leaf node
                free(node);
                break;
            } else if (node->left != NULL) {
                // Replace the node with its left child
                node->record = node->left->record;
                free(node->left);
                break;
            } else {
                // Replace the node with its right child
                node->record = node->right->record;
                free(node->right);
                break;
            }
        } else if (node->record->key > key) {
            node = node->left;
        } else {
            node = node->right;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Function to update a record in the collection by key
void updateRecord(int key, long offset) {
    pthread_mutex_lock(&tree->mutex);
    RBNode *node = tree->root;
    while (1) {
        if (node == NULL) {
            break;
        } else if (node->record->key == key) {
            node->record->offset = offset;
            break;
        } else if (node->record->key > key) {
            node = node->left;
        } else {
            node = node->right;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Function to print the collection
void printCollection() {
    pthread_mutex_lock(&tree->mutex);
    RBNode *node = tree->root;
    while (1) {
        if (node == NULL) {
            break;
        } else {
            printf("%d %ld\n", node->record->key, node->record->offset);
            node = node->right;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Function to track the number of retries due to duplicate keys and the average time taken for successful insertions
void trackRetries(int key, long offset) {
    // Implement a counter to keep track of the number of retries
    int numRetries = 0;
    // Implement a timer to measure the time taken for each successful insertion
    struct timespec startTime, endTime;
    clock_gettime(CLOCK_MONOTONIC, &startTime);
    while (1) {
        if (findRecord(key)) {
            numRetries++;
            // Generate a new key and retry the insertion
            int newKey = generateNewKey(record);
            record->key = newKey;
            insertRecord(newKey, offset);
        } else {
            break;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &endTime);
    // Calculate the average time taken for successful insertions
    long totalTime = (endTime.tv_sec - startTime.tv_sec) * 1000 + (endTime.tv_nsec - startTime.tv_nsec) / 1000000;
    printf("Average time taken for successful insertions: %ld ms\n", totalTime / numRetries);
}

// Function to periodically schedule a compaction process to reduce fragmentation and improve cache locality
void scheduleCompaction() {
    // Implement a timer to schedule the compaction process
    struct timespec startTime, endTime;
    clock_gettime(CLOCK_MONOTONIC, &startTime);
    while (1) {
        // Check if there are any records that need to be compacted
        RBNode *node = tree->root;
        while (1) {
            if (node == NULL) {
                break;
            } else if (node->record->offset > 0) {
                // Compact the record by updating its offset value
                node->record->offset -= 1;
            } else {
                // Delete the record from the tree
                deleteRecord(node->record->key);
            }
            node = node->right;
        }
        clock_gettime(CLOCK_MONOTONIC, &endTime);
        // Calculate the time taken for the compaction process
        long totalTime = (endTime.tv_sec - startTime.tv_sec) * 1000 + (endTime.tv_nsec - startTime.tv_nsec) / 1000000;
        printf("Compaction time: %ld ms\n", totalTime);
    }
}
