#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define a structure to represent a record with an offset, key, and string
typedef struct Record {
    long offset;
    int key;
    char* string;
} Record;

// Function to manage and initialize a dynamic array of records
Record* init_records(char* buffer, size_t buflen, int min_key, int max_key, size_t limit) {
    // Allocate memory for the record array
    Record* records = malloc(limit * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize each record with a random key and string derived from the buffer
    size_t i = 0;
    while (i < limit) {
        Record* record = &records[i];
        record->offset = i * buflen;
        record->key = min_key + rand() % (max_key - min_key);
        record->string = malloc(buflen * sizeof(char));
        if (record->string == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for string\n");
            return NULL;
        }
        memcpy(record->string, buffer + i * buflen, buflen);
        i++;
    }

    // Return the initialized record array
    return records;
}

// Function to deallocate a dynamic array of records
void free_records(Record* records) {
    if (records == NULL) {
        return;
    }
    for (size_t i = 0; i < limit; i++) {
        Record* record = &records[i];
        free(record->string);
    }
    free(records);
}
```
