    Camellia_set_encrypt_key(camelliaKey, 256);
    Camellia_ecb_encrypt((unsigned char *)offsetArray, (unsigned char *)recordArray, camelliaKey, CAMELLIA_ENCRYPT);

    // Perform MD5 hash using OpenSSL library
    MD5_Init(md5Ctx);
    MD5_Update(md5Ctx, (unsigned char *)offsetArray, MEM_SIZE);
    MD5_Final((unsigned char *)recordArray, md5Ctx);

    // Perform SHA1 hash using OpenSSL library
    SHA1_Init(sha1Ctx);
    SHA1_Update(sha1Ctx, (unsigned char *)offsetArray, MEM_SIZE);
    SHA1_Final((unsigned char *)recordArray, sha1Ctx);

    // Perform RSA encryption using OpenSSL library
    RSA_set_encrypt_key(rsaKey, 2048, RSA_PKCS1_PADDING);
    RSA_ecb_encrypt((unsigned char *)offsetArray, (unsigned char *)recordArray, rsaKey, RSA_ENCRYPT);

    // Free memory for OpenSSL structures
    free(aesKey);
    free(camelliaKey);
    free(md5Ctx);
    free(sha1Ctx);
    free(rsaKey);

    return recordArray;
}

