    for (int i = 0; i < *key_size; i++) {
        total_allocated += sizeof(long) + sizeof(int);
        if ((*offset_arr)[i] != NULL) {
            total_free += sizeof(long);
        }
        if ((*key_arr)[i] != NULL) {
            total_free += sizeof(int);
        }
