    // Calculate the memory pool utilization and log the statistics
    float memory_pool_utilization = (total_allocated - total_free) / (float)total_allocated;
    fprintf(stderr, "Memory usage: Total allocated = %ld bytes, Free = %ld bytes, Memory pool utilization = %.2f%%\n", total_allocated, total_free, memory_pool_utilization * 100);
}

