using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace FileProcessor
{
    public class FileProcessor
    {
        private readonly string _inputFilePath;
        private readonly string _outputFilePath;
        private readonly EncryptionAlgorithm _encryptionAlgorithm;
        private readonly DecryptionAlgorithm _decryptionAlgorithm;
        private readonly MemoryPool<byte> _memoryPool;
        private readonly ILogger _logger;

        public FileProcessor(string inputFilePath, string outputFilePath, EncryptionAlgorithm encryptionAlgorithm, DecryptionAlgorithm decryptionAlgorithm, MemoryPool<byte> memoryPool, ILogger logger)
        {
            _inputFilePath = inputFilePath;
            _outputFilePath = outputFilePath;
            _encryptionAlgorithm = encryptionAlgorithm;
            _decryptionAlgorithm = decryptionAlgorithm;
            _memoryPool = memoryPool;
            _logger = logger;
        }

        public async Task ProcessAsync(CancellationToken cancellationToken)
        {
            try
            {
                // Validate file paths and permissions
                if (!File.Exists(_inputFilePath))
                {
                    throw new FileNotFoundException($"Input file '{_inputFilePath}' does not exist.");
                }

                if (string.IsNullOrEmpty(_outputFilePath))
                {
                    throw new ArgumentException("Output file path is required.", nameof(outputFilePath));
                }

                // Use memory pools for efficient buffer management
                using var inputStream = File.OpenRead(_inputFilePath);
                using var outputStream = File.Create(_outputFilePath);
                using var memoryOwner = _memoryPool.Rent();
                var buffer = memoryOwner.Memory;

                // Handle encryption or decryption operation based on command line option
                if (_encryptionAlgorithm != null)
                {
                    await EncryptAsync(inputStream, outputStream, cancellationToken);
                }
                else if (_decryptionAlgorithm != null)
                {
                    await DecryptAsync(inputStream, outputStream, cancellationToken);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process file.");
            }
        }

        private async Task EncryptAsync(Stream inputStream, Stream outputStream, CancellationToken cancellationToken)
        {
            // Use a stream reader and writer to handle the encryption operation
            using var reader = new StreamReader(inputStream);
            using var writer = new StreamWriter(outputStream);

            // Encrypt the data in chunks using the configured encryption algorithm
            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync();
                var encryptedData = _encryptionAlgorithm.Encrypt(line);
                await writer.WriteLineAsync(encryptedData);
            }
        }

        private async Task DecryptAsync(Stream inputStream, Stream outputStream, CancellationToken cancellationToken)
        {
            // Use a stream reader and writer to handle the decryption operation
            using var reader = new StreamReader(inputStream);
            using var writer = new StreamWriter(outputStream);

            // Decrypt the data in chunks using the configured decryption algorithm
            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync();
                var decryptedData = _decryptionAlgorithm.Decrypt(line);
                await writer.WriteLineAsync(decryptedData);
            }
        }
    }
}
```
