typedef struct {
    double value;
    char* str;
} data_point;

// Function to manage dynamic data structures under operational constraints
int manage_data(int num_doubles, int num_strings) {
    // Initialize array of data points with size equal to the number of strings
    data_point* data = (data_point*)malloc(num_strings * sizeof(data_point));
    if (!data) {
        fprintf(stderr, "Error: Failed to allocate memory for data points\n");
        return -1;
    }

    // Initialize random number generator with current time
    srand((unsigned int)time(NULL));

    // Loop through each data point and set its double field to a random value within the specified range
    for (int i = 0; i < num_strings; i++) {
        data[i].value = (double)(rand() % 100);
    }

    // Allocate memory for each string and set its pointer in the corresponding data point
    for (int i = 0; i < num_strings; i++) {
        char* str = (char*)malloc(256 * sizeof(char));
        if (!str) {
            fprintf(stderr, "Error: Failed to allocate memory for string %d\n", i);
            return -1;
        }
        data[i].str = str;
    }

    // Register each allocated memory block with the external memory pool manager
    for (int i = 0; i < num_strings; i++) {
        if (!register_memory(data[i].str, sizeof(char) * 256)) {
            fprintf(stderr, "Error: Failed to register memory block with memory pool\n");
            return -1;
        }
    }

    // Read a list of floating-point numbers and strings from standard input
    float largest_float = 0.0f;
    char* longest_string = NULL;
    for (int i = 0; i < num_doubles; i++) {
        float val;
        scanf("%f", &val);
        if (val > largest_float) {
            largest_float = val;
        }
    }
    for (int i = 0; i < num_strings; i++) {
        char* str;
        scanf("%s", str);
        if (strlen(str) > strlen(longest_string)) {
            longest_string = str;
        }
    }

    // Print the largest floating-point number and the longest string in the respective arrays
    printf("Largest float: %f\n", largest_float);
    printf("Longest string: %s\n", longest_string);

    // Clear all allocated resources and reset the memory pool
    for (int i = 0; i < num_strings; i++) {
        free(data[i].str);
    }
    free(data);
    clear_memory_pool();

    return 0;
}

// Helper function to report current memory usage statistics
void print_memory_usage() {
    printf("Total allocated memory: %lu\n", get_total_allocated_memory());
    printf("Free memory: %lu\n", get_free_memory());
    printf("Memory pool utilization: %lu\n", get_memory_pool_utilization());
}

// Helper function to clear all allocated resources and reset the memory pool
void clear_memory_pool() {
    // Release any allocated resources
    for (int i = 0; i < num_strings; i++) {
        free(data[i].str);
    }
    free(data);

    // Reset the memory pool to its initial state
    reset_memory_pool();
}

// Helper function to register a memory block with the external memory pool manager
int register_memory(void* mem, size_t size) {
    // Check if the memory pool is full
    if (is_memory_pool_full()) {
        fprintf(stderr, "Error: Memory pool is full\n");
        return 0;
    }

    // Register the memory block with the external memory pool manager
    int ret = register_mem_block(mem, size);
    if (ret != 1) {
        fprintf(stderr, "Error: Failed to register memory block with memory pool\n");
        return 0;
    }

    return 1;
}

// Helper function to handle potential errors during memory allocation and deallocation processes efficiently
void handle_error() {
    // Release any allocated resources
    for (int i = 0; i < num_strings; i++) {
        free(data[i].str);
    }
    free(data);

    // Reset the memory pool to its initial state
    reset_memory_pool();
}
