// Define a function to read the CSV file and store it in an array of data points
void read_csv(char *filename, int num_data_points) {
    // Allocate memory for the floating-point array and initialize it to 0.0
    double *floating_array = (double *)malloc(num_data_points * sizeof(double));
    memset(floating_array, 0.0, num_data_points * sizeof(double));

    // Allocate memory for the character array and initialize it to '\0'
    char *character_array = (char *)malloc(num_data_points * sizeof(char));
    memset(character_array, '\0', num_data_points * sizeof(char));

    // Allocate memory for the data point array and initialize it to 0.0 and '\0'
    data_point *data_points = (data_point *)malloc(num_data_points * sizeof(data_point));
    memset(data_points, 0.0, num_data_points * sizeof(data_point));

    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the data from the CSV file and store it in the arrays
    int i = 0;
    while (fscanf(file, "%lf,%c", &floating_array[i], &character_array[i]) == 2) {
        data_points[i].value = floating_array[i];
        data_points[i].label = character_array[i];
        i++;
    }

    // Close the CSV file
    fclose(file);

    // Register the allocated memory with the external memory pool manager
    int status = register_memory(floating_array, num_data_points * sizeof(double));
    if (status != 0) {
        printf("Error: unable to register floating-point array\n");
        return;
    }
    status = register_memory(character_array, num_data_points * sizeof(char));
    if (status != 0) {
        printf("Error: unable to register character array\n");
        return;
    }
    status = register_memory(data_points, num_data_points * sizeof(data_point));
    if (status != 0) {
        printf("Error: unable to register data point array\n");
        return;
    }

    // Print the memory usage statistics
    printf("Memory usage:\n");
    printf("\tTotal allocated memory: %lu bytes\n", get_total_allocated_memory());
    printf("\tFree memory: %lu bytes\n", get_free_memory());
    printf("\tMemory pool utilization: %.2f%%\n", get_memory_pool_utilization());
}

// Define a function to read the CSV file and store it in an array of data points using memory-mapped I/O
void read_csv_mmap(char *filename, int num_data_points) {
    // Open the CSV file for reading using memory-mapped I/O
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Map the CSV file into memory using mmap
    void *data_ptr = mmap(NULL, num_data_points * sizeof(double), PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (data_ptr == NULL) {
        printf("Error: unable to map file %s\n", filename);
        return;
    }

    // Read the data from the CSV file and store it in the arrays
    double *floating_array = (double *)data_ptr;
    char *character_array = (char *)(data_ptr + num_data_points * sizeof(double));
    data_point *data_points = (data_point *)(data_ptr + num_data_points * (sizeof(double) + sizeof(char)));
    int i = 0;
    while (i < num_data_points) {
        data_points[i].value = floating_array[i];
        data_points[i].label = character_array[i];
        i++;
    }

    // Close the CSV file and unmap the memory
    fclose(file);
    munmap(data_ptr, num_data_points * sizeof(double));

    // Register the allocated memory with the external memory pool manager
    int status = register_memory(floating_array, num_data_points * sizeof(double));
    if (status != 0) {
        printf("Error: unable to register floating-point array\n");
