    printf("\tFree memory: %lu bytes\n", get_free_memory());
    printf("\tMemory pool utilization: %.2f%%\n", get_memory_pool_utilization());
}

// Define a function to read the CSV file and store it in an array of data points using buffered reading
void read_csv_buffer(char *filename, int num_data_points) {
