// Define the request and response types
struct Request {
  string url;
};

struct Response {
  int status_code;
  string body;
};

// Define the client class
class SandeshClient {
 public:
  // Constructor
  SandeshClient(io_service& io_service, const string& server_url) :
      io_service_(io_service),
      resolver_(io_service),
      socket_(io_service),
      server_url_(server_url) {}

  // Send a GET request to the server
  void sendRequest(const Request& request, function<void(const Response&)> callback) {
    // Resolve the server address and port
    resolver_.async_resolve(server_url_, "http", [this, &request, &callback](const error_code& ec, const tcp::resolver::results_type& endpoints) {
      if (!ec) {
        // Connect to the server
        asio::connect(socket_, endpoints);

        // Send the request
        boost::asio::async_write(socket_, boost::asio::buffer(request.url), [this, &callback](const error_code& ec, size_t bytes_transferred) {
          if (!ec) {
            // Read the response
            Response response;
            async_read(socket_, boost::asio::buffer(&response, sizeof(Response)), [this, &callback](const error_code& ec, size_t bytes_transferred) {
              if (!ec) {
                callback(response);
              } else {
                // Handle the error
                cout << "Error: " << ec.message() << endl;
              }
            });
          } else {
            // Handle the error
            cout << "Error: " << ec.message() << endl;
          }
        });
      } else {
        // Handle the error
        cout << "Error: " << ec.message() << endl;
      }
    });
  }

