#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>

namespace Logging {
    class Logger {
    public:
        enum Level { DEBUG, INFO, WARNING, ERROR };

        Logger(const std::string& configFile) {
            // Load configuration from file
            loadConfig(configFile);
        }

        ~Logger() {}

        void logMessage(Level level, const std::string& message) {
            // Lock mutex to prevent concurrent access
            std::lock_guard<std::mutex> lock(mutex_);

            // Check if logging is enabled for current level
            if (level >= logLevel_) {
                // Format and store log message
                std::ostringstream oss;
                oss << "[" << getCurrentTime() << "] [" << levelToString(level) << "] " << message;
                messages_.push_back(oss.str());

                // Adjust logging frequency based on current load
                if (messages_.size() > maxMessages_) {
                    adjustLoggingFrequency();
                }
            }
        }

        void logDebug(const std::string& message) {
            logMessage(DEBUG, message);
        }

        void logInfo(const std::string& message) {
            logMessage(INFO, message);
        }

        void logWarning(const std::string& message) {
            logMessage(WARNING, message);
        }

        void logError(const std::string& message) {
            logMessage(ERROR, message);
        }

    private:
        // Load configuration from file
        void loadConfig(const std::string& configFile) {
            // Open configuration file
            std::ifstream ifs(configFile);
            if (!ifs.is_open()) {
                throw std::runtime_error("Failed to open configuration file");
            }

            // Parse configuration parameters
            std::map<std::string, std::string> params;
            for (std::string line; std::getline(ifs, line);) {
                if (line.empty() || line[0] == '#') {
                    continue;
                }
                auto pos = line.find('=');
                if (pos != std::string::npos) {
                    params[line.substr(0, pos)] = line.substr(pos + 1);
                }
            }

            // Set log level
            if (params.count("log_level")) {
                logLevel_ = stringToLevel(params["log_level"]);
            } else {
                logLevel_ = Level::INFO;
            }

            // Set maximum number of messages to store
            if (params.count("max_messages")) {
                maxMessages_ = std::stoi(params["max_messages"]);
            } else {
                maxMessages_ = 1000;
            }
        }

        // Adjust logging frequency based on current load
        void adjustLoggingFrequency() {
            // Calculate current load
            auto load = getCurrentLoad();

            // Adjust logging frequency based on load
            if (load > 0.75) {
                logLevel_ = Level::ERROR;
            } else if (load > 0.5) {
                logLevel_ = Level::WARNING;
            } else if (load > 0.25) {
                logLevel_ = Level::INFO;
            } else {
                logLevel_ = Level::DEBUG;
            }
        }

        // Get current time in ISO format
        std::string getCurrentTime() {
            auto now = std::chrono::system_clock::now();
            return std::put_time(std::localtime(&now), "%F %T");
        }

        // Convert log level to string
        std::string levelToString(Level level) {
            switch (level) {
                case Level::DEBUG: return "DEBUG";
                case Level::INFO: return "INFO";
                case Level::WARNING: return "WARNING";
                case Level::ERROR: return "ERROR";
            }
        }

        // Convert string to log level
        Level stringToLevel(const std::string& str) {
            if (str == "DEBUG") {
                return Level::DEBUG;
            } else if (str == "INFO") {
                return Level::INFO;
            } else if (str == "WARNING") {
                return Level::WARNING;
            } else if (str == "ERROR") {
                return Level::ERROR;
            } else {
                throw std::runtime_error("Invalid log level");
            }
        }

        // Get current load based on number of messages stored
        double getCurrentLoad() {
            return static_cast<double>(messages_.size()) / maxMessages_;
        }

        // Mutex to prevent concurrent access
        std::mutex mutex_;

        // Vector to store log messages
        std::vector<std::string> messages_;

        // Maximum number of messages to store
        size_t maxMessages_;

        // Current log level
        Level logLevel_;
    };
}
```
