BST* bst_init(MemoryPoolManager* pool_manager) {
    // Allocate the root node using the memory pool manager
    Node* root = (Node*)pool_manager->allocate(sizeof(Node));
    assert(root != NULL);

    // Initialize the root node with a null key and no children
    root->key = 0;
    root->parent = NULL;
    root->left = NULL;
    root->right = NULL;

    // Create a new binary search tree structure with the allocated root node
    BST* bst = (BST*)malloc(sizeof(BST));
    assert(bst != NULL);
    bst->root = root;
    bst->pool_manager = pool_manager;

    return bst;
}

// Insert a new node into the binary search tree with a given key
void bst_insert(BST* bst, int key) {
    // Find the parent node for the new node
    Node* parent = NULL;
    Node* current = bst->root;
    while (current != NULL) {
        if (key < current->key) {
            parent = current;
            current = current->left;
        } else if (key > current->key) {
            parent = current;
            current = current->right;
        } else {
            // The key is already present in the tree, do nothing
            return;
        }
    }

    // Allocate a new node using the memory pool manager
    Node* new_node = (Node*)bst->pool_manager->allocate(sizeof(Node));
    assert(new_node != NULL);

    // Initialize the new node with the given key and parent pointer
    new_node->key = key;
    new_node->parent = parent;
    new_node->left = NULL;
    new_node->right = NULL;

    // Update the tree structure to include the new node
    if (parent == NULL) {
        bst->root = new_node;
    } else if (key < parent->key) {
        parent->left = new_node;
    } else {
        parent->right = new_node;
    }
}

// Delete a node from the binary search tree with a given key
void bst_delete(BST* bst, int key) {
    // Find the node to be deleted
    Node* current = bst->root;
    while (current != NULL && current->key != key) {
        if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // If the node is not found, do nothing
    if (current == NULL) {
        return;
    }

    // Update the tree structure to remove the node
    Node* parent = current->parent;
    if (parent == NULL) {
        bst->root = NULL;
    } else if (current == parent->left) {
        parent->left = NULL;
    } else {
        parent->right = NULL;
    }
}

// Traverse the binary search tree in-order, pre-order, and post-order
void bst_traverse(BST* bst, int order) {
    // Define the traversal function for each order
    switch (order) {
        case 0: // In-order traversal
            traverse_in_order(bst->root);
            break;
        case 1: // Pre-order traversal
            traverse_pre_order(bst->root);
            break;
        case 2: // Post-order traversal
            traverse_post_order(bst->root);
            break;
    }
}

// Helper function for in-order traversal
void traverse_in_order(Node* node) {
    if (node == NULL) {
        return;
    }

    // Traverse the left subtree
    traverse_in_order(node->left);

    // Visit the current node
    printf("%d ", node->key);

    // Traverse the right subtree
    traverse_in_order(node->right);
}

// Helper function for pre-order traversal
void traverse_pre_order(Node* node) {
    if (node == NULL) {
        return;
    }

    // Visit the current node
    printf("%d ", node->key);

    // Traverse the left subtree
    traverse_pre_order(node->left);

    // Traverse the right subtree
    traverse_pre_order(node->right);
}

// Helper function for post-order traversal
void traverse_post_order(Node* node) {
    if (node == NULL) {
        return;
    }

    // Traverse the left subtree
    traverse_post_order(node->left);

    // Traverse the right subtree
    traverse_post_order(node->right);

    // Visit the current node
    printf("%d ", node->key);
}

// Report tree statistics, including total number of nodes and height
void bst_report_stats(BST* bst) {
    int num_nodes = 0;
    int height = 0;

    // Count the number of nodes in the tree
    Node* current = bst->root;
    while (current != NULL) {
        num_nodes++;
        if (current->left != NULL || current->right != NULL) {
            height++;
        }
        current = current->left;
    }

    // Print the tree statistics
    printf("Total number of nodes: %d\n", num_nodes);
    printf("Tree height: %d\n", height);
}
