    size_t i = 0;
    while (i < pool->num_mem_blocks && pool->mem_blocks[i].data) {
        ++i;
    }
    if (i == pool->num_mem_blocks) {
        // No available memory block found, allocate a new one
        mem_block *new_block = malloc(pool->block_size);
        if (!new_block) {
            fprintf(stderr, "Failed to allocate memory for the data point\n");
            exit(1);
        }
        pool->mem_blocks[i].data = new_block;
        pool->mem_blocks[i].size = pool->block_size;
    }
    // Set the data pointer and size of the memory block
    mem_block *block = &pool->mem_blocks[i];
    block->data = data;
    block->size = sizeof(data_point);
    // Release the mutex
    pthread_mutex_unlock(&pool->mutex);
    return block;
}

// Deallocate a memory block for the given data point
void dealloc(mem_pool *pool, void *data) {
    // Acquire the mutex to protect concurrent access to the memory pool
    pthread_mutex_lock(&pool->mutex);
    // Find the memory block that contains the data point
    size_t i = 0;
    while (i < pool->num_mem_blocks && pool->mem_blocks[i].data != data) {
        ++i;
    }
    if (i == pool->num_mem_blocks) {
        fprintf(stderr, "Failed to find the memory block for the data point\n");
        exit(1);
    }
    // Set the data pointer and size of the memory block to NULL and 0
    mem_block *block = &pool->mem_blocks[i];
    block->data = NULL;
    block->size = 0;
    // Release the mutex
    pthread_mutex_unlock(&pool->mutex);
}

// Garbage collector that reclaims unused memory blocks and minimizes memory pressure
void gc(mem_pool *pool) {
    // Acquire the mutex to protect concurrent access to the memory pool
    pthread_mutex_lock(&pool->mutex);
    // Iterate over each memory block and check if it is unused
    for (size_t i = 0; i < pool->num_mem_blocks; ++i) {
        mem_block *block = &pool->mem_blocks[i];
        if (!block->data) {
            // Free the memory block
            free(block);
            // Shift all subsequent memory blocks to fill the gap
            for (size_t j = i; j < pool->num_mem_blocks - 1; ++j) {
                memcpy(&pool->mem_blocks[j], &pool->mem_blocks[j + 1], sizeof(mem_block));
            }
            // Decrement the number of memory blocks by 1
            pool->num_mem_blocks--;
        }
    }
    // Release the mutex
    pthread_mutex_unlock(&pool->mutex);
}

// Real-time monitoring system that tracks memory pool performance metrics and adjusts parameters dynamically
void monitor(mem_pool *pool) {
    // Acquire the mutex to protect concurrent access to the memory pool
    pthread_mutex_lock(&pool->mutex);
    // Calculate the allocation rate and deallocation rate for the last second
    size_t allocations = 0;
    size_t deallocations = 0;
    for (size_t i = 0; i < pool->num_mem_blocks; ++i) {
        if (pool->mem_blocks[i].data) {
            allocations++;
        } else {
            deallocations++;
        }
    }
    // Print the allocation and deallocation rates, as well as the memory pressure
    printf("Allocation rate: %lu\n", allocations);
    printf("Deallocation rate: %lu\n", deallocations);
    printf("Memory pressure: %lu\n", pool->num_mem_blocks - allocations + deallocations);
    // Release the mutex
    pthread_mutex_unlock(&pool->mutex);
}
