            if (block == NULL) {
                block = malloc(size);
                manager->blocks = block;
            } else {
                void* start = block->start;
                block->start += size;
                manager->freeMemory -= size;
                return start;
            }
        }

        void deallocate(void* ptr) {
            // Find the block of memory that contains the pointer
            struct Block* block = manager->blocks;
            while (block != NULL && block->start > ptr) {
                block = block->next;
            }

            // If the pointer is not within any allocated block, do nothing
            if (block == NULL || block->end <= ptr) {
                return;
            }

            // Deallocate the block of memory
            void* start = block->start;
            manager->freeMemory += block->end - start;
            block->start = ptr;
        }
    };
}

// Define a function to implement thread safety for the memory pool manager
void synchronizeMemoryPoolManager(struct MemoryPoolManager* manager) {
    // Use appropriate synchronization mechanisms when interacting with the external memory pool manager
    pthread_mutex_t mutex;
    pthread_cond_t cond;

    // Initialize the mutex and condition variable for thread safety
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Define a locking strategy to avoid race conditions and deadlocks
    struct Lock {
        void acquire() {
            pthread_mutex_lock(&mutex);
        }

        void release() {
            pthread_mutex_unlock(&mutex);
        }
    };

    // Use fine-grained locks for specific sections of code to minimize lock contention and ensure thread safety
    struct Lock lock;
}
```
