// Function to read data from file and initialize arrays
void init_data(char* input_file, int seed) {
    // Open the input file
    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }

    // Read the number of records from the file
    int num_records;
    fscanf(fp, "%d", &num_records);

    // Allocate memory for the arrays
    long *offset_array = (long*)malloc(sizeof(long) * num_records);
    int *key_array = (int*)malloc(sizeof(int) * num_records);
    record *record_array = (record*)malloc(sizeof(record) * num_records);

    // Read the data from the file and initialize the arrays
    for (int i = 0; i < num_records; i++) {
        fscanf(fp, "%ld %d %lf %s", &offset_array[i], &key_array[i], &record_array[i].value, record_array[i].name);
    }

    // Close the input file
    fclose(fp);

    // Sort the records based on the keys
    qsort(key_array, num_records, sizeof(int), compare_keys);

    // Shuffle the records using a specified seed for the random number generator
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        int j = rand() % num_records;
        record temp = record_array[i];
        record_array[i] = record_array[j];
        record_array[j] = temp;
    }
}

// Function to compare keys for sorting
int compare_keys(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Main function to demonstrate usage of the init_data function
int main() {
    // Set the input file path and seed for reproducibility
    char* input_file = "input.txt";
    int seed = 42;

    // Initialize the data from the file
    init_data(input_file, seed);

    // Print the sorted and shuffled records
    for (int i = 0; i < num_records; i++) {
        printf("%ld %d %lf %s\n", offset_array[i], key_array[i], record_array[i].value, record_array[i].name);
    }

    return 0;
}
