// Define the structure for a record
typedef struct {
    double value;
    char name[256];
    int age;
} Record;

// Define the function to read and process CSV files
void read_csv(char* filepath, int num_records, int shuffle, unsigned long seed) {
    // Open the file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Allocate memory for the arrays
    long* offset_array = malloc(num_records * sizeof(long));
    int* key_array = malloc(num_records * sizeof(int));
    Record** record_array = malloc(num_records * sizeof(Record*));
    if (offset_array == NULL || key_array == NULL || record_array == NULL) {
        printf("Error: unable to allocate memory for arrays\n");
        fclose(fp);
        return;
    }

    // Read the records from the file
    int i = 0;
    while (i < num_records && fscanf(fp, "%ld,%d,%lf,%255[^,],%d", &offset_array[i], &key_array[i], &record_array[i]->value, record_array[i]->name, &record_array[i]->age) == 5) {
        i++;
    }

    // Close the file
    fclose(fp);

    // Shuffle the records if necessary
    if (shuffle) {
        srand(seed);
        for (int j = 0; j < num_records - 1; j++) {
            int random_index = rand() % (num_records - j) + j;
            long temp_offset = offset_array[j];
            int temp_key = key_array[j];
            Record* temp_record = record_array[j];
            offset_array[j] = offset_array[random_index];
            key_array[j] = key_array[random_index];
            record_array[j] = record_array[random_index];
            offset_array[random_index] = temp_offset;
            key_array[random_index] = temp_key;
            record_array[random_index] = temp_record;
        }
    }

    // Print the records
    for (int i = 0; i < num_records; i++) {
        printf("%ld,%d,%lf,%s,%d\n", offset_array[i], key_array[i], record_array[i]->value, record_array[i]->name, record_array[i]->age);
    }

    // Free the memory for the arrays
    free(offset_array);
    free(key_array);
    for (int i = 0; i < num_records; i++) {
        free(record_array[i]);
    }
    free(record_array);
}

// Define the main function to read and process multiple CSV files
int main(int argc, char* argv[]) {
    // Check if there are enough command-line arguments
    if (argc < 3) {
        printf("Usage: %s [file1] [file2] ... [filen]\n", argv[0]);
        return 1;
    }

    // Parse the command-line arguments
    int num_files = argc - 1;
    int num_records = 0;
    int shuffle = 0;
    unsigned long seed = time(NULL);
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0) {
            shuffle = 1;
        } else if (strcmp(argv[i], "-seed") == 0 && i + 1 < argc) {
            seed = atol(argv[i + 1]);
        } else {
            num_records += read_csv(argv[i], -1, shuffle, seed);
        }
    }

    // Print the total number of records processed
    printf("Total number of records: %d\n", num_records);

    return 0;
}
```
