// Define function to shuffle records using specified seed
void shuffle(const char* input_files[], int num_input_files, long seed) {
    // Allocate memory for data structures
    data_t *data = malloc(sizeof(data_t) * 5);
    metadata_t *metadata = malloc(sizeof(metadata_t) * 5);

    // Initialize data structures with default values
    for (int i = 0; i < 5; i++) {
        data[i].offset = 0;
        data[i].key = 0;
        data[i].record = NULL;
        data[i].metadata = NULL;
    }

    // Read and initialize data structures from JSON files
    for (int i = 0; i < num_input_files; i++) {
        FILE *file = fopen(input_files[i], "r");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        // Read JSON file and initialize data structures
        while (true) {
            char *line = NULL;
            size_t len = 0;
            ssize_t read = getline(&line, &len, file);
            if (read == -1) {
                break;
            }

            // Parse JSON line and initialize data structures
            json_error_t error;
            json_t *root = json_loads(line, 0, &error);
            if (!root) {
                fprintf(stderr, "Error: %s\n", error.text);
                exit(EXIT_FAILURE);
            }

            // Initialize record structure
            data[i].record = malloc(sizeof(record_t));
            data[i].record->value = json_number_value(json_object_get(root, "value"));
            data[i].record->name = strdup(json_string_value(json_object_get(root, "name")));
            data[i].record->age = json_integer_value(json_object_get(root, "age"));

            // Initialize metadata structure
            data[i].metadata = malloc(sizeof(metadata_t));
            data[i].metadata->source = strdup(json_string_value(json_object_get(root, "source")));
            data[i].metadata->timestamp = json_integer_value(json_object_get(root, "timestamp"));
            data[i].metadata->status = json_boolean_value(json_object_get(root, "status"));
        }

        // Close JSON file
        fclose(file);
    }

    // Sort records based on keys
    qsort(data, 5, sizeof(data_t), compare_keys);

    // Shuffle records using specified seed
    srand(seed);
    for (int i = 0; i < 5; i++) {
        int j = rand() % (i + 1);
        data_t temp = data[i];
        data[i] = data[j];
        data[j] = temp;
    }

    // Free memory for metadata structures
    for (int i = 0; i < 5; i++) {
        free(data[i].metadata);
    }

    // Free memory for record structures
    for (int i = 0; i < 5; i++) {
        free(data[i].record->name);
        free(data[i].record);
    }

    // Free memory for data structures
    free(data);
}

