    // Handle potential file I/O errors
    if (errno == EACCES) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Handle potential memory allocation failures
    if (errno == ENOMEM) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }

    // Handle potential synchronization issues when dealing with concurrent access to shared resources
    if (errno == EAGAIN) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
}

