// Define a struct to represent a memory block in the pool
typedef struct mem_block {
    void* data; // Pointer to the actual data
    size_t size; // Size of the data
    data_type_t type; // Type of the data
} mem_block_t;

// Define a struct to represent the memory pool
typedef struct mem_pool {
    mem_block_t* blocks; // Array of memory blocks
    size_t num_blocks; // Number of memory blocks in the pool
    size_t block_size; // Size of each memory block
} mem_pool_t;

// Define a struct to represent a thread-safe allocator
typedef struct allocator {
    pthread_mutex_t mutex; // Mutex for synchronizing access to the pool
    mem_pool_t* pool; // Memory pool to allocate from
} allocator_t;

// Initialize a memory pool with the given number of blocks and block size
void init_mem_pool(mem_pool_t* pool, size_t num_blocks, size_t block_size) {
    pool->num_blocks = num_blocks;
    pool->block_size = block_size;
    pool->blocks = (mem_block_t*)malloc(sizeof(mem_block_t) * num_blocks);
}

// Allocate a memory block from the pool with the given size and type
void* alloc_mem_block(mem_pool_t* pool, size_t size, data_type_t type) {
    // Find the first available block that is large enough to hold the requested size
    for (int i = 0; i < pool->num_blocks; i++) {
        if (pool->blocks[i].size >= size && pool->blocks[i].type == type) {
            // If a suitable block is found, mark it as allocated and return its data pointer
            pool->blocks[i].allocated = true;
            return pool->blocks[i].data;
        }
    }
    // If no suitable block is found, allocate a new one from the system
    mem_block_t* new_block = (mem_block_t*)malloc(sizeof(mem_block_t));
    new_block->size = size;
    new_block->type = type;
    new_block->data = malloc(size);
    pool->blocks[pool->num_blocks++] = *new_block;
    return new_block->data;
}

// Deallocate a memory block from the pool
void dealloc_mem_block(mem_pool_t* pool, void* data) {
    // Find the block that contains the given data pointer and mark it as available
    for (int i = 0; i < pool->num_blocks; i++) {
        if (pool->blocks[i].data == data) {
            pool->blocks[i].allocated = false;
            return;
        }
    }
}

// Initialize a thread-safe allocator with the given memory pool
void init_allocator(allocator_t* allocator, mem_pool_t* pool) {
    pthread_mutex_init(&allocator->mutex, NULL);
    allocator->pool = pool;
}

// Allocate a memory block from the pool with the given size and type
void* alloc(allocator_t* allocator, size_t size, data_type_t type) {
    pthread_mutex_lock(&allocator->mutex);
    void* data = alloc_mem_block(allocator->pool, size, type);
    pthread_mutex_unlock(&allocator->mutex);
    return data;
}

// Deallocate a memory block from the pool
void dealloc(allocator_t* allocator, void* data) {
    pthread_mutex_lock(&allocator->mutex);
    dealloc_mem_block(allocator->pool, data);
    pthread_mutex_unlock(&allocator->mutex);
}
