#include <stdlib.h>
#include <time.h>
#include <stdio.h>
#include <stdbool.h>
#include <math.h>

// Define the entry structure
typedef struct {
    long timestamp;
    int event_id;
    double value;
} entry;

// Function to dynamically allocate memory for an array of entries
entry* create_entries(int num_entries, int min_value, int max_value) {
    // Check if the number of entries is valid
    if (num_entries <= 0) {
        printf("Invalid number of entries: %d\n", num_entries);
        return NULL;
    }

    // Calculate the size of the array in bytes
    int size = sizeof(entry) * num_entries;

    // Allocate memory for the array
    entry* entries = (entry*)malloc(size);
    if (!entries) {
        printf("Failed to allocate memory for %d entries\n", num_entries);
        return NULL;
    }

    // Initialize each entry's timestamp, event ID, and metric value
    int i;
    for (i = 0; i < num_entries; i++) {
        // Get the current system time in milliseconds
        long timestamp = (long)(time(NULL) * 1000);

        // Generate a unique sequential number for the event ID
        int event_id = i + 1;

        // Generate a random floating-point number within the specified range
        double value = (double)rand() / RAND_MAX * (max_value - min_value) + min_value;

        // Initialize the entry's fields
        entries[i].timestamp = timestamp;
        entries[i].event_id = event_id;
        entries[i].value = value;
    }

    return entries;
}

// Function to free memory allocated for an array of entries
void destroy_entries(entry* entries) {
    // Check if the input is valid
    if (!entries) {
        printf("Invalid input: NULL pointer\n");
        return;
    }

    // Free the memory allocated for the array
    free(entries);
}
