void optimize_memory(struct record* records, size_t num_keys) {
    // Validate input
    if (!records || num_keys == 0) {
        printf("Invalid input: records or number of keys is null\n");
        return;
    }

    // Initialize caching mechanism with last accessed memory block
    struct record* last_accessed = NULL;

    // Iterate over each record and check if it has been accessed recently
    for (size_t i = 0; i < num_keys; i++) {
        struct record* record = &records[i];
        if (record == last_accessed) {
            // Record has been accessed recently, use it preferentially for new allocations
            void* block = malloc(sizeof(struct record));
            if (!block) {
