            manager_register_block(block, sizeof(struct record));
        } else {
            // Record has not been accessed recently, mark it as last accessed and use it preferentially for new allocations
            last_accessed = record;
            void* block = malloc(sizeof(struct record));
            if (!block) {
                printf("Memory allocation failure: unable to allocate memory for record %zu\n", i);
                continue;
            }
            manager_register_block(block, sizeof(struct record));
