        printf("Invalid input: records or number of keys is null\n");
        return;
    }

    // Initialize memory usage statistics
    size_t total_allocated = 0;
    size_t free_memory = 0;
    size_t pool_utilization = 0;

    // Iterate over each record and update memory usage statistics
    for (size_t i = 0; i < num_keys; i++) {
        struct record* record = &records[i];
        void* block = malloc(sizeof(struct record));
        if (!block) {
            printf("Memory allocation failure: unable to allocate memory for record %zu\n", i);
            continue;
        }
        total_allocated += sizeof(struct record);
        free_memory += manager_get_free_memory();
        pool_utilization = manager_get_pool_utilization();
    }

    // Print memory usage statistics
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Free memory: %zu\n", free_memory);
    printf("Memory pool utilization: %zu\n", pool_utilization);
}
