// Define the Entry struct
typedef struct {
    double value;
    char identifier[10];
} Entry;

// Define a linked list node for storing entries
typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

// Function to allocate memory for the data structure
Node* create_list() {
    // Allocate memory for the head node
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) {
        printf("Error: Failed to allocate memory for list\n");
        return NULL;
    }

    // Initialize the head node
    head->next = NULL;

    return head;
}

// Function to add a new entry to the list
void add_entry(Node* head, double value, char* identifier) {
    // Allocate memory for the new entry
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new entry\n");
        return;
    }

    // Initialize the new entry with the given value and identifier
    new_node->entry.value = value;
    strcpy(new_node->entry.identifier, identifier);

    // Add the new node to the end of the list
    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
}

// Function to iterate over the entries in the list
void iterate_entries(Node* head) {
    // Iterate over the nodes in the list
    Node* current = head;
    while (current != NULL) {
        printf("Entry: %f, %s\n", current->entry.value, current->entry.identifier);
        current = current->next;
    }
}

// Function to free the memory allocated for the data structure
void destroy_list(Node* head) {
    // Free the nodes in the list
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    // Create a linked list of entries
    Node* head = create_list();

    // Add some entries to the list
    add_entry(head, 1.0, "A");
    add_entry(head, 2.0, "B");
    add_entry(head, 3.0, "C");

    // Iterate over the entries in the list
    iterate_entries(head);

    // Free the memory allocated for the data structure
    destroy_list(head);

    return 0;
}
