        $stmt->execute($user);

        // Send notification to external service
        if (isset($_REQUEST['external_service_token'])) {
            sendNotificationToExternalService('user-updated', $_REQUEST['external_service_token'], $user);
        }
    }

    // Handle delete action
    elseif ($_REQUEST['action'] === 'delete') {
        // Check if sub_action is provided
        if (!isset($_REQUEST['sub_action'])) {
            throw new Exception('Sub-action is required');
        }

        // Validate sub-action format
        if (!in_array($_REQUEST['sub_action'], ['soft', 'hard'])) {
            throw new Exception('Invalid sub-action format');
        }

        // Check if user exists
        $stmt = $db->prepare('SELECT * FROM users WHERE id = :id');
        $stmt->execute([':id' => $_REQUEST['id']]);
        $user = $stmt->fetch();
        if (!$user) {
            throw new Exception('User not found');
        }

        // Perform soft delete or hard delete
        if ($_REQUEST['sub_action'] === 'soft') {
            $user['deleted_at'] = date('Y-m-d H:i:s');
            $stmt = $db->prepare('UPDATE users SET deleted_at = :deleted_at WHERE id = :id');
            $stmt->execute($user);
        } else {
            $stmt = $db->prepare('DELETE FROM users WHERE id = :id');
            $stmt->execute([':id' => $_REQUEST['id']]);
        }

        // Send notification to external service
        if (isset($_REQUEST['external_service_token'])) {
            sendNotificationToExternalService('user-deleted', $_REQUEST['external_service_token'], $user);
        }
    }

    // Handle bulk delete action
