        // Check if user_ids is provided
        if (!isset($_REQUEST['user_ids'])) {
            throw new Exception('User IDs are required');
        }

        // Validate user_ids format
        if (!preg_match('/^[0-9,]+$/', $_REQUEST['user_ids'])) {
            throw new Exception('Invalid user IDs format');
        }

        // Check if rate limit is exceeded
        $stmt = $db->prepare('SELECT COUNT(*) FROM users WHERE id IN (:user_ids)');
        $stmt->execute([':user_ids' => $_REQUEST['user_ids']]);
        $count = $stmt->fetchColumn();
        if ($count > 100) {
            throw new Exception('Rate limit exceeded');
        }

        // Delete users in bulk
        $stmt = $db->prepare('DELETE FROM users WHERE id IN (:user_ids)');
        $stmt->execute([':user_ids' => $_REQUEST['user_ids']]);

        // Send notification to external service
        if (isset($_REQUEST['external_service_token'])) {
            sendNotificationToExternalService('users-deleted', $_REQUEST['external_service_token'], $user);
        }
    }
}

