#include <dlfcn.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>

// Define the configuration file path as a global variable
const char* config_file_path = "/path/to/config/file";

// Define the cryptographic primitives to be loaded from the library
typedef struct {
    const char* name;
    void* (*init)();
} primitive_t;

primitive_t primitives[] = {
    {"aes", AES_init},
    {"camellia", Camellia_init},
    {"md5", MD5_init},
    {"sha256", SHA256_init},
    {"rsa", RSA_init}
};

// Define the number of primitives to be loaded from the library
#define NUM_PRIMITIVES (sizeof(primitives) / sizeof(primitive_t))

// Define the mocking library for testing purposes
void* blueslip = NULL;

// Function to initialize and test the cryptographic library
int initialize_and_test_crypto_library() {
    // Load the configuration file from disk
    FILE* config_file = fopen(config_file_path, "r");
    if (config_file == NULL) {
        printf("Error: unable to open configuration file\n");
        return -1;
    }

    // Read the configuration file and extract the list of primitives to be loaded
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, config_file)) != -1) {
        // Trim whitespace from the end of the line
        int i = strlen(line) - 1;
        while (i >= 0 && isspace(line[i])) {
            line[i] = '\0';
            --i;
        }

        // Check if the line contains a valid primitive name
        for (int j = 0; j < NUM_PRIMITIVES; ++j) {
            if (strcmp(line, primitives[j].name) == 0) {
                // Initialize and test the primitive
                void* handle = dlopen(primitives[j].name, RTLD_LAZY);
                if (handle == NULL) {
                    printf("Error: unable to load %s\n", primitives[j].name);
                    return -1;
                }
                void* (*init)() = dlsym(handle, "init");
                if (init == NULL) {
                    printf("Error: unable to find init function for %s\n", primitives[j].name);
                    return -1;
                }
                void* result = init();
                if (result == NULL) {
                    printf("Error: unable to initialize %s\n", primitives[j].name);
                    return -1;
                }
                break;
            }
        }
    }

    // Close the configuration file
    fclose(config_file);

    // Test the loaded primitives
    for (int i = 0; i < NUM_PRIMITIVES; ++i) {
        void* handle = dlopen(primitives[i].name, RTLD_LAZY);
        if (handle == NULL) {
            printf("Error: unable to load %s\n", primitives[i].name);
            return -1;
        }
        void* (*test)() = dlsym(handle, "test");
        if (test == NULL) {
            printf("Error: unable to find test function for %s\n", primitives[i].name);
            return -1;
        }
        void* result = test();
        if (result == NULL) {
            printf("Error: unable to test %s\n", primitives[i].name);
            return -1;
        }
    }

    // Reset the mocking library for testing purposes
    blueslip = dlopen("blueslip", RTLD_LAZY);
    if (blueslip == NULL) {
        printf("Error: unable to load blueslip\n");
        return -1;
    }

    // Return success
    return 0;
}
```
This code defines a function `initialize_and_test_crypto_library` that dynamically loads a set of cryptographic primitives from an OpenSSL library, based on the configuration file specified by the global variable `config_file_path`. The function first reads the configuration file and extracts the list of primitives to be loaded. It then initializes and tests each primitive using the `dlopen` and `dlsym` functions from the `dlfcn.h` header, which are used to dynamically load shared libraries at runtime.

The function also defines a mocking library called `blueslip`, which is used for testing purposes only. The `blueslip` library is loaded using the `dlopen` function and its `test` function is called to test the loaded primitives. If any of the tests fail, the function returns an error code.

