#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a struct to represent a record in the collection
typedef struct {
    int value;
} Record;

// Define a struct to represent the dynamic collection of records
typedef struct {
    Record* records; // Pointer to an array of Records
    size_t capacity; // Maximum number of records allowed in the collection
    size_t count; // Current number of records in the collection
} Collection;

// Function to create a new empty collection with the specified capacity
Collection* create_collection(size_t capacity) {
    assert(capacity > 0);
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) {
        return NULL;
    }
    collection->records = malloc(capacity * sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    return collection;
}

// Function to insert a new record into the collection
int insert_record(Collection* collection, int value) {
    assert(collection != NULL);
    if (collection->count == collection->capacity) {
        // Collection is full, cannot insert any more records
        return -1;
    }
    collection->records[collection->count].value = value;
    collection->count++;
    return 0;
}

// Function to retrieve a record from the collection by its index
int get_record(Collection* collection, size_t index) {
    assert(collection != NULL);
    if (index >= collection->count) {
        // Index is out of bounds, cannot retrieve any records
        return -1;
    }
    return collection->records[index].value;
}

// Function to delete a record from the collection by its index
int delete_record(Collection* collection, size_t index) {
    assert(collection != NULL);
    if (index >= collection->count) {
        // Index is out of bounds, cannot delete any records
        return -1;
    }
    for (size_t i = index; i < collection->count - 1; i++) {
        collection->records[i] = collection->records[i + 1];
    }
    collection->count--;
    return 0;
}

// Function to destroy the collection and free its resources
void destroy_collection(Collection* collection) {
    assert(collection != NULL);
    free(collection->records);
    free(collection);
}

int main() {
    // Create a new collection with capacity for 10 records
    Collection* collection = create_collection(10);
    if (!collection) {
        printf("Failed to create collection\n");
        return -1;
    }

    // Insert some records into the collection
    insert_record(collection, 1);
    insert_record(collection, 2);
    insert_record(collection, 3);

    // Retrieve a record from the collection by its index
    int value = get_record(collection, 0);
    printf("Retrieved value: %d\n", value);

    // Delete a record from the collection by its index
    delete_record(collection, 1);

    // Destroy the collection and free its resources
    destroy_collection(collection);

    return 0;
}
```
