void init_distributed_storage_layer(StorageLayer* layer, int initial_capacity) {
    // Allocate memory for the storage layer on each node
    layer->records = (Record*)malloc(sizeof(Record) * initial_capacity);
    layer->pointers = (void**)malloc(sizeof(void*) * initial_capacity);
    layer->size = 0;
    layer->capacity = initial_capacity;
}

void add_record_distributed(StorageLayer* layer, int key, long offset) {
    // Check if the storage layer needs to be resized on each node
    if (layer->size == layer->capacity) {
        // Resize the storage layer by a factor of 2 on each node
        layer->capacity *= 2;
        layer->records = (Record*)realloc(layer->records, sizeof(Record) * layer->capacity);
        layer->pointers = (void**)realloc(layer->pointers, sizeof(void*) * layer->capacity);
    }

    // Add the new record to the storage layer on each node
    layer->records[layer->size].key = key;
    layer->records[layer->size].offset = offset;
    layer->pointers[layer->size] = &(layer->records[layer->size]);
    layer->size++;
}

void remove_record_distributed(StorageLayer* layer, int index) {
    // Check if the storage layer needs to be resized on each node
    if (layer->size == 0) {
        return;
    }

    // Remove the record from the storage layer on each node
    Record temp = layer->records[index];
    void* pointer = layer->pointers[index];
    layer->records[index] = layer->records[layer->size - 1];
    layer->pointers[index] = layer->pointers[layer->size - 1];
    layer->size--;

    // Free the memory used by the removed record on each node
    free(pointer);
}

void update_record_distributed(StorageLayer* layer, int index, long offset) {
    // Update the offset value of the specified record on each node
    layer->records[index].offset = offset;
}

// Define the function for verifying the integrity of the allocated memory and initialized values
void verify_storage_layer(StorageLayer* layer) {
    // Check if the storage layer is properly initialized
