// Define the maximum number of records allowed in the collection
#define MAX_RECORDS 10000

// Define the data structure to hold the records
struct Record {
    int value;
};

// Define a linked list node to store the records
struct Node {
    struct Record record;
    struct Node* next;
};

// Define the head and tail pointers of the linked list
struct Node* head = NULL;
struct Node* tail = NULL;

// Define the number of operations (insertions, deletions, retrievals)
int num_operations = 0;

// Define the mutex for thread-safe access to the data structure
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to insert a record into the collection
void insert(int value) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if the maximum number of records has been reached
    if (head == NULL || tail->next == NULL) {
        // Allocate a new node for the record
        struct Node* new_node = malloc(sizeof(struct Node));
        new_node->record.value = value;
        new_node->next = NULL;

        // If the head is null, set it to the new node
        if (head == NULL) {
            head = new_node;
        } else {
            tail->next = new_node;
        }

        // Set the new node as the tail
        tail = new_node;
    } else {
        // If the maximum number of records has not been reached, insert the record at the end of the linked list
        struct Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }

        // Allocate a new node for the record
        struct Node* new_node = malloc(sizeof(struct Node));
        new_node->record.value = value;
        new_node->next = NULL;

        // Set the next pointer of the last node to the new node
        current->next = new_node;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Define a function to retrieve a record from the collection
int retrieve(int index) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if the index is within the bounds of the linked list
    if (index < 0 || index >= num_operations) {
        return -1;
    }

    // Initialize a variable to keep track of the current node
    struct Node* current = head;

    // Iterate through the linked list until the desired node is reached
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Return the value of the record at the desired node
    int value = current->record.value;

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);

    return value;
}

// Define a function to delete a record from the collection
void delete(int index) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if the index is within the bounds of the linked list
    if (index < 0 || index >= num_operations) {
        return;
    }

    // Initialize a variable to keep track of the current node
    struct Node* current = head;

    // Iterate through the linked list until the desired node is reached
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Set the next pointer of the previous node to the next node
    current->prev->next = current->next;

    // Free the memory allocated to the deleted node
    free(current);

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Define a function to track the number of operations and provide statistical information about their frequency and duration
void track_operations() {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Increment the number of operations
    num_operations++;

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Define a function to serialize the collection and deserialize it upon restart or failure
void serialize() {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Allocate memory for the serialized data
    char* serialized = malloc(sizeof(struct Node) * num_operations);

    // Initialize a variable to keep track of the current node
    struct Node* current = head;

    // Iterate through the linked list and serialize each record
    for (int i = 0; i < num_operations; i++) {
        serialized[i] = current->record.value;
        current = current->next;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

void deserialize() {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Allocate memory for the deserialized data
    struct Node* current = head;

    // Iterate through the linked list and deserialize each record
    for (int i = 0; i < num_operations; i++) {
        current->record.value = serialized[i];
        current = current->next;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}
