    if (pool_manager != NULL) {
        for (int i = 0; i < pool_manager->num_pools; i++) {
            free(pool_manager->pools[i]);
        }
        free(pool_manager->pool_sizes);
        free(pool_manager->pools);
        pthread_mutex_destroy(&pool_manager->mutex);
        free(pool_manager);
    }
