    pthread_mutex_lock(&pool_manager->mutex);
    void *ptr = NULL;
    for (int i = 0; i < pool_manager->num_pools; i++) {
        if (pool_manager->pool_sizes[i] >= size) {
            ptr = pool_manager->pools[i];
            pool_manager->pool_sizes[i] -= size;
            break;
        }
    }
    pthread_mutex_unlock(&pool_manager->mutex);
    return ptr;
}

// Function to deallocate memory from the memory pool manager
void deallocate_memory(MemoryPoolManager *pool_manager, void *ptr) {
    pthread_mutex_lock(&pool_manager->mutex);
    for (int i = 0; i < pool_manager->num_pools; i++) {
        if (pool_manager->pools[i] == ptr) {
            pool_manager->pool_sizes[i] += size;
            break;
        }
    }
    pthread_mutex_unlock(&pool_manager->mutex);
}

// Function to cache a memory block
void cache_memory(Cache *cache, void *ptr) {
    if (cache->size >= MAX_CACHE_SIZE) {
        return;
    }
    Record *record = (Record *)malloc(sizeof(Record));
    record->key = ptr;
    record->offset = -1;
    cache->records[cache->size++] = record;
