class MemoryPoolManager {
public:
    // Constructor
    MemoryPoolManager(size_t size) : size_(size), used_(0) {}

    // Allocate memory from the pool
    void* allocate(size_t size) {
        if (used_ + size > size_) {
            return nullptr;
        }
        void* ptr = &pool_[used_];
        used_ += size;
        return ptr;
    }

    // Deallocate memory from the pool
    void deallocate(void* ptr) {
        if (ptr < &pool_[0] || ptr >= &pool_[size_]) {
            return;
        }
        used_ -= (ptr - &pool_[0]);
    }

