        for (size_t i = 0; i < used_; i++) {
            if (records_[i].key == key) {
                records_[i] = records_[used_ - 1];
                used_--;
                return;
            }
        }
    }

    // Get a record from the structure
    Record* getRecord(int key) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < used_; i++) {
            if (records_[i].key == key) {
                return &records_[i];
            }
        }
        return nullptr;
