    MemoryUsageStatistics(size_t size) : size_(size), used_(0) {}

    // Update memory usage statistics
    void update() {
        std::lock_guard<std::mutex> lock(mutex_);
        used_ = 0;
        for (auto& record : records_) {
            if (record.second != nullptr) {
                used_ += record.first;
            }
        }
    }

    // Get total allocated memory
    size_t getTotalAllocatedMemory() {
        std::lock_guard<std::mutex> lock(mutex_);
        return used_;
    }

    // Get free memory
    size_t getFreeMemory() {
        std::lock_guard<std::mutex> lock(mutex_);
        return size_ - used_;
    }

    // Get pool utilization
    double getPoolUtilization() {
        std::lock_guard<std::mutex> lock(mutex_);
        return (double)used_ / size_;
    }

private:
