    void start() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (thread_.joinable()) {
            return;
        }
        thread_ = std::thread([this]() { this->run(); });
    }

    // Stop the background service
    void stop() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!thread_.joinable()) {
            return;
        }
        thread_.detach();
    }

