// Custom memory pool manager
struct MemoryPool {
    size_t capacity;
    void* data;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->data = malloc(pool->capacity);
}

void destroyMemoryPool(struct MemoryPool* pool) {
    free(pool->data);
}

void* allocate(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity) {
        return NULL;
    }
    void* data = pool->data;
    pool->data += size;
    pool->capacity -= size;
    return data;
}

void deallocate(struct MemoryPool* pool, void* data, size_t size) {
    if (size > pool->capacity) {
        return;
    }
    memcpy(data, pool->data, size);
    pool->data += size;
    pool->capacity -= size;
}

