void initMemory(int numFloats, int numDoubles, int numStrings) {
    // Allocate memory for the arrays
    float *fArray = (float *)malloc(numFloats * sizeof(float));
    double *dArray = (double *)malloc(numDoubles * sizeof(double));
    char **sArray = (char **)malloc(numStrings * sizeof(char *));

    // Initialize the arrays with random values within a specified range
    for (int i = 0; i < numFloats; i++) {
        fArray[i] = (float)(rand() % 100);
    }
    for (int i = 0; i < numDoubles; i++) {
        dArray[i] = (double)(rand() % 100);
    }
    for (int i = 0; i < numStrings; i++) {
        sArray[i] = (char *)malloc(10 * sizeof(char));
        for (int j = 0; j < 10; j++) {
            sArray[i][j] = 'a' + (rand() % 26);
        }
    }

    // Register the allocated memory with an external memory pool manager
    // to optimize memory usage and minimize fragmentation
    registerMemory(fArray, numFloats * sizeof(float));
    registerMemory(dArray, numDoubles * sizeof(double));
    for (int i = 0; i < numStrings; i++) {
        registerMemory(sArray[i], 10 * sizeof(char));
    }
}

