#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a structure for sensor data
typedef struct {
    float temperature;
    char location[10];
} SensorData;

// Function to dynamically allocate memory for arrays and initialize them
void initArrays(int numSensors, int *temperatureArray, char **locationArray) {
    // Allocate memory for the temperature array
    *temperatureArray = (float *)malloc(numSensors * sizeof(float));
    if (*temperatureArray == NULL) {
        printf("Error: Failed to allocate memory for temperature array\n");
        return;
    }

    // Allocate memory for the location array
    *locationArray = (char **)malloc(numSensors * sizeof(char));
    if (*locationArray == NULL) {
        printf("Error: Failed to allocate memory for location array\n");
        free(*temperatureArray);
        return;
    }

    // Initialize the temperature and location arrays
    for (int i = 0; i < numSensors; i++) {
        (*temperatureArray)[i] = 0.0f;
        strcpy((*locationArray)[i], "");
    }
}

// Function to create an array of sensor structures and populate them with random temperature readings
void initSensorData(int numSensors, SensorData *sensorData) {
    // Allocate memory for the sensor data array
    *sensorData = (SensorData *)malloc(numSensors * sizeof(SensorData));
    if (*sensorData == NULL) {
        printf("Error: Failed to allocate memory for sensor data\n");
        return;
    }

    // Populate the temperature and location fields of each sensor structure with random values
    srand(time(NULL));
    for (int i = 0; i < numSensors; i++) {
        (*sensorData)[i].temperature = rand() % 100 + 20.0f;
        strcpy((*locationArray)[i], "Location ");
        strcat((*locationArray)[i], (rand() % 5) + 1);
    }
}

// Function to integrate with an external memory pool manager and register allocated memory blocks
void registerMemoryPool(int numSensors, SensorData *sensorData) {
