// Function to generate a random integer within the specified range
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to allocate and initialize an array of records
record_t* allocate_records(int n) {
    record_t* records = malloc(n * sizeof(record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for %d records\n", n);
        return NULL;
    }

    // Initialize the array of records with random values
    for (int i = 0; i < n; i++) {
        records[i].key = rand_range(0, MAX_KEY);
        records[i].offset = rand_range(0, MAX_OFFSET);
        records[i].value = rand_range(MIN_VALUE, MAX_VALUE);
    }

    return records;
}

// Function to allocate and initialize an array of keys
int* allocate_keys(int m) {
    int* keys = malloc(m * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for %d keys\n", m);
        return NULL;
    }

    // Initialize the array of keys with unique values
    for (int i = 0; i < m; i++) {
        keys[i] = rand_range(0, MAX_KEY);
    }

    return keys;
}

// Function to allocate and initialize a hash table for unique keys
record_t* allocate_key_hash(int m) {
    record_t* key_hash = malloc(m * sizeof(record_t));
    if (!key_hash) {
        printf("Error: Failed to allocate memory for %d key hash entries\n", m);
        return NULL;
    }

    // Initialize the hash table with empty slots
    for (int i = 0; i < m; i++) {
        key_hash[i].key = -1;
    }

    return key_hash;
}

// Function to check if a key is already in the hash table
int key_exists(record_t* key_hash, int key) {
    for (int i = 0; i < m; i++) {
        if (key_hash[i].key == key) {
            return 1;
        }
    }
    return 0;
}

// Function to add a new key to the hash table
void add_key(record_t* key_hash, int key) {
    for (int i = 0; i < m; i++) {
        if (key_hash[i].key == -1) {
            key_hash[i].key = key;
            return;
        }
    }
}

// Function to allocate and initialize a pool of records
record_t* allocate_pool(int p) {
    record_t* pool = malloc(p * sizeof(record_t));
    if (!pool) {
        printf("Error: Failed to allocate memory for %d records in the pool\n", p);
        return NULL;
    }

    // Initialize the pool of records with random values
    for (int i = 0; i < p; i++) {
        pool[i].key = rand_range(0, MAX_KEY);
        pool[i].offset = rand_range(0, MAX_OFFSET);
        pool[i].value = rand_range(MIN_VALUE, MAX_VALUE);
    }

    return pool;
}

// Function to allocate and initialize a record from the pool
record_t* allocate_record(record_t* pool) {
    for (int i = 0; i < p; i++) {
        if (pool[i].key == -1) {
            return &pool[i];
        }
    }
    return NULL;
}

// Function to free all allocated memory
void free_memory() {
    free(records);
    free(keys);
    free(key_hash);
    free(pool);
}

