    records = allocate_records(N);
    keys = allocate_keys(M);
    key_hash = allocate_key_hash(M);
    pool = allocate_pool(P);

    // Initialize the record array with random values
    for (int i = 0; i < N; i++) {
        records[i].key = rand_range(0, MAX_KEY);
        records[i].offset = rand_range(0, MAX_OFFSET);
        records[i].value = rand_range(MIN_VALUE, MAX_VALUE);
    }

    // Initialize the key array with unique values
    for (int i = 0; i < M; i++) {
        keys[i] = rand_range(0, MAX_KEY);
    }

    // Initialize the hash table with empty slots
    for (int i = 0; i < M; i++) {
        key_hash[i].key = -1;
    }

    // Allocate and initialize a record from the pool
    record_t* new_record = allocate_record(pool);
    if (!new_record) {
        printf("Error: Failed to allocate memory for a new record\n");
        return 1;
    }

    // Add the new record to the hash table
    add_key(key_hash, new_record->key);

    // Free all allocated memory upon completion
    free_memory();

    return 0;
}
