// Function to perform DNS resolution for a given hostname using the standard library functions
int resolve_hostname(const char *hostname, u_char **ip) {
    struct addrinfo hints, *res;
    int status;

    // Initialize the addrinfo structure
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4 only for now
    hints.ai_socktype = SOCK_STREAM;

    // Perform DNS resolution using the standard library functions
    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(status));
        return FAILURE;
    }

    // Allocate memory for the IP address
    *ip = malloc(sizeof(u_char) * 4);
    if (*ip == NULL) {
        freeaddrinfo(res);
        return OUT_OF_MEMORY;
    }

    // Copy the IP address to the output parameter
    memcpy(*ip, res->ai_addr, sizeof(u_char) * 4);

