// Define the record structure
typedef struct {
    int key;
    long offset;
    int value;
} record_t;

// Define the hash table for storing records
static record_t *records = NULL;
static size_t num_records = 0;
static size_t max_records = 0;

// Define the pool allocation strategy
#define POOL_SIZE (1 << 20) // 1 MB
static char *pool = NULL;
static size_t pool_size = 0;
static size_t pool_used = 0;

// Define the maximum offset and key values
#define MAX_OFFSET (1 << 30) - 1
#define MAX_KEY (1 << 24) - 1

// Define the minimum and maximum values for the random integer
#define MIN_VALUE 0
#define MAX_VALUE 100

// Define the cache size and eviction policy
#define CACHE_SIZE (1 << 16) // 64 KB
#define EVICTION_POLICY "LRU"

// Define the locking strategy for multi-threaded applications
#define LOCKING_STRATEGY "Spinlock"

// Initialize the pool allocation strategy
static void init_pool() {
    pool = malloc(POOL_SIZE);
    if (pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for pool\n");
        exit(1);
    }
    pool_size = POOL_SIZE;
}

// Allocate a record from the pool
static record_t *alloc_record() {
    // Check if the pool is full
    if (pool_used == pool_size) {
        fprintf(stderr, "Pool is full\n");
        exit(1);
    }

    // Allocate a record from the pool
    record_t *record = (record_t *)pool + pool_used;
    pool_used += sizeof(record_t);

    return record;
}

// Initialize a record with a random key and offset
static void init_record(record_t *record) {
    // Generate a random key between 0 and MAX_KEY
    record->key = rand() % (MAX_KEY + 1);

    // Generate a random offset between 0 and MAX_OFFSET
    record->offset = rand() % (MAX_OFFSET + 1);

    // Initialize the value to a random integer within the specified range
