<?php

function updatePatientDemographics($patientId, $newDemographics) {
    // Check if patient ID is valid
    if (!isValidPatientId($patientId)) {
        return "Invalid patient ID";
    }

    // Get current demographics for the patient
    $currentDemographics = getCurrentDemographics($patientId);

    // Check if any critical fields have changed
    $criticalFieldsChanged = checkCriticalFieldsChanged($newDemographics, $currentDemographics);

    // Update patient demographics in the database
    try {
        updatePatientDemographicsInDatabase($patientId, $newDemographics);
    } catch (Exception $e) {
        return "Error updating patient demographics: " . $e->getMessage();
    }

    // Update billing system with new demographics
    try {
        updateBillingSystem($patientId, $newDemographics);
    } catch (Exception $e) {
        return "Error updating billing system: " . $e->getMessage();
    }

    // Update insurance verification API with new demographics
    try {
        updateInsuranceVerificationApi($patientId, $newDemographics);
    } catch (Exception $e) {
        return "Error updating insurance verification API: " . $e->getMessage();
    }

    // Log update operation and any potential issues encountered
    logUpdateOperation($patientId, $criticalFieldsChanged);

    // Return success message with any potential issues encountered
    if ($criticalFieldsChanged) {
        return "Critical fields changed. Please review and confirm changes.";
    } else {
        return "Patient demographics updated successfully";
    }
}

function isValidPatientId($patientId) {
    // Check if patient ID exists in the database
    $query = "SELECT COUNT(*) FROM patients WHERE id = ?";
    $result = executeQuery($query, [$patientId]);
    return $result[0]["COUNT(*)"] > 0;
}

function getCurrentDemographics($patientId) {
    // Get current demographics for the patient from the database
    $query = "SELECT * FROM patients WHERE id = ?";
    $result = executeQuery($query, [$patientId]);
    return $result[0];
}

function checkCriticalFieldsChanged($newDemographics, $currentDemographics) {
    // Check if any critical fields have changed
    foreach ($criticalFields as $field) {
        if ($newDemographics[$field] != $currentDemographics[$field]) {
            return true;
        }
    }
    return false;
}

function updatePatientDemographicsInDatabase($patientId, $newDemographics) {
    // Update patient demographics in the database
    $query = "UPDATE patients SET first_name = ?, last_name = ?, birthdate = ? WHERE id = ?";
    executeQuery($query, [$newDemographics["first_name"], $newDemographics["last_name"], $newDemographics["birthdate"], $patientId]);
}

function updateBillingSystem($patientId, $newDemographics) {
    // Update billing system with new demographics
    $query = "UPDATE billing SET first_name = ?, last_name = ?, birthdate = ? WHERE patient_id = ?";
    executeQuery($query, [$newDemographics["first_name"], $newDemographics["last_name"], $newDemographics["birthdate"], $patientId]);
}

function updateInsuranceVerificationApi($patientId, $newDemographics) {
    // Update insurance verification API with new demographics
    $query = "UPDATE insurance_verification SET first_name = ?, last_name = ?, birthdate = ? WHERE patient_id = ?";
    executeQuery($query, [$newDemographics["first_name"], $newDemographics["last_name"], $newDemographics["birthdate"], $patientId]);
}

function logUpdateOperation($patientId, $criticalFieldsChanged) {
    // Log update operation and any potential issues encountered
    $logEntry = [
        "timestamp" => date("Y-m-d H:i:s"),
        "patient_id" => $patientId,
        "critical_fields_changed" => $criticalFieldsChanged,
        "error_message" => ""
    ];
    insertLogEntry($logEntry);
}

function executeQuery($query, $params) {
    // Execute query with parameters and return result
    try {
        $result = $db->prepare($query)->execute($params);
        return $result;
    } catch (Exception $e) {
        throw new Exception("Error executing query: " . $e->getMessage());
    }
}

function insertLogEntry($logEntry) {
    // Insert log entry into database
    try {
        $db->prepare("INSERT INTO logs (timestamp, patient_id, critical_fields_changed, error_message) VALUES (?, ?, ?, ?)")
            ->execute([$logEntry["timestamp"], $logEntry["patient_id"], $logEntry["critical_fields_changed"], $logEntry["error_message"]]);
    } catch (Exception $e) {
        throw new Exception("Error inserting log entry: " . $e->getMessage());
    }
}
