    init_memory_pool(&double_pool, 512);
    struct memory_pool string_pool;
    init_memory_pool(&string_pool, 256);

    // Allocate memory for the data arrays
    float *floats = malloc(sizeof(float) * 1024);
    double *doubles = malloc(sizeof(double) * 512);
