    }
    for (int i = 0; i < 256; i++) {
        strings[i] = malloc(sizeof(char) * 32);
        memset(strings[i], 0, sizeof(char) * 32);
    }

    // Register the memory blocks with the memory pool manager
    register_memory_block(&float_pool, floats);
    register_memory_block(&double_pool, doubles);
    for (int i = 0; i < 256; i++) {
        register_memory_block(&string_pool, strings[i]);
