// Function to provide a mechanism to report the current memory usage statistics, including total allocated memory, free memory, and memory pool utilization
void reportMemoryUsage() {
    // Calculate the total allocated memory and free memory using the memory pool manager
    int totalAllocatedMemory = 0;
    int freeMemory = 0;
    for (int i = 0; i < numItems; i++) {
        if (manager->blocks[i] != NULL) {
            totalAllocatedMemory += sizeof(Record);
        } else {
            freeMemory += sizeof(Record);
        }
    }

    // Calculate the memory pool utilization using the number of allocated blocks and the maximum number of blocks in the pool
    int memoryPoolUtilization = (manager->numBlocks / MAX_BLOCKS) * 100;

    // Print the memory usage statistics to standard output
    printf("Total allocated memory: %d bytes\n", totalAllocatedMemory);
    printf("Free memory: %d bytes\n", freeMemory);
    printf("Memory pool utilization: %d%%\n", memoryPoolUtilization);
}

// Function to clear all allocated resources and reset the memory pool, allowing subsequent calls to reuse the memory effectively
void clearResources() {
    // Release each allocated block of memory using the memory pool manager
