#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define a struct for a node in the linked list
struct node {
    int value;
    char character;
    struct node* next;
};

// Define a custom memory pool for managing the linked lists
struct memory_pool {
    size_t size; // Size of the memory pool
    void* data; // Pointer to the start of the memory pool
    pthread_mutex_t mutex; // Mutex for synchronizing access to the memory pool
};

// Define a function to allocate memory from the custom memory pool
void* alloc(struct memory_pool* pool, size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&pool->mutex);
    if (size <= pool->size) {
        ptr = pool->data;
        pool->data += size;
        pool->size -= size;
    }
    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

// Define a function to free memory from the custom memory pool
void free(struct memory_pool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);
    pool->data -= size;
    pool->size += size;
    pthread_mutex_unlock(&pool->mutex);
}

// Define a function to insert nodes into the linked list
void insert(struct node** head, int lower_bound, int upper_bound) {
    struct node* new_node = NULL;
    pthread_mutex_lock(&head->mutex);
    // Generate a random integer within the specified range
    int value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    // Allocate memory for the new node
    new_node = alloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }
    // Initialize the new node with the random integer and a character
    new_node->value = value;
    new_node->character = 'a' + (rand() % 26);
    // Insert the new node into the linked list
    new_node->next = *head;
    *head = new_node;
    pthread_mutex_unlock(&head->mutex);
}

// Define a function to coalesce adjacent free nodes in the linked list
void coalesce(struct node** head) {
    struct node* current = NULL;
    struct node* next = NULL;
    pthread_mutex_lock(&head->mutex);
    // Iterate through the linked list and coalesce adjacent free nodes
    for (current = *head; current != NULL; current = next) {
        next = current->next;
        if (next == NULL || next->value != 0) {
            continue;
        }
        // Coalesce the adjacent free nodes
        current->next = next->next;
        free(sizeof(struct node));
    }
    pthread_mutex_unlock(&head->mutex);
}

// Define a function to report the memory usage statistics
void report_memory_usage(struct memory_pool* pool) {
    size_t total = 0;
    size_t free = 0;
    pthread_mutex_lock(&pool->mutex);
    // Calculate the total and free memory in the memory pool
    for (void* ptr = pool->data; ptr < pool->data + pool->size; ptr += sizeof(struct node)) {
        if (*((int*)ptr) == 0) {
            free++;
        } else {
            total++;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    // Print the memory usage statistics
    printf("Total allocated memory: %zu\n", total);
    printf("Free memory: %zu\n", free);
    printf("Memory pool utilization: %.2f%%\n", (float)free / (total + free) * 100);
}

// Define a function to handle allocation failures
void handle_allocation_failure(struct memory_pool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);
    // Free any allocated resources before returning an error status
    free(sizeof(struct node));
    pthread_mutex_unlock(&pool->mutex);
}

// Define a function to handle random number generation
int generate_random_number(int lower_bound, int upper_bound) {
    return rand() % (upper_bound - lower_bound + 1) + lower_bound;
}
