    if (!data) {
        return;
    }

    // Cast the input data to the appropriate type
    array_list *array = (array_list *)data;

    // Deallocate memory for the linked list
    node *current = array->head;
    while (current != NULL) {
        node *next = current->next;
        free(current);
        current = next;
    }

    // Deallocate memory for the data structure
    free(array->array);
    free(data);
