// Define the function to serialize the data structures to a file
void dyn_mem_serialize(void *data, FILE *file) {
    // Check if the input data is valid
    if (!data || !file) {
        return;
    }

    // Cast the input data to the appropriate type
    array_list *array = (array_list *)data;

    // Serialize the linked list
    node *current = array->head;
    while (current != NULL) {
        fwrite(current, sizeof(node), 1, file);
        current = current->next;
    }

    // Serialize the data structure
    fwrite(array->array, sizeof(int), array->num_elements, file);
}

// Define the function to deserialize the data structures from a file
void *dyn_mem_deserialize(FILE *file) {
