    array_list *data = malloc(sizeof(array_list));
    if (!data) {
        return NULL;
    }

    // Initialize the data structure
    data->head = NULL;

    // Deserialize the linked list
    node *current = malloc(sizeof(node));
    while (fread(current, sizeof(node), 1, file) == 1) {
        current->next = data->head;
        data->head = current;
        current = malloc(sizeof(node));
    }

    // Deserialize the data structure
    fread(data->array, sizeof(int), array->num_elements, file);

    // Return the deserialized data structure
    return data;
