// Define the record structure
typedef struct {
    int key;
} Record;

// Function to initialize the arrays of offsets and keys
void init_arrays(int num_records, int min_key, int max_key) {
    // Allocate memory for the offset array
    long *offsets = malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the key array
    int *keys = malloc(num_records * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(1);
    }

    // Initialize the key array with unique values from the offset array
    for (int i = 0; i < num_records; i++) {
        int j = 0;
        while (j < i) {
            if (offsets[i] == offsets[j]) {
                // If a duplicate is found, regenerate the offset value
                offsets[i] = rand() % (max_key - min_key + 1) + min_key;
            } else {
                j++;
            }
        }
        keys[i] = offsets[i];
    }

    // Free the offset array and return the key array
    free(offsets);
    return keys;
}

// Function to populate an array of records with unique values
void populate_records(Record *records, int num_records, int min_key, int max_key) {
    // Initialize the arrays of offsets and keys
    long *offsets = init_arrays(num_records, min_key, max_key);
    int *keys = init_arrays(num_records, min_key, max_key);

    // Populate the records with unique values from the key array
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
    }

    // Free the offset and key arrays
    free(offsets);
    free(keys);
}
