                double area = 0.5 * fabs(polygons[i]->vertices[0].x * polygons[i]->vertices[1].y - polygons[i]->vertices[1].x * polygons[i]->vertices[2].y + polygons[i]->vertices[2].x * polygons[i]->vertices[3].y - polygons[i]->vertices[3].x * polygons[i]->vertices[0].y);
