                printf("Polygon %d has an area of %.2f\n", i, area);
            }
            break;
    }

    // Clean up the memory pool and free all allocated memory
    free(pool->memory);
    free(polygons);
    free(vertices);
}

// Define a function to calculate the area of a polygon using the shoelace formula
