// Define a node structure to hold a double value and a pointer to another node
typedef struct node {
    double value;
    struct node* next;
} node_t;

// Define a linked list structure to hold nodes
typedef struct linked_list {
    node_t* head;
    node_t* tail;
    size_t size;
    pthread_mutex_t mutex; // Mutex for thread safety
} linked_list_t;

// Initialize a new linked list with an initial capacity of 10 nodes
linked_list_t* init_linked_list(size_t capacity) {
    linked_list_t* list = malloc(sizeof(linked_list_t));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for linked list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL); // Initialize mutex for thread safety
    return list;
}

// Insert a new node into the linked list with a given value
int insert_node(linked_list_t* list, double value) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread safety
    node_t* new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&list->mutex); // Unlock mutex
        return -1;
    }
    new_node->value = value;
    new_node->next = NULL;
    if (list->head == NULL) { // If list is empty, set head and tail to new node
        list->head = new_node;
        list->tail = new_node;
    } else { // Otherwise, insert new node after tail
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex); // Unlock mutex
    return 0;
}

// Remove a node from the linked list with a given value
int remove_node(linked_list_t* list, double value) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread safety
    node_t* current = list->head;
    while (current != NULL && current->value != value) {
        current = current->next;
    }
    if (current == NULL) { // If node not found, return error code
        pthread_mutex_unlock(&list->mutex); // Unlock mutex
        return -1;
    }
    if (current == list->head) { // If node is head, set new head and update tail
        list->head = current->next;
        if (list->tail == current) {
            list->tail = NULL;
        }
    } else if (current == list->tail) { // If node is tail, set new tail and update head
        list->tail = current->prev;
        if (list->head == current) {
            list->head = NULL;
        }
    } else { // Otherwise, remove node from middle of list
        current->prev->next = current->next;
        current->next->prev = current->prev;
    }
    free(current); // Free memory for removed node
    list->size--;
    pthread_mutex_unlock(&list->mutex); // Unlock mutex
    return 0;
}

// Traverse the linked list and print each node's value
void traverse_linked_list(linked_list_t* list) {
    pthread_mutex_lock(&list->mutex); // Lock mutex for thread safety
    node_t* current = list->head;
    while (current != NULL) {
        printf("%f\n", current->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex); // Unlock mutex
}

// Free the memory allocated for the linked list and its nodes
void free_linked_list(linked_list_t* list) {
    node_t* current = list->head;
    while (current != NULL) {
        node_t* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex); // Destroy mutex for thread safety
    free(list); // Free memory for linked list structure
}
