// Custom memory allocator optimized for reducing fragmentation and improving memory efficiency
void* custom_malloc(size_t size) {
    // Allocate a block of memory from the system
    void* ptr = malloc(size);

    // If allocation failed, return NULL
    if (ptr == NULL) {
        return NULL;
    }

    // Initialize the memory block with a header and footer
    struct MemoryBlockHeader* header = (struct MemoryBlockHeader*)ptr;
    header->size = size;
    header->next = NULL;
    header->prev = NULL;

    // Add the new block to the free list
    pthread_mutex_lock(&free_list_mutex);
    header->next = free_list;
    if (free_list != NULL) {
        free_list->prev = header;
    }
    free_list = header;
    pthread_mutex_unlock(&free_list_mutex);

    return ptr;
}

// Custom memory deallocator optimized for reducing fragmentation and improving memory efficiency
void custom_free(void* ptr) {
    // If the pointer is NULL, do nothing
    if (ptr == NULL) {
        return;
    }

    // Remove the block from the free list
    pthread_mutex_lock(&free_list_mutex);
    struct MemoryBlockHeader* header = (struct MemoryBlockHeader*)ptr - 1;
    if (header->prev != NULL) {
        header->prev->next = header->next;
    } else {
        free_list = header->next;
    }
    if (header->next != NULL) {
        header->next->prev = header->prev;
    }
    pthread_mutex_unlock(&free_list_mutex);

    // Deallocate the memory block from the system
    free(ptr);
}

