    struct MemoryBlockHeader* free_list;

    // Mutex for protecting the free list
    pthread_mutex_t free_list_mutex;

    // Number of active allocations
    size_t num_allocs;

    // Maximum number of concurrent threads allowed
    size_t max_threads;
};

// Initialize a memory pool with the given maximum number of concurrent threads
struct MemoryPool* init_memory_pool(size_t max_threads) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }

    // Initialize the free list and mutex
    pthread_mutex_init(&pool->free_list_mutex, NULL);
    pool->free_list = NULL;
    pool->num_allocs = 0;
    pool->max_threads = max_threads;

    return pool;
}

// Allocate a memory block from the memory pool
void* allocate(struct MemoryPool* pool, size_t size) {
    // If the allocation size is larger than the maximum allowed size, return NULL
    if (size > MAX_ALLOCATION_SIZE) {
        return NULL;
    }

    // Acquire the mutex for protecting the free list
    pthread_mutex_lock(&pool->free_list_mutex);

    // If there are no available memory blocks, allocate a new block from the system
    if (pool->free_list == NULL) {
        void* ptr = malloc(size);
        if (ptr == NULL) {
            pthread_mutex_unlock(&pool->free_list_mutex);
            return NULL;
        }

        // Initialize the memory block with a header and footer
        struct MemoryBlockHeader* header = (struct MemoryBlockHeader*)ptr;
        header->size = size;
        header->next = NULL;
        header->prev = NULL;

        // Add the new block to the free list
        pool->free_list = header;
    }

    // Remove the first available memory block from the free list
    struct MemoryBlockHeader* header = pool->free_list;
    pool->free_list = header->next;
    if (header->next != NULL) {
        header->next->prev = NULL;
    }

    // Increment the number of active allocations
    pool->num_allocs++;

    // Release the mutex for protecting the free list
    pthread_mutex_unlock(&pool->free_list_mutex);

    return header + 1;
}

// Deallocate a memory block from the memory pool
void deallocate(struct MemoryPool* pool, void* ptr) {
    // If the pointer is NULL, do nothing
    if (ptr == NULL) {
        return;
    }

    // Acquire the mutex for protecting the free list
    pthread_mutex_lock(&pool->free_list_mutex);

    // Remove the memory block from the free list
    struct MemoryBlockHeader* header = (struct MemoryBlockHeader*)ptr - 1;
    if (header->prev != NULL) {
        header->prev->next = header->next;
    } else {
        pool->free_list = header->next;
    }
    if (header->next != NULL) {
        header->next->prev = header->prev;
    }

    // Deallocate the memory block from the system
    free(ptr);

    // Decrement the number of active allocations
    pool->num_allocs--;

    // Release the mutex for protecting the free list
    pthread_mutex_unlock(&pool->free_list_mutex);
}

// Destroy a memory pool and release all resources
void destroy_memory_pool(struct MemoryPool* pool) {
    // Acquire the mutex for protecting the free list
    pthread_mutex_lock(&pool->free_list_mutex);

    // Deallocate all memory blocks from the system
    while (pool->free_list != NULL) {
        struct MemoryBlockHeader* header = pool->free_list;
        pool->free_list = header->next;
        free(header + 1);
    }

    // Release the mutex for protecting the free list
    pthread_mutex_unlock(&pool->free_list_mutex);

    // Destroy the mutex for protecting the free list
    pthread_mutex_destroy(&pool->free_list_mutex);

    // Release all resources associated with the memory pool
    free(pool);
}
```
