// Define the function to perform a network check
struct NetworkCheckResult performNetworkCheck(char *hostname) {
    // Initialize the network check result structure
    struct NetworkCheckResult result;
    result.success = 0;
    result.latency = -1;

    // Perform the network check and update the latency data
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error: unable to create socket\n");
        exit(1);
    }

    struct sockaddr_in serv_addr;
    bzero((char *)&serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    inet_pton(AF_INET, hostname, &serv_addr.sin_addr);
    serv_addr.sin_port = htons(80);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        printf("Error: unable to connect to host\n");
        exit(1);
    }

    // Send a request to the server and receive the response
    char *request = "GET / HTTP/1.1\r\nHost: www.example.com\r\n\r\n";
    send(sockfd, request, strlen(request), 0);
    char buffer[4096];
    bzero(buffer, sizeof(buffer));
    recv(sockfd, buffer, sizeof(buffer), 0);

    // Close the socket and update the latency data
    close(sockfd);
    result.latency = getLatency(buffer);
    result.success = 1;

    return result;
}

// Define the function to calculate the latency of a network check
int getLatency(char *buffer) {
    // Initialize the latency variable
    int latency = -1;

    // Parse the response buffer and extract the latency data
    char *token = strtok(buffer, " ");
    while (token != NULL) {
        if (strcmp(token, "latency") == 0) {
            token = strtok(NULL, " ");
            latency = atoi(token);
            break;
        }
        token = strtok(NULL, " ");
    }

    return latency;
}

