// Define data structure for data points
typedef struct {
    double value;
    char* string;
} data_point;

// Define memory pool structure
typedef struct {
    size_t capacity; // Total capacity of the memory pool
    size_t used; // Number of used blocks in the memory pool
    size_t free; // Number of free blocks in the memory pool
    data_point* blocks; // Array of data points
} memory_pool;

// Define custom hash function for mapping data points to memory blocks
unsigned long hash(data_point* point) {
    unsigned long hash = 0;
    char* string = point->string;
    while (*string != '\0') {
        hash = (hash << 5) - hash + *string++;
    }
    return hash % capacity;
}

// Define memory pool manager functions
memory_pool* create_memory_pool(size_t capacity) {
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (pool == NULL) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->free = capacity;
    pool->blocks = calloc(capacity, sizeof(data_point));
    if (pool->blocks == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

void destroy_memory_pool(memory_pool* pool) {
    free(pool->blocks);
    free(pool);
}

data_point* allocate_block(memory_pool* pool, size_t size) {
    if (size > pool->free) {
        return NULL;
    }
    data_point* block = &pool->blocks[hash(pool)];
    pool->used++;
    pool->free--;
    return block;
}

void deallocate_block(memory_pool* pool, data_point* block) {
    if (block == NULL) {
        return;
    }
    pool->used--;
    pool->free++;
}

// Define thread-safe memory allocation and deallocation functions
data_point* allocate_thread_safe(memory_pool* pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);
    data_point* block = allocate_block(pool, size);
    pthread_mutex_unlock(&pool->mutex);
    return block;
}

void deallocate_thread_safe(memory_pool* pool, data_point* block) {
    pthread_mutex_lock(&pool->mutex);
    deallocate_block(pool, block);
    pthread_mutex_unlock(&pool->mutex);
}

// Define random number generation function for each thread
void generate_random_numbers(memory_pool* pool) {
    size_t i;
    for (i = 0; i < pool->capacity; i++) {
        data_point* block = &pool->blocks[i];
        block->value = rand() / (double)RAND_MAX;
        block->string = malloc(16); // Allocate memory for string
        sprintf(block->string, "%.2f", block->value);
    }
}

// Define coalescing strategy for adjacent free blocks
void coalesce_free_blocks(memory_pool* pool) {
    size_t i;
    for (i = 0; i < pool->capacity - 1; i++) {
        data_point* block = &pool->blocks[i];
        if (block->used == 0 && block->next != NULL) {
            data_point* next = block->next;
            while (next != NULL && next->used == 0) {
                next = next->next;
            }
            if (next != NULL) {
                block->next = next->next;
                next->next = block;
            }
        }
    }
}

// Define synchronization strategy for memory pool manager
void synchronize_memory_pool(memory_pool* pool, pthread_mutex_t* mutex) {
    pthread_mutex_lock(&mutex);
    if (pool->used > 0.9 * pool->capacity) {
        coalesce_free_blocks(pool);
    }
    pthread_mutex_unlock(&mutex);
}

// Define thread-safe memory allocation and deallocation functions with synchronization
