typedef struct {
    double value;
    char* string;
} data_point;

// Define memory pool manager to allocate and manage memory efficiently
void* mempool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage memory for multiple data structures in a high-throughput, multi-threaded environment
int dynamic_memory_manager(int size) {
    // Check if input size exceeds maximum predefined value
    if (size > MAX_SIZE) {
        return -1;
    }

    // Allocate memory for array of data points
    data_point* data = malloc(sizeof(data_point) * size);
    if (!data) {
        return -2;
    }

    // Register allocated block with memory pool to facilitate optimal resource management and integration
    mempool = realloc(mempool, sizeof(data_point) * (size + 1));
    if (!mempool) {
        free(data);
        return -3;
    }

    // Populate array of data points with values read from standard input
    for (int i = 0; i < size; i++) {
        scanf("%lf", &data[i].value);
        data[i].string = malloc(sizeof(char) * MAX_STRING_LENGTH);
        if (!data[i].string) {
            free(data);
            return -4;
        }
        scanf("%s", data[i].string);
    }

    // Integrate with memory pool manager to maintain performance and resource efficiency
    pthread_mutex_lock(&mutex);
    mempool = realloc(mempool, sizeof(data_point) * (size + 1));
    if (!mempool) {
        free(data);
        return -5;
    }
    pthread_mutex_unlock(&mutex);

    // Optimize memory allocation patterns to minimize fragmentation and maximize throughput
    for (int i = 0; i < size; i++) {
        mempool[i] = data[i];
    }

    // Periodically report memory usage statistics, including total allocated memory, free memory, and pool utilization
    printf("Total allocated memory: %lu\n", sizeof(data_point) * (size + 1));
    printf("Free memory: %lu\n", sizeof(data_point) * size);
    printf("Pool utilization: %.2f%%\n", ((double)sizeof(data_point) * (size + 1)) / (MAX_SIZE * sizeof(data_point)));

    // Clear all allocated resources and reset memory pool to enable subsequent calls to reuse memory effectively
    pthread_mutex_lock(&mutex);
    free(mempool);
    mempool = NULL;
    pthread_mutex_unlock(&mutex);

    return 0;
}
