    void *data = malloc(sizeof(long) * num_records + sizeof(int) * num_records + sizeof(record) * num_records);
    if (data == NULL) {
        printf("Failed to allocate memory for data\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&mutex);
        return;
