    // Copy the offsets, keys, and records into the single allocation
    memcpy(data, offsets, sizeof(long) * num_records);
    memcpy((char *) data + sizeof(long) * num_records, keys, sizeof(int) * num_records);
    memcpy((char *) data + sizeof(long) * num_records + sizeof(int) * num_records, records, sizeof(record) * num_records);

