polygon_t* allocate_polygons(int num_polygons, int num_sides) {
    // Allocate memory for the array of polygons
    polygon_t *polygons = (polygon_t*)malloc(num_polygons * sizeof(polygon_t));
    if (!polygons) {
        fprintf(stderr, "Failed to allocate memory for polygons\n");
        return NULL;
    }

    // Initialize each polygon's sides and labels
    for (int i = 0; i < num_polygons; i++) {
        polygons[i].sides = (float*)malloc(num_sides * sizeof(float));
        if (!polygons[i].sides) {
            fprintf(stderr, "Failed to allocate memory for polygon sides\n");
            return NULL;
        }
        polygons[i].labels = (char*)malloc(num_sides * sizeof(char));
        if (!polygons[i].labels) {
            fprintf(stderr, "Failed to allocate memory for polygon labels\n");
            return NULL;
        }
    }

    // Initialize the sides and labels of each polygon
    for (int i = 0; i < num_polygons; i++) {
        for (int j = 0; j < num_sides; j++) {
            polygons[i].sides[j] = 0.0f;
            polygons[i].labels[j] = ' ';
        }
    }

    return polygons;
}

// Function to calculate the area of a polygon based on its side lengths
