```cpp
void insertStringAfter(std::forward_list<std::string>& forwardList, const std::string& targetString, const std::string& newString) {
  // Search for the first occurrence of targetString within the forwardList
  auto it = std::find(forwardList.begin(), forwardList.end(), targetString);

  // If found, insert newString immediately after the first occurrence of targetString
  if (it != forwardList.end()) {
    forwardList.insert_after(it, newString);
  } else {
    // Otherwise, append newString to the end of the list
    forwardList.push_back(newString);
  }
}
