Record* allocateRecords(int numRecords, struct MemoryPoolManager *manager) {
    // Validate input
    if (numRecords <= 0 || manager == NULL) {
        return NULL;
    }

    // Allocate memory for the record array
    Record* records = malloc(sizeof(Record) * numRecords);
    if (records == NULL) {
        return NULL;
    }

    // Initialize each record with a random value, weight, and offset
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 100;
        records[i].weight = (double)rand() / RAND_MAX;
        records[i].offset = rand() % 1000000;
    }

    // Register the allocated memory with the manager
    manager->registerMemory(records, sizeof(Record) * numRecords);

    return records;
}

// Function to generate random values for each record's int field, double weight, and long offset within specified ranges
void generateRandomValues(Record* records, int numRecords, int keyMin, int keyMax, double weightMin, double weightMax, long offsetMin, long offsetMax) {
