    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % keyMax + keyMin;
        records[i].weight = (double)rand() / RAND_MAX * weightMax + weightMin;
        records[i].offset = rand() % offsetMax + offsetMin;
