StateList* createStateList(int *stateIds, size_t stateCount, FSA *fsa, int lastStateId) {
    // Check for null pointers and negative state counts
    if (stateIds == NULL || stateCount <= 0) {
        ERROR_HANDLING_MECHANISM("Invalid input: stateIds or stateCount is null or negative");
        return NULL;
    }

    // Allocate memory for the state list
    StateList *stateList = malloc(sizeof(StateList));
    if (stateList == NULL) {
        ERROR_HANDLING_MECHANISM("Failed to allocate memory for state list");
        return NULL;
    }

    // Initialize the state list
    stateList->states = malloc(stateCount * sizeof(State));
    if (stateList->states == NULL) {
        ERROR_HANDLING_MECHANISM("Failed to allocate memory for state list");
        free(stateList);
        return NULL;
    }
    stateList->count = 0;

    // Iterate over the input states and add them to the state list
    for (size_t i = 0; i < stateCount; i++) {
        int stateId = stateIds[i];
        State *state = &(stateList->states[stateList->count]);
        state->id = stateId;
        state->label = fsa->getStateLabel(stateId);
        state->referenceCount = 0;

        // Check for duplicates and skip adding the duplicate state
        if (findStateById(stateList, stateId) != NULL) {
            LOGGING_MECHANISM("Duplicate state found: %d\n", stateId);
            continue;
        }

        // Increment the reference count of each added state
        state->referenceCount++;

        // Check for exceeding the reference count threshold and reset it if necessary
        if (state->referenceCount > REFERENCE_COUNT_THRESHOLD) {
            LOGGING_MECHANISM("Reference count exceeded: %d\n", stateId);
            state->referenceCount = REFERENCE_COUNT_THRESHOLD;
        }

        // Update the 'next' pointer of the last state in the list to point to the newly created state list
        if (stateList->count > 0) {
            State *lastState = &(stateList->states[stateList->count - 1]);
            lastState->next = state;
        }

        // Increment the count of states in the list
        stateList->count++;
    }

    // Sort the state list if sorting is enabled
    if (SORTING_ALGORITHM != NULL) {
        SORTING_ALGORITHM(stateList->states, stateList->count, sizeof(State), compareStatesById);
    }

    return stateList;
}

void destroyStateList(StateList *stateList) {
    // Check for null pointers
    if (stateList == NULL || stateList->states == NULL) {
        ERROR_HANDLING_MECHANISM("Invalid input: stateList or stateList->states is null");
        return;
    }

    // Free the memory allocated for the state list
    free(stateList->states);
    free(stateList);
}

State* findStateById(StateList *stateList, int stateId) {
    // Check for null pointers
    if (stateList == NULL || stateList->states == NULL) {
        ERROR_HANDLING_MECHANISM("Invalid input: stateList or stateList->states is null");
        return NULL;
    }

    // Iterate over the states in the list and find the one with the matching ID
    for (size_t i = 0; i < stateList->count; i++) {
        State *state = &(stateList->states[i]);
        if (state->id == stateId) {
            return state;
        }
    }

    // Return null if the state is not found in the list
    return NULL;
}

int compareStatesById(const void *a, const void *b) {
    State *stateA = (State *)a;
    State *stateB = (State *)b;
    return stateA->id - stateB->id;
}
