// Octree node structure
struct Node {
  int featureSize; // Size of the feature vector for this node
  int numLeafNodes; // Number of leaf nodes in this subtree
  int dataCapacity; // Capacity of the data buffer for this node
  std::vector<float>* dataBuffer; // Buffer to store data points
  std::vector<Node*> children; // Children nodes
};

// Octree structure
struct Octree {
  Node* root; // Root node of the octree
  int featureSize; // Size of the feature vector for this octree
  int numLeafNodes; // Number of leaf nodes in this octree
  int dataCapacity; // Capacity of the data buffer for this octree
  std::vector<float>* dataBuffer; // Buffer to store data points
};

// Initialize an octree with customizable feature size, number of leaf nodes, and data capacity
Octree* initOctree(int featureSize, int numLeafNodes, int dataCapacity) {
  Octree* octree = new Octree();
  octree->featureSize = featureSize;
  octree->numLeafNodes = numLeafNodes;
  octree->dataCapacity = dataCapacity;
  octree->root = new Node(featureSize, numLeafNodes, dataCapacity);
  return octree;
}

// Insert a data point into the octree
void insertDataPoint(Octree* octree, float* data) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() < octree->root->dataCapacity) {
    // Add the data point to the buffer
    octree->root->dataBuffer->push_back(data);
  } else {
    // Find the appropriate child node for the new data point
    Node* child = findChildNode(octree, data);

    // Insert the data point into the child node
    insertDataPoint(child, data);
  }
}

// Remove a data point from the octree
void removeDataPoint(Octree* octree, float* data) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() > 0) {
    // Remove the data point from the buffer
    octree->root->dataBuffer->erase(std::remove(octree->root->dataBuffer->begin(), octree->root->dataBuffer->end(), data), octree->root->dataBuffer->end());
  } else {
    // Find the appropriate child node for the new data point
    Node* child = findChildNode(octree, data);

    // Remove the data point from the child node
    removeDataPoint(child, data);
  }
}

// Update a data point in the octree
void updateDataPoint(Octree* octree, float* oldData, float* newData) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() > 0) {
    // Update the data point in the buffer
    std::replace(octree->root->dataBuffer->begin(), octree->root->dataBuffer->end(), oldData, newData);
  } else {
    // Find the appropriate child node for the new data point
    Node* child = findChildNode(octree, oldData);

    // Update the data point in the child node
    updateDataPoint(child, oldData, newData);
  }
}

// Hierarchical queries to retrieve all nodes within a given radius
std::vector<float*> queryRadius(Octree* octree, float* center, float radius) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Initialize an empty vector to store the results
  std::vector<float*> results;

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() > 0) {
    // Iterate over the data points in the buffer
    for (float* data : octree->root->dataBuffer) {
      // Calculate the distance between the center and the current data point
      float dist = calculateDistance(center, data);

      // If the distance is within the radius, add it to the results vector
      if (dist <= radius) {
        results.push_back(data);
      }
    }
  } else {
    // Find the appropriate child node for the new data point
    Node* child = findChildNode(octree, center);

    // Recursively query the child node with the given radius
    std::vector<float*> childResults = queryRadius(child, center, radius);

    // Add the results from the child node to the overall results vector
    results.insert(results.end(), childResults.begin(), childResults.end());
  }

  return results;
}

// Hierarchical clustering that dynamically adjusts the granularity of the tree based on data point density, allowing for node merging or splitting as needed
void clusterDataPoints(Octree* octree) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() > 0) {
    // Calculate the density of the current node
    float density = calculateDensity(octree->root);

    // If the density is below a certain threshold, split the node into smaller subtrees
    if (density < 0.5) {
      // Split the node into two child nodes with half the capacity of the original node
      Node* leftChild = new Node(octree->featureSize, octree->numLeafNodes, octree->root->dataCapacity / 2);
      Node* rightChild = new Node(octree->featureSize, octree->numLeafNodes, octree->root->dataCapacity / 2);

      // Add the child nodes to the parent node
      octree->root->children.push_back(leftChild);
      octree->root->children.push_back(rightChild);

      // Recursively split the child nodes
      clusterDataPoints(leftChild);
      clusterDataPoints(rightChild);
    } else {
      // If the density is above a certain threshold, merge the node with its sibling nodes
      if (octree->root->children.size() > 1) {
        // Merge the node with its sibling nodes
        Node* leftSibling = octree->root->children[0];
        Node* rightSibling = octree->root->children[1];

        // Combine the data buffers of the sibling nodes into the parent node
        for (float* data : leftSibling->dataBuffer) {
          octree->root->dataBuffer->push_back(data);
        }
        for (float* data : rightSibling->dataBuffer) {
          octree->root->dataBuffer->push_back(data);
        }

        // Remove the sibling nodes from the parent node
        octree->root->children.erase(octree->root->children.begin() + 1);
        octree->root->children.erase(octree->root->children.begin());
      }
    }
  } else {
    // Recursively cluster the child nodes
    for (Node* child : octree->root->children) {
      clusterDataPoints(child);
    }
  }
}

// Calculate the distance between two data points
float calculateDistance(float* data1, float* data2) {
  // Calculate the Euclidean distance between the two data points
  return std::sqrt(std::pow(data1[0] - data2[0], 2) + std::pow(data1[1] - data2[1], 2));
}

// Calculate the density of a node based on its number of data points and capacity
float calculateDensity(Node* node) {
  return (float)node->dataBuffer->size() / node->dataCapacity;
}

// Find the appropriate child node for a given data point
Node* findChildNode(Octree* octree, float* data) {
  // Lock the mutex to prevent concurrent access
  std::lock_guard<std::mutex> lock(octree->root->mutex);

  // Initialize an empty vector to store the results
  std::vector<float*> results;

  // Check if the node is a leaf node and has enough capacity for the new data point
  if (octree->root->children.empty() && octree->root->dataBuffer->size() > 0) {
    // Iterate over the data points in the buffer
    for (float* point : octree->root->dataBuffer) {
      // Calculate the distance between the current data point and the center of the node
      float dist = calculateDistance(point, data);

      // If the distance is within the radius, add it to the results vector
      if (dist <= 0.5) {
        results.push_back(point);
      }
    }
  } else {
    // Find the appropriate child node for the new data point
    Node* child = findChildNode(octree, data);

    // Recursively query the child node with the given radius
    std::vector<float*> childResults = queryRadius(child, center, radius);

    // Add the results from the child node to the overall results vector
    results.insert(results.end(), childResults.begin(), childResults.end());
  }

  return results;
}
