// Define a memory pool structure to manage memory allocation and deallocation
typedef struct {
    size_t capacity; // Total capacity of the memory pool
    size_t used; // Used memory in the pool
    void* blocks[]; // Array of memory blocks
} MemoryPool;

// Define a custom memory pool manager to allocate and deallocate memory
MemoryPool* createMemoryPool(size_t capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->blocks = calloc(capacity, sizeof(void*));
    if (pool->blocks == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->used; i++) {
        free(pool->blocks[i]);
    }
    free(pool);
}

// Define a function to allocate memory from the memory pool
void* allocateMemory(MemoryPool* pool, size_t size) {
    if (pool == NULL || size == 0) {
        return NULL;
    }
    void* block = malloc(size);
    if (block == NULL) {
        return NULL;
    }
    pool->used++;
    pool->blocks[pool->used - 1] = block;
    return block;
}

// Define a function to deallocate memory from the memory pool
void deallocateMemory(MemoryPool* pool, void* block) {
    if (pool == NULL || block == NULL) {
        return;
    }
    size_t i = 0;
    while (i < pool->used && pool->blocks[i] != block) {
        i++;
    }
    if (i < pool->used) {
        free(pool->blocks[i]);
        pool->used--;
        memmove(&pool->blocks[i], &pool->blocks[i + 1], (pool->used - i) * sizeof(void*));
    }
}

