void process_sensor_data_concurrently(float *float_array, char *char_array, unsigned long *timestamp_array) {
    // Create a thread pool with the number of threads equal to the number of sensors
    pthread_t thread[num_sensors];

    // Loop through each sensor data entry and create a new thread for it
    for (int i = 0; i < num_sensors; i++) {
