bucket_t* allocate_buckets(int *counts, size_t count_len, float threshold) {
    // Check for edge cases
    if (count_len == 0 || threshold <= 0.0f) {
        return NULL;
    }

    // Allocate memory for the bucket array and initialize it to NULL
    bucket_t *buckets = malloc(sizeof(bucket_t) * count_len);
    if (buckets == NULL) {
        return NULL;
    }
    memset(buckets, 0, sizeof(bucket_t) * count_len);

    // Allocate memory for the counts and weights arrays
    int *counts_array = malloc(sizeof(int) * count_len);
    float *weights_array = malloc(sizeof(float) * count_len);
    if (counts_array == NULL || weights_array == NULL) {
        free(buckets);
        return NULL;
    }

    // Initialize the counts and weights arrays
    for (size_t i = 0; i < count_len; i++) {
        buckets[i].count = &counts_array[i];
        buckets[i].weight = &weights_array[i];
        *buckets[i].count = counts[i];
        *buckets[i].weight = (float)counts[i] / threshold;
    }

    // Compute the average for each bucket
    for (size_t i = 0; i < count_len; i++) {
        buckets[i].average = (double)*buckets[i].count / *buckets[i].weight;
    }

    // Partition the counts array into buckets based on the threshold
    size_t bucket_index = 0;
    for (size_t i = 0; i < count_len; i++) {
        if (*buckets[i].count <= threshold) {
            *buckets[bucket_index].count += *buckets[i].count;
            *buckets[bucket_index].weight += *buckets[i].weight;
            buckets[i].count = NULL;
            buckets[i].weight = NULL;
        } else {
            bucket_index++;
            if (bucket_index >= count_len) {
                break;
            }
            *buckets[bucket_index].count = *buckets[i].count - threshold;
            *buckets[bucket_index].weight = *buckets[i].weight - threshold / (float)*buckets[i].count;
        }
    }

    // Free the unused memory for the counts and weights arrays
    free(counts_array);
    free(weights_array);

    return buckets;
}
