// Define the memory pool manager
class MemoryPoolManager {
private:
    // The list of free blocks
    std::list<void*> free_blocks_;

    // The list of allocated blocks
    std::list<void*> allocated_blocks_;

    // The lock for synchronizing access to the memory pool
    pthread_mutex_t mutex_;

public:
    MemoryPoolManager() {
        pthread_mutex_init(&mutex_, NULL);
    }

    ~MemoryPoolManager() {
        pthread_mutex_destroy(&mutex_);
    }

    // Allocate a block of memory from the pool
    void* allocate(size_t size) {
        std::lock_guard<pthread_mutex_t> lock(mutex_);

        // Check if there are any free blocks available
        if (!free_blocks_.empty()) {
            // Get the first free block and remove it from the list
            void* block = free_blocks_.front();
            free_blocks_.pop_front();

            // Add the block to the allocated list
            allocated_blocks_.push_back(block);

            return block;
        } else {
            // If there are no free blocks, allocate a new one
            void* block = malloc(size);
            if (block != NULL) {
                allocated_blocks_.push_back(block);
            }

            return block;
        }
    }

    // Deallocate a block of memory from the pool
    void deallocate(void* block) {
        std::lock_guard<pthread_mutex_t> lock(mutex_);

        // Check if the block is in the allocated list
        if (std::find(allocated_blocks_.begin(), allocated_blocks_.end(), block) != allocated_blocks_.end()) {
            // Remove the block from the allocated list and add it to the free list
            allocated_blocks_.remove(block);
            free_blocks_.push_back(block);
        } else {
            // If the block is not in the allocated list, deallocate it
            free(block);
        }
    }
};

