#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define data structures for records and memory pool management
typedef struct {
    int key;
    long offset;
} record_t;

typedef struct {
    size_t size;
    void* ptr;
} mempool_block_t;

typedef struct {
    size_t total_allocated;
    size_t total_free;
    size_t utilization;
    mempool_block_t* blocks;
} mempool_t;

// Define function prototypes
void init_mempool(mempool_t* pool, size_t block_size);
void* alloc_mempool(mempool_t* pool, size_t size);
void free_mempool(mempool_t* pool, void* ptr);
void compact_mempool(mempool_t* pool);
void clear_mempool(mempool_t* pool);
void serialize_records(record_t* records, size_t num_records, FILE* fp);

// Define function to perform tasks
int perform_tasks(size_t long_array_size, size_t int_array_size, int lower_bound, int upper_bound) {
    // Validate input sizes and bounds
    if (long_array_size == 0 || int_array_size == 0 || lower_bound > upper_bound) {
        return -1;
    }

    // Initialize memory pool for record structures
    mempool_t* pool = malloc(sizeof(mempool_t));
    init_mempool(pool, sizeof(record_t));

    // Allocate and initialize array of records
    record_t* records = alloc_mempool(pool, long_array_size * int_array_size);
    for (int i = 0; i < long_array_size * int_array_size; i++) {
        records[i].key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        records[i].offset = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    // Set values of each record's int field to a random value within the specified range
    for (int i = 0; i < long_array_size * int_array_size; i++) {
        records[i].key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    // Compact memory pool to minimize fragmentation
    compact_mempool(pool);

    // Serialize records to a file format
    FILE* fp = fopen("records.bin", "wb");
    serialize_records(records, long_array_size * int_array_size, fp);
    fclose(fp);

    // Clear memory pool and release resources
    clear_mempool(pool);
    free(pool);

    return 0;
}

// Define function to initialize memory pool for record structures
void init_mempool(mempool_t* pool, size_t block_size) {
    // Initialize total allocated and free memory to zero
    pool->total_allocated = 0;
    pool->total_free = 0;

    // Allocate initial block of memory for the memory pool
    pool->blocks = malloc(sizeof(mempool_block_t));
    if (pool->blocks == NULL) {
        return -1;
    }

    // Initialize size and pointer to null
    pool->blocks[0].size = block_size;
    pool->blocks[0].ptr = malloc(block_size);
    if (pool->blocks[0].ptr == NULL) {
        return -1;
    }

    // Set utilization to the size of the initial block
    pool->utilization = block_size;
}

// Define function to allocate memory from the memory pool
void* alloc_mempool(mempool_t* pool, size_t size) {
    // Check if requested size is within bounds
    if (size > pool->blocks[0].size) {
        return NULL;
    }

    // Find first block with sufficient space for allocation
    int i = 0;
    while (pool->blocks[i].size < size) {
        i++;
        if (i == pool->num_blocks) {
            break;
        }
    }

    // If no suitable block found, allocate a new one
    if (i == pool->num_blocks) {
        mempool_block_t* new_block = malloc(sizeof(mempool_block_t));
        new_block->size = size;
        new_block->ptr = malloc(size);
        if (new_block->ptr == NULL) {
            return NULL;
        }
        pool->num_blocks++;
    }

    // Allocate memory from the selected block
    void* ptr = pool->blocks[i].ptr;
    pool->blocks[i].ptr += size;
    pool->blocks[i].size -= size;
    pool->total_allocated += size;
    pool->utilization -= size;

    return ptr;
}

// Define function to free memory from the memory pool
void free_mempool(mempool_t* pool, void* ptr) {
    // Find block containing the pointer
    int i = 0;
    while (pool->blocks[i].ptr != ptr) {
        i++;
        if (i == pool->num_blocks) {
            break;
        }
    }

    // If block found, update its size and pointer
    if (i < pool->num_blocks) {
        pool->blocks[i].size += pool->blocks[i].ptr - ptr;
        pool->blocks[i].ptr = ptr;
        pool->total_free += pool->blocks[i].size;
        pool->utilization += pool->blocks[i].size;
    }
}

// Define function to compact memory pool to minimize fragmentation
void compact_mempool(mempool_t* pool) {
    // Sort blocks by size in descending order
    qsort(pool->blocks, pool->num_blocks, sizeof(mempool_block_t), compare_blocks);

    // Merge adjacent blocks with the same size
    int i = 0;
    while (i < pool->num_blocks - 1) {
        if (pool->blocks[i].size == pool->blocks[i + 1].size) {
            memcpy(pool->blocks[i].ptr, pool->blocks[i + 1].ptr, pool->blocks[i].size);
            free(pool->blocks[i + 1].ptr);
            pool->num_blocks--;
        } else {
            i++;
        }
    }
}

// Define function to clear memory pool and release resources
void clear_mempool(mempool_t* pool) {
    // Free all allocated blocks
    for (int i = 0; i < pool->num_blocks; i++) {
        free(pool->blocks[i].ptr);
    }

    // Release memory for block array and reset utilization
    free(pool->blocks);
    pool->utilization = 0;
}

// Define function to serialize records to a file format
void serialize_records(record_t* records, size_t num_records, FILE* fp) {
    // Write header with number of records and record size
    fwrite(&num_records, sizeof(size_t), 1, fp);
    fwrite(&sizeof(record_t), sizeof(size_t), 1, fp);

    // Write each record to file
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i].key, sizeof(int), 1, fp);
        fwrite(&records[i].offset, sizeof(long), 1, fp);
    }
}
