void manage_memory(int num_keys, int num_offsets, long min_value, long max_value) {
    // Initialize the memory pool manager
    struct MemoryPoolManager* mem_pool_manager = (struct MemoryPoolManager*)malloc(sizeof(struct MemoryPoolManager));
    mem_pool_manager->num_pools = 1;
    mem_pool_manager->mem_pools = (struct MemoryPool*)malloc(sizeof(struct MemoryPool) * mem_pool_manager->num_pools);

    // Initialize the memory pool
    struct MemoryPool* mem_pool = &mem_pool_manager->mem_pools[0];
    mem_pool->total_size = 1024 * 1024; // 1 MB
    mem_pool->used_size = 0;
    mem_pool->mem_pool = malloc(mem_pool->total_size);

    // Allocate memory for arrays of long, int, and record structures
    long* offsets = (long*)malloc(sizeof(long) * num_offsets);
    int* keys = (int*)malloc(sizeof(int) * num_keys);
    struct Record* records = (struct Record*)malloc(sizeof(struct Record) * num_keys);

    // Initialize the arrays of long, int, and record structures
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }
    for (int i = 0; i < num_keys; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[rand() % num_offsets];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Free the memory allocated for arrays of long, int, and record structures
    free(offsets);
    free(keys);
    free(records);

    // Clear all allocated resources and reset the memory pool
    mem_pool->used_size = 0;
    free(mem_pool->mem_pool);
    free(mem_pool_manager);
}

