using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace FileProcessor
{
    public class FileProcessor
    {
        private readonly string _inputFilePath;
        private readonly string _outputFilePath;
        private readonly CipherAlgorithm _cipherAlgorithm;
        private readonly int _bufferSize;
        private readonly bool _streamingEnabled;

        public FileProcessor(string inputFilePath, string outputFilePath, CipherAlgorithm cipherAlgorithm, int bufferSize = 4096, bool streamingEnabled = false)
        {
            _inputFilePath = inputFilePath;
            _outputFilePath = outputFilePath;
            _cipherAlgorithm = cipherAlgorithm;
            _bufferSize = bufferSize;
            _streamingEnabled = streamingEnabled;
        }

        public void Process()
        {
            if (!File.Exists(_inputFilePath))
                throw new FileNotFoundException($"Input file '{_inputFilePath}' does not exist.");

            if (string.IsNullOrEmpty(_outputFilePath))
                throw new ArgumentException("Output file path is required.", nameof(outputFilePath));

            using var inputStream = new FileStream(_inputFilePath, FileMode.Open);
            using var outputStream = new FileStream(_outputFilePath, FileMode.Create);

            if (_streamingEnabled)
            {
                ProcessStreaming(inputStream, outputStream);
            }
            else
            {
                ProcessBuffered(inputStream, outputStream);
            }
        }

        private void ProcessStreaming(FileStream inputStream, FileStream outputStream)
        {
            var buffer = new byte[_bufferSize];
            int read;

            while ((read = inputStream.Read(buffer, 0, _bufferSize)) > 0)
            {
                if (_cipherAlgorithm == CipherAlgorithm.Encrypt)
                {
                    var encryptedBuffer = Encrypt(buffer);
                    outputStream.Write(encryptedBuffer, 0, encryptedBuffer.Length);
                }
                else if (_cipherAlgorithm == CipherAlgorithm.Decrypt)
                {
                    var decryptedBuffer = Decrypt(buffer);
                    outputStream.Write(decryptedBuffer, 0, decryptedBuffer.Length);
                }
            }
        }

        private void ProcessBuffered(FileStream inputStream, FileStream outputStream)
        {
            var buffer = new byte[_bufferSize];
            int read;

            while ((read = inputStream.Read(buffer, 0, _bufferSize)) > 0)
            {
                if (_cipherAlgorithm == CipherAlgorithm.Encrypt)
                {
                    var encryptedBuffer = Encrypt(buffer);
                    outputStream.Write(encryptedBuffer, 0, encryptedBuffer.Length);
                }
                else if (_cipherAlgorithm == CipherAlgorithm.Decrypt)
                {
                    var decryptedBuffer = Decrypt(buffer);
                    outputStream.Write(decryptedBuffer, 0, decryptedBuffer.Length);
                }
            }
        }

        private byte[] Encrypt(byte[] buffer)
        {
            using var aes = new AesManaged();
            return aes.Encrypt(buffer);
        }

        private byte[] Decrypt(byte[] buffer)
        {
            using var aes = new AesManaged();
            return aes.Decrypt(buffer);
        }
    }

    public enum CipherAlgorithm
    {
        Encrypt,
        Decrypt
    }
}
