using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AdvancedRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly Dictionary<string, DistributionModel> _distributionModels = new Dictionary<string, DistributionModel>();
        private readonly List<int> _integers = new List<int>();
        private readonly List<double> _floatingPoints = new List<double>();
        private readonly List<GaussianDistribution> _gaussians = new List<GaussianDistribution>();
        private readonly Dictionary<string, BoundaryCondition> _boundaryConditions = new Dictionary<string, BoundaryCondition>();
        private readonly StringBuilder _logBuilder = new StringBuilder();

        public RandomValueGenerator()
        {
            // Initialize distribution models and boundary conditions
            _distributionModels.Add("Uniform", new UniformDistributionModel());
            _distributionModels.Add("Normal", new NormalDistributionModel());
            _boundaryConditions.Add("Inclusive", new InclusiveBoundaryCondition());
            _boundaryConditions.Add("Exclusive", new ExclusiveBoundaryCondition());
        }

        public int GenerateInteger(string distribution, string boundary)
        {
            // Validate input parameters
            if (!_distributionModels.ContainsKey(distribution))
                throw new ArgumentException($"Invalid distribution model: {distribution}");
            if (!_boundaryConditions.ContainsKey(boundary))
                throw new ArgumentException($"Invalid boundary condition: {boundary}");

            // Generate random integer value within specified range
            var distributionModel = _distributionModels[distribution];
            var boundaryCondition = _boundaryConditions[boundary];
            return distributionModel.GenerateInteger(boundaryCondition);
        }

        public double GenerateFloatingPoint(string distribution, string boundary)
        {
            // Validate input parameters
            if (!_distributionModels.ContainsKey(distribution))
                throw new ArgumentException($"Invalid distribution model: {distribution}");
            if (!_boundaryConditions.ContainsKey(boundary))
                throw new ArgumentException($"Invalid boundary condition: {boundary}");

            // Generate random floating-point value within specified range
            var distributionModel = _distributionModels[distribution];
            var boundaryCondition = _boundaryConditions[boundary];
            return distributionModel.GenerateFloatingPoint(boundaryCondition);
        }

        public GaussianDistribution GenerateGaussian(string boundary)
        {
            // Validate input parameters
            if (!_boundaryConditions.ContainsKey(boundary))
                throw new ArgumentException($"Invalid boundary condition: {boundary}");

            // Generate random Gaussian distribution within specified range
            var boundaryCondition = _boundaryConditions[boundary];
            return new GaussianDistribution(boundaryCondition);
        }

        public void LogValue(object value)
        {
            // Append log entry to internal buffer
            _logBuilder.AppendLine($"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {value}");
        }

        public override string ToString()
        {
            // Return detailed description of current range settings and applied probability distribution function parameters
            var sb = new StringBuilder();
            sb.AppendLine($"Current range settings:");
            foreach (var boundaryCondition in _boundaryConditions)
            {
                sb.AppendLine($"\t{boundaryCondition.Key}: {boundaryCondition.Value}");
            }
            sb.AppendLine($"Applied probability distribution function parameters:");
            foreach (var distributionModel in _distributionModels)
            {
                sb.AppendLine($"\t{distributionModel.Key}: {distributionModel.Value}");
            }
            return sb.ToString();
        }
    }

    public class DistributionModel
    {
        private readonly Random _random = new Random();

        public virtual int GenerateInteger(BoundaryCondition boundaryCondition)
        {
            // Generate random integer value within specified range
            var minValue = (int)boundaryCondition.Min;
            var maxValue = (int)boundaryCondition.Max;
            return _random.Next(minValue, maxValue);
        }

        public virtual double GenerateFloatingPoint(BoundaryCondition boundaryCondition)
        {
            // Generate random floating-point value within specified range
            var minValue = (double)boundaryCondition.Min;
            var maxValue = (double)boundaryCondition.Max;
            return _random.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public class UniformDistributionModel : DistributionModel
    {
        public override int GenerateInteger(BoundaryCondition boundaryCondition)
        {
            // Generate random integer value within specified range
            var minValue = (int)boundaryCondition.Min;
            var maxValue = (int)boundaryCondition.Max;
            return _random.Next(minValue, maxValue);
        }

        public override double GenerateFloatingPoint(BoundaryCondition boundaryCondition)
        {
            // Generate random floating-point value within specified range
            var minValue = (double)boundaryCondition.Min;
            var maxValue = (double)boundaryCondition.Max;
            return _random.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public class NormalDistributionModel : DistributionModel
    {
        private readonly double _mean;
        private readonly double _standardDeviation;

        public NormalDistributionModel(double mean, double standardDeviation)
        {
            // Initialize normal distribution parameters
            _mean = mean;
            _standardDeviation = standardDeviation;
        }

        public override int GenerateInteger(BoundaryCondition boundaryCondition)
        {
            // Generate random integer value within specified range
            var minValue = (int)boundaryCondition.Min;
            var maxValue = (int)boundaryCondition.Max;
            return _random.Next(minValue, maxValue);
        }

        public override double GenerateFloatingPoint(BoundaryCondition boundaryCondition)
        {
            // Generate random floating-point value within specified range
            var minValue = (double)boundaryCondition.Min;
            var maxValue = (double)boundaryCondition.Max;
            return _random.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public class GaussianDistribution
    {
        private readonly Random _random = new Random();
        private readonly double _mean;
        private readonly double _standardDeviation;

        public GaussianDistribution(BoundaryCondition boundaryCondition)
        {
            // Initialize normal distribution parameters
            _mean = (double)boundaryCondition.Min;
            _standardDeviation = (double)boundaryCondition.Max;
        }

        public double Generate()
        {
            // Generate random floating-point value within specified range
            return _random.NextDouble() * _standardDeviation + _mean;
        }
    }

    public class BoundaryCondition
    {
        private readonly object _min;
        private readonly object _max;

        public BoundaryCondition(object min, object max)
        {
            // Initialize boundary condition parameters
            _min = min;
            _max = max;
        }

        public object Min => _min;
        public object Max => _max;
    }

    public class InclusiveBoundaryCondition : BoundaryCondition
