#include <pthread.h>

// Define the structure for an element in the array
struct Element {
    double value;
    char* key;
    int counter;
    float other_value;
    bool toggle;
};

// Define a global variable to store the sum of all counters
int total_counter = 0;

// Define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize an array of structures with unique string keys, random double values within a specified range, int counters initialized to zero, and bool toggles set to false.
void init_array(struct Element* arr, int size) {
    // Initialize the mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Loop through each element in the array
    for (int i = 0; i < size; i++) {
        // Generate a unique string key for each element
        char* key = generate_key();

        // Initialize the double value within the specified range
        double value = generate_double(MIN_VALUE, MAX_VALUE);

        // Initialize the int counter to zero
        arr[i].counter = 0;

        // Initialize the float value
        arr[i].other_value = 0.0f;

        // Initialize the bool toggle to false
        arr[i].toggle = false;

        // Store the key, value, and counter in the element
        arr[i].key = key;
        arr[i].value = value;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to generate a unique string key for each element
char* generate_key() {
    // Generate a random integer between 0 and 1000
    int rand_int = rand() % 1000;

    // Convert the integer to a string
    char* str = malloc(sizeof(char) * 4);
    sprintf(str, "%d", rand_int);

    return str;
}

// Function to generate a random double value within a specified range
double generate_double(double min, double max) {
    // Generate a random integer between the minimum and maximum values
    int rand_int = rand() % (max - min + 1) + min;

    // Convert the integer to a double
    return (double)rand_int;
}

// Function to increment the counter for each element in the array
void increment_counter(struct Element* arr, int size) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Loop through each element in the array
    for (int i = 0; i < size; i++) {
        // Increment the counter for each element
        arr[i].counter++;

        // Update the total counter
        total_counter += arr[i].counter;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory allocation failures gracefully
void handle_allocation_failure() {
    // Log the allocation failure
    printf("Memory allocation failed. Shutting down system.\n");

    // Exit the program with a non-zero exit code
    exit(1);
}
```
