        exit(1);
    }
    int *key_array = malloc(sizeof(int) * 20);
    if (key_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for key array\n");
        exit(1);
    }
    struct record *record_array = malloc(sizeof(struct record) * 20);
    if (record_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        exit(1);
    }

    // Use an external memory pool manager to optimize memory usage and reduce fragmentation
