// Memory pool manager with fixed-size and variable-size blocks
struct mempool {
    void **blocks; // Array of pointers to allocated blocks
    size_t block_size; // Size of each block in bytes
    size_t num_blocks; // Number of blocks in the pool
    size_t free_blocks; // Number of free blocks in the pool
};

// Initialize memory pool manager with a fixed-size or variable-size block size
void mempool_init(struct mempool *mp, size_t block_size) {
    mp->blocks = NULL;
    mp->block_size = block_size;
    mp->num_blocks = 0;
    mp->free_blocks = 0;
}

// Allocate a new block from the memory pool
void *mempool_alloc(struct mempool *mp) {
    void *ptr = NULL;
    if (mp->free_blocks > 0) {
        ptr = mp->blocks[--mp->free_blocks];
    } else {
        size_t new_size = mp->num_blocks + 1;
        void **new_blocks = realloc(mp->blocks, new_size * sizeof(void*));
        if (new_blocks) {
            mp->blocks = new_blocks;
            ptr = malloc(mp->block_size);
            mp->num_blocks++;
        }
    }
    return ptr;
}

// Free a block back to the memory pool
void mempool_free(struct mempool *mp, void *ptr) {
    if (ptr) {
        size_t index = custom_hash(ptr) % mp->num_blocks;
        mp->blocks[index] = ptr;
        mp->free_blocks++;
    }
}

// Cryptographic library with support for AES, Camellia, MD5, SHA, and RSA
struct cryptolib {
    struct mempool *mempool; // Memory pool manager
