    int camellia_key_size; // Size of the Camellia key in bytes
    int md5_hash_size; // Size of the MD5 hash in bytes
    int sha_hash_size; // Size of the SHA hash in bytes
    int rsa_key_size; // Size of the RSA key in bits
};

