    lib->mempool = NULL;
    lib->aes_key_size = 0;
    lib->camellia_key_size = 0;
    lib->md5_hash_size = 0;
    lib->sha_hash_size = 0;
    lib->rsa_key_size = 0;
}

// Dynamically load the necessary cryptographic modules and validate their successful addition
void cryptolib_load(struct cryptolib *lib, const char *openssl_version) {
    // Load AES module
    if (lib->aes_key_size == 0) {
        lib->aes_key_size = AES_KEY_SIZE;
    }
    // Load Camellia module
    if (lib->camellia_key_size == 0) {
        lib->camellia_key_size = CAMELLIA_KEY_SIZE;
    }
    // Load MD5 module
    if (lib->md5_hash_size == 0) {
        lib->md5_hash_size = MD5_DIGEST_LENGTH;
    }
    // Load SHA module
    if (lib->sha_hash_size == 0) {
        lib->sha_hash_size = SHA_DIGEST_LENGTH;
    }
    // Load RSA module
    if (lib->rsa_key_size == 0) {
        lib->rsa_key_size = RSA_KEY_SIZE;
    }
}

// Validate the integrity of the library's cryptographic capabilities
void cryptolib_validate(struct cryptolib *lib) {
    // Check AES key size
    if (lib->aes_key_size != AES_KEY_SIZE) {
        printf("AES key size is not valid\n");
    }
    // Check Camellia key size
    if (lib->camellia_key_size != CAMELLIA_KEY_SIZE) {
        printf("Camellia key size is not valid\n");
    }
    // Check MD5 hash size
    if (lib->md5_hash_size != MD5_DIGEST_LENGTH) {
        printf("MD5 hash size is not valid\n");
    }
    // Check SHA hash size
    if (lib->sha_hash_size != SHA_DIGEST_LENGTH) {
        printf("SHA hash size is not valid\n");
    }
    // Check RSA key size
    if (lib->rsa_key_size != RSA_KEY_SIZE) {
        printf("RSA key size is not valid\n");
    }
}

