// Memory pool manager with fixed-size and variable-sized blocks
struct mempool {
    void **blocks; // array of pointers to allocated blocks
    size_t block_size; // size of each block in bytes
    size_t num_blocks; // number of blocks in the pool
    size_t free_blocks; // number of free blocks in the pool
    pthread_mutex_t lock; // mutex for synchronizing access to the pool
};

// Initialize memory pool with a specified number of blocks and block size
void mempool_init(struct mempool *pool, size_t num_blocks, size_t block_size) {
    pool->blocks = malloc(num_blocks * sizeof(void*));
    if (!pool->blocks) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        exit(1);
    }
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate a fixed-size block from the memory pool
void* mempool_alloc(struct mempool *pool) {
    void *ptr = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_blocks > 0) {
        ptr = pool->blocks[--pool->free_blocks];
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Free a fixed-size block to the memory pool
void mempool_free(struct mempool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);
    pool->blocks[pool->free_blocks++] = ptr;
    pthread_mutex_unlock(&pool->lock);
}

// Allocate a variable-size block from the memory pool
void* mempool_alloc_var(struct mempool *pool, size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_blocks > 0) {
        ptr = pool->blocks[--pool->free_blocks];
        memset(ptr, 0, size);
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Free a variable-size block to the memory pool
void mempool_free_var(struct mempool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);
    pool->blocks[pool->free_blocks++] = ptr;
    pthread_mutex_unlock(&pool->lock);
}

