    // Calculate the total allocated memory
    int total_allocated = num_keys * sizeof(Record) + num_offsets * sizeof(long);

    // Calculate the free memory
    int free_memory = get_free_memory();

    // Print the memory usage statistics
    printf("Total allocated memory: %d\n", total_allocated);
    printf("Free memory: %d\n", free_memory);
}
