    graph->vertices = (Vertex *)malloc(sizeof(Vertex) * graph->num_vertices);
    graph->edges = (Edge *)malloc(sizeof(Edge) * graph->num_edges);
}

// Function to deallocate memory for vertices and edges
void deallocateMemory(Graph *graph) {
    free(graph->vertices);
    free(graph->edges);
}

// Function to add a vertex to the graph
void addVertex(Graph *graph, int id, float x, float y, char attributes[10]) {
    Vertex *vertex = &graph->vertices[id];
    vertex->x = x;
    vertex->y = y;
    strcpy(vertex->attributes, attributes);
}

// Function to add an edge to the graph
void addEdge(Graph *graph, int src, int dst, float weight) {
    Edge *edge = &graph->edges[src];
    edge->src = src;
    edge->dst = dst;
    edge->weight = weight;
}

// Function to remove a vertex from the graph
void removeVertex(Graph *graph, int id) {
    // Remove all edges incident on the vertex
    for (int i = 0; i < graph->num_edges; i++) {
        if (graph->edges[i].src == id || graph->edges[i].dst == id) {
            removeEdge(graph, i);
        }
    }
    // Remove the vertex from the array of vertices
    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->vertices[i].id == id) {
            graph->vertices[i] = graph->vertices[--graph->num_vertices];
            break;
        }
    }
}

// Function to remove an edge from the graph
void removeEdge(Graph *graph, int id) {
    // Remove the edge from the array of edges
    for (int i = 0; i < graph->num_edges; i++) {
        if (graph->edges[i].id == id) {
            graph->edges[i] = graph->edges[--graph->num_edges];
            break;
        }
    }
}

// Function to update the coordinates of a vertex in the graph
