// Function to load the network topology from a custom binary file format
void loadTopology(Network *network, char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }
    // Read the number of nodes and edges from the file
    int num_nodes, num_edges;
    fread(&num_nodes, sizeof(int), 1, file);
    fread(&num_edges, sizeof(int), 1, file);
    // Allocate memory for the nodes and edges
    network->nodes = (Node *)malloc(sizeof(Node) * num_nodes);
    network->edges = (Edge *)malloc(sizeof(Edge) * num_edges);
    // Read the data from the file into the nodes and edges
    for (int i = 0; i < num_nodes; i++) {
        fread(&network->nodes[i], sizeof(Node), 1, file);
    }
    for (int i = 0; i < num_edges; i++) {
        fread(&network->edges[i], sizeof(Edge), 1, file);
    }
    // Close the file
    fclose(file);
}

// Function to save the network topology to a custom binary file format
void saveTopology(Network *network, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Could not open file %s\n", filename);
        return;
    }
    // Write the number of nodes and edges to the file
    int num_nodes = network->num_nodes;
    int num_edges = network->num_edges;
    fwrite(&num_nodes, sizeof(int), 1, file);
    fwrite(&num_edges, sizeof(int), 1, file);
    // Write the data from the nodes and edges to the file
    for (int i = 0; i < num_nodes; i++) {
        fwrite(&network->nodes[i], sizeof(Node), 1, file);
    }
    for (int i = 0; i < num_edges; i++) {
        fwrite(&network->edges[i], sizeof(Edge), 1, file);
    }
    // Close the file
    fclose(file);
}
