// Custom hash function for efficient data mapping and retrieval within the memory pool
uint64_t customHash(void* data) {
    uint64_t hash = 0;
    char* cdata = (char*)data;
    for (int i = 0; i < sizeof(void*); i++) {
        hash += *cdata++;
    }
    return hash % POOL_SIZE;
}

// Memory pool structure
struct memoryPool {
    void** blocks; // Array of pointers to allocated blocks
    int blockSize; // Size of each block in bytes
    int numBlocks; // Number of blocks in the pool
    int freeList; // Index of the first free block
};

// Memory pool initialization function
void initMemoryPool(struct memoryPool* pool, int blockSize) {
    pool->blockSize = blockSize;
    pool->numBlocks = POOL_SIZE / blockSize;
    pool->freeList = 0;
    for (int i = 0; i < pool->numBlocks; i++) {
        pool->blocks[i] = NULL;
    }
}

// Memory allocation function
void* allocate(struct memoryPool* pool, int size) {
    // Check if the requested size is within the bounds of a single block
    if (size > pool->blockSize) {
        return NULL;
    }

    // Find a free block that can accommodate the requested size
    for (int i = 0; i < pool->numBlocks; i++) {
        if (pool->blocks[i] == NULL) {
            continue;
        }
        void* block = pool->blocks[i];
        int blockSize = *(int*)block;
        if (blockSize >= size) {
            // Split the block into two parts: a free block and a used block
            int splitSize = blockSize - size;
            void* newBlock = (char*)block + size;
            *(int*)newBlock = splitSize;
            pool->blocks[i] = newBlock;
            return block;
        }
    }

    // No free block found, allocate a new one
    int index = pool->freeList++;
    if (index >= pool->numBlocks) {
        return NULL;
    }
    void* block = mmap(NULL, pool->blockSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (block == MAP_FAILED) {
        return NULL;
    }
    *(int*)block = pool->blockSize;
    pool->blocks[index] = block;
    return block;
}

// Memory deallocation function
void deallocate(struct memoryPool* pool, void* block) {
    // Find the index of the block in the pool
    int index = 0;
    for (int i = 0; i < pool->numBlocks; i++) {
        if (pool->blocks[i] == block) {
            index = i;
            break;
        }
    }
    if (index >= pool->numBlocks) {
        return;
    }

    // Merge the block with adjacent free blocks
    void* prevBlock = NULL;
    void* nextBlock = NULL;
    for (int i = index - 1; i >= 0; i--) {
        if (pool->blocks[i] == NULL) {
            continue;
        }
        prevBlock = pool->blocks[i];
        break;
    }
    for (int i = index + 1; i < pool->numBlocks; i++) {
        if (pool->blocks[i] == NULL) {
            continue;
        }
        nextBlock = pool->blocks[i];
        break;
    }
    if (prevBlock != NULL && nextBlock != NULL) {
        // Merge the block with adjacent free blocks
        int prevSize = *(int*)prevBlock;
        int nextSize = *(int*)nextBlock;
        void* mergedBlock = mmap(NULL, prevSize + nextSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (mergedBlock == MAP_FAILED) {
            return;
        }
        memcpy(mergedBlock, prevBlock, prevSize);
        memcpy((char*)mergedBlock + prevSize, nextBlock, nextSize);
        pool->blocks[index] = mergedBlock;
        *(int*)mergedBlock = prevSize + nextSize;
        pool->freeList--;
    } else if (prevBlock != NULL) {
        // Merge the block with the previous free block
        int prevSize = *(int*)prevBlock;
        void* mergedBlock = mmap(NULL, prevSize + pool->blockSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (mergedBlock == MAP_FAILED) {
            return;
        }
        memcpy(mergedBlock, prevBlock, prevSize);
        memcpy((char*)mergedBlock + prevSize, block, pool->blockSize);
        pool->blocks[index] = mergedBlock;
        *(int*)mergedBlock = prevSize + pool->blockSize;
        pool->freeList--;
    } else if (nextBlock != NULL) {
        // Merge the block with the next free block
        int nextSize = *(int*)nextBlock;
        void* mergedBlock = mmap(NULL, pool->blockSize + nextSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (mergedBlock == MAP_FAILED) {
            return;
        }
        memcpy(mergedBlock, block, pool->blockSize);
        memcpy((char*)mergedBlock + pool->blockSize, nextBlock, nextSize);
        pool->blocks[index] = mergedBlock;
        *(int*)mergedBlock = pool->blockSize + nextSize;
        pool->freeList--;
    } else {
        // The block is not adjacent to any free blocks, mark it as free
        pool->blocks[index] = NULL;
        pool->freeList++;
    }
}

// Memory coalescing function
void coalesce(struct memoryPool* pool) {
    int numBlocks = 0;
    for (int i = 0; i < pool->numBlocks; i++) {
        if (pool->blocks[i] != NULL) {
            numBlocks++;
        }
    }
    if (numBlocks == pool->numBlocks) {
        return;
    }

    // Find the first free block and the last used block
    int firstFree = 0;
    while (firstFree < pool->numBlocks && pool->blocks[firstFree] != NULL) {
        firstFree++;
    }
    if (firstFree == pool->numBlocks) {
        return;
    }
    int lastUsed = pool->numBlocks - 1;
    while (lastUsed >= 0 && pool->blocks[lastUsed] != NULL) {
        lastUsed--;
    }
    if (lastUsed < 0) {
        return;
    }

    // Merge the first free block with the last used block
    void* mergedBlock = mmap(NULL, *(int*)pool->blocks[firstFree] + *(int*)pool->blocks[lastUsed], PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mergedBlock == MAP_FAILED) {
        return;
    }
    memcpy(mergedBlock, pool->blocks[firstFree], *(int*)pool->blocks[firstFree]);
    memcpy((char*)mergedBlock + *(int*)pool->blocks[firstFree], pool->blocks[lastUsed], *(int*)pool->blocks[lastUsed]);
    pool->blocks[firstFree] = mergedBlock;
    *(int*)mergedBlock = *(int*)pool->blocks[firstFree] + *(int*)pool->blocks[lastUsed];
}

// Proactive memory allocation function
void proactiveAllocation(struct memoryPool* pool) {
    // Find the first free block and the last used block
    int firstFree = 0;
    while (firstFree < pool->numBlocks && pool->blocks[firstFree] != NULL) {
        firstFree++;
    }
    if (firstFree == pool->numBlocks) {
        return;
    }
    int lastUsed = pool->numBlocks - 1;
    while (lastUsed >= 0 && pool->blocks[lastUsed] != NULL) {
        lastUsed--;
    }
    if (lastUsed < 0) {
        return;
    }

    // Allocate a new block and merge it with the first free block
    void* newBlock = mmap(NULL, pool->blockSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (newBlock == MAP_FAILED) {
        return;
    }
    *(int*)newBlock = pool->blockSize;
    void* mergedBlock = mmap(NULL, *(int*)pool->blocks[firstFree] + pool->blockSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mergedBlock == MAP_FAILED) {
        return;
    }
    memcpy(mergedBlock, pool->blocks[firstFree], *(int*)pool->blocks[firstFree]);
    memcpy((char*)mergedBlock + *(int*)pool->blocks[firstFree], newBlock, pool->blockSize);
    pool->blocks[firstFree] = mergedBlock;
    *(int*)mergedBlock = *(int*)pool->blocks[firstFree] + pool->blockSize;
}

// Garbage collection function
void garbageCollect(struct memoryPool* pool) {
    // Find the first free block and the last used block
    int firstFree = 0;
    while (firstFree < pool->numBlocks && pool->blocks[firstFree] != NULL) {
        firstFree++;
    }
    if (firstFree == pool->numBlocks) {
        return;
    }
    int lastUsed = pool->numBlocks - 1;
    while (lastUsed >= 0 && pool->blocks[lastUsed] != NULL) {
        lastUsed--;
    }
    if (lastUsed < 0) {
        return;
    }

    // Reclaim unused memory blocks and merge them with adjacent free blocks
    for (int i = firstFree; i <= lastUsed; i++) {
        if (pool->blocks[i] == NULL) {
            continue;
        }
        void* block = pool->blocks[i];
        int blockSize = *(int*)block;
        munmap(block, blockSize);
        pool->blocks[i] = NULL;
    }
}

