    if (strcmp(name, "aes") == 0 || strcmp(name, "camellia") == 0) {
        EVP_remove_cipher(EVP_get_cipherbyname(name));
    }
    // Remove MD5 and SHA digests
    if (strcmp(name, "md5") == 0 || strcmp(name, "sha") == 0) {
        EVP_remove_digest(EVP_get_digestbyname(name));
    }
    // Remove RSA with SHA1
