    char *str; // Pointer to a dynamically allocated string
    int num;  // Integer field
} Record;

// Define the memory pool for managing memory allocation and reducing fragmentation
#define MEMORY_POOL_SIZE (1024*1024) // 1 MB
static char memory_pool[MEMORY_POOL_SIZE];
static int memory_pool_index = 0;

// Function to initialize a new Record structure
Record *init_record() {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->list = NULL;
    record->str = NULL;
    record->num = 0;
    return record;
}

// Function to add an integer to the linked list associated with a Record structure
int add_integer(Record *record, int value) {
    if (!record || !record->list) {
        return -1; // Invalid operation
    }
    int *new_node = (int *)malloc(sizeof(int));
    if (!new_node) {
        return -2; // Memory allocation failed
    }
    *new_node = value;
    new_node->next = record->list;
    record->list = new_node;
    return 0;
}

// Function to retrieve an integer from the linked list associated with a Record structure
int get_integer(Record *record, int index) {
    if (!record || !record->list) {
        return -1; // Invalid operation
    }
    int *current = record->list;
    for (int i = 0; i < index; i++) {
        current = current->next;
        if (!current) {
            return -2; // Index out of bounds
        }
    }
    return *current;
}

// Function to release all resources when the application terminates
void cleanup() {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (memory_pool[i]) {
            free(memory_pool[i]);
        }
    }
}

// Thread-safe function to manage memory for an array of Record structures
void manage_records(Record **records, int num_records) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        if (!record) {
            record = init_record();
            if (!record) {
                pthread_mutex_unlock(&mutex);
                return; // Memory allocation failed
            }
            records[i] = record;
        }
    }
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        if (!record->str) {
            char *new_str = (char *)malloc(sizeof(char));
            if (!new_str) {
                pthread_mutex_unlock(&mutex);
                return; // Memory allocation failed
            }
            record->str = new_str;
        }
    }
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        if (!record->list) {
            int *new_list = (int *)malloc(sizeof(int));
            if (!new_list) {
                pthread_mutex_unlock(&mutex);
                return; // Memory allocation failed
            }
            record->list = new_list;
        }
    }
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        if (!record->num) {
            record->num = 0;
        }
    }
    pthread_mutex_unlock(&mutex);
}
