        *head = new_node;
    } else {
        node_t* current = *head;
        while (current != NULL && current->level_depth <= level_depth) {
            current = current->next;
        }
        new_node->next = current;
        if (current == NULL) {
            *head = new_node;
        } else {
            current->next = new_node;
        }
    }
}

