int validate_config(const char *filename) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: %s\n", error.text);
        return -1;
    }
    // Check that the configuration file has the expected format
    if (json_object_get_int(root, "num_records") < 0) {
        fprintf(stderr, "Error: invalid num_records value\n");
        return -1;
    }
    json_decref(root);
    return 0;
