// Function to retrieve data from the network API
void *retrieve_data_from_api(void *args) {
    // Cast the args pointer to a Record structure
    Record *record = (Record *)args;
    CURL *curl;
    CURLcode res;
    char *url = "https://example.com/api";
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
            return NULL;
        }
        // Parse the JSON response and extract the value and timestamp
        json_t *root = json_loads(curl_easy_getinfo(curl, CURLINFO_RESPONSE_BODY), 0, &error);
        if (!root) {
            fprintf(stderr, "Error: %s\n", error.text);
            return NULL;
        }
        record->value = json_object_get_int(root, "value");
        record->timestamp = json_object_get_double(root, "timestamp");
        json_decref(root);
    } else {
        fprintf(stderr, "Error: failed to initialize cURL\n");
        return NULL;
    }
    curl_easy_cleanup(curl);
    return record;
}

// Function to retrieve data from the local CSV file
void *retrieve_data_from_csv(void *args) {
    // Cast the args pointer to a Record structure
    Record *record = (Record *)args;
    FILE *file = fopen("example.csv", "r");
    if (!file) {
        fprintf(stderr, "Error: failed to open CSV file\n");
        return NULL;
    }
    // Read the first line of the CSV file and extract the value and timestamp
    char *line = malloc(1024);
    if (fgets(line, 1024, file) == NULL) {
        fprintf(stderr, "Error: failed to read from CSV file\n");
        return NULL;
    }
    sscanf(line, "%d,%lf", &record->value, &record->timestamp);
    free(line);
    fclose(file);
    return record;
}

// Function to initialize the Record array
Record *init_records(const char *filename) {
    // Validate the JSON configuration file
    if (validate_config(filename) < 0) {
        fprintf(stderr, "Error: failed to validate configuration file\n");
        return NULL;
    }
    // Load the JSON configuration file and extract the number of records
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: %s\n", error.text);
        return NULL;
    }
    int num_records = json_object_get_int(root, "num_records");
    json_decref(root);
    // Allocate memory for the Record array
    Record *records = malloc(sizeof(Record) * num_records);
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        return NULL;
    }
    // Initialize each Record structure with default values
    for (int i = 0; i < num_records; i++) {
        records[i].value = 0;
        records[i].timestamp = 0.0;
        records[i].status = 'N';
    }
    // Retrieve data from the network API and local CSV file in parallel
    pthread_t threads[2];
    void *args[2] = {&records[0], &records[1]};
    if (pthread_create(&threads[0], NULL, retrieve_data_from_api, args[0]) != 0) {
        fprintf(stderr, "Error: failed to create thread\n");
        return NULL;
    }
    if (pthread_create(&threads[1], NULL, retrieve_data_from_csv, args[1]) != 0) {
        fprintf(stderr, "Error: failed to create thread\n");
        return NULL;
    }
    // Wait for both threads to complete
    if (pthread_join(threads[0], NULL) != 0) {
        fprintf(stderr, "Error: failed to join thread\n");
        return NULL;
    }
    if (pthread_join(threads[1], NULL) != 0) {
        fprintf(stderr, "Error: failed to join thread\n");
        return NULL;
    }
    // Return a pointer to the initialized Record array
    return records;
}

// Function to free memory allocated by init_records()
void free_records(Record *records) {
    if (records) {
        free(records);
    }
}
