void* load_records(int num_files) {
    // Initialize the cache and the memory usage statistics
    void** cache = malloc(sizeof(void*) * CACHE_SIZE);
    MemoryUsageStats stats;
    stats.total_memory = 0;
    stats.used_memory = 0;

    // Iterate over each input file and read its records
    for (int i = 0; i < num_files; i++) {
        Schema* schema = &input_files[i];
        FILE* file = fopen(schema->filename, "r");
        if (!file) {
            // Handle the case where the file fails to load completely
            printf("Error: failed to open file %s\n", schema->filename);
            continue;
        }

        // Read the records from the file and validate them against the predefined schema
        while (1) {
            Record* record = malloc(sizeof(Record));
            if (!record) {
                printf("Error: failed to allocate memory for record\n");
                break;
            }
            stats.total_memory += sizeof(Record);
            stats.used_memory += sizeof(Record);
            cache[stats.used_memory] = record;

            // Read the record from the file and validate it against the schema
            if (fread(&record->value, sizeof(int), 1, file) != 1 || fread(&record->timestamp, sizeof(double), 1, file) != 1 || fread(&record->status, sizeof(char), 1, file) != 1) {
                // Handle the case where the record fails to load completely
                printf("Error: failed to read record from file %s\n", schema->filename);
                free(record);
                break;
            }
            if (record->value < schema->offset || record->timestamp < 0.0 || record->status != 'N') {
                // Handle the case where the record is invalid according to the schema
                printf("Error: invalid record in file %s\n", schema->filename);
                free(record);
                break;
            }
        }
    }

    // Merge the records from all input files into a single sorted list based on the timestamp field
    qsort(cache, stats.used_memory, sizeof(Record), compare_records);

    // Return the merged records and the memory usage statistics
    return cache;
}

// Define the function to compare two records based on their timestamps
int compare_records(const void* a, const void* b) {
    Record* record1 = (Record*)a;
    Record* record2 = (Record*)b;
