#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define task structure
typedef struct Task {
    char *description;
    int priority;
    long execution_time;
} Task;

// Define task collection structure
typedef struct TaskCollection {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} TaskCollection;

// Initialize task collection with given capacity
void initTaskCollection(TaskCollection *collection, size_t capacity) {
    // Allocate memory for tasks array
    collection->tasks = (Task **)malloc(capacity * sizeof(Task *));
    if (!collection->tasks) {
        fprintf(stderr, "Failed to allocate memory for task collection\n");
        exit(1);
    }

    // Initialize mutex and semaphore
    pthread_mutex_init(&collection->mutex, NULL);
    semaphore_init(&collection->semaphore, 0, SEM_UNDO);

    // Set capacity and count to zero
    collection->capacity = capacity;
    collection->count = 0;
}

// Insert task into task collection
void insertTask(TaskCollection *collection, Task *task) {
    // Acquire mutex lock
    pthread_mutex_lock(&collection->mutex);

    // Check if capacity is reached
    if (collection->count == collection->capacity) {
        fprintf(stderr, "Task collection capacity reached\n");
        exit(1);
    }

    // Insert task into tasks array
    collection->tasks[collection->count++] = task;

    // Release mutex lock
    pthread_mutex_unlock(&collection->mutex);
}

// Remove task from task collection
void removeTask(TaskCollection *collection, Task *task) {
    // Acquire mutex lock
    pthread_mutex_lock(&collection->mutex);

    // Find index of task in tasks array
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (task == collection->tasks[i]) {
            break;
        }
    }

    // Check if task was found
    if (i == collection->count) {
        fprintf(stderr, "Task not found in task collection\n");
        exit(1);
    }

    // Remove task from tasks array
    for (size_t j = i; j < collection->count - 1; j++) {
        collection->tasks[j] = collection->tasks[j + 1];
    }
    collection->count--;

    // Release mutex lock
    pthread_mutex_unlock(&collection->mutex);
}

// Update task in task collection
void updateTask(TaskCollection *collection, Task *task) {
    // Acquire mutex lock
    pthread_mutex_lock(&collection->mutex);

    // Find index of task in tasks array
    size_t i;
    for (i = 0; i < collection->count; i++) {
        if (task == collection->tasks[i]) {
            break;
        }
    }

    // Check if task was found
    if (i == collection->count) {
        fprintf(stderr, "Task not found in task collection\n");
        exit(1);
    }

    // Update task in tasks array
    collection->tasks[i] = task;

    // Release mutex lock
    pthread_mutex_unlock(&collection->mutex);
}

// Sort tasks based on priority and scheduled execution time
void sortTasks(TaskCollection *collection) {
    // Acquire semaphore lock
    semaphore_wait(&collection->semaphore);

    // Sort tasks array using custom sorting algorithm
    qsort(collection->tasks, collection->count, sizeof(Task *), compareTasks);

    // Release semaphore lock
    semaphore_post(&collection->semaphore);
}

// Compare two tasks based on priority and scheduled execution time
int compareTasks(const void *a, const void *b) {
    Task *task1 = (Task *)a;
    Task *task2 = (Task *)b;

    // Compare priority levels
    if (task1->priority != task2->priority) {
        return task1->priority - task2->priority;
    }

    // Compare scheduled execution times
    if (task1->execution_time != task2->execution_time) {
        return task1->execution_time - task2->execution_time;
    }

    // Tasks are equal
    return 0;
}
