    while (!feof(fp)) {
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), fp);
        if (bytes_read == 0) {
            break;
        }

        // Parse the contents of the buffer and generate an optimized output file
        for (int i = 0; i < bytes_read; i++) {
            char c = buffer[i];
            if (c == 'a') {
                fputc('A', out);
            } else if (c == 'b') {
                fputc('B', out);
            } else if (c == 'c') {
                fputc('C', out);
            }
        }
    }

    // Close the input and output files
    fclose(fp);
    fclose(out);
}
