    // An array of free block pointers
    void** free_blocks;
};

// Define the function to allocate memory for the arrays
void* allocate_array(size_t size) {
    // Validate the input size
    if (size < 100 || size > 1000000) {
        fprintf(stderr, "Invalid array size: %zu\n", size);
        return NULL;
    }

    // Allocate memory for the arrays
    long* offset_array = (long*)malloc(size * sizeof(long));
    int* key_array = (int*)malloc(size * sizeof(int));

    // Check for allocation failures
    if (!offset_array || !key_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset_array);
        free(key_array);
        return NULL;
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offset_array[i] = rand() % 1000000;
        key_array[i] = rand() % 1000000;
    }

    // Return the arrays
    return (void*)offset_array;
}

// Define the function to allocate memory for the record array
Record* allocate_record_array(size_t size) {
    // Validate the input size
    if (size < 100 || size > 1000000) {
        fprintf(stderr, "Invalid record array size: %zu\n", size);
        return NULL;
    }

    // Allocate memory for the record array
    Record* record_array = (Record*)malloc(size * sizeof(Record));

    // Check for allocation failures
    if (!record_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(record_array);
        return NULL;
    }

    // Initialize the record array with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        record_array[i].key = rand() % 1000000;
    }

    // Return the record array
    return record_array;
}

// Define the function to populate the arrays with random values
void populate_arrays(long* offset_array, int* key_array, size_t size) {
    // Validate the input size
    if (size < 100 || size > 1000000) {
        fprintf(stderr, "Invalid array size: %zu\n", size);
        return;
    }

    // Populate the arrays with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offset_array[i] = rand() % 1000000;
        key_array[i] = rand() % 1000000;
    }
}

// Define the function to clear all allocated resources and reset the memory pool
void clear_resources(struct MemoryPoolManager* manager) {
    // Check if the manager is NULL
    if (!manager) {
        return;
    }

    // Free the memory for the arrays
    free(manager->offset_array);
    free(manager->key_array);

    // Reset the memory pool manager
    manager->total_memory = 0;
    manager->num_free_blocks = 0;
    manager->free_blocks = NULL;
}
