    }

    // Allocate memory for the float array
    float *floats = (float *)malloc(num_floats * sizeof(float));
    if (!floats) {
        printf("Error: Failed to allocate memory for floats\n");
        free(ints);
        return;
    }

    // Initialize the float array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_floats; i++) {
        floats[i] = rand() % 100 + 1.0;
    }

    // Allocate memory for the string array
    char **strings = (char **)malloc(num_strings * sizeof(char *));
    if (!strings) {
        printf("Error: Failed to allocate memory for strings\n");
