    if (num_ints < 0 || num_floats < 0 || num_strings < 0) {
        printf("Error: Invalid input\n");
        return;
    }

    // Allocate memory for the arrays and initialize them with random values within a specified range
    allocate_memory(num_ints, num_floats, num_strings);
}

// Function to allocate memory for an array of record structures
