    pthread_mutex_t *mutexes = (pthread_mutex_t *)malloc(num_records * sizeof(pthread_mutex_t));
    if (!mutexes) {
        printf("Error: Failed to allocate memory for mutexes\n");
        return;
    }

    // Initialize each mutex with a unique value
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

// Function to report the current memory usage statistics, including total allocated memory, free memory, and memory pool utilization
void report_memory_usage() {
    // Calculate the total amount of memory allocated for the record array
    int total_allocated = num_records * sizeof(record);

    // Calculate the amount of free memory available in the system
    int free_memory = 0;
    struct sysinfo info;
    if (sysinfo(&info) == 0) {
        free_memory = info.freeram * info.mem_unit;
    }

    // Calculate the amount of memory pool utilization
    int pool_utilization = 0;
    for (int i = 0; i < num_records; i++) {
        pool_utilization += records[i].str - (char *)malloc(10 * sizeof(char));
    }

    // Print the memory usage statistics
    printf("Total allocated memory: %d bytes\n", total_allocated);
    printf("Free memory available: %d bytes\n", free_memory);
    printf("Memory pool utilization: %d%%\n", pool_utilization * 100 / total_allocated);
}

// Function to clear all allocated resources and reset the memory pool, enabling the function to be reused effectively without leaving memory leaks or resource contention issues
void clear_resources() {
    // Free each record in the array
    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
    }

    // Free the record array
    free(records);

    // Reset the memory pool utilization to zero
    pool_utilization = 0;
}
