#include <zstd.h>

// Define the compression algorithms supported by the library
enum CompressionAlgorithm {
    ZLIB,
    LZ4,
    ZSTD
};

// Define the compression presets for different file formats
struct CompressionPreset {
    enum CompressionAlgorithm algorithm;
    int level;
};

// Define the compression context structure
struct CompressionContext {
    enum CompressionAlgorithm algorithm;
    void* ctx; // Context pointer for the selected algorithm
};

// Define the decompression context structure
struct DecompressionContext {
    enum CompressionAlgorithm algorithm;
    void* ctx; // Context pointer for the selected algorithm
};

// Initialize the compression context with the specified algorithm and level
int init_compression(struct CompressionContext* ctx, enum CompressionAlgorithm algorithm, int level) {
    switch (algorithm) {
        case ZLIB:
            ctx->ctx = zlib_init(level);
            break;
        case LZ4:
            ctx->ctx = lz4_init(level);
            break;
        case ZSTD:
            ctx->ctx = zstd_init(level);
            break;
    }
    return 0;
}

// Initialize the decompression context with the specified algorithm and level
int init_decompression(struct DecompressionContext* ctx, enum CompressionAlgorithm algorithm, int level) {
    switch (algorithm) {
        case ZLIB:
            ctx->ctx = zlib_init(level);
            break;
        case LZ4:
            ctx->ctx = lz4_init(level);
            break;
        case ZSTD:
            ctx->ctx = zstd_init(level);
            break;
    }
    return 0;
}

// Compress the input data using the specified compression context and preset
int compress(struct CompressionContext* ctx, const void* input, size_t length, void** output) {
    switch (ctx->algorithm) {
        case ZLIB:
            *output = zlib_compress(ctx->ctx, input, length);
            break;
        case LZ4:
            *output = lz4_compress(ctx->ctx, input, length);
            break;
        case ZSTD:
            *output = zstd_compress(ctx->ctx, input, length);
            break;
    }
    return 0;
}

// Decompress the input data using the specified decompression context and preset
int decompress(struct DecompressionContext* ctx, const void* input, size_t length, void** output) {
    switch (ctx->algorithm) {
        case ZLIB:
            *output = zlib_decompress(ctx->ctx, input, length);
            break;
        case LZ4:
            *output = lz4_decompress(ctx->ctx, input, length);
            break;
        case ZSTD:
            *output = zstd_decompress(ctx->ctx, input, length);
            break;
    }
    return 0;
}

// Free the memory allocated for the compression context and decompression context
void free_context(struct CompressionContext* ctx) {
    switch (ctx->algorithm) {
        case ZLIB:
            zlib_free(ctx->ctx);
            break;
        case LZ4:
            lz4_free(ctx->ctx);
            break;
        case ZSTD:
            zstd_free(ctx->ctx);
            break;
    }
}

// Main function for testing the compression library
int main() {
    // Initialize the compression context with the specified algorithm and level
    struct CompressionContext ctx;
    init_compression(&ctx, ZLIB, 9);

    // Allocate memory for the input data
    size_t length = 1024 * 1024;
    void* input = malloc(length);
    assert(input != NULL);

    // Compress the input data using the specified compression context and preset
    void* output;
    compress(&ctx, input, length, &output);

    // Decompress the compressed data using the specified decompression context and preset
    struct DecompressionContext dctx;
    init_decompression(&dctx, ZLIB, 9);
    void* decompressed = malloc(length);
    assert(decompressed != NULL);
    decompress(&dctx, output, length, &decompressed);

    // Free the memory allocated for the compression context and decompression context
    free_context(&ctx);

    return 0;
}
