#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Memory pool manager
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* memory;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->memory = malloc(capacity);
}

void* allocateMemory(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* memory = pool->memory + pool->used;
    pool->used += size;
    return memory;
}

void deallocateMemory(struct MemoryPool* pool, void* memory) {
    if (memory < pool->memory || memory >= pool->memory + pool->capacity) {
        return;
    }
    size_t offset = (char*)memory - (char*)pool->memory;
    pool->used -= offset;
}

// Data structures
struct data_point {
    double value;
    char* string;
};

void initDataPoints(struct data_point* points, size_t count) {
    for (size_t i = 0; i < count; i++) {
        points[i].value = 0.0;
        points[i].string = NULL;
    }
}

void populateDataPoints(struct data_point* points, size_t count) {
    for (size_t i = 0; i < count; i++) {
        points[i].value = generateRandomNumber();
        points[i].string = generateRandomString();
    }
}

void freeDataPoints(struct data_point* points, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (points[i].string != NULL) {
            free(points[i].string);
        }
    }
}

// Random number generation
double generateRandomNumber() {
    return (double)(rand() % 1000) / 1000;
}

char* generateRandomString() {
    char* string = malloc(16);
    for (size_t i = 0; i < 16; i++) {
        string[i] = 'a' + rand() % 26;
    }
    return string;
}

// Concurrency control
void initConcurrencyControl(struct MemoryPool* pool) {
    pthread_mutex_init(&pool->lock, NULL);
}

void acquireLock(struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
}

void releaseLock(struct MemoryPool* pool) {
    pthread_mutex_unlock(&pool->lock);
}

// Performance optimization
void optimizeMemoryAllocation(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity - pool->used) {
        return;
    }
    void* memory = allocateMemory(pool, size);
    if (memory == NULL) {
        return;
    }
    memset(memory, 0, size);
}

void optimizeDataPointAllocation(struct data_point* points, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (points[i].string != NULL) {
            free(points[i].string);
            points[i].string = NULL;
        }
    }
}

// Resource reporting
void reportMemoryUsage(struct MemoryPool* pool) {
    printf("Total allocated memory: %zu\n", pool->capacity);
    printf("Free memory: %zu\n", pool->capacity - pool->used);
    printf("Memory pool utilization: %zu%%\n", (pool->used * 100) / pool->capacity);
}

// Resource cleanup
void clearResources(struct MemoryPool* pool, struct data_point* points) {
    freeDataPoints(points, count);
    deallocateMemory(pool, pool->memory);
    pthread_mutex_destroy(&pool->lock);
}
```
This code implements the required functionality for managing numerical and textual data using a limited resource environment. The memory pool manager is used to optimize performance and minimize fragmentation by allocating memory in large blocks and reusing existing memory blocks where possible. The `data_point` structure is defined to store a single floating-point value and a string pointer, and the function `initDataPoints()` initializes an array of these structures with default values. The function `populateDataPoints()` populates each data point with a random floating-point number within a specified range and a random string. The function `freeDataPoints()` frees all allocated memory for the data points.

