#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the memory pool structure
typedef struct MemoryPool {
    size_t blockSize; // Size of each memory block in bytes
    size_t maxCapacity; // Maximum capacity of the memory pool in blocks
    size_t numBlocks; // Number of available memory blocks
    size_t numAllocations; // Number of active allocations
    void **blocks; // Array of pointers to allocated memory blocks
    sem_t *semaphore; // Semaphore for synchronizing access to the memory pool
} MemoryPool;

// Define the memory allocation structure
typedef struct MemoryAllocation {
    size_t blockSize; // Size of the memory block in bytes
    void *block; // Pointer to the allocated memory block
    int nodeID; // ID of the node that made the allocation
} MemoryAllocation;

// Initialize a memory pool with the given parameters
void initMemoryPool(MemoryPool *pool, size_t blockSize, size_t maxCapacity) {
    pool->blockSize = blockSize;
    pool->maxCapacity = maxCapacity;
    pool->numBlocks = 0;
    pool->numAllocations = 0;
    pool->blocks = malloc(sizeof(void *) * maxCapacity);
    for (size_t i = 0; i < maxCapacity; i++) {
        pool->blocks[i] = NULL;
    }
    pool->semaphore = sem_open("memory_pool", O_CREAT, 0644, 1);
}

// Allocate a memory block from the memory pool
void *allocMemory(MemoryPool *pool, size_t blockSize) {
    // Check if there is enough capacity in the pool to allocate the requested block
    if (pool->numBlocks + 1 > pool->maxCapacity) {
        return NULL;
    }

    // Acquire the semaphore to synchronize access to the memory pool
    sem_wait(pool->semaphore);

    // Find a free block in the pool that matches the requested size
    for (size_t i = 0; i < pool->maxCapacity; i++) {
        if (pool->blocks[i] == NULL && pool->blockSize == blockSize) {
            pool->numBlocks++;
            pool->numAllocations++;
            return pool->blocks[i];
        }
    }

    // If no free block is found, allocate a new one and add it to the pool
    void *newBlock = malloc(blockSize);
    if (newBlock == NULL) {
        sem_post(pool->semaphore);
        return NULL;
    }
    pool->numBlocks++;
    pool->numAllocations++;
    pool->blocks[pool->numBlocks - 1] = newBlock;

    // Release the semaphore and return the allocated block
    sem_post(pool->semaphore);
    return newBlock;
}

// Free a memory block from the memory pool
void freeMemory(MemoryPool *pool, void *block) {
    // Acquire the semaphore to synchronize access to the memory pool
    sem_wait(pool->semaphore);

    // Find the index of the given block in the pool and mark it as free
    for (size_t i = 0; i < pool->maxCapacity; i++) {
        if (pool->blocks[i] == block) {
            pool->numBlocks--;
            pool->numAllocations--;
            pool->blocks[i] = NULL;
            break;
        }
    }

    // Release the semaphore and free the given block
    sem_post(pool->semaphore);
    free(block);
}

// Main function for testing the memory pool
int main() {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    initMemoryPool(pool, 1024, 1000);

    // Allocate and free a few blocks from the pool
    void *block1 = allocMemory(pool, 512);
    void *block2 = allocMemory(pool, 1024);
    freeMemory(pool, block1);
    freeMemory(pool, block2);

    // Print the number of available blocks in the pool
    printf("Number of available blocks: %zu\n", pool->numBlocks);

    // Clean up and exit
    sem_close(pool->semaphore);
    free(pool);
    return 0;
}
```
This code implements a flexible memory allocation system for a high-throughput distributed processing platform. The system supports both fixed-size and variable-size memory blocks, with each allocation uniquely identified and managed across multiple nodes. The initialization routine allows configuring memory pools with parameters such as block size, maximum capacity, and a customizable timeout for synchronization operations.

