void register_buffer(struct MemoryPool* pool, void* buffer) {
    if (pool == NULL || buffer == NULL) {
        fprintf(stderr, "Error: Invalid arguments for registering buffer\n");
        return;
    }
    pool->buffers[pool->num_buffers++] = buffer;
}

// Function to allocate a buffer from the memory pool manager
void* alloc_buffer(struct MemoryPool* pool) {
    if (pool == NULL) {
        fprintf(stderr, "Error: Invalid arguments for allocating buffer\n");
        return NULL;
    }
    if (pool->free_buffers > 0) {
        void* buffer = pool->buffers[--pool->free_buffers];
        return buffer;
    } else {
        fprintf(stderr, "Error: No free buffers available in memory pool\n");
        return NULL;
    }
}

// Function to deallocate a buffer from the memory pool manager
void dealloc_buffer(struct MemoryPool* pool, void* buffer) {
    if (pool == NULL || buffer == NULL) {
        fprintf(stderr, "Error: Invalid arguments for deallocating buffer\n");
        return;
    }
    int i = 0;
    while (i < pool->num_buffers && pool->buffers[i] != buffer) {
        i++;
    }
    if (i == pool->num_buffers) {
        fprintf(stderr, "Error: Buffer not found in memory pool\n");
        return;
    } else {
        pool->buffers[i] = pool->buffers[--pool->num_buffers];
        pool->free_buffers++;
    }
}

