// Initialize the memory pool manager
void mempool_init(struct mempool_manager *m, size_t block_size) {
    m->blocks = malloc(sizeof(void *) * 1024);
    m->num_blocks = 0;
    m->block_size = block_size;
    pthread_mutex_init(&m->mutex, NULL);
}

// Allocate a new block from the memory pool manager
void *mempool_alloc(struct mempool_manager *m) {
    void *ptr = malloc(m->block_size);
    if (ptr == NULL) {
        return NULL;
    }
    pthread_mutex_lock(&m->mutex);
    m->blocks[m->num_blocks++] = ptr;
    pthread_mutex_unlock(&m->mutex);
    return ptr;
}

// Free a block from the memory pool manager
