    int i;
    for (i = 0; i < m->num_blocks; i++) {
        if (m->blocks[i] == ptr) {
            break;
        }
    }
    if (i == m->num_blocks) {
        free(ptr);
    } else {
        pthread_mutex_lock(&m->mutex);
        m->blocks[i] = NULL;
        pthread_mutex_unlock(&m->mutex);
