#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent a task
typedef struct {
    char *name;
    int priority;
    void *metadata;
} task_t;

// Define a linked list node for the tasks
typedef struct task_node {
    task_t *task;
    struct task_node *next;
} task_node_t;

// Define a memory pool manager to optimize memory usage and reduce fragmentation
typedef struct {
    size_t total_size;
    size_t free_size;
    task_node_t *head;
    pthread_mutex_t mutex;
} mempool_manager_t;

// Define a custom hash function to map tasks to memory blocks within the pool
unsigned long hash(task_t *task) {
    // Implement a custom hash function that takes into account the task's name and priority
    return (unsigned long)(task->name + task->priority);
}

// Initialize the memory pool manager with a given size
void mempool_init(mempool_manager_t *manager, size_t size) {
    // Allocate memory for the linked list of tasks and initialize it
    manager->head = (task_node_t *)malloc(sizeof(task_node_t));
    manager->head->next = NULL;

    // Initialize the total and free sizes to the given size
    manager->total_size = size;
    manager->free_size = size;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&manager->mutex, NULL);
}

// Allocate memory for a task and register it with the memory pool manager
void *mempool_alloc(mempool_manager_t *manager, size_t size) {
    // Check if there is enough free memory in the pool to allocate the given size
    if (manager->free_size < size) {
        return NULL;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Find a suitable block of memory within the pool to allocate from
    task_node_t *current = manager->head;
    while (current != NULL && current->next != NULL) {
        if (current->next->free_size >= size) {
            break;
        }
        current = current->next;
    }

    // If no suitable block was found, return NULL
    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    // Allocate memory from the suitable block and update the free size
    void *ptr = current->next->data;
    current->next->free_size -= size;
    manager->free_size -= size;

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);

    return ptr;
}

// Free memory for a task and update the memory pool statistics
void mempool_free(mempool_manager_t *manager, void *ptr) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Find the block of memory that contains the given pointer
    task_node_t *current = manager->head;
    while (current != NULL && current->next != NULL) {
        if (current->next->data == ptr) {
            break;
        }
        current = current->next;
    }

    // If the block was not found, return
    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Update the free size and unlock the mutex
    manager->free_size += current->next->free_size;
    current->next->free_size = 0;
    pthread_mutex_unlock(&manager->mutex);
}

// Insert a task into the linked list and register it with the memory pool manager
void insert_task(mempool_manager_t *manager, task_t *task) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Allocate memory for the task and register it with the memory pool manager
    void *ptr = mempool_alloc(manager, sizeof(task_t));
    if (ptr == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Copy the task data into the allocated memory
    memcpy(ptr, task, sizeof(task_t));

    // Create a new node for the task and insert it into the linked list
    task_node_t *new_node = (task_node_t *)malloc(sizeof(task_node_t));
    new_node->task = (task_t *)ptr;
    new_node->next = manager->head;
    manager->head = new_node;

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Remove a task from the linked list and deregister it with the memory pool manager
void remove_task(mempool_manager_t *manager, task_t *task) {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Find the node that contains the given task and remove it from the linked list
    task_node_t *current = manager->head;
    while (current != NULL && current->next != NULL) {
        if (current->task == task) {
            break;
        }
        current = current->next;
    }

    // If the node was not found, return
    if (current == NULL || current->next == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Deregister the task with the memory pool manager and free its memory
    mempool_free(manager, current->task);
    free(current->next);
    current->next = NULL;

    // Unlock the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Print the current memory usage statistics for the memory pool manager
void print_mempool_stats(mempool_manager_t *manager) {
    printf("Total allocated memory: %zu\n", manager->total_size);
    printf("Free memory: %zu\n", manager->free_size);
}
