        if (pool_manager->is_registered(&data_points[i])) {
            available_free += sizeof(data_point);
        }
    }
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Available free memory: %zu\n", available_free);
    printf("Memory pool state: %s\n", pool_manager->is_empty() ? "empty" : "not empty");

    // Implement a cleanup routine to release all allocated resources and reset the memory pool, preparing it for future operations
    for (int i = 0; i < num_data_points; i++) {
        pool_manager->deallocate(&data_points[i]);
    }
    free(doubles);
    free(strings);
    free(data_points);
}
