    size_t poolSize;

    // The number of free blocks in the pool
    size_t numFreeBlocks;

    // The list of free blocks in the pool
    struct FreeBlock *freeBlocks;
};

// Define a free block structure
struct FreeBlock {
    // The address of the free block
    void *address;

    // The size of the free block in bytes
    size_t size;

    // The next free block in the list
    struct FreeBlock *next;
};

// Define a function to allocate memory from the pool manager
void *allocateMemory(struct MemoryPoolManager *manager, size_t size) {
    // Check if there are any free blocks available
    if (manager->numFreeBlocks > 0) {
        // Get the first free block in the list
        struct FreeBlock *freeBlock = manager->freeBlocks;

        // Remove the free block from the list
        manager->freeBlocks = freeBlock->next;
        manager->numFreeBlocks--;

        // Return the address of the free block
        return freeBlock->address;
    } else {
        // If there are no free blocks available, allocate a new block from the system
        void *address = malloc(size);

        // Check if the allocation was successful
        if (address == NULL) {
            // If the allocation failed, return an error status
            return NULL;
        } else {
            // If the allocation was successful, register the block with the pool manager
            struct FreeBlock *freeBlock = malloc(sizeof(struct FreeBlock));
            freeBlock->address = address;
            freeBlock->size = size;
            freeBlock->next = NULL;

            // Add the new free block to the list of free blocks
            if (manager->numFreeBlocks == 0) {
                manager->freeBlocks = freeBlock;
            } else {
                struct FreeBlock *lastFreeBlock = manager->freeBlocks;
                while (lastFreeBlock->next != NULL) {
                    lastFreeBlock = lastFreeBlock->next;
                }
                lastFreeBlock->next = freeBlock;
            }
            manager->numFreeBlocks++;

            // Return the address of the new block
            return address;
        }
    }
}

// Define a function to deallocate memory from the pool manager
void deallocateMemory(struct MemoryPoolManager *manager, void *address) {
    // Check if the address is in the list of free blocks
    struct FreeBlock *freeBlock = manager->freeBlocks;
    while (freeBlock != NULL) {
        if (freeBlock->address == address) {
            // If the address is in the list, remove it from the list and return
            struct FreeBlock *nextFreeBlock = freeBlock->next;
            free(freeBlock);
            manager->numFreeBlocks--;
            return;
        }
        freeBlock = freeBlock->next;
    }

    // If the address is not in the list, deallocate it from the system
    free(address);
}

