// Define a struct to represent a record with a long value and an int key
typedef struct {
    long value;
    int key;
} Record;

// Define a struct to represent the dynamic collection of records
typedef struct {
    Record* records; // Pointer to an array of Records
    size_t capacity; // Capacity of the array
    size_t size; // Current number of elements in the array
} RecordCollection;

// Function to allocate and initialize a new record with a random key
Record* create_record(long value) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        return NULL;
    }
    record->value = value;
    record->key = rand(); // Use a random seed based on the current time to ensure consistent but varying random values across function calls
    return record;
}

// Function to allocate and initialize a new collection of records with a given capacity
RecordCollection* create_collection(size_t capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) {
        return NULL;
    }
    collection->records = malloc(capacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->size = 0;
    return collection;
}

// Function to add a new record to the collection, growing the array if necessary
void add_record(RecordCollection* collection, long value) {
    // Check if the array needs to be grown
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            return; // Reallocation failed, do not add the record
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    Record* record = create_record(value);
    if (record == NULL) {
        return; // Record creation failed, do not add the record
    }
    collection->records[collection->size++] = *record;
}

// Function to update a record in the collection by its key
void update_record(RecordCollection* collection, int key, long value) {
    // Find the index of the record with the given key
    size_t i;
    for (i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            break;
        }
    }
    // If the record was not found, do nothing
    if (i == collection->size) {
        return;
    }
    // Update the value of the record and return
    collection->records[i].value = value;
}

// Function to free all memory allocated by the collection
void destroy_collection(RecordCollection* collection) {
    if (collection == NULL) {
        return;
    }
    for (size_t i = 0; i < collection->size; i++) {
        free(&collection->records[i]);
    }
    free(collection->records);
    free(collection);
}
```
