typedef struct Record {
    int value;
    char *str;
} Record;

// Define a linked list node to store records
typedef struct Node {
    Record record;
    struct Node *next;
} Node;

// Function to insert a new record into the linked list
void insertRecord(int value, char *str) {
    // Create a new node for the record
    Node *newNode = malloc(sizeof(Node));
    newNode->record.value = value;
    newNode->record.str = strdup(str);

    // Insert the new node into the linked list in sorted order
    Node **current = &head;
    while (*current != NULL && (*current)->record.value < value) {
        current = &(*current)->next;
    }
    newNode->next = *current;
    *current = newNode;
}

// Function to delete a record from the linked list
void deleteRecord(int value) {
    // Find the node containing the record with the given value
    Node **current = &head;
    while (*current != NULL && (*current)->record.value != value) {
        current = &(*current)->next;
    }

    // If the node is found, delete it from the linked list
    if (*current != NULL) {
        Node *nodeToDelete = *current;
        *current = nodeToDelete->next;
        free(nodeToDelete);
    }
}

// Function to traverse the linked list and print each record's details
void traverseList() {
    // Start at the head of the linked list
    Node *current = head;

    // Traverse the linked list and print each record's details
    while (current != NULL) {
        printf("Record: %d, %s\n", current->record.value, current->record.str);
        current = current->next;
    }
}

// Function to free all memory allocated for the linked list
void freeList() {
    // Start at the head of the linked list and traverse it
    Node *current = head;
    while (current != NULL) {
        Node *nodeToFree = current;
        current = current->next;
        free(nodeToFree);
    }
}
