// Define a struct to represent a record in the collection
typedef struct Record {
    int key;
    long offset;
    char identifier;
} Record;

// Define a struct to represent the dynamic data structure
typedef struct Collection {
    Record *records; // Array of records
    size_t capacity; // Capacity of the array
    size_t count; // Number of records in the collection
    LinkedList *linkedList; // Linked list for efficient insertion and deletion
} Collection;

// Define a function to allocate memory for the records, keys, and offsets
Collection* allocateMemory(size_t capacity) {
    Collection *collection = malloc(sizeof(Collection));
    if (collection == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    collection->records = malloc(capacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        // Handle memory allocation failure
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    collection->linkedList = createLinkedList();
    if (collection->linkedList == NULL) {
        free(collection->records);
        free(collection);
        // Handle memory allocation failure
        return NULL;
    }
    return collection;
}

// Define a function to initialize the keys sequentially and populate the offsets with random values
void initKeysAndOffsets(Collection *collection) {
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < collection->capacity; i++) {
        collection->records[i].key = i + 1;
        collection->records[i].offset = rand() % MAX_OFFSET;
    }
}

// Define a function to implement a linked list for efficient insertion and deletion
LinkedList* createLinkedList() {
    LinkedList *linkedList = malloc(sizeof(LinkedList));
    if (linkedList == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    linkedList->head = NULL;
    linkedList->tail = NULL;
    linkedList->count = 0;
    return linkedList;
}

// Define a function to insert a record into the collection
void insertRecord(Collection *collection, Record *record) {
    if (collection->count == collection->capacity) {
        // Handle capacity limit reached
        return;
    }
    LinkedListNode *node = malloc(sizeof(LinkedListNode));
    if (node == NULL) {
        // Handle memory allocation failure
        return;
    }
    node->record = record;
    node->next = NULL;
    if (collection->linkedList->tail == NULL) {
        collection->linkedList->head = node;
        collection->linkedList->tail = node;
    } else {
        collection->linkedList->tail->next = node;
        collection->linkedList->tail = node;
    }
    collection->count++;
}

// Define a function to delete a record from the collection
void deleteRecord(Collection *collection, int key) {
    if (collection->count == 0) {
        // Handle empty collection
        return;
    }
    LinkedListNode *node = collection->linkedList->head;
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle record not found
        return;
    }
    LinkedListNode *prev = NULL;
    while (node != NULL && node->record->key == key) {
        prev = node;
        node = node->next;
    }
    if (prev == NULL) {
        collection->linkedList->head = node;
    } else {
        prev->next = node;
    }
    free(node);
    collection->count--;
}

// Define a function to serialize the entire data structure to a file
void serializeCollection(Collection *collection, FILE *file) {
    fwrite(&collection->capacity, sizeof(size_t), 1, file);
    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; i++) {
        Record *record = &collection->records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->identifier, sizeof(char), 1, file);
    }
}

// Define a function to deserialize the entire data structure from a file
Collection* deserializeCollection(FILE *file) {
    Collection *collection = malloc(sizeof(Collection));
    if (collection == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    fread(&collection->capacity, sizeof(size_t), 1, file);
    fread(&collection->count, sizeof(size_t), 1, file);
    collection->records = malloc(collection->capacity * sizeof(Record));
    if (collection->records == NULL) {
        free(collection);
        // Handle memory allocation failure
        return NULL;
    }
    for (size_t i = 0; i < collection->count; i++) {
        Record *record = &collection->records[i];
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
        fread(&record->identifier, sizeof(char), 1, file);
    }
    collection->linkedList = createLinkedList();
    if (collection->linkedList == NULL) {
        free(collection->records);
        free(collection);
        // Handle memory allocation failure
        return NULL;
    }
    for (size_t i = 0; i < collection->count; i++) {
        Record *record = &collection->records[i];
        insertRecord(collection, record);
    }
    return collection;
}
