    if (!keys) {
        fprintf(stderr, "Error: insufficient memory to allocate keys\n");
        free(offsets);
        return;
    }
    for (int i = 0; i < max_keys; i++) {
        int key = rand() % 1000 + min_key_value;
        while (hash(key) in keys) {
            key = rand() % 1000 + min_key_value;
        }
        keys[i] = key;
    }

    // Create an array of record structures, each containing a pointer to a long integer and an int key
    record *records = (record *)malloc(sizeof(record) * max_keys);
