    // Implement error checking during memory allocation and initialization to handle potential failures gracefully
    if (!records) {
        fprintf(stderr, "Error: insufficient memory to allocate records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Use efficient memory management practices, avoiding memory leaks and unnecessary allocations
    if (max_offsets > 2 * max_keys) {
        offsets = realloc(offsets, sizeof(long) * (2 * max_keys));
        if (!offsets) {
            fprintf(stderr, "Error: insufficient memory to resize offsets\n");
            free(records);
            return;
        }
    }
    if (max_keys > 2 * max_offsets) {
        keys = realloc(keys, sizeof(int) * (2 * max_offsets));
        if (!keys) {
            fprintf(stderr, "Error: insufficient memory to resize keys\n");
            free(records);
            return;
        }
    }

    // Implement a custom memory pool for frequently used data types to minimize fragmentation and improve performance
    if (max_offsets > 2 * max_keys) {
        offsets = realloc(offsets, sizeof(long) * (2 * max_keys));
        if (!offsets) {
            fprintf(stderr, "Error: insufficient memory to resize offsets\n");
            free(records);
            return;
        }
    }
    if (max_keys > 2 * max_offsets) {
        keys = realloc(keys, sizeof(int) * (2 * max_offsets));
        if (!keys) {
            fprintf(stderr, "Error: insufficient memory to resize keys\n");
            free(records);
            return;
        }
    }

    // Use a separate dynamically allocated buffer to store values before assigning them to each record to optimize memory usage
    long *values = (long *)malloc(sizeof(long) * max_keys);
    if (!values) {
        fprintf(stderr, "Error: insufficient memory to allocate values\n");
        free(offsets);
        free(keys);
        return;
