        values[i] = rand() % 1000 + min_key_value;
    }
    for (int i = 0; i < max_keys; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Implement a mechanism to minimize the effects of asynchronous resizing on system throughput and latency
    if (threshold > 0 && max_keys >= threshold) {
        int new_max_offsets = max_offsets * 2;
        long *new_offsets = (long *)realloc(offsets, sizeof(long) * new_max_offsets);
