    if (array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

// Function to initialize an enum status array with a unique random value within the range of 0 to 1000
enum status *initialize_status_array(size_t size) {
    enum status *array = malloc(sizeof(enum status) * size);
    if (array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; i++) {
        array[i] = (enum status)(rand() % 1000);
    }
    return array;
}

// Function to initialize an array of processing tasks with unique random measurement values within the range of 0 to 1000
struct processing_task *initialize_processing_tasks(size_t size) {
    struct processing_task *array = malloc(sizeof(struct processing_task) * size);
    if (array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; i++) {
