    // The total amount of memory allocated in the pool
    size_t total_allocated;
    // The total amount of free memory in the pool
    size_t total_free;
    // The number of blocks currently allocated
    size_t num_blocks;
    // The maximum number of blocks that can be allocated
    size_t max_num_blocks;
    // The list of all allocated blocks
    struct Block* blocks;
};

// Define the block structure
struct Block {
    // The address of the block in memory
    void* addr;
    // The size of the block in bytes
    size_t size;
    // The next block in the list
    struct Block* next;
};

// Initialize a dynamic array of Record structures
void init_records(const char* input, size_t num_records) {
    // Create a new memory pool manager
    struct MemoryPoolManager* pool = malloc(sizeof(struct MemoryPoolManager));
    if (!pool) {
        // Handle error: out of memory
        return;
    }
    pool->total_allocated = 0;
    pool->total_free = 0;
    pool->num_blocks = 0;
    pool->max_num_blocks = num_records;
    pool->blocks = NULL;

    // Allocate memory for the records
    Record* records = malloc(sizeof(Record) * num_records);
