    // Register the allocated blocks with the memory pool manager
    for (size_t i = 0; i < num_records; i++) {
        struct Block* block = malloc(sizeof(struct Block));
        if (!block) {
            // Handle error: out of memory
            free(pool);
            return;
        }
        block->addr = records + i;
        block->size = sizeof(Record);
        block->next = pool->blocks;
        pool->blocks = block;
    }

    // Update the total allocated and free memory in the pool
    pool->total_allocated += num_records * sizeof(Record);
    pool->total_free += num_records * sizeof(Record);

    // Return the initialized records
    return records;
}

// Clean up all allocated resources and reset the memory pool
void cleanup_records() {
    struct MemoryPoolManager* pool = malloc(sizeof(struct MemoryPoolManager));
    if (!pool) {
        // Handle error: out of memory
        return;
    }
    pool->total_allocated = 0;
    pool->total_free = 0;
    pool->num_blocks = 0;
    pool->max_num_blocks = 0;
    pool->blocks = NULL;
}
