// Define the Record structure to hold the data
typedef struct {
    long offset;
    int key;
    char* string;
} Record;

// Define the memory pool manager interface
typedef struct {
    void* (*alloc)(size_t size);
    void (*free)(void* ptr);
} MemoryPoolManager;

// Define the configuration data model
typedef struct {
    int maxArraySize;
    int numRecords;
    Record records[];
} Configuration;

// Define the memory pool manager implementation
static MemoryPoolManager mempool = {
    .alloc = malloc,
    .free = free
};

// Define the configuration data model implementation
static Configuration config = {
    .maxArraySize = 1000000, // maximum array size
    .numRecords = 0, // number of records in the array
    .records = NULL // pointer to the array of records
};

// Define the mutex for synchronizing access to the configuration data model
static pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the dynamic array of Records
void initRecords(int maxArraySize) {
    // Allocate memory for the array of records
    config.records = (Record*)mempool.alloc(maxArraySize * sizeof(Record));
    assert(config.records != NULL);

    // Initialize the number of records to 0
    config.numRecords = 0;
}

// Add a new record to the dynamic array
void addRecord(long offset, int key, char* string) {
    // Acquire the mutex for synchronizing access to the configuration data model
    pthread_mutex_lock(&configMutex);

    // Check if the maximum array size has been reached
    if (config.numRecords >= config.maxArraySize) {
        // Release the mutex and return
        pthread_mutex_unlock(&configMutex);
        return;
    }

    // Allocate memory for the new record
    Record* newRecord = (Record*)mempool.alloc(sizeof(Record));
    assert(newRecord != NULL);

    // Initialize the fields of the new record
    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->string = string;

    // Add the new record to the array
    config.records[config.numRecords++] = *newRecord;

    // Release the mutex
    pthread_mutex_unlock(&configMutex);
}

// Get a record from the dynamic array by its index
Record* getRecord(int index) {
    // Acquire the mutex for synchronizing access to the configuration data model
    pthread_mutex_lock(&configMutex);

    // Check if the index is valid
    if (index < 0 || index >= config.numRecords) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&configMutex);
        return NULL;
    }

    // Get the record at the specified index
    Record* record = &config.records[index];

    // Release the mutex
    pthread_mutex_unlock(&configMutex);

    // Return the record
    return record;
}

// Clear all allocated resources and reset the memory pool
void clearRecords() {
    // Acquire the mutex for synchronizing access to the configuration data model
    pthread_mutex_lock(&configMutex);

    // Free the array of records
    mempool.free(config.records);

    // Reset the number of records to 0
    config.numRecords = 0;

    // Release the mutex
    pthread_mutex_unlock(&configMutex);
}

// Report real-time memory usage statistics
void reportMemoryUsage() {
    // Acquire the mutex for synchronizing access to the configuration data model
    pthread_mutex_lock(&configMutex);

    // Calculate the total allocated memory
    size_t totalAllocated = config.numRecords * sizeof(Record);

    // Calculate the free memory
    size_t freeMemory = mempool.free(NULL) - totalAllocated;

    // Calculate the memory pool utilization
    float memPoolUtilization = (float)(totalAllocated / mempool.alloc(0));

    // Print the memory usage statistics
    printf("Total allocated memory: %zu\n", totalAllocated);
    printf("Free memory: %zu\n", freeMemory);
    printf("Memory pool utilization: %.2f%%\n", memPoolUtilization * 100.0);

    // Release the mutex
    pthread_mutex_unlock(&configMutex);
}
