struct codec_module {
    const char *name; // Name of the codec module
    void (*init)(void); // Initialization function for the codec module
    int (*encode)(const unsigned char *data, size_t size, struct frame **frame); // Encoding function for the codec module
    int (*decode)(struct frame *frame, unsigned char **data, size_t *size); // Decoding function for the codec module
};

// Define the multimedia processing module structure
struct multimed_module {
    struct mem_pool *mem_pool; // Memory pool manager for the multimedia processing module
