    struct mem_pool *mem_pool = malloc(sizeof(struct mem_pool));
    if (!mem_pool) {
        return NULL;
    }
    mem_pool->base = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem_pool->base == MAP_FAILED) {
        free(mem_pool);
        return NULL;
    }
    mem_pool->size = size;
    mem_pool->used = 0;
    pthread_mutex_init(&mem_pool->lock, NULL);
    return mem_pool;
}

