// Function to set the value of each data point's double field to a random floating-point number within a specified range
void set_random_double(double* arr, int size, double min, double max) {
    for (int i = 0; i < size; i++) {
        arr[i] = min + ((max - min) * rand() / RAND_MAX);
    }
}

// Function to set the value of each data point's string field to a random string within a specified range
void set_random_string(char** arr, int size, char* min, char* max) {
