    char** string_array = (char**)custom_alloc(size * sizeof(char*));

    // Set the value of each data point's double field to a random floating-point number within a specified range
    set_random_double(double_array, size, 0.0, 100.0);

    // Set the value of each data point's string field to a random string within a specified range
    set_random_string(string_array, size, "hello", "world");
