// Function to report current memory usage statistics in JSON format
void report_memory_usage() {
    // Calculate total allocated memory and free memory
    int total_allocated = 0;
    int total_free = 0;
    for (int i = 0; i < size; i++) {
        total_allocated += sizeof(double) + strlen(string_array[i]);
        total_free += sizeof(double) + strlen(string_array[i]);
    }

    // Calculate memory pool utilization
    int memory_pool_utilization = (total_allocated - total_free) / total_allocated;

    // Create a JSON object to store the memory usage statistics
    json_object* mem_usage_stats = json_object_new_object();

    // Add total allocated memory, free memory, and memory pool utilization to the JSON object
    json_object_object_add(mem_usage_stats, "total_allocated", json_object_new_int(total_allocated));
    json_object_object_add(mem_usage_stats, "total_free", json_object_new_int(total_free));
    json_object_object_add(mem_usage_stats, "memory_pool_utilization", json_object_new_double(memory_pool_utilization));

