// Define the record structure
typedef struct {
    int value;
} Record;

// Define the memory pool configuration
#define POOL_SIZE 1024 * 1024 // 1 MB
#define POOL_ALIGNMENT 8 // 8-byte alignment

// Define the random number generator seed
static unsigned int seed = time(NULL);

// Define the memory pool
static Record* pool;

// Initialize the memory pool
void initPool() {
    pool = (Record*) malloc(POOL_SIZE);
    if (!pool) {
        printf("Error: Failed to allocate memory for the pool\n");
        exit(1);
    }
}

// Deallocate the memory pool
void destroyPool() {
    free(pool);
}

// Allocate a new record from the pool
Record* allocRecord() {
    pthread_mutex_lock(&poolMutex);
    Record* record = (Record*) malloc(sizeof(Record));
    if (!record) {
        printf("Error: Failed to allocate memory for the record\n");
        exit(1);
    }
    // Initialize the record's value to a random value within the given range
    record->value = rand_r(&seed) % 100;
    pthread_mutex_unlock(&poolMutex);
    return record;
}

// Deallocate a record from the pool
void freeRecord(Record* record) {
    pthread_mutex_lock(&poolMutex);
    free(record);
    pthread_mutex_unlock(&poolMutex);
}

// Thread-local storage for caching frequently accessed random values
__thread Record* cachedValue;

// Get a random value from the pool
int getRandomValue() {
    if (cachedValue) {
        return cachedValue->value;
    } else {
        Record* record = allocRecord();
        cachedValue = record;
        return record->value;
    }
}

// Clear all allocated resources and reset the memory pool
void clearResources() {
    pthread_mutex_lock(&poolMutex);
    for (int i = 0; i < POOL_SIZE / sizeof(Record); i++) {
        freeRecord((Record*) &pool[i]);
    }
    destroyPool();
    initPool();
    pthread_mutex_unlock(&poolMutex);
}

// Memory usage statistics
static size_t totalAllocatedMemory = 0;
static size_t freeMemory = 0;
static float poolUtilization = 0.0f;

// Report memory usage statistics
void reportMemoryUsage() {
    pthread_mutex_lock(&poolMutex);
    totalAllocatedMemory += POOL_SIZE;
    freeMemory += getFreeMemory();
    poolUtilization = (float) (totalAllocatedMemory - freeMemory) / totalAllocatedMemory;
    printf("Total allocated memory: %zu\n", totalAllocatedMemory);
    printf("Free memory: %zu\n", freeMemory);
    printf("Pool utilization: %.2f%%\n", poolUtilization * 100.0f);
    pthread_mutex_unlock(&poolMutex);
}

// Main function
int main() {
    initPool();
    // Use the memory pool to allocate and initialize records
    Record* record = allocRecord();
    printf("Random value: %d\n", getRandomValue());
    freeRecord(record);
    clearResources();
    reportMemoryUsage();
    return 0;
}
