typedef struct Node {
    Order *order;
    struct Node *next;
} Node;

// Define a hash map for efficient order retrieval
typedef struct {
    unsigned long id;
    Order *order;
} HashMap;

// Function to manage and process customer orders
Order* processOrders(int size) {
    // Check if the input size is valid
    if (size <= 0) {
        return NULL;
    }

    // Allocate memory for the linked list of orders
    Node *head = malloc(sizeof(Node));
    head->next = NULL;

    // Allocate memory for the hash map
    HashMap *hashMap = malloc(size * sizeof(HashMap));

    // Initialize the hash map with invalid values
    for (int i = 0; i < size; i++) {
        hashMap[i].id = -1;
        hashMap[i].order = NULL;
    }

    // Allocate memory for each order and its items
    Order *orders = malloc(size * sizeof(Order));
    Item *items = malloc(size * sizeof(Item));

    // Initialize the orders and items with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        orders[i].id = i + 1;
        strcpy(orders[i].name, "Item");
        orders[i].quantity = rand() % 100;
        orders[i].price = (double)rand() / RAND_MAX * 100.0;

        items[i].name = "Item";
        items[i].quantity = rand() % 100;
        items[i].price = (double)rand() / RAND_MAX * 100.0;
    }

    // Add each order to the linked list and hash map
    for (int i = 0; i < size; i++) {
        Node *node = malloc(sizeof(Node));
        node->order = &orders[i];
        node->next = head->next;
        head->next = node;

        hashMap[i].id = orders[i].id;
        hashMap[i].order = &orders[i];
    }

    // Return the first order structure or NULL if allocation fails
    return head->next ? head->next->order : NULL;
}
