#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the data structure to store a double value and a char* string pointer
typedef struct {
    double value;
    char* str;
} data_point;

// Define the memory pool manager interface
struct mempool_manager {
    // Function to allocate memory from the pool
    void* (*alloc)(size_t size);
    // Function to free memory from the pool
    void (*free)(void* ptr);
    // Function to resize the pool
    int (*resize)(size_t new_size);
};

// Define the hash function for mapping data points to memory blocks
unsigned long hash(data_point* dp) {
    unsigned long h = 0;
    char* str = dp->str;
    while (*str != '\0') {
        h = (h << 5) - h + *str++;
    }
    return h;
}

// Define the memory pool for storing data points
struct mempool {
    // The size of the memory pool
    size_t size;
    // The number of free blocks in the pool
    int num_free_blocks;
    // The list of free blocks in the pool
    struct block* free_blocks;
    // The hash table for mapping data points to memory blocks
    struct {
        unsigned long key;
        struct block* value;
    }* hash_table;
};

// Define the block structure for storing data points
struct block {
    // The next free block in the pool
    struct block* next;
    // The previous free block in the pool
    struct block* prev;
    // The data point stored in this block
    data_point dp;
};

// Define the memory pool manager for managing the memory pool
struct mempool_manager mempool_mgr = {
    .alloc = alloc,
    .free = free,
    .resize = resize
};

// Function to allocate memory from the pool
void* alloc(size_t size) {
    // Check if the requested size is within the bounds of the pool
    if (size > mempool.size) {
        return NULL;
    }

    // Find a free block in the pool that can hold the requested size
    struct block* block = find_free_block(size);
    if (block == NULL) {
        return NULL;
    }

    // Remove the block from the list of free blocks
    remove_block(block);

    // Return a pointer to the data point stored in the block
    return &block->dp;
}

// Function to free memory from the pool
void free(void* ptr) {
    // Check if the pointer is within the bounds of the pool
    if (ptr < mempool.free_blocks || ptr > mempool.free_blocks + mempool.size) {
        return;
    }

    // Find the block that contains the data point
    struct block* block = find_block(ptr);
    if (block == NULL) {
        return;
    }

    // Add the block to the list of free blocks
    add_block(block);
}

// Function to resize the pool
int resize(size_t new_size) {
    // Check if the requested size is within the bounds of the pool
    if (new_size > mempool.size) {
        return -1;
    }

    // Update the size of the pool
    mempool.size = new_size;

    // Update the number of free blocks in the pool
    mempool.num_free_blocks = 0;

    // Update the list of free blocks in the pool
    struct block* block = mempool.free_blocks;
    while (block != NULL) {
        if (block->next == NULL || block->next < mempool.free_blocks || block->next > mempool.free_blocks + mempool.size) {
            break;
        }
        block = block->next;
    }
    mempool.free_blocks = block;

    // Update the hash table for mapping data points to memory blocks
    struct {
        unsigned long key;
        struct block* value;
    }* new_hash_table = (struct {
        unsigned long key;
        struct block* value;
    }*)realloc(mempool.hash_table, sizeof(struct {
        unsigned long key;
        struct block* value;
    }) * new_size);
    if (new_hash_table == NULL) {
        return -1;
    }
    mempool.hash_table = new_hash_table;

    // Return success
    return 0;
}

// Function to find a free block in the pool that can hold the requested size
struct block* find_free_block(size_t size) {
    struct block* block = mempool.free_blocks;
    while (block != NULL && block->next != NULL && block->next < mempool.free_blocks + mempool.size) {
        if (block->next->size >= size) {
            return block->next;
        }
        block = block->next;
    }
    return NULL;
}

// Function to remove a block from the list of free blocks
void remove_block(struct block* block) {
    struct block* prev = block->prev;
    struct block* next = block->next;
    if (prev != NULL && next != NULL) {
        prev->next = next;
        next->prev = prev;
    } else if (prev != NULL) {
        prev->next = NULL;
    } else if (next != NULL) {
        next->prev = NULL;
    }
}

// Function to add a block to the list of free blocks
void add_block(struct block* block) {
    struct block* prev = mempool.free_blocks;
    while (prev != NULL && prev->next < mempool.free_blocks + mempool.size) {
        if (prev->next == NULL || prev->next > mempool.free_blocks + mempool.size) {
            break;
        }
        prev = prev->next;
    }
    block->prev = prev;
    block->next = prev->next;
    prev->next = block;
}

// Function to find a block that contains the data point
struct block* find_block(void* ptr) {
    struct block* block = mempool.free_blocks;
    while (block != NULL && block < mempool.free_blocks + mempool.size) {
        if (ptr >= &block->dp && ptr <= &block->dp + sizeof(data_point)) {
            return block;
        }
        block = block->next;
    }
    return NULL;
}

// Function to map a data point to a memory block in the pool
struct block* map_to_block(data_point* dp) {
    unsigned long key = hash(dp);
    struct block* block = mempool.hash_table[key];
    while (block != NULL && block < mempool.free_blocks + mempool.size) {
        if (&block->dp == dp) {
            return block;
        }
        block = block->next;
    }
    return NULL;
}

// Function to unmap a data point from its memory block in the pool
void unmap_from_block(data_point* dp) {
    unsigned long key = hash(dp);
    struct block* block = mempool.hash_table[key];
    while (block != NULL && block < mempool.free_blocks + mempool.size) {
        if (&block->dp == dp) {
            break;
        }
        block = block->next;
    }
    if (block != NULL) {
        remove_block(block);
    }
}

// Function to report memory usage statistics
void report_memory_usage() {
    // Calculate the total allocated memory
    size_t total_allocated = 0;
    struct block* block = mempool.free_blocks;
    while (block != NULL && block < mempool.free_blocks + mempool.size) {
        total_allocated += block->size;
        block = block->next;
    }

    // Calculate the free memory
    size_t free_memory = 0;
    for (int i = 0; i < mempool.num_free_blocks; i++) {
        free_memory += mempool.free_blocks[i].size;
    }

    // Calculate the peak usage
    size_t peak_usage = total_allocated - free_memory;

    // Print the memory usage statistics
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Free memory: %zu\n", free_memory);
    printf("Peak usage: %zu\n", peak_usage);
}
