// Define data structure for storing double values and string pointers
typedef struct {
    double value;
    char* str;
} Data;

// Function to manage and process data structures under constrained and dynamic environments
void processData(int numStrings, int lowerBound, int upperBound) {
    // Allocate memory for string array
    char** strings = malloc(numStrings * sizeof(char*));
    if (strings == NULL) {
        printf("Error: Failed to allocate memory for string array\n");
        return;
    }

    // Initialize string array with unique prefixes and sequential indices
    for (int i = 0; i < numStrings; i++) {
        strings[i] = malloc(16 * sizeof(char));
        if (strings[i] == NULL) {
            printf("Error: Failed to allocate memory for string %d\n", i);
            return;
        }
        sprintf(strings[i], "string%d", i);
    }

    // Allocate memory for data structure array
    Data* data = malloc(numStrings * sizeof(Data));
    if (data == NULL) {
        printf("Error: Failed to allocate memory for data structure array\n");
        return;
    }

    // Initialize data structure array with random double values and string pointers
    for (int i = 0; i < numStrings; i++) {
        data[i].value = lowerBound + (double)rand() / RAND_MAX * (upperBound - lowerBound);
        data[i].str = strings[i];
    }

    // Release memory for string array and data structure array if any allocation failed
    if (strings == NULL || data == NULL) {
        printf("Error: Failed to allocate memory for string or data structure array\n");
        return;
    }

    // Integrate with external memory pool manager
    MemoryPoolManager* manager = getMemoryPoolManager();
    if (manager == NULL) {
        printf("Error: Failed to retrieve memory pool manager\n");
        return;
    }
    for (int i = 0; i < numStrings; i++) {
        manager->registerBlock(data[i].str, sizeof(char*));
        manager->registerBlock(data + i, sizeof(Data));
    }

    // Optimize memory allocation and deallocation for performance
    for (int i = 0; i < numStrings; i++) {
        if (data[i].str != NULL) {
            free(data[i].str);
        }
        if (data + i != NULL) {
            free(data + i);
        }
    }

    // Ensure thread safety by using appropriate synchronization mechanisms
    pthread_mutex_t* mutex = getMutex();
    if (mutex == NULL) {
        printf("Error: Failed to retrieve mutex\n");
        return;
    }
    pthread_mutex_lock(mutex);
    for (int i = 0; i < numStrings; i++) {
        manager->registerBlock(data[i].str, sizeof(char*));
        manager->registerBlock(data + i, sizeof(Data));
    }
    pthread_mutex_unlock(mutex);

    // Provide mechanism to report memory usage statistics
    printf("Memory usage: %d bytes allocated, %d bytes free, %d%% utilization\n", manager->getTotalAllocated(), manager->getFreeMemory(), (manager->getTotalAllocated() * 100) / manager->getMaximumSize());

    // Implement function to clear all allocated resources and reset memory pool
    for (int i = 0; i < numStrings; i++) {
        if (data[i].str != NULL) {
            free(data[i].str);
        }
        if (data + i != NULL) {
            free(data + i);
        }
    }
    manager->reset();
}

// Helper function to read a list of integers from standard input and find their average
void readAndPrintAverage() {
    int* numbers = malloc(10 * sizeof(int));
    if (numbers == NULL) {
        printf("Error: Failed to allocate memory for integer array\n");
        return;
    }

    // Read integers from standard input and store them in the array
    for (int i = 0; i < 10; i++) {
        scanf("%d", &numbers[i]);
    }

    // Calculate average of the integers
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        sum += numbers[i];
    }
    double average = (double)sum / 10;

    // Print the average
    printf("Average of integers: %f\n", average);

    // Release memory for integer array
    free(numbers);
}
