// Define a structure to represent a record in the bundle
typedef struct {
    int value;
} Record;

// Define a function to load a resource bundle from a file path and return the number of items in the bundle
int load_bundle(const char* file_path) {
    // Open the file at the specified path for reading
    FILE* fp = fopen(file_path, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read the number of items in the bundle from the first line of the file
    int num_items;
    fscanf(fp, "%d", &num_items);

    // Allocate memory for the bundle and read each item into it
    Record* bundle = (Record*)malloc(sizeof(Record) * num_items);
    for (int i = 0; i < num_items; i++) {
        fscanf(fp, "%d", &bundle[i].value);
    }

    // Close the file and return the number of items in the bundle
    fclose(fp);
    return num_items;
}

// Define a function to allocate memory for an array of 'record' structures and initialize each record with a random value within a specified range
Record* allocate_records(int num_records, int lower_bound, int upper_bound) {
    // Allocate memory for the array of records
    Record* records = (Record*)malloc(sizeof(Record) * num_records);

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = lower_bound + rand() % (upper_bound - lower_bound);
    }

    return records;
