int readCSVFile(char* filename, TransactionBatch** batch) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Read the header line
    char* line = NULL;
    size_t len = 0;
    ssize_t read = getline(&line, &len, fp);
    if (read < 0) {
        printf("Error: unable to read file %s\n", filename);
        return -1;
    }

    // Allocate memory for the transaction batch
    *batch = malloc(sizeof(TransactionBatch));
    (*batch)->transactions = NULL;
    (*batch)->numTransactions = 0;

    // Read each line of the file and parse it into a transaction
    while ((read = getline(&line, &len, fp)) != -1) {
        char* token = strtok(line, ",");
        if (token == NULL) {
            printf("Error: unable to parse transaction in file %s\n", filename);
            return -1;
        }
        (*batch)->transactions = realloc((*batch)->transactions, ((*batch)->numTransactions + 1) * sizeof(Transaction));
        Transaction* transaction = &(*batch)->transactions[(*batch)->numTransactions];
        transaction->userId = strdup(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: unable to parse transaction amount in file %s\n", filename);
            return -1;
        }
        transaction->amount = atof(token);
        (*batch)->numTransactions++;
    }

    // Close the file
    fclose(fp);

    return 0;
}

// Function to process a batch of transactions and calculate the average transaction amount over the last three entries
