    double totalAmount = 0.0;
    int numTransactions = batch->numTransactions;
    if (numTransactions < 3) {
        return -1.0; // Not enough transactions to calculate average
    }
    for (int i = numTransactions - 3; i < numTransactions; i++) {
        totalAmount += batch->transactions[i].amount;
    }
    return totalAmount / 3.0;
}

