        pthread_mutex_lock(&mutex);

        // Find an empty slot in the key array and initialize the corresponding record
        int index = find_empty_slot(key_array, num_records);
        if (index == -1) {
            // Release the lock on the mutex and return an error status
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Initialize the record with the given task entity
        record_array[index].value = task->description;
        record_array[index].priority = task->priority;
        record_array[index].scheduled_time = task->scheduled_time;

        // Release the lock on the mutex and signal the condition variable
        pthread_mutex_unlock(&mutex);
        pthread_cond_signal(&cond);
    }

    // Implement the function to delete a task entity from the collection
    void delete_task(int key) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Find the index of the record with the given key and remove it from the array
        int index = find_record(key, key_array, num_records);
        if (index == -1) {
            // Release the lock on the mutex and return an error status
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Remove the record from the array and release the corresponding memory block
        remove_record(record_array + index, manager);

        // Release the lock on the mutex and signal the condition variable
        pthread_mutex_unlock(&mutex);
        pthread_cond_signal(&cond);
    }

    // Implement the function to retrieve a task entity from the collection
    Task *retrieve_task(int key) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Find the index of the record with the given key and return it
        int index = find_record(key, key_array, num_records);
        if (index == -1) {
            // Release the lock on the mutex and return an error status
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        // Return the record with the given key
        Task *task = malloc(sizeof(Task));
        task->description = record_array[index].value;
        task->priority = record_array[index].priority;
        task->scheduled_time = record_array[index].scheduled_time;

        // Release the lock on the mutex and return the task entity
        pthread_mutex_unlock(&mutex);
        return task;
    }

    // Implement the function to clear all allocated resources and reset the memory pool
    void clear_resources() {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Release all allocated blocks of memory with the manager
        for (int i = 0; i < num_records; i++) {
            remove_record(record_array + i, manager);
        }

        // Reset the memory pool manager
        reset_memory_pool_manager(manager);

        // Release the lock on the mutex and signal the condition variable
        pthread_mutex_unlock(&mutex);
        pthread_cond_signal(&cond);
    }
}
