#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants for priority levels
#define PRIORITY_HIGH 0
#define PRIORITY_MEDIUM 1
#define PRIORITY_LOW 2

// Define a struct to represent a task entity
typedef struct Task {
    char *description; // String describing the task
    int priority; // Priority level (high, medium, low)
    time_t scheduledTime; // Scheduled execution time
    time_t lastModified; // Timestamp for last modified time
} Task;

// Define a struct to represent a collection of tasks
typedef struct TaskCollection {
    Task **tasks; // Array of task pointers
    int *keys; // Array of integer keys
    int size; // Size of the array
    int capacity; // Capacity of the array
} TaskCollection;

// Define a function to allocate and initialize an array of tasks
TaskCollection* createTaskCollection(int initialCapacity) {
    // Allocate memory for the task collection struct
    TaskCollection *collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    if (!collection) {
        printf("Error: Failed to allocate memory for task collection\n");
        return NULL;
    }

    // Initialize the size and capacity of the array
    collection->size = 0;
    collection->capacity = initialCapacity;

    // Allocate memory for the tasks array
    collection->tasks = (Task**)malloc(sizeof(Task*) * initialCapacity);
    if (!collection->tasks) {
        printf("Error: Failed to allocate memory for tasks array\n");
        free(collection);
        return NULL;
    }

    // Allocate memory for the keys array
    collection->keys = (int*)malloc(sizeof(int) * initialCapacity);
    if (!collection->keys) {
        printf("Error: Failed to allocate memory for keys array\n");
        free(collection->tasks);
        free(collection);
        return NULL;
    }

    // Initialize the tasks and keys arrays
    for (int i = 0; i < initialCapacity; i++) {
        collection->tasks[i] = NULL;
        collection->keys[i] = -1;
    }

    return collection;
}

// Define a function to add a task to the collection
void addTask(TaskCollection *collection, Task *task) {
    // Check if the collection is full
    if (collection->size == collection->capacity) {
        // Increase the capacity of the array by 50%
        int newCapacity = collection->capacity + (collection->capacity / 2);
        Task **newTasks = realloc(collection->tasks, sizeof(Task*) * newCapacity);
        if (!newTasks) {
            printf("Error: Failed to reallocate memory for tasks array\n");
            return;
        }
        collection->tasks = newTasks;
        int *newKeys = realloc(collection->keys, sizeof(int) * newCapacity);
        if (!newKeys) {
            printf("Error: Failed to reallocate memory for keys array\n");
            return;
        }
        collection->keys = newKeys;
        collection->capacity = newCapacity;
    }

    // Add the task to the end of the array
    int index = collection->size++;
    collection->tasks[index] = task;
    collection->keys[index] = -1;
}

// Define a function to update the scheduled execution time of tasks dynamically
void updateScheduledTime(TaskCollection *collection, int key, time_t newScheduledTime) {
    // Check if the key is valid
    if (key < 0 || key >= collection->size) {
        printf("Error: Invalid key\n");
        return;
    }

    // Update the scheduled execution time of the task
    Task *task = collection->tasks[key];
    task->scheduledTime = newScheduledTime;
}

// Define a function to find and print the largest integer in an array of integers
void findLargestInteger(int *array, int size) {
    // Check if the array is empty
    if (size == 0) {
        printf("Error: Empty array\n");
        return;
    }

    // Initialize the largest integer to the first element of the array
    int largest = array[0];

    // Iterate over the remaining elements of the array
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    // Print the largest integer
    printf("Largest integer: %d\n", largest);
}

// Define a function to report current memory usage statistics
void reportMemoryUsage(TaskCollection *collection) {
    // Calculate the total allocated memory in bytes
    size_t totalAllocated = sizeof(Task*) * collection->capacity + sizeof(int) * collection->capacity;

    // Calculate the free memory in bytes
    size_t freeMemory = 0;
    for (int i = 0; i < collection->size; i++) {
        if (collection->tasks[i] == NULL) {
            freeMemory += sizeof(Task*);
        } else {
            freeMemory += sizeof(Task*) + strlen(collection->tasks[i]->description) + 1;
        }
    }

    // Calculate the memory pool utilization in bytes
    size_t memoryPoolUtilization = totalAllocated - freeMemory;

    // Print the memory usage statistics
    printf("Total allocated memory: %zu bytes\n", totalAllocated);
    printf("Free memory: %zu bytes\n", freeMemory);
    printf("Memory pool utilization: %zu bytes\n", memoryPoolUtilization);
}

// Define a function to clear all allocated resources and reset the memory pool
void clearResources(TaskCollection *collection) {
    // Free the tasks array
    for (int i = 0; i < collection->size; i++) {
        if (collection->tasks[i] != NULL) {
            free(collection->tasks[i]);
        }
    }
    free(collection->tasks);

    // Free the keys array
    free(collection->keys);

    // Reset the size and capacity of the array
    collection->size = 0;
    collection->capacity = 0;
}
