// Define a function to manage the dynamic collection of task entities
void manage_tasks(int num_tasks, int max_priority) {
    // Allocate memory for the offset and key arrays
    offsets = (long *)malloc(num_tasks * sizeof(long));
    keys = (int *)malloc(num_tasks * sizeof(int));

    // Initialize the offset and key arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_tasks; i++) {
        offsets[i] = rand() % max_priority;
        keys[i] = i + 1;
    }

    // Allocate memory for the record array
    records = (Record *)malloc(num_tasks * sizeof(Record));

    // Initialize the record array with random integer values
    srand(time(NULL));
    for (int i = 0; i < num_tasks; i++) {
        records[i].value = rand() % max_priority;
    }
}

// Define a function to insert a new task entity into the collection
void insert_task(Task *task) {
    // Check if there is enough memory available for the new task
    if (num_tasks >= MAX_TASKS) {
        printf("Error: Not enough memory available for new task\n");
        return;
    }

    // Allocate memory for the new task and copy its contents
    Task *new_task = (Task *)malloc(sizeof(Task));
    memcpy(new_task, task, sizeof(Task));

    // Insert the new task into the offset and key arrays
    offsets[num_tasks] = new_task->scheduled_execution_time;
    keys[num_tasks] = new_task->priority;

    // Update the record array with the new task's random integer value
    records[num_tasks].value = rand() % max_priority;

    // Increment the number of tasks and free the memory allocated for the new task
    num_tasks++;
    free(new_task);
}

// Define a function to delete a task entity from the collection
void delete_task(int key) {
    // Check if the specified key exists in the offset and key arrays
    int index = -1;
    for (int i = 0; i < num_tasks; i++) {
        if (keys[i] == key) {
            index = i;
            break;
        }
    }

    // If the specified key exists, delete it from the offset and key arrays
    if (index != -1) {
        offsets[index] = 0;
        keys[index] = 0;

        // Update the record array with the deleted task's random integer value
        records[index].value = 0;

        // Decrement the number of tasks and free the memory allocated for the deleted task
        num_tasks--;
        free(new_task);
    } else {
        printf("Error: Task with key %d does not exist\n", key);
    }
}

// Define a function to retrieve a task entity from the collection
Task *get_task(int key) {
    // Check if the specified key exists in the offset and key arrays
    int index = -1;
    for (int i = 0; i < num_tasks; i++) {
        if (keys[i] == key) {
            index = i;
            break;
        }
    }

    // If the specified key exists, return a pointer to its corresponding task entity
    if (index != -1) {
        return &records[index];
    } else {
        printf("Error: Task with key %d does not exist\n", key);
        return NULL;
    }
}

