    // Calculate the total allocated memory and free memory
    long total_allocated_memory = (long)num_tasks * sizeof(Task);
    long total_free_memory = 0;

    // Calculate the memory pool utilization
    float memory_pool_utilization = (float)(total_allocated_memory - total_free_memory) / total_allocated_memory;

    // Print the current memory usage statistics
    printf("Total allocated memory: %ld bytes\n", total_allocated_memory);
    printf("Total free memory: %ld bytes\n", total_free_memory);
    printf("Memory pool utilization: %.2f%%\n", memory_pool_utilization * 100);
}
