// Define the struct for storing records
typedef struct record {
    long *offset;
    int *key;
    size_t size;
} record_t;

// Function to initialize a semaphore with a unique name and support both increment and decrement operations
sem_t* init_semaphore(const char* name) {
    // Create the semaphore with a unique name
    sem_t* sem = sem_open(name, O_CREAT | O_EXCL, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    // Initialize the semaphore with a value of 1
    if (sem_init(sem, 0, 1) < 0) {
        perror("Failed to initialize semaphore");
        sem_close(sem);
        return NULL;
    }

    return sem;
}

// Function to dynamically allocate memory for an array of long integers and initialize it with the given values
long* alloc_long_array(size_t size, const long* values) {
    // Allocate memory for the array
    long* arr = malloc(sizeof(long) * size);
    if (arr == NULL) {
        perror("Failed to allocate memory for long array");
        return NULL;
    }

    // Initialize the array with the given values
    memcpy(arr, values, sizeof(long) * size);

    return arr;
}

// Function to dynamically allocate memory for an array of int integers and initialize it with the given values
int* alloc_int_array(size_t size, const int* values) {
    // Allocate memory for the array
    int* arr = malloc(sizeof(int) * size);
    if (arr == NULL) {
        perror("Failed to allocate memory for int array");
        return NULL;
    }

    // Initialize the array with the given values
    memcpy(arr, values, sizeof(int) * size);

    return arr;
}

// Function to dynamically allocate memory for an array of struct record objects and initialize it with the given values
record_t* alloc_record_array(size_t size, const long* offsets, const int* keys, const size_t* sizes) {
    // Allocate memory for the array
    record_t* arr = malloc(sizeof(record_t) * size);
    if (arr == NULL) {
        perror("Failed to allocate memory for record array");
        return NULL;
    }

    // Initialize each element of the array with the given values
    for (size_t i = 0; i < size; i++) {
        arr[i].offset = alloc_long_array(sizes[i], offsets + i);
        arr[i].key = alloc_int_array(sizes[i], keys + i);
        arr[i].size = sizes[i];
    }

    return arr;
}

// Function to free the memory allocated for an array of struct record objects
void free_record_array(record_t* arr, size_t size) {
    // Free each element of the array
    for (size_t i = 0; i < size; i++) {
        free(arr[i].offset);
        free(arr[i].key);
    }

    // Free the memory allocated for the array itself
    free(arr);
}

// Function to process a stream of floating-point numbers read from standard input, ensuring no more than 10,000 numbers are provided, and store these numbers in a dynamically allocated array, handling memory allocation errors gracefully and freeing the allocated memory after processing
void process_stream(FILE* stream) {
    // Initialize the semaphore for concurrent thread operations
    sem_t* sem = init_semaphore("process_stream");
    if (sem == NULL) {
        perror("Failed to initialize semaphore");
        return;
    }

    // Dynamically allocate memory for an array of long integers to store the offsets of each record
    long* offsets = malloc(sizeof(long) * 10000);
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        sem_close(sem);
        return;
    }

    // Dynamically allocate memory for an array of int integers to store the keys of each record
    int* keys = malloc(sizeof(int) * 10000);
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        sem_close(sem);
        return;
    }

    // Dynamically allocate memory for an array of struct record objects to store the records read from the stream
    record_t* records = alloc_record_array(10000, offsets, keys, NULL);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        sem_close(sem);
        return;
    }

    // Read the stream and store the numbers in the dynamically allocated arrays
    size_t i = 0;
    while (i < 10000 && fscanf(stream, "%lf", &records[i].value) == 1) {
        records[i].offset = offsets + i;
        records[i].key = keys + i;
        i++;
    }

    // Free the memory allocated for the arrays of long integers and int integers
    free(offsets);
    free(keys);

    // Find the smallest number in the array and print it along with its offset
    if (i > 0) {
        size_t smallest = 0;
        for (size_t j = 1; j < i; j++) {
            if (records[j].value < records[smallest].value) {
                smallest = j;
            }
        }
        printf("Smallest number: %lf at offset %ld\n", records[smallest].value, *(records[smallest].offset));
    } else {
        printf("No numbers were read from the stream\n");
    }

    // Calculate the median of all numbers in the array and print it along with its offset
    if (i > 0) {
        size_t median = i / 2;
        if (i % 2 == 0) {
            printf("Median: %lf at offset %ld\n", (records[median].value + records[median - 1].value) / 2, *(records[median].offset));
        } else {
            printf("Median: %lf at offset %ld\n", records[median].value, *(records[median].offset));
        }
    } else {
        printf("No numbers were read from the stream\n");
    }

    // Free the memory allocated for the array of struct record objects
    free_record_array(records, i);

    // Close the semaphore
    sem_close(sem);
}
