using System;
using System.IO;
using System.Text;
using Newtonsoft.Json;

namespace ConfigurationManager
{
    public class ConfigData
    {
        public int[] IntegerList { get; set; }
        public string StringValue { get; set; }
    }

    public static class ConfigurationManager
    {
        private const string CONFIG_FILE = "config.bin";
        private const string LOG_FILE = "log.txt";

        // Memory pool manager for efficient memory allocation and deallocation
        private static readonly MemoryPoolManager _memoryPoolManager = new MemoryPoolManager();

        public static ConfigData LoadConfiguration()
        {
            try
            {
                using (var fileStream = File.OpenRead(CONFIG_FILE))
                {
                    // Use JSON serialization for enhanced flexibility and interoperability
                    var jsonSerializer = new JsonSerializer();
                    return jsonSerializer.Deserialize<ConfigData>(new StreamReader(fileStream));
                }
            }
            catch (Exception ex)
            {
                LogError("Failed to load configuration: " + ex.Message);
                return null;
            }
        }

        public static void SaveConfiguration(ConfigData configData)
        {
            try
            {
                using (var fileStream = File.OpenWrite(CONFIG_FILE))
                {
                    // Use JSON serialization for enhanced flexibility and interoperability
                    var jsonSerializer = new JsonSerializer();
                    jsonSerializer.Serialize(new StreamWriter(fileStream), configData);
                }
            }
            catch (Exception ex)
            {
                LogError("Failed to save configuration: " + ex.Message);
            }
        }

        public static void ReadIntegerListFromStandardInput()
        {
            var integerList = new List<int>();
            while (true)
            {
                Console.Write("Enter an integer value or press Enter to stop: ");
                var input = Console.ReadLine();
                if (string.IsNullOrEmpty(input))
                {
                    break;
                }
                else
                {
                    try
                    {
                        integerList.Add(int.Parse(input));
                    }
                    catch (FormatException)
                    {
                        Console.WriteLine("Invalid input, please enter an integer value.");
                    }
                }
            }
            var largestInteger = FindLargestInteger(integerList);
            Console.WriteLine($"The largest integer in the list is: {largestInteger}");
        }

        private static int FindLargestInteger(List<int> integerList)
        {
            if (integerList == null || integerList.Count == 0)
            {
                return -1;
            }
            var largestInteger = integerList[0];
            for (var i = 1; i < integerList.Count; i++)
            {
                if (integerList[i] > largestInteger)
                {
                    largestInteger = integerList[i];
                }
            }
            return largestInteger;
        }

        private static void LogError(string message)
        {
            // Use an existing logging framework for error tracking and performance monitoring
            var logger = new Logger();
            logger.LogError(message);
        }
    }
}
