#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for each dataset
typedef struct {
    int *offsets; // Array of offsets for each record
    char **keys; // Array of keys for each record
    void **records; // Array of records for each key
    size_t num_records; // Number of records in the dataset
} dataset_t;

// Define the structure for the memory pool manager
typedef struct {
    void *memory; // Pointer to the memory block
    size_t size; // Size of the memory block
    size_t used; // Amount of memory currently in use
} mempool_t;

// Define the structure for the function's state
typedef struct {
    dataset_t *datasets; // Array of datasets
    int num_datasets; // Number of datasets
    mempool_t *mempool; // Memory pool manager
    pthread_mutex_t mutex; // Mutex for synchronizing access to the memory pool
} state_t;

// Function to add a new dataset
void add_dataset(state_t *state, int num_records) {
    // Allocate memory for the new dataset
    dataset_t *new_dataset = malloc(sizeof(dataset_t));
    if (new_dataset == NULL) {
        printf("Error: Failed to allocate memory for new dataset\n");
        return;
    }

    // Initialize the new dataset
    new_dataset->offsets = malloc(num_records * sizeof(int));
    new_dataset->keys = malloc(num_records * sizeof(char*));
    new_dataset->records = malloc(num_records * sizeof(void*));
    new_dataset->num_records = num_records;

    // Add the new dataset to the array of datasets
    state->datasets = realloc(state->datasets, (state->num_datasets + 1) * sizeof(dataset_t));
    if (state->datasets == NULL) {
        printf("Error: Failed to allocate memory for new dataset\n");
        return;
    }
    state->datasets[state->num_datasets++] = new_dataset;
}

// Function to remove a dataset
void remove_dataset(state_t *state, int index) {
    // Check if the index is valid
    if (index < 0 || index >= state->num_datasets) {
        printf("Error: Invalid index for removing dataset\n");
        return;
    }

    // Free the memory for the dataset
    free(state->datasets[index]->offsets);
    free(state->datasets[index]->keys);
    free(state->datasets[index]->records);
    free(state->datasets[index]);

    // Shift the remaining datasets to fill the gap
    for (int i = index; i < state->num_datasets - 1; i++) {
        state->datasets[i] = state->datasets[i + 1];
    }
    state->num_datasets--;
}

// Function to allocate memory from the memory pool
void *allocate(state_t *state, size_t size) {
    // Check if there is enough memory in the pool
    if (size > state->mempool->size - state->mempool->used) {
        printf("Error: Not enough memory in the pool\n");
        return NULL;
    }

    // Allocate memory from the pool
    void *memory = state->mempool->memory + state->mempool->used;
    state->mempool->used += size;

    return memory;
}

// Function to deallocate memory from the memory pool
void deallocate(state_t *state, void *memory) {
    // Check if the memory is valid
    if (memory < state->mempool->memory || memory > state->mempool->memory + state->mempool->size) {
        printf("Error: Invalid memory address\n");
        return;
    }

    // Deallocate the memory from the pool
    size_t size = (char*)memory - (char*)state->mempool->memory;
    state->mempool->used -= size;
}

// Function to generate a random value for a record
int generate_random(state_t *state, int min, int max) {
    // Generate a random number between the minimum and maximum values
    return rand() % (max - min + 1) + min;
}

// Function to add a new record to a dataset
void add_record(state_t *state, int dataset_index, void *record) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for adding record\n");
        return;
    }

    // Allocate memory for the new record
    size_t size = sizeof(void*);
    void *new_record = allocate(state, size);
    if (new_record == NULL) {
        printf("Error: Failed to allocate memory for new record\n");
        return;
    }

    // Add the new record to the dataset
    state->datasets[dataset_index]->records = realloc(state->datasets[dataset_index]->records, (state->datasets[dataset_index]->num_records + 1) * sizeof(void*));
    if (state->datasets[dataset_index]->records == NULL) {
        printf("Error: Failed to allocate memory for new record\n");
        return;
    }
    state->datasets[dataset_index]->records[state->datasets[dataset_index]->num_records++] = new_record;
}

// Function to remove a record from a dataset
void remove_record(state_t *state, int dataset_index, int record_index) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for removing record\n");
        return;
    }
    if (record_index < 0 || record_index >= state->datasets[dataset_index]->num_records) {
        printf("Error: Invalid index for removing record\n");
        return;
    }

    // Deallocate the memory for the record
    deallocate(state, state->datasets[dataset_index]->records[record_index]);

    // Shift the remaining records to fill the gap
    for (int i = record_index; i < state->datasets[dataset_index]->num_records - 1; i++) {
        state->datasets[dataset_index]->records[i] = state->datasets[dataset_index]->records[i + 1];
    }
    state->datasets[dataset_index]->num_records--;
}

// Function to update a record in a dataset
void update_record(state_t *state, int dataset_index, int record_index, void *record) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for updating record\n");
        return;
    }
    if (record_index < 0 || record_index >= state->datasets[dataset_index]->num_records) {
        printf("Error: Invalid index for updating record\n");
        return;
    }

    // Deallocate the memory for the old record
    deallocate(state, state->datasets[dataset_index]->records[record_index]);

    // Allocate memory for the new record
    size_t size = sizeof(void*);
    void *new_record = allocate(state, size);
    if (new_record == NULL) {
        printf("Error: Failed to allocate memory for new record\n");
        return;
    }

    // Update the record in the dataset
    state->datasets[dataset_index]->records[record_index] = new_record;
}

// Function to retrieve a record from a dataset
void *get_record(state_t *state, int dataset_index, int record_index) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for retrieving record\n");
        return NULL;
    }
    if (record_index < 0 || record_index >= state->datasets[dataset_index]->num_records) {
        printf("Error: Invalid index for retrieving record\n");
        return NULL;
    }

    // Return the record from the dataset
    return state->datasets[dataset_index]->records[record_index];
}

// Function to retrieve a random record from a dataset
void *get_random_record(state_t *state, int dataset_index) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for retrieving random record\n");
        return NULL;
    }

    // Generate a random index for the record
    int random_index = generate_random(state, 0, state->datasets[dataset_index]->num_records - 1);

    // Return the record from the dataset
    return get_record(state, dataset_index, random_index);
}

// Function to retrieve a record by key from a dataset
void *get_record_by_key(state_t *state, int dataset_index, char *key) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for retrieving record by key\n");
        return NULL;
    }

    // Search for the record with the given key
    for (int i = 0; i < state->datasets[dataset_index]->num_records; i++) {
        if (strcmp(state->datasets[dataset_index]->keys[i], key) == 0) {
            return get_record(state, dataset_index, i);
        }
    }

    // Return NULL if the record is not found
    return NULL;
}

// Function to retrieve a random record by key from a dataset
void *get_random_record_by_key(state_t *state, int dataset_index) {
    // Check if the index is valid
    if (dataset_index < 0 || dataset_index >= state->num_datasets) {
        printf("Error: Invalid index for retrieving random record by key\n");
        return NULL;
    }

    // Generate a random key
    char *random_key = generate_random(state, 0, state->datasets[dataset_index]->num_records - 1);

    // Search for the record with the given key
    for (int i = 0; i < state->datasets[dataset_index]->num_records; i++) {
        if (strcmp(state->datasets[dataset_index]->keys[i], random_key) == 0) {
            return get_record(state, dataset_index, i);
        }
    }

    // Return NULL if the record is not found
    return NULL;
}

// Function to clear all allocated resources and reset the memory pool
void clear_resources(state_t *state) {
    // Free the memory for each dataset
    for (int i = 0; i < state->num_datasets; i++) {
        free(state->datasets[i]->offsets);
        free(state->datasets[i]->keys);
        free(state->datasets[i]->records);
        free(state->datasets[i]);
    }

    // Reset the memory pool
    state->mempool->used = 0;
}
