#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a record structure to store an int value and a pointer to a long
typedef struct {
    int value;
    long *ptr;
} record;

// Define a function to dynamically manage memory for offsets, keys, and records
void dynamic_memory_management(int num_records) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offsets to random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 100 + 1;
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the keys to random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100 + 1;
    }

    // Allocate memory for the record structure array
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record values and pointers
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1;
        records[i].ptr = malloc(sizeof(long));
