            printf("Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
    }

    // Preallocate memory for the offset array and key array to reduce reallocation overhead
    int preallocation_size = 1000;
    long *preallocated_offsets = (long *)malloc(preallocation_size * sizeof(long));
    if (!preallocated_offsets) {
        printf("Error: Failed to allocate memory for preallocated offsets\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }
    int *preallocated_keys = (int *)malloc(preallocation_size * sizeof(int));
    if (!preallocated_keys) {
        printf("Error: Failed to allocate memory for preallocated keys\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Reallocate the offset and key arrays as needed to accommodate up to 10,000 records
    while (num_records < 10000) {
        preallocation_size *= 2;
        long *reallocated_offsets = (long *)realloc(preallocated_offsets, preallocation_size * sizeof(long));
        if (!reallocated_offsets) {
            printf("Error: Failed to reallocate memory for offsets\n");
            free(preallocated_offsets);
            free(preallocated_keys);
            return;
        }
        preallocated_offsets = reallocated_offsets;
        int *reallocated_keys = (int *)realloc(preallocated_keys, preallocation_size * sizeof(int));
        if (!reallocated_keys) {
            printf("Error: Failed to reallocate memory for keys\n");
            free(preallocated_offsets);
            free(preallocated_keys);
            return;
        }
        preallocated_keys = reallocated_keys;
    }

    // Copy the preallocated offsets and keys to the actual offset and key arrays
    memcpy(offsets, preallocated_offsets, num_records * sizeof(long));
    memcpy(keys, preallocated_keys, num_records * sizeof(int));

    // Free the preallocated memory
    free(preallocated_offsets);
    free(preallocated_keys);

    // Reallocate the record structure array as needed to accommodate up to 10,000 records
    while (num_records < 10000) {
        preallocation_size *= 2;
        record *reallocated_records = (record *)realloc(records, preallocation_size * sizeof(record));
        if (!reallocated_records) {
            printf("Error: Failed to reallocate memory for records\n");
            free(offsets);
            free(keys);
            return;
        }
        records = reallocated_records;
    }

    // Free the memory allocated for the record structure array
    free(records);

    // Print the final results
    printf("Final offsets: ");
    for (int i = 0; i < num_records; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Final keys: ");
    for (int i = 0; i < num_records; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
}
