void shortest_path(vertex_t *vertices, int num_vertices, edge_t *edges, int num_edges, int src, int dst) {
    // Initialize the distance and predecessor arrays for each vertex
    float *distances = (float *)malloc(num_vertices * sizeof(float));
    if (distances == NULL) {
        printf("Error: Failed to allocate memory for distances\n");
        return;
    }
    int *predecessors = (int *)malloc(num_vertices * sizeof(int));
    if (predecessors == NULL) {
        printf("Error: Failed to allocate memory for predecessors\n");
        free(distances);
        return;
    }

    // Initialize the distance and predecessor arrays for each vertex
    for (int i = 0; i < num_vertices; i++) {
        distances[i] = INFINITY;
        predecessors[i] = -1;
    }

    // Set the source vertex as the starting point
    distances[src] = 0.0f;
    predecessors[src] = src;

    // Loop until all vertices have been visited
    while (true) {
        // Find the unvisited vertex with the minimum distance
        int min_distance = INFINITY;
        int min_vertex = -1;
        for (int i = 0; i < num_vertices; i++) {
            if (distances[i] < min_distance && distances[i] != INFINITY) {
                min_distance = distances[i];
                min_vertex = i;
            }
        }

        // If no unvisited vertex has been found, the algorithm is complete
        if (min_vertex == -1) {
            break;
        }

        // Update the distance and predecessor arrays for each neighbor of the current vertex
        for (int i = 0; i < num_edges; i++) {
            int neighbor = edges[i].dst;
            if (neighbor == min_vertex) {
                float new_distance = distances[min_vertex] + edges[i].weight;
                if (new_distance < distances[neighbor]) {
                    distances[neighbor] = new_distance;
                    predecessors[neighbor] = min_vertex;
                }
            }
        }
    }

    // Print the shortest path from the source vertex to the destination vertex
    int current_vertex = dst;
    while (current_vertex != -1) {
        printf("%d ", current_vertex);
        current_vertex = predecessors[current_vertex];
    }
    printf("\n");

    // Free the memory allocated for the distance and predecessor arrays
    free(distances);
    free(predecessors);
}
