#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Custom allocator for fixed-size and variable-size blocks
struct block {
    size_t size;
    void* data;
};

struct memory_pool {
    struct block* blocks;
    size_t num_blocks;
    size_t capacity;
};

void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->num_blocks = 0;
    pool->blocks = malloc(sizeof(struct block) * capacity);
}

void free_memory_pool(struct memory_pool* pool) {
    for (size_t i = 0; i < pool->num_blocks; i++) {
        free(pool->blocks[i].data);
    }
    free(pool->blocks);
}

void* allocate_memory(struct memory_pool* pool, size_t size) {
    if (size > pool->capacity) {
        return NULL;
    }
    for (size_t i = 0; i < pool->num_blocks; i++) {
        if (pool->blocks[i].size >= size) {
            void* data = pool->blocks[i].data;
            pool->blocks[i].size -= size;
            return data;
        }
    }
    // No block found, allocate a new one
    struct block* new_block = malloc(sizeof(struct block) * size);
    if (new_block == NULL) {
        return NULL;
    }
    pool->num_blocks++;
    pool->blocks[pool->num_blocks - 1].size = size;
    pool->blocks[pool->num_blocks - 1].data = new_block;
    return new_block;
}

void deallocate_memory(struct memory_pool* pool, void* data) {
    for (size_t i = 0; i < pool->num_blocks; i++) {
        if (pool->blocks[i].data == data) {
            pool->blocks[i].size += sizeof(struct block);
            return;
        }
    }
}

// Custom hash function for mapping data points to memory blocks
unsigned int hash_function(const void* key, size_t capacity) {
    unsigned int hash = 0;
    const char* str = (const char*)key;
    for (size_t i = 0; i < strlen(str); i++) {
        hash = (hash << 5) - hash + str[i];
    }
    return hash % capacity;
}

// Custom memory pool manager with efficient coalescing of free blocks
struct memory_pool* create_memory_pool(size_t capacity) {
    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    init_memory_pool(pool, capacity);
    return pool;
}

void destroy_memory_pool(struct memory_pool* pool) {
    free_memory_pool(pool);
    free(pool);
}

void* allocate_data_point(struct memory_pool* pool, size_t size) {
    void* data = allocate_memory(pool, sizeof(double) + sizeof(char*));
    if (data == NULL) {
        return NULL;
    }
    double* dp = (double*)data;
    char** str = (char**)(dp + 1);
    *str = malloc(size);
    if (*str == NULL) {
        free_memory_pool(pool);
        return NULL;
    }
    return data;
}

void deallocate_data_point(struct memory_pool* pool, void* data) {
    deallocate_memory(pool, data);
}

// Random number generation with thread-safe seeding and no predictability issues
unsigned int random_number(size_t lower_bound, size_t upper_bound) {
    static unsigned int seed = 0;
    if (seed == 0) {
        seed = time(NULL);
    }
    return rand_r(&seed) % (upper_bound - lower_bound + 1) + lower_bound;
}

// Custom random number generator with adjustable seeding and no predictability issues
unsigned int custom_random_number(size_t lower_bound, size_t upper_bound) {
    static unsigned int seed = 0;
    if (seed == 0) {
        seed = time(NULL);
    }
    return rand_r(&seed) % (upper_bound - lower_bound + 1) + lower_bound;
}

// Loop to set the value of each data point's double field to a random floating-point number within a specified range
void set_random_double(struct memory_pool* pool, size_t num_data_points, size_t lower_bound, size_t upper_bound) {
    for (size_t i = 0; i < num_data_points; i++) {
        void* data = allocate_data_point(pool, sizeof(double));
