#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a struct to store 'struct item' objects
typedef struct {
    float f;
    int i;
    char c;
} item_t;

// Function to manage dynamic memory allocation and initialization for three distinct data structures
void initialize_data(double *doubles, char **strings, item_t **items) {
    // Allocate memory for the 'double' precision floating-point numbers
    doubles = (double *)malloc(sizeof(double) * 10);
    if (!doubles) {
        printf("Error: Failed to allocate memory for 'double' precision floating-point numbers\n");
        return;
    }

    // Initialize the 'double' precision floating-point numbers
    for (int i = 0; i < 10; i++) {
        doubles[i] = i * 0.5;
    }

    // Allocate memory for the 'char' strings
    strings = (char **)malloc(sizeof(char *) * 10);
    if (!strings) {
        printf("Error: Failed to allocate memory for 'char' strings\n");
        free(doubles);
        return;
    }

    // Initialize the 'char' strings
    for (int i = 0; i < 10; i++) {
        strings[i] = malloc(sizeof(char) * 10);
        if (!strings[i]) {
            printf("Error: Failed to allocate memory for 'char' string %d\n", i);
            free(doubles);
            free(strings);
            return;
        }
        strcpy(strings[i], "Hello, world!");
    }

    // Allocate memory for the 'struct item' objects
    items = (item_t **)malloc(sizeof(item_t *) * 10);
    if (!items) {
        printf("Error: Failed to allocate memory for 'struct item' objects\n");
        free(doubles);
        free(strings);
        return;
    }

    // Initialize the 'struct item' objects
    for (int i = 0; i < 10; i++) {
        items[i] = malloc(sizeof(item_t));
        if (!items[i]) {
            printf("Error: Failed to allocate memory for 'struct item' object %d\n", i);
            free(doubles);
            free(strings);
            free(items);
            return;
        }
        items[i]->f = i * 0.5;
        items[i]->i = i;
        items[i]->c = 'a' + i;
    }
}

// Function to free the allocated memory
void cleanup_data(double *doubles, char **strings, item_t **items) {
    // Free the memory for the 'double' precision floating-point numbers
    if (doubles) {
        free(doubles);
    }

    // Free the memory for the 'char' strings
    if (strings) {
        for (int i = 0; i < 10; i++) {
            if (strings[i]) {
                free(strings[i]);
            }
        }
        free(strings);
    }

    // Free the memory for the 'struct item' objects
    if (items) {
        for (int i = 0; i < 10; i++) {
            if (items[i]) {
                free(items[i]);
            }
        }
        free(items);
    }
}
