    if (argc < 4) {
        printf("Usage: %s <long offset array size> <int key array size> <record array size>\n", argv[0]);
        return 1;
    }
    int long_offset_size = atoi(argv[1]);
    int int_key_size = atoi(argv[2]);
    int record_size = atoi(argv[3]);
    if (long_offset_size < 0 || int_key_size < 0 || record_size < 0) {
        printf("Invalid input sizes. Must be non-negative.\n");
        return 1;
    }
    size_t memory_pool_size = long_offset_size + int_key_size + record_size;
    if (memory_pool_size > MEMORY_POOL_SIZE) {
        printf("Memory pool size exceeds maximum of %d elements.\n", MEMORY_POOL_SIZE);
        return 1;
    }

    // Initialize memory pool and record array
    MemoryPool* memory_pool = (MemoryPool*) allocate(sizeof(MemoryPool));
    memory_pool->size = memory_pool_size;
    memory_pool->pool = allocate(memory_pool_size * sizeof(void*));
    pthread_mutex_init(&memory_pool->lock, NULL);
    Record* record_array = (Record*) allocate(record_size * sizeof(Record));

    // Initialize seed for random number generator based on current time
    srand(time(NULL));

    // Populate record array with random integer values
    for (int i = 0; i < record_size; i++) {
        initialize_record(&record_array[i], rand());
    }

    // Clear memory pool and reset memory management system on exit
    atexit(clear_memory_pool);

    return 0;
}

void* allocate(size_t size) {
    MemoryPool* memory_pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (!memory_pool) {
        printf("Failed to allocate memory pool.\n");
        exit(1);
    }
    memory_pool->size = size;
    memory_pool->pool = malloc(size * sizeof(void*));
    if (!memory_pool->pool) {
        printf("Failed to allocate memory pool.\n");
        free(memory_pool);
        exit(1);
    }
    pthread_mutex_init(&memory_pool->lock, NULL);
    return memory_pool;
}

void deallocate(void* ptr) {
    MemoryPool* memory_pool = (MemoryPool*) ptr;
    free(memory_pool->pool);
    pthread_mutex_destroy(&memory_pool->lock);
    free(memory_pool);
}

void initialize_record(Record* record, int value) {
    record->value = value;
}

void clear_memory_pool() {
    MemoryPool* memory_pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (!memory_pool) {
        printf("Failed to allocate memory pool.\n");
        exit(1);
    }
    memory_pool->size = 0;
    memory_pool->pool = NULL;
    pthread_mutex_destroy(&memory_pool->lock);
    free(memory_pool);
}
