void resolve_hostname(const char *hostname) {
    // Initialize the DNS resolver
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Perform the DNS resolution
    struct addrinfo *result;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        printf("Failed to resolve hostname\n");
        return;
    }

    // Print the resolved IP address
    char ip_address[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &((struct sockaddr_in *)result->ai_addr)->sin_addr, ip_address, INET_ADDRSTRLEN);
    printf("Resolved IP address: %s\n", ip_address);

    // Free the memory allocated for the DNS resolution result
    freeaddrinfo(result);
}

