    printf("Free memory: %zu bytes\n", pool->free_memory);
    printf("Memory pool utilization: %.2f%%\n", (pool->used_memory / (double)pool->size) * 100.0);
}

// Function to clear all allocated resources and reset the memory pool
void reset_memory_pool() {
    // Get the memory pool manager
    struct memory_pool *pool = get_memory_pool();
    if (!pool) {
        printf("Failed to get memory pool\n");
        return;
    }

    // Clear all allocated resources and reset the memory pool
    clear_resources(pool->memory, pool->size);
}
