db = SQLAlchemy(app)
Base = declarative_base()

class Post(Base):
    __tablename__ = "posts"
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    content = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow())
    updated_at = db.Column(db.DateTime, onupdate=datetime.utcnow())

class PostCache:
    def __init__(self):
        self.cache = {}

post_cache = PostCache()

@app.route("/posts", methods=["GET"])
def get_posts():
    posts = []
    for post in db.session.query(Post).all():
        posts.append({"id": post.id, "title": post.title, "content": post.content})
    return jsonify(posts)

@app.route("/posts", methods=["POST"])
def create_post():
    data = request.get_json()
    if not data:
        return jsonify({"error": "Invalid request"}), 400
    try:
        post = Post(title=data["title"], content=data["content"])
        db.session.add(post)
        db.session.commit()
        post_cache.cache[post.id] = {"title": post.title, "content": post.content}
        return jsonify({"message": f"Post {post.id} created successfully"}), 201
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "Failed to create post"}), 500

@app.route("/posts/<int:post_id>", methods=["PUT"])
def update_post(post_id):
    data = request.get_json()
    if not data:
        return jsonify({"error": "Invalid request"}), 400
    try:
        post = db.session.query(Post).filter_by(id=post_id).one()
        post.title = data["title"]
        post.content = data["content"]
        db.session.commit()
        post_cache.cache[post.id] = {"title": post.title, "content": post.content}
        return jsonify({"message": f"Post {post.id} updated successfully"}), 200
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "Failed to update post"}), 500

@app.route("/posts/<int:post_id>", methods=["DELETE"])
def delete_post(post_id):
    try:
        post = db.session.query(Post).filter_by(id=post_id).one()
        db.session.delete(post)
        db.session.commit()
        del post_cache.cache[post.id]
        return jsonify({"message": f"Post {post.id} deleted successfully"}), 200
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "Failed to delete post"}), 500

@app.route("/posts/<int:post_id>/history", methods=["GET"])
def get_post_history(post_id):
    try:
        post = db.session.query(Post).filter_by(id=post_id).one()
        history = []
        for version in post.versions:
            history.append({"version": version.version, "title": version.title, "content": version.content})
        return jsonify(history)
    except IntegrityError:
        db.session.rollback()
        return jsonify({"error": "Failed to retrieve post history"}), 500
