void destroyMemoryPoolManager(struct MemoryPoolManager *manager) {
    // Free all the free blocks in the pool
    struct FreeBlock *block = manager->freeList;
    while (block != NULL) {
        struct FreeBlock *next = block->next;
        free(block);
        block = next;
    }
}

void *allocateMemoryPoolBlock(struct MemoryPoolManager *manager, size_t size) {
    // Check if there are any free blocks in the pool
    if (manager->numFreeBlocks > 0) {
        // Get the first free block from the list
        struct FreeBlock *block = manager->freeList;

        // Remove the block from the list
        manager->freeList = block->next;
        --manager->numFreeBlocks;

        // Return the block
        return block;
    } else {
        // Allocate a new block of memory
        void *block = malloc(size);
        if (block == NULL) {
            // Handle allocation failure
            return NULL;
        }

        // Return the block
        return block;
    }
}

