    // Integrate the DNS resolution function into the main function's workflow, providing the resolved IP addresses as part of the final output
    struct in_addr* resolvedAddrs = (struct in_addr*)malloc(sizeof(struct in_addr) * arraySize);
    for (int i = 0; i < arraySize; i++) {
