// Custom memory management system
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
}

void freeMemoryPool(struct MemoryPool* pool) {
    free(pool->buffer);
}

void* allocate(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

void deallocate(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->buffer || ptr >= pool->buffer + pool->capacity) {
        return;
    }
    size_t offset = ptr - pool->buffer;
    memset(ptr, 0, sizeof(char));
    pool->used -= offset;
}

