    for (size_t i = 0; i < manager->numPools; i++) {
        freeMemoryPool(&manager->pools[i]);
    }
    free(manager->pools);
}

void* allocateFromPool(struct MemoryPoolManager* manager, size_t poolIndex, size_t size) {
    struct MemoryPool* pool = &manager->pools[poolIndex];
    void* ptr = allocate(pool, size);
