    int i;
    for (i = 0; i < 5; i++) {
        if (lib->edge_algos[i] == NULL) {
            lib->edge_algos[i] = malloc(sizeof(edge_algo_t));
            lib->edge_algos[i]->name = name;
            lib->edge_algos[i]->detect = detect;
