    pthread_mutex_init(&pool->mutex, NULL);
}

// Create a new data pool with the specified number of records
data_pool_t *create_data_pool(size_t num_records) {
    // Allocate memory for the data pool structure
    data_pool_t *pool = (data_pool_t *)malloc(sizeof(data_pool_t));

    // Initialize the data pool structure
    init_data_pool(pool, num_records);

    return pool;
}

// Add a new memory pool to the manager
void add_memory_pool(mem_pool_manager_t *manager, size_t size) {
    // Allocate memory for the new memory pool
    void **new_pools = (void **)realloc(manager->memory_pools, (manager->num_pools + 1) * sizeof(void *));
    if (!new_pools) {
        fprintf(stderr, "Failed to allocate memory for new memory pool\n");
        return;
    }

    // Initialize the new memory pool
    new_pools[manager->num_pools] = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (new_pools[manager->num_pools] == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for new memory pool\n");
        return;
    }

    // Increment the number of pools and reallocate the memory pool array
    manager->num_pools++;
    manager->memory_pools = new_pools;
}

// Allocate memory for a record in the data pool
void *allocate_record(data_pool_t *pool) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Check if there is enough space in the current memory pool for a new record
    if (pool->num_records == pool->max_records) {
        // If not, add a new memory pool to the manager and allocate a new record in it
        add_memory_pool(mem_pool_manager, pool->max_records * sizeof(record_t));
        pool->records = (record_t *)realloc(pool->records, pool->max_records * sizeof(record_t));
    }

    // Allocate a new record in the current memory pool and return its address
    void *new_record = &pool->records[pool->num_records++];
    pthread_mutex_unlock(&pool->mutex);

    return new_record;
}

// Free a record from the data pool
void free_record(data_pool_t *pool, void *record) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Decrement the number of records in the current memory pool and release the record
    pool->num_records--;
    free(record);

    pthread_mutex_unlock(&pool->mutex);
}

// Look up a record by its key in the data pool
void *lookup_record(data_pool_t *pool, int key) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Search for the record with the specified key in the current memory pool
    for (size_t i = 0; i < pool->num_records; i++) {
        if (pool->keys[i] == key) {
            void *record = &pool->records[i];
            pthread_mutex_unlock(&pool->mutex);
            return record;
        }
    }

    // If the record is not found, search in the other memory pools
    for (size_t i = 0; i < mem_pool_manager->num_pools; i++) {
        void *record = lookup_record(mem_pool_manager->memory_pools[i], key);
        if (record) {
            pthread_mutex_unlock(&pool->mutex);
            return record;
        }
    }

    // If the record is not found in any memory pool, return NULL
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

// Update a record by its key in the data pool
void update_record(data_pool_t *pool, int key, void *record) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

