    // If the record is not found, search in the other memory pools
    for (size_t i = 0; i < mem_pool_manager->num_pools; i++) {
        update_record(mem_pool_manager->memory_pools[i], key, record);
    }

    // If the record is not found in any memory pool, add a new record to the current memory pool
    void *new_record = allocate_record(pool);
    memcpy(&pool->records[pool->num_records++], record, sizeof(record_t));
    pthread_mutex_unlock(&pool->mutex);
}

// Delete a record by its key from the data pool
void delete_record(data_pool_t *pool, int key) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Search for the record with the specified key in the current memory pool
    for (size_t i = 0; i < pool->num_records; i++) {
        if (pool->keys[i] == key) {
