    }

    // If the record is not found in any memory pool, do nothing
    pthread_mutex_unlock(&pool->mutex);
}

// Monitor and report memory usage statistics for the data pool
void monitor_memory_usage(data_pool_t *pool) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Calculate the total allocated memory and free memory in the current memory pool
    size_t total_allocated = 0;
    size_t total_free = 0;
    for (size_t i = 0; i < pool->num_records; i++) {
        total_allocated += sizeof(record_t);
    }
    total_free = pool->max_records * sizeof(record_t) - total_allocated;

    // Calculate the memory pool utilization and print the statistics
    float utilization = (float)total_allocated / (pool->max_records * sizeof(record_t));
    printf("Memory usage statistics for data pool %p:\n", pool);
    printf("\tTotal allocated memory: %zu bytes\n", total_allocated);
    printf("\tTotal free memory: %zu bytes\n", total_free);
    printf("\tMemory pool utilization: %.2f%%\n", utilization * 100);

    pthread_mutex_unlock(&pool->mutex);
}

// Implement a caching mechanism to improve lookup performance for frequently accessed records
void cache_record(data_pool_t *pool, int key) {
    // Acquire the mutex to ensure thread-safe operations
    pthread_mutex_lock(&pool->mutex);

    // Search for the record with the specified key in the current memory pool
    for (size_t i = 0; i < pool->num_records; i++) {
        if (pool->keys[i] == key) {
