use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
};

use tokio::runtime::Runtime;

struct Node {
    value: f64,
}

struct LinkedList {
    nodes: Vec<Node>,
}

impl LinkedList {
    fn new() -> Self {
        LinkedList {
            nodes: Vec::new(),
        }
    }

    fn insert_node(&mut self, index: usize, value: f64) {
        let node = Node { value };
        self.nodes.insert(index, node);
    }
}

struct MemoryManager {
    allocated_memory: HashMap<usize, Arc<Mutex<Vec<u8>>>>,
}

impl MemoryManager {
    fn new() -> Self {
        MemoryManager {
            allocated_memory: HashMap::new(),
        }
    }

    fn allocate(&mut self, size: usize) -> Arc<Mutex<Vec<u8>>> {
        let mutex = Arc::new(Mutex::new(vec![0; size]));
        self.allocated_memory.insert(size, mutex.clone());
        mutex
    }

    fn deallocate(&mut self, size: usize) {
        self.allocated_memory.remove(&size);
    }
}

struct MemoryPool {
    memory_manager: MemoryManager,
}

impl MemoryPool {
    fn new() -> Self {
        MemoryPool {
            memory_manager: MemoryManager::new(),
        }
    }

    fn allocate(&mut self, size: usize) -> Arc<Mutex<Vec<u8>>> {
        self.memory_manager.allocate(size)
    }

    fn deallocate(&mut self, size: usize) {
        self.memory_manager.deallocate(size);
    }
}

struct NodeReferenceCounter {
    count: usize,
}

impl NodeReferenceCounter {
    fn new() -> Self {
        NodeReferenceCounter { count: 0 }
    }

    fn increment(&mut self) {
        self.count += 1;
    }

    fn decrement(&mut self) {
        self.count -= 1;
    }
}

struct LinkedListManager {
    linked_lists: HashMap<usize, LinkedList>,
    node_reference_counters: HashMap<usize, NodeReferenceCounter>,
}

impl LinkedListManager {
    fn new() -> Self {
        LinkedListManager {
            linked_lists: HashMap::new(),
            node_reference_counters: HashMap::new(),
        }
    }

    fn create_linked_list(&mut self, size: usize) -> LinkedList {
        let mut linked_list = LinkedList::new();
        for i in 0..size {
            linked_list.insert_node(i, rand::random());
        }
        self.linked_lists.insert(size, linked_list);
        self.node_reference_counters.insert(size, NodeReferenceCounter::new());
    }

    fn get_linked_list(&mut self, size: usize) -> &mut LinkedList {
        self.linked_lists.get_mut(&size).unwrap()
    }

    fn delete_linked_list(&mut self, size: usize) {
        self.linked_lists.remove(&size);
        self.node_reference_counters.remove(&size);
    }
}

struct DataManagementSystem {
    memory_pool: MemoryPool,
    linked_list_manager: LinkedListManager,
}

impl DataManagementSystem {
    fn new() -> Self {
        DataManagementSystem {
            memory_pool: MemoryPool::new(),
            linked_list_manager: LinkedListManager::new(),
        }
    }

    fn execute_operation(&mut self, operation: Operation) {
        match operation {
            Operation::CreateLinkedList(size) => {
                let mut linked_list = self.linked_list_manager.create_linked_list(size);
                for node in &mut linked_list.nodes {
                    let memory_block = self.memory_pool.allocate(8);
                    node.value = f64::from_bits(u64::to_ne_bytes(rand::random()));
                    self.node_reference_counters[&size].increment();
                }
            }
            Operation::ModifyLinkedList(index, value) => {
                let linked_list = self.linked_list_manager.get_linked_list(index);
                linked_list.nodes[index].value = value;
            }
            Operation::DeleteLinkedList(size) => {
                self.linked_list_manager.delete_linked_list(size);
            }
        }
    }
}

enum Operation {
    CreateLinkedList(usize),
    ModifyLinkedList(usize, f64),
    DeleteLinkedList(usize),
}

fn main() {
    let mut data_management_system = DataManagementSystem::new();
    let runtime = Runtime::new().unwrap();
    for operation in &mut runtime.block_on(parse_command_line()) {
        data_management_system.execute_operation(operation);
    }
}
