        if (line == NULL) {
            break;
        }
        head->data[i].value = atof(line);
        head->data[i].str_value = malloc(byte_array_size);
        strcpy(head->data[i].str_value, line);
        head->data[i].key = i;
    }
    fclose(file);

    // Shuffle the records using a random number generator seeded with the specified seed
    srand(shuffle_seed);
    for (int i = 0; i < record_limit - 1; i++) {
        int j = rand() % (record_limit - i) + i;
        if (j != i) {
            record *temp = head->data + sizeof(record) * i;
            head->data + sizeof(record) * j = temp;
            temp->key = j;
        }
    }
