// Custom hash function for long integers
unsigned long hash(long x) {
    return (x >> 32) ^ (x & 0xFFFFFFFF);
}

// Memory pool structure
typedef struct {
    int size; // Current size of the memory pool
    int capacity; // Maximum capacity of the memory pool
    void** data; // Array of pointers to allocated memory blocks
} MemoryPool;

// Initialize a new memory pool with the given initial size and maximum capacity
MemoryPool* init_memory_pool(int initial_size, int max_capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->size = initial_size;
    pool->capacity = max_capacity;
    pool->data = calloc(max_capacity, sizeof(void*));
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Allocate a new memory block from the memory pool
void* allocate(MemoryPool* pool, int size) {
    // Check if there is enough space in the pool to allocate the requested size
    if (pool->size + size > pool->capacity) {
        return NULL;
    }
    void* ptr = malloc(size);
    if (!ptr) {
        return NULL;
    }
    // Add the new memory block to the pool
    pool->data[pool->size++] = ptr;
    return ptr;
}

// Free all allocated memory blocks in the memory pool
void free_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < pool->size; ++i) {
        free(pool->data[i]);
    }
    free(pool->data);
    free(pool);
}

// Custom collision resolution strategy for the hash table
typedef struct {
    int size; // Current size of the hash table
    int capacity; // Maximum capacity of the hash table
    long* keys; // Array of keys in the hash table
    void** values; // Array of values associated with each key
} HashTable;

// Initialize a new hash table with the given initial size and maximum capacity
HashTable* init_hash_table(int initial_size, int max_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->size = initial_size;
    table->capacity = max_capacity;
    table->keys = calloc(max_capacity, sizeof(long));
    if (!table->keys) {
        free(table);
        return NULL;
    }
    table->values = calloc(max_capacity, sizeof(void*));
    if (!table->values) {
        free(table->keys);
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new record into the hash table
int insert(HashTable* table, long key, void* value) {
    // Check if there is enough space in the hash table to store the new record
    if (table->size == table->capacity) {
        return -1;
    }
    // Calculate the hash of the key and find an empty slot for the new record
    long hash = hash(key);
    int index = hash % table->capacity;
    while (table->keys[index] != 0 && table->keys[index] != key) {
        index = (index + 1) % table->capacity;
    }
    // If the slot is already occupied by another record with the same key, update its value
    if (table->keys[index] == key) {
        table->values[index] = value;
        return 0;
    }
    // Otherwise, insert a new record into the hash table
    table->keys[index] = key;
    table->values[index] = value;
    table->size++;
    return 0;
}

// Retrieve a record from the hash table by its key
void* retrieve(HashTable* table, long key) {
    // Calculate the hash of the key and find the corresponding slot in the hash table
    long hash = hash(key);
    int index = hash % table->capacity;
    while (table->keys[index] != 0 && table->keys[index] != key) {
        index = (index + 1) % table->capacity;
    }
    // If the slot is empty or contains a different key, return NULL
    if (table->keys[index] == 0 || table->keys[index] != key) {
        return NULL;
    }
    // Otherwise, return the associated value
    return table->values[index];
}

// Clear all allocated resources and reset the memory pool
void clear_memory_pool(MemoryPool* pool) {
    for (int i = 0; i < pool->size; ++i) {
        free(pool->data[i]);
    }
    pool->size = 0;
}

// Clear all allocated resources and reset the hash table
void clear_hash_table(HashTable* table) {
    for (int i = 0; i < table->capacity; ++i) {
        free(table->values[i]);
    }
    table->size = 0;
}

