// Function to load configuration settings from a JSON file into a structured data model
void load_config(const char *filename, config *cfg) {
    // Open the JSON file and parse it into a json_object
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
