void save_config(const char *filename, config *cfg) {
    // Serialize the configuration data back to a JSON string
    json_object *json = cfg->json;
    char *str = json_to_string(json);

    // Open the JSON file and write the serialized data to it
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
