void update_config(const char *key, int value, config *cfg) {
    // Acquire the mutex for synchronizing access to the configuration data
    pthread_mutex_lock(&cfg->lock);

    // Find the key in the JSON object and update its value
    json_object *obj = cfg->json;
    json_object *key_obj = json_object_object_get(obj, key);
