// Define a record structure with a double value
typedef struct {
    double value;
} record;

// Define the memory pool size and the number of records to allocate
#define POOL_SIZE 1024
#define NUM_RECORDS 1000

// Define the range for random double values
#define MIN_VALUE -1.0
#define MAX_VALUE 1.0

// Define a mutex to protect the memory pool and record array
pthread_mutex_t mem_pool_lock;

// Function to allocate memory for the arrays
void* allocate_memory(size_t size) {
    void* ptr = NULL;
    if (size > 0) {
        ptr = malloc(size);
        if (!ptr) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
        }
    }
    return ptr;
}

// Function to initialize the record array with random double values
void init_records(record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = MIN_VALUE + ((double)rand() / RAND_MAX) * (MAX_VALUE - MIN_VALUE);
    }
}

// Function to allocate memory for the arrays and initialize the record array with random double values
void* init_memory(size_t num_records) {
    // Allocate memory for the offset array
    size_t offset_array_size = sizeof(long) * (num_records + 1);
    long* offsets = allocate_memory(offset_array_size);
    if (!offsets) {
        return NULL;
    }

    // Allocate memory for the key array
    size_t key_array_size = sizeof(int) * num_records;
    int* keys = allocate_memory(key_array_size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for the record array
    size_t record_array_size = sizeof(record) * num_records;
    record* records = allocate_memory(record_array_size);
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the offset array with the starting index of each record
    offsets[0] = 0;
    for (size_t i = 1; i <= num_records; i++) {
        offsets[i] = offsets[i - 1] + sizeof(record);
    }

    // Initialize the key array with random keys
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = rand() % NUM_RECORDS;
    }

    // Initialize the record array with random double values
    init_records(records, num_records);

    return records;
}

// Function to deallocate memory for the arrays
void free_memory(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

// Function to release resources and exit the program
void cleanup() {
    pthread_mutex_destroy(&mem_pool_lock);
    exit(0);
}

int main() {
    // Initialize the memory pool with a fixed size but allow resizing if needed
    void* mem_pool = allocate_memory(POOL_SIZE);
    if (!mem_pool) {
        fprintf(stderr, "Error: Failed to initialize memory pool\n");
        cleanup();
    }

