    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Detect and handle deadlocks gracefully, ensuring that the utility remains stable under high concurrency conditions
    pthread_mutex_lock(&mutex);
    while (true) {
        if (mempool.is_full()) {
            pthread_cond_wait(&cond, &mutex);
        } else {
