        }
    }
    pthread_mutex_unlock(&mutex);

    // Provide a mechanism to report detailed memory usage statistics, including total allocated memory, free memory, and memory pool utilization, at various stages of the utility’s operation
    printf("Memory usage: %lu bytes\n", mempool.get_total_allocated());
    printf("Free memory: %lu bytes\n", mempool.get_free_memory());
