#include <stdbool.h>
#include <pthread.h>

// Define the data structures for the configuration settings
typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    int size;
    Record* records;
} Configuration;

// Define the schema for the configuration file
const char* SCHEMA = "{\"type\": \"object\", \"properties\": {\"offset\": {\"type\": \"integer\"}, \"key\": {\"type\": \"string\"}}}";

// Define the function to load the configuration settings from a binary format
void LoadConfiguration(Configuration* config, const char* filename) {
    // Open the file and read its contents into memory
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    rewind(fp);
    char* buffer = (char*)malloc(size);
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for configuration file\n");
        fclose(fp);
        return;
    }
    size_t read = fread(buffer, 1, size, fp);
    if (read != size) {
        printf("Error: unable to read entire configuration file\n");
        free(buffer);
        fclose(fp);
        return;
    }
    fclose(fp);

    // Parse the JSON data in the buffer and validate it against the schema
    json_error_t error;
    json_t* root = json_loadb(buffer, size, 0, &error);
    if (root == NULL) {
        printf("Error: unable to parse configuration file\n");
        free(buffer);
        return;
    }
    bool valid = json_validate(root, SCHEMA, &error);
    if (!valid) {
        printf("Error: invalid configuration file\n");
        json_decref(root);
        free(buffer);
        return;
    }

    // Extract the offset and key values from the JSON data
    int offset = 0;
    const char* key = NULL;
    json_t* value = NULL;
    json_object_foreach(root, key, value) {
        if (strcmp(key, "offset") == 0) {
