int init_arrays(long *offsets, int *keys, record **records, int num_records, int min_value, int max_value) {
    // Check input parameters for validity
    if (num_records < 0 || min_value >= max_value) {
        return -1;
    }

    // Initialize random seed for generating random values
    srand(time(NULL));

    // Allocate memory for the offset and key arrays
