public:
    SocialMediaPostManager() {
        // Initialize the entries vector and entry map
        entries.reserve(100);
        for (int i = 0; i < 100; i++) {
            Entry entry;
            entry.timestamp = chrono::system_clock::now().time_since_epoch().count();
            entry.eventID = i + 1;
            entry.metricValue = (double)rand() / RAND_MAX * 100;
            entries.push_back(entry);
            entryMap[i] = entry;
        }
    }

    ~SocialMediaPostManager() {
        isRunning = false;
        cv.notify_all();
    }

    void addEntry(int eventID, const string& jsonPayload) {
        // Lock the entries mutex to prevent concurrent updates
        unique_lock<mutex> lock(entriesMutex);

        // Create a new entry and add it to the vector
        Entry entry;
        entry.timestamp = chrono::system_clock::now().time_since_epoch().count();
        entry.eventID = eventID;
        entry.metricValue = (double)rand() / RAND_MAX * 100;
        entries.push_back(entry);

        // Add the new entry to the map
        entryMap[eventID] = entry;

        // Notify all waiting threads that an update has occurred
        cv.notify_all();
    }

    void updateEntry(int eventID, const string& jsonPayload) {
        // Lock the entries mutex to prevent concurrent updates
        unique_lock<mutex> lock(entriesMutex);

        // Update the entry in the map and vector
        Entry& entry = entryMap[eventID];
        entry.timestamp = chrono::system_clock::now().time_since_epoch().count();
        entry.metricValue = (double)rand() / RAND_MAX * 100;
        entries[eventID] = entry;

        // Notify all waiting threads that an update has occurred
        cv.notify_all();
    }

    void deleteEntry(int eventID) {
        // Lock the entries mutex to prevent concurrent updates
        unique_lock<mutex> lock(entriesMutex);

        // Remove the entry from the map and vector
        entryMap.erase(eventID);
        entries.erase(remove_if(entries.begin(), entries.end(), [&](const Entry& e) { return e.eventID == eventID; }), entries.end());

        // Notify all waiting threads that an update has occurred
        cv.notify_all();
    }

    void getEntries(vector<Entry>& result) {
        // Lock the entries mutex to prevent concurrent updates
        unique_lock<mutex> lock(entriesMutex);

        // Copy the vector of entries into the result vector
        result = entries;
    }
};
