#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent a task
typedef struct {
    int priority;
    time_t deadline;
    char *description;
} Task;

// Define a linked list node to store tasks
typedef struct Node {
    Task task;
    struct Node *next;
} Node;

// Define a function to add a new task
void addTask(Node **head, int priority, time_t deadline, char *description) {
    // Create a new node for the task
    Node *newNode = malloc(sizeof(Node));
    newNode->task.priority = priority;
    newNode->task.deadline = deadline;
    newNode->task.description = description;
    newNode->next = NULL;

    // Check if the head is NULL, meaning there are no tasks yet
    if (*head == NULL) {
        *head = newNode;
    } else {
        // Find the correct position to insert the new task
        Node *current = *head;
        while (current->next != NULL && current->task.deadline < deadline) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Define a function to update an existing task
void updateTask(Node **head, int priority, time_t deadline, char *description) {
    // Find the task with the given priority and deadline
    Node *current = *head;
    while (current != NULL && current->task.priority != priority || current->task.deadline != deadline) {
        current = current->next;
    }

    // If the task is found, update its description and return
    if (current != NULL) {
        current->task.description = description;
        return;
    }

    // Otherwise, add a new task with the given priority and deadline
    addTask(head, priority, deadline, description);
}

// Define a function to delete an existing task
void deleteTask(Node **head, int priority, time_t deadline) {
    // Find the task with the given priority and deadline
    Node *current = *head;
    while (current != NULL && current->task.priority != priority || current->task.deadline != deadline) {
        current = current->next;
    }

    // If the task is found, delete it from the list and return
    if (current != NULL) {
        Node *previous = current->prev;
        previous->next = current->next;
        free(current);
        return;
    }
}

// Define a function to sort tasks based on priority and deadline
void sortTasks(Node **head) {
    // Create an array of tasks to be sorted
    Task *tasks = malloc(sizeof(Task) * 10000);
    int count = 0;
    Node *current = *head;
    while (current != NULL) {
        tasks[count++] = current->task;
        current = current->next;
    }

    // Sort the array of tasks based on priority and deadline
    qsort(tasks, count, sizeof(Task), compareTasks);

    // Update the linked list with the sorted tasks
    for (int i = 0; i < count; i++) {
        addTask(head, tasks[i].priority, tasks[i].deadline, tasks[i].description);
    }
}

// Define a function to compare two tasks based on priority and deadline
int compareTasks(const void *a, const void *b) {
    Task *taskA = (Task *)a;
    Task *taskB = (Task *)b;
    if (taskA->priority != taskB->priority) {
        return taskA->priority - taskB->priority;
    } else {
        return taskA->deadline - taskB->deadline;
    }
}
