    public class DynamicValueGenerator
    {
        private readonly ConcurrentDictionary<string, DistributionModel> _distributionModels = new ConcurrentDictionary<string, DistributionModel>();
        private readonly Random _random = new Random();

        public void AddDistributionModel(string name, Func<double, double> distribution)
        {
            if (_distributionModels.ContainsKey(name))
                throw new ArgumentException($"A distribution model with the name '{name}' already exists.");

            _distributionModels[name] = new DistributionModel(distribution);
        }

