                throw new ArgumentException($"No distribution model with the name '{distributionName}' exists.");

            var distribution = _distributionModels[distributionName];
            return distribution.GenerateValue();
        }

        public void ValidateAndProcessString(string input, int sizeLimit, int characterCountThreshold)
        {
            if (input.Length > sizeLimit)
                throw new ArgumentException($"The string length exceeds the limit of {sizeLimit} characters.");

            if (input.Count(c => c == '/') > characterCountThreshold)
                throw new ArgumentException($"The string contains more than {characterCountThreshold} forward slashes.");
        }

