        private readonly Func<double, double> _distribution;

        public DistributionModel(Func<double, double> distribution)
        {
            _distribution = distribution;
        }

        public double GenerateValue(int min, int max)
        {
            return _distribution.Invoke((max - min + 1) * _random.NextDouble() + min);
        }

        public double GenerateValue(double min, double max)
        {
            return _distribution.Invoke(_random.NextDouble() * (max - min) + min);
        }

        public double GenerateValue()
        {
            return _distribution.Invoke(_random.NextDouble());
        }
    }
