function traverseDOM(element, selector, performanceBudget) {
  const nodes = [];
  let currentNode = element;
  while (currentNode && !nodes.length) {
    if (currentNode.matches(selector)) {
      nodes.push(currentNode);
    } else {
      currentNode = currentNode.nextElementSibling || currentNode.parentElement;
    }
  }
  return nodes;
}
