// Define the project structure
typedef struct Project {
    int priority;
    time_t dueDate;
    char *title;
    enum Status status;
    void *resource;
} Project;

// Define the status enum
enum Status { PENDING, IN_PROGRESS, COMPLETED };

// Define the project collection structure
typedef struct ProjectCollection {
    int size;
    Project **projects;
} ProjectCollection;

// Function to add a new project to the collection
void addProject(ProjectCollection *collection, int priority, time_t dueDate, char *title, enum Status status, void *resource) {
    // Check if the due date is valid and does not conflict with existing projects
    for (int i = 0; i < collection->size; i++) {
        Project *project = collection->projects[i];
        if (dueDate == project->dueDate || dueDate < project->dueDate) {
            // Due date conflicts with an existing project, return early
            return;
        }
    }

    // Allocate memory for the new project
    Project *newProject = malloc(sizeof(Project));
    if (newProject == NULL) {
        // Memory allocation failed, handle error gracefully
        return;
    }

    // Initialize the new project fields
    newProject->priority = priority;
    newProject->dueDate = dueDate;
    newProject->title = title;
    newProject->status = status;
    newProject->resource = resource;

    // Add the new project to the collection
    collection->projects[collection->size++] = newProject;
}

// Function to sort the projects based on priority and due date in ascending order
void sortProjects(ProjectCollection *collection) {
    // Bubble sort implementation
    for (int i = 0; i < collection->size - 1; i++) {
        for (int j = 0; j < collection->size - i - 1; j++) {
            if (collection->projects[j]->priority > collection->projects[j + 1]->priority ||
                (collection->projects[j]->priority == collection->projects[j + 1]->priority &&
                 collection->projects[j]->dueDate > collection->projects[j + 1]->dueDate)) {
                Project *temp = collection->projects[j];
                collection->projects[j] = collection->projects[j + 1];
                collection->projects[j + 1] = temp;
            }
        }
    }
}

// Function to handle project rescheduling
void rescheduleProject(ProjectCollection *collection, int index, int newPriority) {
    // Check if the index is valid and the new priority is different from the current one
    if (index < 0 || index >= collection->size || collection->projects[index]->priority == newPriority) {
        return;
    }

    // Update the project's priority
    collection->projects[index]->priority = newPriority;
}

// Function to handle project deletion
void deleteProject(ProjectCollection *collection, int index) {
    // Check if the index is valid and there are still projects in the collection
    if (index < 0 || index >= collection->size || collection->size == 0) {
        return;
    }

    // Remove the project from the collection
    free(collection->projects[index]);
    collection->projects[index] = NULL;

    // Shift all projects after the deleted project to fill the gap
    for (int i = index; i < collection->size - 1; i++) {
        collection->projects[i] = collection->projects[i + 1];
    }

    // Decrement the size of the collection
    collection->size--;
}

// Function to handle project updates
void updateProject(ProjectCollection *collection, int index, int newPriority) {
    // Check if the index is valid and the new priority is different from the current one
    if (index < 0 || index >= collection->size || collection->projects[index]->priority == newPriority) {
        return;
    }

    // Update the project's priority
    collection->projects[index]->priority = newPriority;
}

// Function to handle project completion
