    // Check if the index is valid and there are still projects in the collection
    if (index < 0 || index >= collection->size || collection->size == 0) {
        return;
    }

    // Update the project's status to completed
    collection->projects[index]->status = COMPLETED;
}

// Function to handle project reopening
