class EventManager:
    def __init__(self):
        self.events = []
        self.event_locations = {}
        self.event_times = {}

    def add_event(self, event):
        if not self.validate_event(event):
            return False
        self.events.append(event)
        self.event_locations[event['location']] = event
        self.event_times[event['start_time']] = event
        return True

    def update_event(self, event):
        if not self.validate_event(event):
            return False
        for i in range(len(self.events)):
            if self.events[i]['title'] == event['title']:
                self.events[i] = event
                break
        self.event_locations[event['location']] = event
        self.event_times[event['start_time']] = event
        return True

    def delete_event(self, title):
        for i in range(len(self.events)):
            if self.events[i]['title'] == title:
                del self.events[i]
                break
        del self.event_locations[title]
        del self.event_times[title]
        return True

    def validate_event(self, event):
        if not isinstance(event['title'], str) or len(event['title']) == 0:
            return False
        if not isinstance(event['location'], str) or len(event['location']) == 0:
            return False
        if not isinstance(event['start_time'], int) or event['start_time'] < 0:
            return False
        if not isinstance(event['end_time'], int) or event['end_time'] < 0:
            return False
        if not isinstance(event['description'], str) or len(event['description']) == 0:
            return False
        for i in range(len(self.events)):
            if self.events[i]['title'] == event['title'] and self.events[i]['start_time'] != event['start_time']:
                return False
        return True

    def sort_events(self, location=None, start_time=None):
        if location is not None:
            events = []
            for event in self.events:
                if event['location'] == location:
                    events.append(event)
            return sorted(events, key=lambda x: (x['start_time'], x['title']))
        elif start_time is not None:
            events = []
            for event in self.events:
                if event['start_time'] == start_time:
                    events.append(event)
            return sorted(events, key=lambda x: (x['location'], x['title']))
        else:
            return sorted(self.events, key=lambda x: (x['location'], x['start_time'], x['title']))
```
