    // Dynamically allocate and initialize two arrays for 'long' offsets and 'int' keys
    long *offsets = (long *)malloc(numKeys * sizeof(long));
    int *keys = (int *)malloc(numKeys * sizeof(int));

    if (!offsets || !keys) {
        // Handle allocation failure by cleaning up previously allocated resources and returning an error status
        if (offsets) free(offsets);
        if (keys) free(keys);
        return;
