        free(keys);
        return;
    }

    // Populate each record's int field with a random value within the specified range
    for (int i = 0; i < numKeys; i++) {
        records[i].key = lowerBound + rand() % (upperBound - lowerBound);
        offsets[i] = records[i].offset;
        keys[i] = records[i].key;
