            manager->reuseBlock(records[i].offset);
            reuseCount++;
        } else {
            manager->allocateBlock(sizeof(Record));
        }
    }

    // Handle memory pressure by dynamically resizing the memory pool based on usage patterns
    int poolSize = 0;
    while (poolSize < numKeys) {
        if (manager->canAllocateBlock()) {
            manager->allocateBlock(sizeof(Record));
            poolSize++;
        } else {
            break;
        }
    }

    // Ensure thread safety by employing appropriate synchronization mechanisms when interacting with the memory pool manager
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < numKeys; i++) {
        pthread_mutex_lock(&mutex);
        manager->registerBlock(records[i].offset, sizeof(Record));
        pthread_mutex_unlock(&mutex);
    }

    // Provide a mechanism to report memory usage statistics, including total allocated memory, free memory, and memory pool utilization
    printf("Memory usage statistics:\n");
    printf("Total allocated memory: %lu bytes\n", manager->getTotalAllocatedMemory());
    printf("Free memory: %lu bytes\n", manager->getFreeMemory());
    printf("Memory pool utilization: %.2f%%\n", (double)manager->getUsedMemory() / manager->getTotalMemory() * 100);

    // Implement a function to clear all allocated resources and reset the memory pool, allowing for subsequent calls to reuse the memory effectively
