#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Custom allocator for managing memory efficiently
struct MemoryAllocator {
    // Tiered storage model for caching frequently accessed records
    struct CacheTier {
        size_t capacity;  // Capacity of the cache tier in bytes
        void* buffer;     // Pointer to the start of the cache tier
        size_t used;      // Amount of memory currently used by the cache tier
    };

    // Array of cache tiers for different access patterns
    struct CacheTier tiers[3];

    // Mutex for synchronizing access to the allocator
    pthread_mutex_t mutex;
};

// Function for managing memory allocation and initialization
void* allocate(struct MemoryAllocator* allocator, size_t size) {
    // Acquire lock on the allocator
    pthread_mutex_lock(&allocator->mutex);

    // Check if there is enough space in any of the cache tiers for the requested size
    for (int i = 0; i < 3; i++) {
        if (allocator->tiers[i].capacity - allocator->tiers[i].used >= size) {
            // Found a suitable cache tier, allocate memory from it
            void* ptr = allocator->tiers[i].buffer + allocator->tiers[i].used;
            allocator->tiers[i].used += size;

            // Release lock on the allocator
            pthread_mutex_unlock(&allocator->mutex);

            return ptr;
        }
    }

    // No suitable cache tier found, allocate memory from the system heap
    void* ptr = malloc(size);

    // Release lock on the allocator
    pthread_mutex_unlock(&allocator->mutex);

    return ptr;
}

// Function for freeing allocated memory
void free(struct MemoryAllocator* allocator, void* ptr) {
    // Acquire lock on the allocator
    pthread_mutex_lock(&allocator->mutex);

    // Check if the pointer is in any of the cache tiers
    for (int i = 0; i < 3; i++) {
        if (ptr >= allocator->tiers[i].buffer && ptr < allocator->tiers[i].buffer + allocator->tiers[i].capacity) {
            // Found the pointer in a cache tier, free it from there
            size_t offset = ptr - allocator->tiers[i].buffer;
            allocator->tiers[i].used -= offset;

            // Release lock on the allocator
            pthread_mutex_unlock(&allocator->mutex);

            return;
        }
    }

    // No suitable cache tier found, free memory from the system heap
    free(ptr);

    // Release lock on the allocator
    pthread_mutex_unlock(&allocator->mutex);
}

// Function for initializing a record structure with random values
void initRecord(struct Record* record, int key, long offset) {
    record->key = key;
    record->offset = offset;
    record->value = rand() % MAX_VALUE + MIN_VALUE;
}

// Function for managing memory allocation and initialization of arrays of records
void allocateRecords(struct MemoryAllocator* allocator, size_t numRecords) {
    // Allocate memory for the array of record structures
    struct Record* records = (struct Record*)allocate(allocator, sizeof(struct Record) * numRecords);

    // Initialize each record structure with a random value
    for (int i = 0; i < numRecords; i++) {
        initRecord(&records[i], i, rand() % MAX_OFFSET + MIN_OFFSET);
    }
}

// Function for freeing allocated memory of arrays of records
void freeRecords(struct MemoryAllocator* allocator, struct Record* records) {
    // Free the array of record structures
    free(allocator, records);
}
```
