import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.function.Function;
import java.util.stream.Collectors;

public class UserSubscriptionManager {
    private final DistributedCache cache;
    private final ConfigurationService configurationService;

    public UserSubscriptionManager(DistributedCache cache, ConfigurationService configurationService) {
        this.cache = cache;
        this.configurationService = configurationService;
    }

    public CompletionStage<Void> subscribeUserToEvent(String userId, String eventId, List<String> requestedTopics) {
        // Validate inputs for null or invalid values
        if (userId == null || eventId == null || requestedTopics == null) {
            return CompletableFuture.failedFuture(new IllegalArgumentException("Invalid input parameters"));
        }

        // Ensure user has the correct subscription rights for the specified event
        if (!hasCorrectSubscriptionRights(userId, eventId)) {
            return CompletableFuture.failedFuture(new SubscriptionException("User does not have the correct subscription rights for the specified event"));
        }

        // Handle concurrent subscription requests from multiple users
        synchronized (this) {
            // Fetch current event configurations asynchronously from the configuration service
            CompletionStage<EventConfiguration> eventConfigurationFuture = configurationService.getEventConfiguration(eventId);

            // Apply topic subscriptions atomically to prevent partial subscriptions
            return eventConfigurationFuture.thenApplyAsync(eventConfiguration -> {
                List<String> validTopics = requestedTopics.stream()
                        .filter(topic -> eventConfiguration.getTopicConfigurations().containsKey(topic))
                        .collect(Collectors.toList());

                if (validTopics.isEmpty()) {
                    return CompletableFuture.failedFuture(new SubscriptionException("No valid topics found for the specified event"));
                }

                // Update user subscription state in the distributed cache
                cache.putUserSubscriptionState(userId, eventId, validTopics);

                return null;
            }, executor);
        }
    }

    private boolean hasCorrectSubscriptionRights(String userId, String eventId) {
        // Implement logic to check if the user has the correct subscription rights for the specified event
