// Define a structure to represent a memory allocation
typedef struct {
    void* base_addr; // Base address of the allocation
    size_t size; // Size of the allocation in bytes
    int id; // Unique identifier for the allocation
} memalloc_t;

// Define a function to initialize a memory pool
void init_mempool(mempool_t* pool, size_t size) {
    pool->base_addr = malloc(size);
    pool->size = size;
    pool->num_allocations = 0;
}

// Define a function to allocate memory from a memory pool
void* alloc_mem(mempool_t* pool, size_t size) {
    // Check if there is enough space in the pool for the allocation
    if (pool->size - pool->num_allocations * sizeof(memalloc_t) < size) {
        return NULL;
    }

    // Allocate memory for the allocation structure
    memalloc_t* alloc = malloc(sizeof(memalloc_t));
    alloc->base_addr = pool->base_addr + pool->num_allocations * sizeof(memalloc_t);
    alloc->size = size;
    alloc->id = pool->num_allocations++;

    // Update the memory pool's statistics
    pool->size -= size;

    return alloc;
}

// Define a function to deallocate memory from a memory pool
void dealloc_mem(mempool_t* pool, void* base_addr) {
    // Find the allocation structure for the given base address
    memalloc_t* alloc = NULL;
    for (int i = 0; i < pool->num_allocations; i++) {
        if (pool->base_addr + i * sizeof(memalloc_t) == base_addr) {
            alloc = pool->base_addr + i * sizeof(memalloc_t);
            break;
        }
    }

    // Check if the allocation structure was found
    if (alloc == NULL) {
        return;
    }

    // Update the memory pool's statistics
