Here is a possible implementation of the scalable C++ class to manage a dynamic collection of records:
```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <random>

class RecordManager {
public:
    // Constructor
    RecordManager(int numRecords, int keySize, int valueSize) :
        numRecords_(numRecords), keySize_(keySize), valueSize_(valueSize) {}

    // Destructor
    ~RecordManager() {
        for (auto& record : records_) {
            delete[] record.first;
            delete[] record.second;
        }
    }

    // Add a new record to the collection
    void addRecord(const std::string& key, double value) {
        std::lock_guard<std::mutex> lock(mutex_);

        // Allocate memory for the record
        char* keyPtr = new char[keySize_];
        double* valuePtr = new double[valueSize_];

        // Initialize the record with random values within the specified range
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dist(0, 100);
        for (int i = 0; i < keySize_; ++i) {
            keyPtr[i] = dist(gen);
        }
        for (int i = 0; i < valueSize_; ++i) {
            valuePtr[i] = dist(gen);
        }

        // Add the record to the collection
        records_.push_back({keyPtr, valuePtr});
    }

    // Retrieve a record from the collection based on its key
    std::pair<const char*, double*> getRecord(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = records_.begin(); it != records_.end(); ++it) {
            if (key == it->first) {
                return *it;
            }
        }

        // If the record is not found, return a null pair
        return {};
    }

    // Update the value of a record in the collection
    void updateRecord(const std::string& key, double newValue) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = records_.begin(); it != records_.end(); ++it) {
            if (key == it->first) {
                it->second[0] = newValue;
                return;
            }
        }
    }

    // Remove a record from the collection based on its key
    void removeRecord(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = records_.begin(); it != records_.end(); ++it) {
            if (key == it->first) {
                delete[] it->first;
                delete[] it->second;
                records_.erase(it);
                return;
            }
        }
    }

    // Periodically clean up unused records based on their last-used timestamp
    void cleanup() {
        std::lock_guard<std::mutex> lock(mutex_);

        auto now = std::chrono::system_clock::now();
        for (auto it = records_.begin(); it != records_.end(); ++it) {
            if (now - it->second[1] > cleanupThreshold_) {
                delete[] it->first;
                delete[] it->second;
                records_.erase(it);
            }
        }
    }

    // Query the collection based on a range of keys, values, or both
    std::vector<std::pair<const char*, double*>> query(const std::string& keyRangeStart, const std::string& keyRangeEnd) {
        std::lock_guard<std::mutex> lock(mutex_);

        // Initialize the result vector
        std::vector<std::pair<const char*, double*>> results;

        // Iterate over the records and check if they match the query criteria
        for (auto it = records_.begin(); it != records_.end(); ++it) {
            const auto& record = *it;
            if (keyRangeStart <= record.first && record.first < keyRangeEnd) {
                results.push_back(record);
            }
        }

        return results;
    }

private:
    // The number of records in the collection
    int numRecords_;

    // The size of each record's key and value
    int keySize_, valueSize_;

    // The collection of records
    std::vector<std::pair<const char*, double*>> records_;

    // The mutex for thread-safe access to the collection
    std::mutex mutex_;

    // The condition variable for signaling when cleanup is needed
    std::condition_variable cv_;

    // The threshold for cleaning up unused records based on their last-used timestamp
    int cleanupThreshold_ = 10; // in minutes
};
