Record records[MAX_RECORDS];

// Define a memory pool manager to optimize memory usage and reduce fragmentation
struct MemoryPoolManager {
    // Allocated memory blocks
    void* allocatedBlocks[MEMORY_POOL_SIZE / MIN_ALLOCATION_SIZE];
    // Number of allocated blocks
    int numAllocatedBlocks;
    // Total size of allocated blocks
    size_t totalSize;
};

// Define a function to validate user-provided input for the size of two arrays
int validateInput(size_t* offsetSize, size_t* keySize) {
    if (*offsetSize > MAX_RECORDS || *keySize > MAX_RECORDS) {
        fprintf(stderr, "Error: Input size exceeds maximum limits.\n");
        return 1;
    }
    return 0;
}

