void* allocateMemory(size_t size) {
    // Validate user-provided input
    if (size > MAX_ALLOCATION_SIZE) {
        fprintf(stderr, "Error: Allocation size exceeds maximum limits.\n");
        return NULL;
    }
    // Check if there is enough memory available in the pool manager
    if (memoryPoolManager.totalSize + size > MEMORY_POOL_SIZE) {
        fprintf(stderr, "Error: Not enough memory available in the pool manager.\n");
        return NULL;
    }
    // Allocate memory from the pool manager
    void* allocatedMemory = malloc(size);
    if (allocatedMemory == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory from the pool manager.\n");
        return NULL;
    }
    // Register the allocated block with the pool manager
    memoryPoolManager.allocatedBlocks[memoryPoolManager.numAllocatedBlocks++] = allocatedMemory;
    memoryPoolManager.totalSize += size;
    return allocatedMemory;
}

// Define a function to clear all allocated resources and reset the memory pool, allowing subsequent calls to reuse the memory effectively
void clearResources() {
    // Release all allocated blocks in the pool manager
    for (int i = 0; i < memoryPoolManager.numAllocatedBlocks; i++) {
