    if (str == NULL || size_limit <= 0 || max_count_threshold <= 0) {
        return -1;
    }
    long_offset_size = sizeof(long) * size_limit;
    int_key_size = sizeof(int) * max_count_threshold;
    record_size = sizeof(Record) * max_count_threshold;

    // Allocate memory for the arrays and initialize them with random values
    long_offsets = malloc(long_offset_size);
    int_keys = malloc(int_key_size);
    records = malloc(record_size);
    if (long_offsets == NULL || int_keys == NULL || records == NULL) {
        error = -1;
        goto cleanup;
    }
    srand(time(NULL));
    for (int i = 0; i < size_limit; i++) {
        ((long*)long_offsets)[i] = rand() % max_count_threshold;
    }
    for (int i = 0; i < max_count_threshold; i++) {
        ((int*)int_keys)[i] = rand() % max_count_threshold;
    }
    for (int i = 0; i < max_count_threshold; i++) {
        ((Record*)records)[i].value = rand() % max_count_threshold;
    }

    // Register the allocated memory blocks with the external resource manager
    if (register_memory(long_offsets, long_offset_size) < 0 || register_memory(int_keys, int_key_size) < 0 || register_memory(records, record_size) < 0) {
        error = -1;
        goto cleanup;
    }

    // Process the input string and manage resources
    if (strlen(str) > size_limit) {
        strcpy(str + size_limit, "LIMIT_EXCEEDED");
    } else {
        str[size_limit] = '/';
    }

cleanup:
    // Free any allocated resources and return the error status
    if (error < 0) {
        free(long_offsets);
        free(int_keys);
        free(records);
    }
    return error;
}

