// Custom random number generator using a linear congruential method
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Record structure to store offset, key, and string
typedef struct {
    long offset;
    int key;
    char* string;
} Record;

// Memory pool manager for allocating and deallocating memory blocks
typedef struct {
    void** blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t mutex;
} MemoryPoolManager;

// Initialize the memory pool manager with a specified number of blocks
void init_memory_pool(MemoryPoolManager* manager, size_t block_size, size_t num_blocks) {
    manager->blocks = (void**)malloc(num_blocks * sizeof(void*));
    manager->block_size = block_size;
    manager->num_blocks = num_blocks;
    pthread_mutex_init(&manager->mutex, NULL);
}

// Allocate a memory block from the pool
void* allocate_memory(MemoryPoolManager* manager) {
    void* block = NULL;
    pthread_mutex_lock(&manager->mutex);
    if (manager->num_blocks > 0) {
        block = manager->blocks[--manager->num_blocks];
    }
    pthread_mutex_unlock(&manager->mutex);
    return block;
}

// Deallocate a memory block to the pool
void deallocate_memory(MemoryPoolManager* manager, void* block) {
    pthread_mutex_lock(&manager->mutex);
    manager->blocks[manager->num_blocks++] = block;
    pthread_mutex_unlock(&manager->mutex);
}

// Initialize and manage a dynamic array of Record structures
void init_record_array(Record** records, size_t* num_records, MemoryPoolManager* manager) {
    *num_records = 0;
    *records = NULL;
    init_memory_pool(manager, sizeof(Record), 10);
}

// Add a new record to the array
void add_record(Record** records, size_t* num_records, MemoryPoolManager* manager) {
    if (*num_records >= *manager->num_blocks) {
        // Resize the memory pool if necessary
        void* new_block = allocate_memory(manager);
        if (new_block == NULL) {
            return;
        }
        manager->blocks[manager->num_blocks++] = new_block;
    }
    // Allocate a new record from the memory pool
    Record* new_record = (Record*)allocate_memory(manager);
    if (new_record == NULL) {
        return;
    }
    // Initialize the new record with random values
    new_record->offset = rand_range(10, 100000);
    new_record->key = rand_range(1, 100000);
    new_record->string = (char*)malloc(256 * sizeof(char));
    if (new_record->string == NULL) {
        deallocate_memory(manager, new_record);
        return;
    }
    strcpy(new_record->string, "Hello, world!");
    // Add the new record to the array
