}

// Clean up and release all allocated resources
void cleanup_record_array(Record** records, size_t* num_records, MemoryPoolManager* manager) {
    for (size_t i = 0; i < *num_records; i++) {
        Record* record = (*records)[i];
        free(record->string);
        deallocate_memory(manager, record);
    }
    free(*records);
    pthread_mutex_destroy(&manager->mutex);
}

// Main function to initialize and manage a dynamic array of Record structures
