    // Initialize the memory pool manager with a specified number of blocks
    MemoryPoolManager manager;
    init_memory_pool(&manager, sizeof(Record), 100000);

    // Initialize and manage a dynamic array of Record structures
    Record* records = NULL;
    size_t num_records = 0;
    init_record_array(&records, &num_records, &manager);

