#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the transaction structure
typedef struct {
    double amount;
    time_t timestamp;
    enum status;
} transaction_t;

// Define a linked list node for storing transactions
typedef struct transaction_node {
    transaction_t *transaction;
    struct transaction_node *next;
} transaction_node_t;

// Define the head of the linked list
static transaction_node_t *head = NULL;

// Define a mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new transaction to the list
void add_transaction(double amount, time_t timestamp, enum status status) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the transaction
    transaction_node_t *new_node = malloc(sizeof(transaction_node_t));
    new_node->transaction = malloc(sizeof(transaction_t));
    new_node->transaction->amount = amount;
    new_node->transaction->timestamp = timestamp;
    new_node->transaction->status = status;
    new_node->next = NULL;

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        transaction_node_t *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to update the status of transactions that have not been processed within the last 30 days
void update_status(int grace_period) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over the linked list and update the status of transactions that have not been processed within the last 30 days
    transaction_node_t *current = head;
    while (current != NULL) {
        if (difftime(time(NULL), current->transaction->timestamp) > grace_period) {
            // Update the status of the transaction to "processed"
            current->transaction->status = PROCESSED;
        }
        current = current->next;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the linked list and print the status of each transaction
void print_status() {
    // Lock the mutex before accessing the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over the linked list and print the status of each transaction
    transaction_node_t *current = head;
    while (current != NULL) {
        printf("Transaction: %f, Timestamp: %ld, Status: %s\n", current->transaction->amount, current->transaction->timestamp, get_status_string(current->transaction->status));
        current = current->next;
    }

    // Unlock the mutex after accessing the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to free the memory allocated for the linked list
void free_list() {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over the linked list and free the memory allocated for each transaction
    transaction_node_t *current = head;
    while (current != NULL) {
        transaction_node_t *next = current->next;
        free(current->transaction);
        free(current);
        current = next;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}
