// Define a function to report detailed memory usage statistics
void report_memory_usage() {
    // Get the total amount of memory available on the system
    long total_mem = sysconf(_SC_PAGESIZE) * sysconf(_SC_PHYS_PAGES);

    // Get the amount of free memory available on the system
    long free_mem = 0;
    FILE *file = fopen("/proc/meminfo", "r");
    if (file != NULL) {
        char line[128];
        while (fgets(line, sizeof(line), file) != NULL) {
            if (strstr(line, "MemFree:") != NULL) {
                sscanf(line, "%*s %ld", &free_mem);
                break;
