    size_t totalSize = sizeof(LongOffsetArray) + sizeof(IntegerKeyArray) + (sizeof(RecordStructure) * 10);
    if (totalSize > 1024) {
        printf("Error: Insufficient memory available for data processing pipeline\n");
        return;
    }
    void* buffer = malloc(totalSize);
    memcpy(buffer, &longOffsets, sizeof(LongOffsetArray));
    memcpy((char*)buffer + sizeof(LongOffsetArray), &intKeys, sizeof(IntegerKeyArray));
