// Custom allocator optimized for up to 1024 points
void* custom_alloc(size_t size) {
    if (size > 1024 * sizeof(struct point)) {
        return NULL;
    }
    void* ptr = malloc(size);
    if (!ptr) {
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

// Custom deallocator for the custom allocator
void custom_dealloc(void* ptr) {
    free(ptr);
}

struct point {
    float x;
    float y;
};

int generate_points(float min_x, float max_x, float min_y, float max_y, int num_points, struct point** points) {
    // Check input parameters
    if (min_x >= max_x || min_y >= max_y || num_points <= 0) {
        return -1;
    }

    // Allocate memory for the points array
    *points = custom_alloc(num_points * sizeof(struct point));
    if (!*points) {
        return -2;
    }

    // Generate random coordinates within the bounding box
    srand(time(NULL));
    for (int i = 0; i < num_points; i++) {
        (*points)[i].x = min_x + ((float)rand() / RAND_MAX) * (max_x - min_x);
        (*points)[i].y = min_y + ((float)rand() / RAND_MAX) * (max_y - min_y);
    }

    // Resize the points array if necessary
    int current_size = num_points;
    while (current_size < 1024 && current_size * 1.25 > num_points) {
        struct point* new_points = custom_alloc(current_size * sizeof(struct point));
        if (!new_points) {
            break;
        }
        memcpy(new_points, *points, current_size * sizeof(struct point));
        custom_dealloc(*points);
        *points = new_points;
        current_size *= 2;
    }

    return num_points;
}

