// Generate a JSON request body for generating points
char* generate_points_json(float min_x, float max_x, float min_y, float max_y, int num_points) {
    // Check input parameters
    if (min_x >= max_x || min_y >= max_y || num_points <= 0) {
        return NULL;
    }

    // Create a JSON object for the request body
    json_t* json = json_object();
    if (!json) {
        return NULL;
    }

    // Add the minimum and maximum coordinates to the JSON object
    json_object_set_new(json, "minX", json_real(min_x));
    json_object_set_new(json, "maxX", json_real(max_x));
    json_object_set_new(json, "minY", json_real(min_y));
    json_object_set_new(json, "maxY", json_real(max_y));

    // Add the number of points to the JSON object
    json_object_set_new(json, "numPoints", json_integer(num_points));

    // Serialize the JSON object as a string
    char* json_string = json_dumps(json, 0);
    if (!json_string) {
        json_decref(json);
        return NULL;
    }

    // Clean up the JSON object
    json_decref(json);

    return json_string;
}

