int cache_api_response(struct api_response_cache* cache, struct api_response* response) {
    // Check input parameters
    if (!cache || !response) {
        return -1;
    }

    // Add the API response to the cache
    cache->num_responses++;
    cache->responses[cache->num_responses - 1] = response;

    return 0;
}

