        case 401:
            // Unauthorized, handle as appropriate
            break;
        case 403:
            // Forbidden, handle as appropriate
            break;
        case 404:
            // Not found, handle as appropriate
            break;
        case 500:
            // Internal server error, handle as appropriate
            break;
        default:
            // Unknown status code, handle as appropriate
            break;
    }

