    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Generate points using the external API if necessary
    int num_api_responses = 0;
    struct api_response* api_responses[10];
    for (int i = 0; i < 10; i++) {
        int num_points_per_response = num_points / 10;
        if (i == 9) {
            num_points_per_response += num_points % 10;
        }
        struct api_response* response = generate_points_api(min_x, max_x, min_y, max_y, num_points_per_response, points);
        if (response) {
            num_api_responses++;
            api_responses[i] = response;
        } else {
            break;
        }
    }

    // Cache the API responses for future use
    struct api_response_cache* cache = malloc(sizeof(struct api_response_cache));
    if (!cache) {
        pthread_mutex_unlock(&mutex);
        return -2;
    }
    cache->num_responses = num_api_responses;
    for (int i = 0; i < num_api_responses; i++) {
        cache->responses[i] = api_responses[i];
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return num_points;
