    *sensor_readings = (float*)malloc(sizeof(float) * num_readings);
    if (*sensor_readings == NULL) {
        printf("Error: unable to allocate memory for sensor readings\n");
        fclose(fp);
        return;
    }
    *device_ids = (char**)malloc(sizeof(char*) * num_devices);
    if (*device_ids == NULL) {
        printf("Error: unable to allocate memory for device IDs\n");
        free(*sensor_readings);
        fclose(fp);
        return;
    }

    // Read the sensor readings and device IDs from the file
