        avg_temp += sensor_readings[i];
        int freq = 1;
        for (int j = i + 1; j < num_readings; j++) {
            if (strcmp(device_ids[i], device_ids[j]) == 0) {
                freq++;
            }
        }
        if (freq > max_freq) {
            max_freq = freq;
            strcpy(most_frequent_id, device_ids[i]);
        }
    }
    avg_temp /= num_readings;

    // Print the statistics
    printf("Average temperature: %.2f\n", avg_temp);
