            list[i].rx_ue_information.value->crc_list[j].value = (void*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
            if (!list[i].rx_ue_information.value->crc_list[j].value) {
                printf("Failed to allocate memory for CRC_INDICATION_REL8_TAG\n");
                return NULL;
            }
