    return list;
}

// Define the function to clear all allocated resources and reset the memory pool for subsequent effective reuse
void clear_resources(MemoryPoolManager* manager) {
    // Check if the memory pool manager exists
    if (!manager) {
        printf("Failed to clear resources: Memory pool manager doesn't exist\n");
        return;
    }

    // Free all allocated blocks in the memory pool manager
    for (int i = 0; i < manager->num_blocks; i++) {
        free(manager->blocks[i]);
    }

    // Reset the number of blocks to zero
    manager->num_blocks = 0;
}
