    public static MoSTState allocateAndManageThemeResources(String themeName) {
        // Load state object from file using ObjectInputStream
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        try {
            fis = new FileInputStream(themeName + ".state");
            ois = new ObjectInputStream(fis);
            MoSTState state = (MoSTState) ois.readObject();
            return state;
        } catch (IOException | ClassNotFoundException e) {
            // Handle exceptions gracefully to ensure resource integrity
            e.printStackTrace();
            return null;
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            if (fis != null) {
                try {
                    fis.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

