        // Recycle unused bitmaps and set them to null
        for (Map.Entry<Integer, Bitmap> entry : bitmapCache.entrySet()) {
            if (!entry.getValue().isRecycled()) {
                entry.getValue().recycle();
            }
            entry.setValue(null);
        }
    }

