    IntPool int_pool;
    ItemPool item_pool;
    MetadataPool metadata_pool;
    pthread_mutex_t mutex;
} MemoryPoolManager;

// Initialize the memory pool manager
void init_memory_pool(MemoryPoolManager *manager) {
    // Initialize the integer, item, and metadata pools
    manager->int_pool.data = NULL;
    manager->item_pool.data = NULL;
    manager->metadata_pool.data = NULL;
    manager->int_pool.size = 0;
    manager->item_pool.size = 0;
    manager->metadata_pool.size = 0;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&manager->mutex, NULL);
}

// Allocate memory from the integer pool
void *allocate_int(MemoryPoolManager *manager, size_t size) {
    void *data = NULL;

    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Check if there is enough space in the integer pool
    if (manager->int_pool.size >= size) {
        data = manager->int_pool.data;
        manager->int_pool.data += size;
        manager->int_pool.size -= size;
    } else {
        // If there is not enough space, allocate a new block of memory
        data = malloc(size);
    }

    // Release the mutex for thread safety
    pthread_mutex_unlock(&manager->mutex);

    return data;
}

