            if (key_array[i] == key_array[j]) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            key_array[unique_keys++] = key_array[i];
        }
    }

    // Allocate memory for the records array based on the number of unique keys
    record_array = malloc(sizeof(Record*) * unique_keys);
    if (record_array == NULL) {
