#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the hash table structure
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} HashTable;

// Initialize a new hash table with a given capacity
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        return NULL;
    }
    ht->records = calloc(capacity, sizeof(Record*));
    if (!ht->records) {
        free(ht);
        return NULL;
    }
    ht->capacity = capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Insert a new record into the hash table
int insert(HashTable* ht, long offset, int key, int value) {
    if (!ht || !ht->records) {
        return -1;
    }
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(offset, key);
    Record* record = malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&ht->mutex);
        return -1;
    }
    record->offset = offset;
    record->key = key;
    record->value = value;
    ht->records[index] = record;
    ht->size++;
    pthread_mutex_unlock(&ht->mutex);
    return 0;
}

// Look up a record in the hash table by its offset and key
Record* lookup(HashTable* ht, long offset, int key) {
    if (!ht || !ht->records) {
        return NULL;
    }
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(offset, key);
    Record* record = ht->records[index];
    pthread_mutex_unlock(&ht->mutex);
    return record;
}

// Delete a record from the hash table by its offset and key
int delete(HashTable* ht, long offset, int key) {
    if (!ht || !ht->records) {
        return -1;
    }
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(offset, key);
    Record* record = ht->records[index];
    if (record) {
        free(record);
        ht->records[index] = NULL;
        ht->size--;
    }
    pthread_mutex_unlock(&ht->mutex);
    return 0;
}

// Expand the hash table size when necessary
void expand(HashTable* ht) {
    if (!ht || !ht->records) {
        return;
    }
    pthread_mutex_lock(&ht->mutex);
    size_t new_capacity = ht->capacity * 2;
    Record** new_records = calloc(new_capacity, sizeof(Record*));
    if (!new_records) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    for (size_t i = 0; i < ht->capacity; i++) {
        Record* record = ht->records[i];
        if (record) {
            size_t new_index = hash(record->offset, record->key);
            new_records[new_index] = record;
        }
    }
    free(ht->records);
    ht->records = new_records;
    ht->capacity = new_capacity;
    pthread_mutex_unlock(&ht->mutex);
}

// Hash function for the hash table
size_t hash(long offset, int key) {
    return (offset + key) % ht->capacity;
}

// Thread-safe reporting mechanism to monitor memory usage and performance metrics
void report(HashTable* ht) {
    if (!ht || !ht->records) {
        return;
    }
    pthread_mutex_lock(&ht->mutex);
    size_t used_memory = 0;
    for (size_t i = 0; i < ht->capacity; i++) {
        Record* record = ht->records[i];
        if (record) {
            used_memory += sizeof(Record);
        }
    }
    printf("Memory usage: %lu bytes\n", used_memory);
    printf("Record processing throughput: %lu records/second\n", ht->size / 10);
    pthread_mutex_unlock(&ht->mutex);
}
```
