    // Allocate memory for the array of numbers
    data->numbers = malloc(5000 * sizeof(float));
    if (data->numbers == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for numbers\n");
        exit(1);
    }

    // Initialize the semaphores
    data->sem1 = sem_open("sem1", O_CREAT | O_EXCL, 0644, 0);
    if (data->sem1 == SEM_FAILED) {
        fprintf(stderr, "Error: failed to create semaphore 1\n");
        exit(1);
    }
    data->sem2 = sem_open("sem2", O_CREAT | O_EXCL, 0644, 0);
    if (data->sem2 == SEM_FAILED) {
        fprintf(stderr, "Error: failed to create semaphore 2\n");
        exit(1);
    }
}

// Function to read and process the input data
void process_input(struct Data *data) {
    // Read the input from standard input
    float number;
    while (scanf("%f", &number) == 1) {
        // Check if the number is within the range of -1000000.0 to 1000000.0
        if (number < -1000000.0 || number > 1000000.0) {
            fprintf(stderr, "Error: invalid input\n");
            continue;
        }

        // Add the number to the array of numbers
        data->numbers[data->num_numbers++] = number;

        // Check if the array is full
        if (data->num_numbers == 5000) {
            fprintf(stderr, "Error: maximum number of inputs reached\n");
            break;
        }
    }
}

// Function to find and print the smallest number in the array
void find_smallest(struct Data *data) {
    // Check if there are any numbers in the array
    if (data->num_numbers == 0) {
        fprintf(stderr, "Error: no numbers in the array\n");
        return;
    }

    // Find the smallest number in the array
    float smallest = data->numbers[0];
    for (int i = 1; i < data->num_numbers; i++) {
        if (data->numbers[i] < smallest) {
            smallest = data->numbers[i];
        }
    }

    // Print the smallest number and its index
    printf("Smallest number: %f\n", smallest);
}

// Function to calculate the median of all numbers in the array
void calculate_median(struct Data *data) {
    // Check if there are any numbers in the array
    if (data->num_numbers == 0) {
        fprintf(stderr, "Error: no numbers in the array\n");
        return;
    }

    // Sort the array of numbers
    qsort(data->numbers, data->num_numbers, sizeof(float), compare);

    // Calculate the median
    int median_index = (data->num_numbers - 1) / 2;
    float median = data->numbers[median_index];

    // Print the median and its index
    printf("Median: %f\n", median);
}

// Function to free the allocated memory and close the semaphores
void cleanup(struct Data *data) {
    // Free the memory for the array of numbers
    free(data->numbers);

    // Close the semaphores
    sem_close(data->sem1);
    sem_close(data->sem2);
}

// Main function to read and process input data, find and print the smallest number, and calculate the median
