    init_data(&data);

    // Read and process the input data
    process_input(&data);

    // Find and print the smallest number in the array
    find_smallest(&data);

    // Calculate the median of all numbers in the array
    calculate_median(&data);

    // Clean up the allocated memory and close the semaphores
    cleanup(&data);

    return 0;
}
