        records[i]->key = rand() % range + 1;
        records[i]->offset = 0;
        records[i]->value = rand() % range + 1;
    }

    // Create a doubly linked list of records, with each node containing a record and pointing to the next and previous nodes
    Node *head = NULL;
    Node *tail = NULL;
    for (int i = 0; i < input_size; i++) {
        Node *node = malloc(sizeof(Node));
        node->record = records[i];
        node->next = head;
        node->prev = tail;
        if (head != NULL) {
            head->prev = node;
        }
        head = node;
        if (tail == NULL) {
            tail = node;
        }
    }

    // Read a sequence of integers from standard input and store them in an auxiliary array
