                current->record->value += aux_array[i];
            }
        }
        current = current->next;
    }

    // Implement a function to find and print the largest integer present in both the doubly linked list and the input array, considering edge cases where all elements might be negative or zero
    int max_value = 0;
    for (int i = 0; i < input_size; i++) {
        if (records[i]->value > max_value) {
            max_value = records[i]->value;
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Implement a function to reverse the order of the doubly linked list in place, optimizing for performance and minimizing memory usage
    Node *current = head;
    while (current != NULL) {
        Node *next = current->next;
        current->next = current->prev;
        current->prev = next;
        current = next;
    }

    // Free dynamically allocated memory at the end of function execution to maintain system stability and resource management
    free(offsets);
    free(keys);
