        log_entries[i].ts.tv_sec = time(NULL);
        log_entries[i].ts.tv_nsec = 0;
        log_entries[i].file_path = strdup(file_path);
    }

    // Serialize the log entries to the specified file path in a structured format
    FILE* fp = fopen(file_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file for writing\n");
        return;
    }
    for (int i = 0; i < num_entries; i++) {
