void process_numbers(int argc, char **argv) {
    // Initialize semaphores for concurrent thread operations
    sem_t *semaphore1 = sem_open("semaphore1", O_CREAT | O_EXCL, 0644, 1);
    sem_t *semaphore2 = sem_open("semaphore2", O_CREAT | O_EXCL, 0644, 1);

    // Initialize an array of long integers to store the offsets
    long *offsets = (long *)malloc(sizeof(long) * argc);

    // Initialize an array of int integers to store the keys
    int *keys = (int *)malloc(sizeof(int) * argc);

    // Initialize an array of struct record objects to store the records
    struct record *records = (struct record *)malloc(sizeof(struct record) * argc);

    // Loop through each argument and process it as a number
    for (int i = 0; i < argc; i++) {
        // Check if the input is a valid floating-point number within the range of -1000000.0 to 1000000.0
        if (!is_valid_number(argv[i])) {
            printf("Invalid input: %s\n", argv[i]);
            continue;
        }

        // Store the offset and key for this number in the appropriate arrays
        offsets[i] = i * sizeof(long);
        keys[i] = i * sizeof(int);
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
        records[i].size = sizeof(long) + sizeof(int);

        // Increment the semaphore to indicate that a new record is available
        sem_post(semaphore1);
    }

    // Wait for all threads to finish processing their records
    sem_wait(semaphore2);

    // Find and print the smallest number in the array
    long smallest = find_smallest(records, argc);
    printf("Smallest number: %ld\n", smallest);

    // Calculate the median of all numbers and print it
    double median = calculate_median(records, argc);
    printf("Median: %f\n", median);

    // Clean up memory and close semaphores
    free(offsets);
    free(keys);
    free(records);
    sem_close(semaphore1);
    sem_close(semaphore2);
}

// Function to validate a floating-point number within the range of -1000000.0 to 1000000.0
int is_valid_number(char *input) {
    double number;
    if (sscanf(input, "%lf", &number) != 1) {
        return 0;
    }
    if (number < -1000000.0 || number > 1000000.0) {
        return 0;
    }
    return 1;
}

// Function to find the smallest number in an array of struct record objects
long find_smallest(struct record *records, int argc) {
    long smallest = LONG_MAX;
    for (int i = 0; i < argc; i++) {
        if (records[i].offset != NULL && records[i].key != NULL) {
            long offset = *(records[i].offset);
            int key = *(records[i].key);
            if (offset < smallest) {
                smallest = offset;
            }
        }
    }
    return smallest;
}

// Function to calculate the median of an array of struct record objects
double calculate_median(struct record *records, int argc) {
    // Calculate the total number of elements in the array
    size_t total = 0;
    for (int i = 0; i < argc; i++) {
        if (records[i].offset != NULL && records[i].key != NULL) {
            total += *(records[i].size);
        }
    }

    // Calculate the median of the array
    double median = 0.0;
    for (int i = 0; i < argc; i++) {
        if (records[i].offset != NULL && records[i].key != NULL) {
            long offset = *(records[i].offset);
            int key = *(records[i].key);
            median += (double)(offset + key) / total;
        }
    }
    return median;
}
