            exit(1);
        }
        tail = tail->next;
    }
    tail->next = NULL;

    // Set the head and tail pointers of the linked list
    head->next = tail;
}

// Traverse the linked list, calculating the sum of all double values while checking for invalid node pointers and handling them gracefully
double traverseList(Node* head) {
    double sum = 0.0;
    Node* current = head;
    while (current != NULL) {
        if (current->value == -1.0) {
            printf("Error: Invalid node pointer detected\n");
            exit(1);
        }
        sum += current->value;
        current = current->next;
    }
    return sum;
}

// Safely insert a new node into the linked list at a specified position, ensuring thread safety and non-disruption of ongoing traversal or computation
void insertNode(Node* head, size_t position, double value, char* string) {
    // Check if the position is valid
    if (position < 0 || position > getListSize(head)) {
        printf("Error: Invalid position specified for node insertion\n");
        exit(1);
