    if (!new_node) {
        printf("Error: Failed to allocate memory for new linked list node\n");
        exit(1);
    }

    // Initialize the new node with the specified value and string
    new_node->value = value;
    new_node->string = (char*)malloc(strlen(string) + 1);
    if (!new_node->string) {
        printf("Error: Failed to allocate memory for new linked list node's string\n");
        exit(1);
    }
    strcpy(new_node->string, string);

    // Insert the new node at the specified position in the linked list
    Node* current = head;
    size_t i = 0;
    while (i < position - 1) {
        current = current->next;
        i++;
    }
    new_node->next = current->next;
    current->next = new_node;

    // Release the lock on the memory pool manager
    pthread_mutex_unlock(&mem_manager->mutex);
}

// Report the current memory usage statistics, including total allocated memory, free memory, and memory pool utilization
void reportMemoryUsage(Node* head) {
