            node_list: vec![],
        });
    }

    // Allocate memory for an array of 'node' structures representing elements in a singly linked list
    let mut node_array = vec![];
    for _ in 0..user_input {
        node_array.push(Node {
            element: (rand::thread_rng().gen_range(1, 10), rand::thread_rng().gen_range(1.0, 10.0)),
        });
    }

    // Initialize the records and nodes with random values
    for record in &mut record_array {
        let mut node_list = vec![];
        for _ in 0..rand::thread_rng().gen_range(1, 10) {
