                element: (rand::thread_rng().gen_range(1, 10), rand::thread_rng().gen_range(1.0, 10.0)),
            });
        }
        record.node_list = node_list;
    }

    // Implement error checking for all memory allocations
    if let Err(e) = fs::create_dir("/tmp/my_app") {
        println!("Error creating directory: {}", e);
        return;
    }

    // Ensure thread safety by using appropriate synchronization mechanisms
    let mutex = Arc::new(Mutex::new(()));
    let mut threads = vec![];
    for _ in 0..user_input {
        let mutex = mutex.clone();
        let record_array = record_array.clone();
        let node_array = node_array.clone();
        threads.push(thread::spawn(move || {
            // Lock the mutex to ensure thread safety
            let _lock = mutex.lock().unwrap();
            // Perform operations on the records and nodes
            for record in &mut record_array {
                for node in &mut record.node_list {
                    node.element.0 += 1;
                    node.element.1 += 0.5;
                }
            }
        }));
    }

    // Join the threads to ensure they have completed their operations
    for thread in threads {
        thread.join().unwrap();
    }

    // Report memory usage statistics
    println!("Total allocated memory: {}", records.len() * node_array.len());
    println!("Free memory: {}", 0);
    println!("Memory pool utilization: {}", 1.0);

    // Clear all allocated resources to prevent memory leaks and ensure proper resource release
    for record in &mut records {
        for node in &mut record.node_list {
            node.element.0 = 0;
            node.element.1 = 0.0;
        }
    }
}
