int get_random_number(int lower, int upper) {
    // Get a random number from the cache if possible
    if (cache_index < CACHE_SIZE) {
        return cache[cache_index++];
    } else {
        // Generate a new random number and update the cache
        srand(time(NULL));
        int num = rand();
        cache[cache_index] = num;
        cache_index++;
        if (cache_index == CACHE_SIZE) {
            cache_index = 0;
        }
        return num;
    }
}

void manage_dynamic_data_structures(int num_elements, int lower, int upper) {
    // Initialize the dynamic arrays with user input
    long* offsets = (long*)my_alloc(sizeof(long) * num_elements);
    int* keys = (int*)my_alloc(sizeof(int) * num_elements);
    double* values = (double*)my_alloc(sizeof(double) * num_elements);
    char* strings = (char*)my_alloc(sizeof(char) * 256 * num_elements);
    struct element* elements = (struct element*)my_alloc(sizeof(struct element) * num_elements);

    // Assign random values to each record's integer field and node's 'struct element' field
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = get_random_number(lower, upper);
        keys[i] = get_random_number(lower, upper);
        values[i] = get_random_number(lower, upper);
        strings[i * 256] = get_random_number(lower, upper);
        elements[i].key = keys[i];
        elements[i].value = values[i];
    }

    // Register each allocated memory block with the external memory pool manager
    for (int i = 0; i < num_elements; i++) {
        my_free(offsets + i);
        my_free(keys + i);
        my_free(values + i);
        my_free(strings + i * 256);
        my_free(elements + i);
    }
}

int main() {
    // Initialize the caching mechanism
    init_cache();

    // Get user input for the number of elements and the range of random values
    int num_elements;
    printf("Enter the number of elements: ");
    scanf("%d", &num_elements);
    if (num_elements < 1 || num_elements > MAX_ELEMENTS) {
        printf("Invalid input. The number of elements must be between 1 and %d.\n", MAX_ELEMENTS);
        return 0;
    }
    int lower, upper;
    printf("Enter the range for random values: ");
    scanf("%d %d", &lower, &upper);
    if (lower > upper) {
        printf("Invalid input. The lower bound must be less than or equal to the upper bound.\n");
        return 0;
    }

    // Manage the dynamic data structures with thread safety and memory pool integration
    manage_dynamic_data_structures(num_elements, lower, upper);

    return 0;
}
