    unsigned long timestamp;
} sensor_data;

// Define the function to process sensor data and image metadata
int processSensorDataAndImage(char* input_image, char* input_string) {
    // Declare variables for TIFF metadata parsing
    int bit_depth = 0;
    int samples_per_pixel = 0;
    int extra_samples = 0;

    // Parse the TIFF image file for metadata
    TIFF* tif = TIFFOpen(input_image, "r");
    if (tif == NULL) {
        printf("Error: Unable to open TIFF image file.\n");
        return 1;
    }

    // Check the bit depth of the image and determine the number of samples per pixel
    bit_depth = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    if (bit_depth == 1 || bit_depth == 2 || bit_depth == 4 || bit_depth == 8 || bit_depth == 16) {
        samples_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    } else {
        printf("Error: Unsupported bit depth (%d).\n", bit_depth);
        return 1;
    }

    // Determine the number of extra samples present in the image
    extra_samples = TIFFGetField(tif, TIFFTAG_EXTRASAMPLES);

    // Allocate memory for the arrays
    float* float_array = (float*)malloc(sizeof(float) * samples_per_pixel * extra_samples);
    char* status_indicator_array = (char*)malloc(sizeof(char) * samples_per_pixel * extra_samples);
    unsigned long* timestamp_array = (unsigned long*)malloc(sizeof(unsigned long) * samples_per_pixel * extra_samples);
    if (float_array == NULL || status_indicator_array == NULL || timestamp_array == NULL) {
        printf("Error: Memory allocation failed.\n");
        return 1;
    }

    // Allocate memory for the sensor data array
    int num_sensor_data = samples_per_pixel * extra_samples;
    sensor_data* sensor_data_array = (sensor_data*)malloc(sizeof(sensor_data) * num_sensor_data);
    if (sensor_data_array == NULL) {
        printf("Error: Memory allocation failed.\n");
        return 1;
    }

    // Set the value of each sensor data's float field based on its corresponding timestamp and status indicator
    for (int i = 0; i < num_sensor_data; i++) {
        sensor_data_array[i].value = float_array[i];
        sensor_data_array[i].status_indicator = status_indicator_array[i];
        sensor_data_array[i].timestamp = timestamp_array[i];
    }

    // Compute the MD5 hash of the input string and return it alongside the parsed TIFF metadata
    unsigned char* md5_hash = (unsigned char*)malloc(sizeof(unsigned char) * 16);
    if (md5_hash == NULL) {
        printf("Error: Memory allocation failed.\n");
        return 1;
    }
    MD5((unsigned char*)input_string, strlen(input_string), md5_hash);
    return 0;
}
