// Function to manage dynamic memory allocation and data processing under real-time constraints
void process_data(size_t num_ints, size_t num_strings, int range_min, int range_max) {
    // Validate input parameters against predefined limits
    if (num_ints > MAX_INT_SIZE || num_strings > MAX_STRING_SIZE) {
        fprintf(stderr, "Invalid input: number of integers or strings exceeds limit\n");
        return;
    }

    // Initialize an array of record structures with the specified size
    record* records = malloc(num_ints * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return;
    }

    // Populate each record with a random integer within the specified range
    srand(time(NULL)); // seed the random number generator with a unique value derived from the current time
    for (size_t i = 0; i < num_ints; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    // Initialize an array of strings with the specified size
    char** strings = malloc(num_strings * sizeof(char*));
    if (strings == NULL) {
        fprintf(stderr, "Failed to allocate memory for string array\n");
        free(records);
        return;
    }

    // Populate each string with a random string of the specified length
    for (size_t i = 0; i < num_strings; i++) {
        strings[i] = malloc(RANDOM_STRING_LENGTH * sizeof(char));
        if (strings[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for string %zu\n", i);
            free(records);
            free(strings);
            return;
        }
        for (size_t j = 0; j < RANDOM_STRING_LENGTH; j++) {
            strings[i][j] = 'a' + rand() % ('z' - 'a');
        }
    }

    // Integrate with an external memory pool manager to optimize memory usage
    struct mempool* pool = create_mempool(num_ints * sizeof(record) + num_strings * RANDOM_STRING_LENGTH);
    if (pool == NULL) {
        fprintf(stderr, "Failed to create memory pool\n");
        free(records);
        free(strings);
        return;
    }

    // Optimize memory usage by reusing previously allocated memory structures when possible
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            free(rec->str);
        }
        rec->str = malloc(RANDOM_STRING_LENGTH * sizeof(char));
        if (rec->str == NULL) {
            fprintf(stderr, "Failed to allocate memory for string %zu\n", i);
            destroy_mempool(pool);
            free(records);
            free(strings);
            return;
        }
    }

    // Optimize the function to minimize the number of memory allocations and deallocations by reusing existing memory whenever possible
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            free(rec->str);
        }
        rec->str = malloc(RANDOM_STRING_LENGTH * sizeof(char));
        if (rec->str == NULL) {
            fprintf(stderr, "Failed to allocate memory for string %zu\n", i);
            destroy_mempool(pool);
            free(records);
            free(strings);
            return;
        }
    }

    // Ensure thread safety by using appropriate synchronization mechanisms when interacting with the external memory pool manager
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            pthread_mutex_lock(&mutex);
            while (pool->used >= pool->capacity) {
                pthread_cond_wait(&cond, &mutex);
            }
            void* block = malloc(RANDOM_STRING_LENGTH * sizeof(char));
            if (block == NULL) {
                fprintf(stderr, "Failed to allocate memory for string %zu\n", i);
                pthread_mutex_unlock(&mutex);
                destroy_mempool(pool);
                free(records);
                free(strings);
                return;
            }
            pool->blocks[pool->used++] = block;
            pthread_mutex_unlock(&mutex);
        }
    }

    // Provide a mechanism to report current memory usage statistics, including total allocated memory, free memory, and memory pool utilization
    size_t total_allocated = 0;
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            total_allocated += RANDOM_STRING_LENGTH * sizeof(char);
        }
    }
    size_t free_memory = 0;
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            free_memory += RANDOM_STRING_LENGTH * sizeof(char);
        }
    }
    size_t pool_utilization = 0;
    for (size_t i = 0; i < num_ints; i++) {
        record* rec = &records[i];
        if (rec->str != NULL) {
            pool_utilization += RANDOM_STRING_LENGTH * sizeof(char);
        }
