using namespace std;
using namespace cv;

// Custom hash function for memory pool manager
struct MemoryPoolHash {
    size_t operator()(const void* ptr) const {
        return reinterpret_cast<size_t>(ptr);
    }
};

// Custom equal-to function for memory pool manager
struct MemoryPoolEqual {
    bool operator()(const void* lhs, const void* rhs) const {
        return lhs == rhs;
    }
};

// Memory pool manager class
class MemoryPoolManager {
public:
    // Constructor
    MemoryPoolManager(size_t blockSize = 1024, size_t numBlocks = 100) : blockSize_(blockSize), numBlocks_(numBlocks) {}

    // Allocate memory from the pool
    void* allocate(size_t size) {
        if (size > blockSize_) {
            return nullptr;
        }

        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = freeList_.begin(); it != freeList_.end(); ++it) {
            if (*it >= size) {
                void* ptr = *it;
                freeList_.erase(it);
                return ptr;
            }
        }

        if (usedList_.size() < numBlocks_) {
            usedList_.push_back(new char[blockSize_]);
            return usedList_.back();
        }

        return nullptr;
    }

    // Deallocate memory to the pool
    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        freeList_.push_back(ptr);
    }

private:
    size_t blockSize_;
    size_t numBlocks_;
    std::vector<char*> usedList_;
    std::unordered_set<void*, MemoryPoolHash, MemoryPoolEqual> freeList_;
    std::mutex mutex_;
};

// Image processing library class
class ImageProcessingLibrary {
public:
    // Constructor
    ImageProcessingLibrary() : memoryPoolManager_(1024, 100) {}

    // Load image processing module
    void loadModule(const string& moduleName) {
        if (moduleName == "edge_detection") {
            edgeDetectionModule_ = true;
        } else if (moduleName == "color_space_conversion") {
            colorSpaceConversionModule_ = true;
        } else if (moduleName == "feature_extraction") {
            featureExtractionModule_ = true;
        } else {
            throw invalid_argument("Invalid module name");
        }
    }

    // Unload image processing module
    void unloadModule(const string& moduleName) {
        if (moduleName == "edge_detection") {
            edgeDetectionModule_ = false;
        } else if (moduleName == "color_space_conversion") {
            colorSpaceConversionModule_ = false;
        } else if (moduleName == "feature_extraction") {
            featureExtractionModule_ = false;
        } else {
            throw invalid_argument("Invalid module name");
        }
    }

    // Check if image processing module is loaded
    bool isModuleLoaded(const string& moduleName) const {
        if (moduleName == "edge_detection") {
            return edgeDetectionModule_;
        } else if (moduleName == "color_space_conversion") {
            return colorSpaceConversionModule_;
        } else if (moduleName == "feature_extraction") {
            return featureExtractionModule_;
        } else {
            throw invalid_argument("Invalid module name");
        }
    }

    // Process image using loaded modules
    void processImage(const Mat& image) {
        if (edgeDetectionModule_) {
            edgeDetector_.detectEdges(image);
        }

        if (colorSpaceConversionModule_) {
            colorConverter_.convertColor(image);
        }

        if (featureExtractionModule_) {
            featureExtractor_.extractFeatures(image);
        }
    }

private:
    // Edge detection module
    bool edgeDetectionModule_ = false;
    EdgeDetector edgeDetector_;

