    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        records[i].value = 0;
        records[i].str_ptr = NULL;
        offsets[i] = 0;
        keys[i] = 0;
