        string_pool[i][0] = '\0';
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to allocate a new string in the pool and return its index
int alloc_string(const char *str) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find an empty slot in the pool
    int i;
    for (i = 0; i < STRING_POOL_SIZE && string_pool[i][0] != '\0'; i++) {}

    // If no empty slots found, return -1
    if (i == STRING_POOL_SIZE) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Copy the string into the pool and set its length
    strcpy(string_pool[i], str);
    int len = strlen(str);

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return i;
}

