#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    double value;
    char *str;
    int key;
} Record;

// Define the shared string pool
typedef struct {
    char **strings;
    size_t capacity;
    pthread_mutex_t mutex;
} StringPool;

// Function to initialize the shared string pool
void initStringPool(StringPool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->strings = malloc(sizeof(char *) * capacity);
    for (size_t i = 0; i < capacity; i++) {
        pool->strings[i] = NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

// Function to add a string to the shared string pool
void addString(StringPool *pool, const char *str) {
    size_t len = strlen(str);
    if (len > 0) {
        pthread_mutex_lock(&pool->mutex);
        for (size_t i = 0; i < pool->capacity; i++) {
            if (pool->strings[i] == NULL || strcmp(str, pool->strings[i]) == 0) {
                pool->strings[i] = strdup(str);
                break;
            }
        }
        pthread_mutex_unlock(&pool->mutex);
    }
}

// Function to retrieve a string from the shared string pool
const char *getString(StringPool *pool, const char *str) {
    size_t len = strlen(str);
    if (len > 0) {
        pthread_mutex_lock(&pool->mutex);
        for (size_t i = 0; i < pool->capacity; i++) {
            if (pool->strings[i] != NULL && strcmp(str, pool->strings[i]) == 0) {
                const char *ret = pool->strings[i];
                pthread_mutex_unlock(&pool->mutex);
                return ret;
            }
        }
        pthread_mutex_unlock(&pool->mutex);
    }
    return NULL;
}

// Function to free the shared string pool
void freeStringPool(StringPool *pool) {
    for (size_t i = 0; i < pool->capacity; i++) {
        if (pool->strings[i] != NULL) {
            free(pool->strings[i]);
        }
    }
    pthread_mutex_destroy(&pool->mutex);
}

// Function to read the configuration file and initialize the components
void initComponents(const char *configFile, StringPool *pool) {
    // Open the configuration file
    FILE *file = fopen(configFile, "r");
    if (file == NULL) {
        printf("Error: unable to open configuration file\n");
        return;
    }

    // Read the initial values for the components from the file
    size_t numRecords = 0;
    while (!feof(file)) {
        Record record;
        fscanf(file, "%lf %s %d", &record.value, record.str, &record.key);
        addString(pool, record.str);
        numRecords++;
    }

    // Close the configuration file
    fclose(file);

    // Sort the records based on the keys
    qsort(records, numRecords, sizeof(Record), compareKeys);

    // Shuffle the records using a specified seed for the random number generator
    srand(time(NULL));
    size_t shuffleSeed = 1234;
    for (size_t i = 0; i < numRecords; i++) {
        size_t j = rand_r(&shuffleSeed) % (numRecords - i);
        Record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }
}

// Function to compare the keys of two records
int compareKeys(const void *a, const void *b) {
    const Record *ra = (const Record *)a;
    const Record *rb = (const Record *)b;
    return ra->key - rb->key;
}

// Function to populate the components with data from a file
void populateComponents(const char *dataFile, StringPool *pool) {
    // Open the data file
    FILE *file = fopen(dataFile, "r");
    if (file == NULL) {
        printf("Error: unable to open data file\n");
        return;
    }

    // Read the data from the file and populate the components
    while (!feof(file)) {
        Record record;
        fscanf(file, "%lf %s %d", &record.value, record.str, &record.key);
        addString(pool, record.str);
    }

    // Close the data file
    fclose(file);
}

// Function to free the memory allocated for the components
void freeComponents() {
    // Free the memory allocated for the string pool
    freeStringPool(&pool);

    // Free the memory allocated for the records
    for (size_t i = 0; i < numRecords; i++) {
        Record *record = &records[i];
        if (record->str != NULL) {
            free(record->str);
        }
    }
}

// Function to handle command-line options for specifying the configuration file path and seed
void handleOptions(int argc, char **argv) {
    // Check if the user has specified a configuration file path
    if (argc > 1) {
        configFile = argv[1];
    } else {
        printf("Error: no configuration file specified\n");
        return;
    }

    // Check if the user has specified a seed for reproducibility
    if (argc > 2) {
        shuffleSeed = atoi(argv[2]);
    } else {
        printf("Error: no seed specified\n");
        return;
    }
}

// Main function to initialize and populate the components
int main(int argc, char **argv) {
    // Handle command-line options for specifying the configuration file path and seed
    handleOptions(argc, argv);

    // Initialize the shared string pool
    initStringPool(&pool, 1024);

    // Read the initial values for the components from the configuration file
    initComponents(configFile, &pool);

    // Populate the components with data from a file
    populateComponents("data.txt", &pool);

    // Sort the records based on the keys
    qsort(records, numRecords, sizeof(Record), compareKeys);

    // Shuffle the records using a specified seed for the random number generator
    srand(time(NULL));
    size_t shuffleSeed = 1234;
    for (size_t i = 0; i < numRecords; i++) {
        size_t j = rand_r(&shuffleSeed) % (numRecords - i);
        Record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }

    // Return a pointer to the first element of the 'record' array
    return records;
}
