    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

// Define the function for managing memory for the structured collection of records
int manage_memory(size_t num_records, size_t num_items, int* keys, double* weights, char** names) {
    // Allocate memory for the array of records
    Record* records = my_alloc(num_records * sizeof(Record));

    // Initialize the array of records
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = i;
        records[i].key = keys[i];
        records[i].value = rand() % 100 + 1; // Generate a random number within the specified range
    }

    // Allocate memory for the array of weights
    double* weight_array = my_alloc(num_items * sizeof(double));

    // Initialize the array of weights
    for (size_t i = 0; i < num_items; i++) {
        if (i % 2 == 0) {
            weight_array[i] = i + 1;
        } else {
            weight_array[i] = pow(i, 2);
        }
    }

    // Allocate memory for the array of item names
    char** name_array = my_alloc(num_items * sizeof(char*));

    // Initialize the array of item names
    for (size_t i = 0; i < num_items; i++) {
        name_array[i] = my_alloc(strlen(names[i]) + 1);
        strcpy(name_array[i], names[i]);
    }

    // Allocate memory for the linked list of items
    Item* head = NULL;
    Item* current = NULL;

    // Populate the linked list of items
    for (size_t i = 0; i < num_items; i++) {
        Item* new_item = my_alloc(sizeof(Item));
        new_item->name = name_array[i];
        new_item->weight = weight_array[i];
        new_item->next = NULL;

        if (head == NULL) {
            head = current = new_item;
        } else {
            current->next = new_item;
            current = new_item;
        }
    }

    // Free the memory allocated for the arrays and linked list
    free(records);
    free(weight_array);
    free(name_array);
    while (head != NULL) {
        Item* temp = head->next;
        free(head);
        head = temp;
    }

    return 0;
}
