// Function to dynamically allocate memory for two arrays: one for 'long' offset values and another for 'int' keys
void* allocateMemory(size_t offsetSize, size_t keySize, size_t numRecords) {
    // Calculate the total size of the memory block needed
    size_t totalSize = (offsetSize * numRecords) + (keySize * numRecords);

    // Allocate memory for the arrays and initialize them to 0
    long* offsetArray = malloc(totalSize);
    memset(offsetArray, 0, totalSize);

