// Function to interact with an external SQL database and execute a query
IDataReader* executeQuery(sqlite3* db, const char* sql, int numParams, ...) {
    // Prepare the parameterized SQL command
    sqlite3_stmt* stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Bind the parameters to the SQL command
    va_list args;
    va_start(args, numParams);
    for (int i = 0; i < numParams; i++) {
        sqlite3_bind_value(stmt, i + 1, va_arg(args, sqlite3_value*));
    }
    va_end(args);

    // Execute the SQL command and retrieve the result set
    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Error executing SQL statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Create an IDataReader for the result set
    IDataReader* reader = malloc(sizeof(IDataReader));
    reader->stmt = stmt;
    reader->numRows = sqlite3_column_count(stmt);

    return reader;
}

// Function to clean up resources allocated by the functions above
void freeResources(Record* records, IDataReader* reader) {
    // Free the memory allocated for the record array and the result set
    free(records);
    sqlite3_finalize(reader->stmt);
}
