#include <pthread.h>

// Define a structure for storing measurements
typedef struct measurement {
    double value;
    char *identifier;
} measurement_t;

// Define a memory pool manager to optimize memory usage and reduce fragmentation
typedef struct mempool {
    void **blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} mempool_t;

// Define a function to initialize the memory pool manager
void init_mempool(mempool_t *mp, size_t block_size) {
    mp->blocks = NULL;
    mp->block_size = block_size;
    mp->num_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

// Define a function to register an allocated memory block with the manager
void mempool_register(mempool_t *mp, void *block) {
    pthread_mutex_lock(&mp->lock);
    mp->blocks = realloc(mp->blocks, (mp->num_blocks + 1) * sizeof(void*));
    mp->blocks[mp->num_blocks++] = block;
    pthread_mutex_unlock(&mp->lock);
}

// Define a function to deregister an allocated memory block with the manager
void mempool_deregister(mempool_t *mp, void *block) {
    pthread_mutex_lock(&mp->lock);
    size_t i;
    for (i = 0; i < mp->num_blocks; i++) {
        if (mp->blocks[i] == block) {
            break;
        }
    }
    if (i < mp->num_blocks - 1) {
        memmove(&mp->blocks[i], &mp->blocks[i + 1], (mp->num_blocks - i - 1) * sizeof(void*));
    }
    mp->num_blocks--;
    pthread_mutex_unlock(&mp->lock);
}

// Define a function to allocate memory from the pool
void *mempool_alloc(mempool_t *mp, size_t size) {
    void *block = NULL;
    if (size <= mp->block_size) {
        pthread_mutex_lock(&mp->lock);
        if (mp->num_blocks > 0) {
            block = mp->blocks[--mp->num_blocks];
        }
        pthread_mutex_unlock(&mp->lock);
    }
    return block;
}

// Define a function to deallocate memory from the pool
void mempool_dealloc(mempool_t *mp, void *block) {
    if (block != NULL) {
        pthread_mutex_lock(&mp->lock);
        size_t i;
        for (i = 0; i < mp->num_blocks; i++) {
            if (mp->blocks[i] == block) {
                break;
            }
        }
        if (i < mp->num_blocks - 1) {
            memmove(&mp->blocks[i], &mp->blocks[i + 1], (mp->num_blocks - i - 1) * sizeof(void*));
        }
        mp->num_blocks--;
        pthread_mutex_unlock(&mp->lock);
    }
}

// Define a function to read measurements from a file and store them in an array
int read_measurements(const char *filename, measurement_t **measurements, size_t *num_measurements) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Allocate memory for the measurements array
    size_t num_lines = 0;
    while (!feof(file)) {
        char line[256];
        if (fgets(line, sizeof(line), file) != NULL) {
            num_lines++;
        }
    }
    fseek(file, 0, SEEK_SET);
    *measurements = malloc(num_lines * sizeof(**measurements));
    if (*measurements == NULL) {
        perror("Error allocating memory for measurements");
        return -1;
    }

    // Read each line of the file and store the measurement values in the array
    size_t i = 0;
