            double value;
            char identifier[128];
            if (sscanf(line, "%lf %s", &value, identifier) == 2) {
                (*measurements)[i].value = value;
                strncpy((*measurements)[i].identifier, identifier, sizeof(identifier));
                i++;
            } else {
                fprintf(stderr, "Error reading measurement from file: %s\n", filename);
                return -1;
            }
        }
    }
    *num_measurements = i;

    // Close the file and return success
    fclose(file);
    return 0;
}

// Define a function to calculate the average value of an array of measurements
double average_measurements(const measurement_t *measurements, size_t num_measurements) {
    double sum = 0.0;
    for (size_t i = 0; i < num_measurements; i++) {
        sum += measurements[i].value;
    }
    return sum / num_measurements;
}

// Define a function to clear all allocated resources and reset the memory pool
void clear_resources(mempool_t *mp) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->num_blocks; i++) {
        free(mp->blocks[i]);
    }
    mp->num_blocks = 0;
    pthread_mutex_unlock(&mp->lock);
}

// Define a function to report current memory usage statistics
void report_memory_usage(mempool_t *mp) {
    size_t total_allocated = 0;
    size_t free_memory = 0;
    size_t pool_utilization = 0;
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->num_blocks; i++) {
        total_allocated += mp->block_size;
        free_memory += mp->block_size - sizeof(void*);
    }
    pool_utilization = (total_allocated * 100) / (total_allocated + free_memory);
    pthread_mutex_unlock(&mp->lock);
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Free memory: %zu\n", free_memory);
    printf("Memory pool utilization: %.2f%%\n", pool_utilization);
}

