// Function to allocate and initialize the arrays for offset values and keys
void initArrays(size_t* numKeys, size_t* numOffsets) {
    // Allocate memory for the key array
    *numKeys = (size_t)malloc(sizeof(int));
    if (*numKeys == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        exit(1);
    }

    // Initialize the number of keys to 0
    **numKeys = 0;

    // Allocate memory for the offset array
    *numOffsets = (size_t)malloc(sizeof(long));
    if (*numOffsets == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Initialize the number of offsets to 0
    **numOffsets = 0;
}

// Function to create an array of 'record' structures and initialize each record with a random value within a specified range
void initRecords(size_t numKeys, size_t numOffsets) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(sizeof(Record) * numKeys);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        exit(1);
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < numKeys; i++) {
        records[i].key = rand() % 10000;
        records[i].offset = rand() % 1000000000;
    }
