// Function to register all allocated memory blocks with the external memory pool manager for optimized memory usage and reduced fragmentation
void registerMemoryBlocks(struct MemoryPoolManager* memPool, void** blocks, size_t numBlocks) {
    // Iterate over each block and register it with the memory pool manager
    for (size_t i = 0; i < numBlocks; i++) {
        // Register the block with the memory pool manager
        memPool->blocks[i] = blocks[i];
        memPool->numBlocks++;
    }
}

// Function to optimize the function to minimize memory allocations and deallocations by reusing existing memory pools where possible
void optimizeMemoryUsage(struct MemoryPoolManager* memPool) {
    // Check if there are any free blocks in the memory pool
    if (memPool->numBlocks > 0) {
        // Reuse a free block from the memory pool
        void* block = memPool->blocks[memPool->numBlocks - 1];
        memPool->numBlocks--;
        return block;
    } else {
        // Allocate a new block of memory from the system
        void* block = malloc(memPool->blockSize);
        if (block == NULL) {
            printf("Error: Failed to allocate memory for record\n");
            exit(1);
        }
        return block;
    }
}

