void getMemoryUsageStats(struct MemoryPoolManager* memPool) {
    // Calculate the total amount of memory allocated by the function
    size_t totalAllocated = 0;
    for (size_t i = 0; i < memPool->numBlocks; i++) {
        totalAllocated += memPool->blockSize;
    }

    // Calculate the amount of free memory available in the system
    size_t freeMemory = 0;
    struct sysinfo info;
    if (sysinfo(&info) == 0) {
        freeMemory = info.freeram * info.mem_unit;
    }

    // Calculate the utilization of the memory pool
