    // Print the memory usage statistics to standard output
    printf("Total allocated memory: %zu\n", totalAllocated);
    printf("Free memory: %zu\n", freeMemory);
    printf("Memory pool utilization: %.2f%%\n", memPoolUtilization * 100);
}

