    printf("Free memory: %lu bytes\n", manager->numFreeBlocks[0] * sizeof(Record) + manager->numFreeBlocks[1] * sizeof(long));
    printf("Memory pool utilization: %.2f%%\n", (manager->numFreeBlocks[0] / (float)keySize) * 100);

    // Clear all allocated resources and reset the memory pool
