    *lock = 1;
    pthread_mutex_unlock(&mutex);

    // Evaluate the trade-offs between lock granularity and performance, and consider using atomic operations where appropriate
    if (*lock) {
        pthread_mutex_lock(&mutex);
        *lock = 0;
        pthread_mutex_unlock(&mutex);
