    // Optimize the function for performance by minimizing memory allocations and deallocations, and ensuring that the random value generation is efficient and non-predictable
    srand(time(NULL));
    for (size_t i = 0; i < num_transactions; i++) {
        transaction_array[i].value = rand() / RAND_MAX;
    }

    // Ensure that memory usage statistics are consistent across different platforms and configurations
    printf("Memory usage statistics:\n");
    printf("Total allocated memory: %zu\n", pool->size);
    printf("Free memory: %zu\n", pool->size - pool->used);
    printf("Memory pool utilization: %.2f%%\n", (pool->used / (double)pool->size) * 100.0);

    // Provide a mechanism to report memory usage statistics, including total allocated memory, free memory, and memory pool utilization, after the function execution
