    printf("Free memory: %zu\n", pool->size - pool->used);
    printf("Memory pool utilization: %.2f%%\n", (pool->used / (double)pool->size) * 100.0);

    // Implement a function to clear all allocated resources and reset the memory pool, allowing subsequent calls
    void clear_memory() {
