// Function to allocate memory for arrays of doubles, chars, and points
void* allocateMemory(size_t numDoubles, size_t numChars, size_t numPoints) {
    // Calculate the total size of the memory block needed
    size_t totalSize = (numDoubles * sizeof(double)) + (numChars * sizeof(char)) + (numPoints * sizeof(Point));

    // Allocate the memory block using malloc()
    void* memBlock = malloc(totalSize);

    // Check if allocation failed and handle error gracefully
    if (!memBlock) {
        printf("Error: Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Initialize the memory block with zeros
    memset(memBlock, 0, totalSize);

    return memBlock;
}

// Function to deallocate memory for arrays of doubles, chars, and points
void deallocateMemory(void* memBlock) {
    free(memBlock);
}

// Function to calculate the Euclidean distance between two points
float euclideanDistance(Point p1, Point p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

// Function to read a list of floating-point numbers from standard input and calculate the Euclidean distance between the first and last points in the array
void readAndCalculateDistance(size_t numPoints) {
    // Allocate memory for the arrays of doubles, chars, and points
    void* memBlock = allocateMemory(numPoints, 0, numPoints);

    // Read the list of floating-point numbers from standard input
    double* doubleArray = (double*)memBlock;
    char* charArray = (char*)memBlock + (numPoints * sizeof(double));
    Point* pointArray = (Point*)memBlock + (numPoints * sizeof(double) + numPoints * sizeof(char));

    for (size_t i = 0; i < numPoints; i++) {
        scanf("%lf", &doubleArray[i]);
    }

    // Calculate the Euclidean distance between the first and last points in the array
    Point firstPoint = pointArray[0];
    Point lastPoint = pointArray[numPoints - 1];
    float distance = euclideanDistance(firstPoint, lastPoint);

    printf("The Euclidean distance between the first and last points is: %f\n", distance);

    // Deallocate memory for the arrays of doubles, chars, and points
    deallocateMemory(memBlock);
}

int main() {
    size_t numPoints = 0;
    scanf("%zu", &numPoints);

    readAndCalculateDistance(numPoints);

    return 0;
}
