#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <chrono>
#include <memory>
#include <cstdlib>
#include <ctime>
#include <filesystem>

using namespace std;

int convertJPEGToPDF(const string& inputFilePath, const string& outputDirectory) {
    // Check if input file exists and is a JPEG image
    if (!filesystem::exists(inputFilePath)) {
        cerr << "Input file does not exist: " << inputFilePath << endl;
        return 1;
    } else if (filesystem::file_size(inputFilePath) == 0) {
        cerr << "Input file is empty: " << inputFilePath << endl;
        return 1;
    } else if (!filesystem::is_regular_file(inputFilePath)) {
        cerr << "Input file is not a regular file: " << inputFilePath << endl;
        return 1;
    } else if (filesystem::extension(inputFilePath) != ".jpg" && filesystem::extension(inputFilePath) != ".jpeg") {
        cerr << "Input file is not a JPEG image: " << inputFilePath << endl;
        return 1;
    }

    // Check if output directory exists and is writable
    if (!filesystem::exists(outputDirectory)) {
        cerr << "Output directory does not exist: " << outputDirectory << endl;
        return 1;
    } else if (!filesystem::is_directory(outputDirectory)) {
        cerr << "Output is not a directory: " << outputDirectory << endl;
        return 1;
    } else if (!filesystem::is_writable(outputDirectory)) {
        cerr << "Output directory is not writable: " << outputDirectory << endl;
        return 1;
    }

    // Convert JPEG image to PDF using third-party library
    try {
        // Load JPEG image and convert it to PDF
        shared_ptr<vector<unsigned char>> pdfData = convertJPEGToPDF(inputFilePath);

        // Serialize PDF data into a byte array
        string pdfBytes;
        for (auto& byte : *pdfData) {
            pdfBytes += static_cast<char>(byte);
        }

        // Save PDF to output directory
        ofstream outfile(outputDirectory + "/output.pdf", ios::binary);
        if (!outfile) {
            cerr << "Error saving PDF file: " << outputDirectory << endl;
            return 1;
        }
        outfile.write(pdfBytes.c_str(), pdfBytes.size());
        outfile.close();

        // Generate metadata JSON file
        string metadata = "{\"inputFilePath\": \"" + inputFilePath + "\", \"outputDirectory\": \"" + outputDirectory + "\", \"startTime\": \"" + to_string(chrono::system_clock::now()) + "\", \"endTime\": \"" + to_string(chrono::system_clock::now()) + "\", \"errors\": []}";
        ofstream metadataFile(outputDirectory + "/metadata.json");
        if (!metadataFile) {
            cerr << "Error generating metadata file: " << outputDirectory << endl;
            return 2;
        }
        metadataFile << metadata;
        metadataFile.close();
    } catch (const exception& e) {
        cerr << "Exception caught during conversion: " << e.what() << endl;
        return 1;
