            free_entries(entries, i);
            return NULL;
        }
        entries[i]->key = 0;
        entries[i]->value = value;
        entries[i]->expiry = time(NULL) + length;

        // Increment the number of active entries if the current entry is not NULL
        if (entries[i]) {
            num_active_entries++;
        }
    }

    return entries;
}

// Function to handle concurrent access from multiple threads, ensuring thread safety and preventing race conditions
entry** allocate_entries_with_thread_safety(int num_entries, size_t length) {
    // Initialize the array of pointers with NULL values
    entry** entries = malloc(num_entries * sizeof(entry*));
    if (!entries) {
        return NULL;
    }

    // Use a mutex to protect the allocation and freeing of memory for each entry
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop until all entries are allocated or a failure occurs
    for (int i = 0; i < num_entries; i++) {
