    size_t num_free_blocks;
    // The list of free blocks in the pool
    struct block* free_blocks;
};

// Define the block structure for the memory pool
struct block {
    // The address of the next block in the pool
    void* next;
    // The size of the block in bytes
    size_t size;
};

// Define the function to allocate memory for the arrays
void* allocate_memory(size_t num_elements, size_t element_size) {
    // Calculate the total size of the array in bytes
    size_t total_size = num_elements * element_size;
    // Allocate the memory for the array
    void* array = malloc(total_size);
    // Check if the allocation was successful
    if (array == NULL) {
        printf("Error: Failed to allocate memory for the arrays\n");
        return NULL;
    }
    // Initialize the memory for the arrays
    memset(array, 0, total_size);
    return array;
}

// Define the function to initialize the arrays
void initialize_arrays(double** double_array, char** char_array, struct point** point_array) {
    // Allocate memory for the arrays
    *double_array = allocate_memory(100, sizeof(double));
    *char_array = allocate_memory(100, sizeof(char));
    *point_array = allocate_memory(100, sizeof(struct point));
}

// Define the function to release memory for the arrays
void release_memory(double* double_array, char* char_array, struct point* point_array) {
    // Release the memory for the arrays
    free(double_array);
    free(char_array);
    free(point_array);
}

// Define the function to handle allocation failures
