    release_memory(*double_array, *char_array, *point_array);
    exit(1);
}

// Define the function to reuse previously allocated memory when possible
void reuse_memory(size_t num_elements) {
    // Check if there are any free blocks in the pool
    if (pool.num_free_blocks > 0) {
        // Get the first free block from the pool
        struct block* free_block = pool.free_blocks;
        // Remove the free block from the pool
        pool.free_blocks = free_block->next;
        --pool.num_free_blocks;
        // Allocate the memory for the arrays
        *double_array = malloc(num_elements * sizeof(double));
        *char_array = malloc(num_elements * sizeof(char));
        *point_array = malloc(num_elements * sizeof(struct point));
        // Check if the allocation was successful
        if (*double_array == NULL || *char_array == NULL || *point_array == NULL) {
            handle_allocation_failure();
        }
        // Initialize the memory for the arrays
        memset(*double_array, 0, num_elements * sizeof(double));
        memset(*char_array, 0, num_elements * sizeof(char));
        memset(*point_array, 0, num_elements * sizeof(struct point));
    } else {
        // Allocate the memory for the arrays
        *double_array = malloc(num_elements * sizeof(double));
        *char_array = malloc(num_elements * sizeof(char));
        *point_array = malloc(num_elements * sizeof(struct point));
        // Check if the allocation was successful
        if (*double_array == NULL || *char_array == NULL || *point_array == NULL) {
            handle_allocation_failure();
        }
        // Initialize the memory for the arrays
        memset(*double_array, 0, num_elements * sizeof(double));
        memset(*char_array, 0, num_elements * sizeof(char));
        memset(*point_array, 0, num_elements * sizeof(struct point));
    }
}

// Define the function to integrate with an external data structure manager
