// Custom Memory Pool Manager

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

#define MAX_BLOCK_SIZE 1024 // Maximum block size in bytes
#define MIN_BLOCK_SIZE 32 // Minimum block size in bytes
#define BLOCK_ALIGNMENT 8 // Block alignment in bytes
#define DEFAULT_POOL_SIZE 1024 * 1024 // Default pool size in bytes
#define MAX_POOL_SIZE 16 * 1024 * 1024 // Maximum pool size in bytes

typedef struct block {
    void* data;
    size_t size;
    struct block* next;
} block_t;

typedef struct memory_pool {
    block_t* blocks;
    size_t num_blocks;
    size_t total_size;
    size_t max_size;
    size_t min_size;
    size_t alignment;
} memory_pool_t;

// Initialize a new memory pool with the given parameters.
void init_memory_pool(memory_pool_t* pool, size_t initial_size, size_t max_size, size_t min_size, size_t alignment) {
    assert(initial_size > 0 && initial_size <= max_size && initial_size >= min_size);
    assert(alignment > 0 && alignment % BLOCK_ALIGNMENT == 0);

    pool->blocks = NULL;
    pool->num_blocks = 0;
    pool->total_size = 0;
    pool->max_size = max_size;
    pool->min_size = min_size;
    pool->alignment = alignment;
}

// Allocate a block of memory from the pool.
void* allocate(memory_pool_t* pool, size_t size) {
    assert(size > 0 && size <= pool->max_size);

    // Find the first free block that is large enough to hold the requested size.
    block_t* block = pool->blocks;
    while (block != NULL && block->size < size) {
        block = block->next;
    }

    if (block == NULL) {
        // No free block found, allocate a new one.
        size_t alloc_size = MAX(size, pool->min_size);
        alloc_size = MIN(alloc_size, pool->max_size);
        void* data = malloc(alloc_size + sizeof(block_t));
        if (data == NULL) {
            return NULL;
        }

        block = (block_t*)((char*)data + sizeof(block_t));
        block->data = data;
        block->size = alloc_size;
        block->next = pool->blocks;
        pool->blocks = block;
    } else {
        // Remove the allocated block from the free list.
        block_t* prev = NULL;
        while (prev != block && prev->next != block) {
            prev = prev->next;
        }
        if (prev == NULL) {
            pool->blocks = block->next;
        } else {
            prev->next = block->next;
        }
    }

    // Update the total size and number of blocks.
    pool->total_size += size;
    pool->num_blocks++;

    return block->data;
}

// Deallocate a block of memory from the pool.
void deallocate(memory_pool_t* pool, void* data) {
    assert(data != NULL);

    // Find the allocated block that contains the given data pointer.
    block_t* block = pool->blocks;
    while (block != NULL && block->data != data) {
        block = block->next;
    }

    if (block == NULL) {
        return;
    }

    // Add the deallocated block to the free list.
    block_t* prev = NULL;
    while (prev != block && prev->next != block) {
        prev = prev->next;
    }
    if (prev == NULL) {
        pool->blocks = block->next;
    } else {
        prev->next = block->next;
    }

    // Update the total size and number of blocks.
    pool->total_size -= block->size;
    pool->num_blocks--;
}

