// Define the memory pool configuration parameters
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
#define MEMORY_ALIGNMENT 64
#define MEMORY_PADDING 8

// Define the external data structure manager
extern void* memoryPool;

// Function to dynamically allocate memory for and initialize three arrays: one for 'long' offset values, one for 'int' keys, and one for 'record' structures
void* initMemory(size_t size) {
    // Check if the allocation size is zero
    if (size == 0) {
        return NULL;
    }

    // Allocate memory for the three arrays
    long* offsetArray = malloc(sizeof(long) * size);
    int* keyArray = malloc(sizeof(int) * size);
    Record* recordArray = malloc(sizeof(Record) * size);

    // Initialize the 'record' structures with a value between 0 and 1000 using a non-blocking, thread-safe random number generator
    for (size_t i = 0; i < size; i++) {
        recordArray[i].value = rand() % 1000;
    }

    // Register the allocated memory with the external data structure manager
    registerMemory(offsetArray, sizeof(long) * size);
    registerMemory(keyArray, sizeof(int) * size);
    registerMemory(recordArray, sizeof(Record) * size);

    // Return a pointer to the first element of the 'record' array
    return recordArray;
}

// Function to clean up resources and reset the memory pool
void clearMemory() {
    // Unregister all allocated memory with the external data structure manager
    unregisterMemory(memoryPool);

    // Free all allocated memory
    free(memoryPool);

    // Reset the memory pool configuration parameters
    MEMORY_POOL_SIZE = 1024 * 1024;
    MEMORY_ALIGNMENT = 64;
    MEMORY_PADDING = 8;
}

// Function to report the current memory usage statistics
void getMemoryUsage(size_t* totalAllocated, size_t* freeMemory, double* poolUtilization) {
    // Calculate the total allocated memory
    *totalAllocated = sizeof(long) * MEMORY_POOL_SIZE + sizeof(int) * MEMORY_POOL_SIZE + sizeof(Record) * MEMORY_POOL_SIZE;

    // Calculate the free memory
    *freeMemory = 0;

    // Calculate the memory pool utilization
    *poolUtilization = (double)(*totalAllocated - *freeMemory) / (double)*totalAllocated;
}
