// Memory pool manager structure
struct memory_pool {
    void* data;
    size_t size;
};

// Record structure for storing integer values
struct record {
    int value;
};

// Function to manage a dynamic data processing pipeline
void process_data(int key_size, int record_size) {
    // Memory allocation and initialization
    struct memory_pool* key_pool = malloc(sizeof(struct memory_pool));
    struct memory_pool* record_pool = malloc(sizeof(struct memory_pool));
    if (!key_pool || !record_pool) {
        fprintf(stderr, "Failed to allocate memory pools\n");
        return;
    }
    key_pool->data = calloc(key_size, sizeof(long));
    record_pool->data = calloc(record_size, sizeof(struct record));
    if (!key_pool->data || !record_pool->data) {
        fprintf(stderr, "Failed to allocate memory for key and record pools\n");
        return;
    }
    key_pool->size = key_size;
    record_pool->size = record_size;

    // Data record initialization
    struct record* records = (struct record*)record_pool->data;
    for (int i = 0; i < record_size; i++) {
        records[i].value = rand() % 100;
    }

    // Random value generation
    long* keys = (long*)key_pool->data;
    srand(time(NULL));
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 1000000;
    }

    // Error handling
    if (!keys || !records) {
        fprintf(stderr, "Failed to allocate memory for keys and records\n");
        return;
    }

    // Integration with external data structures
    struct memory_pool* external_pool = malloc(sizeof(struct memory_pool));
    if (!external_pool) {
        fprintf(stderr, "Failed to allocate memory for external pool\n");
        return;
    }
    external_pool->data = calloc(100, sizeof(int));
    if (!external_pool->data) {
        fprintf(stderr, "Failed to allocate memory for external data structure\n");
        return;
    }
    external_pool->size = 100;

    // Performance optimization
    struct record* optimized_records = (struct record*)record_pool->data;
    for (int i = 0; i < record_size; i++) {
        optimized_records[i].value = rand() % 100;
    }

    // Memory usage reporting
    printf("Total allocated memory: %zu\n", key_pool->size * sizeof(long) + record_pool->size * sizeof(struct record));
    printf("Free memory: %zu\n", external_pool->size * sizeof(int));
    printf("Memory pool utilization: %.2f%%\n", (float)(key_pool->size + record_pool->size) / (external_pool->size * 100));

    // Resource cleanup
    free(key_pool);
    free(record_pool);
    free(external_pool);
}
