// Function to dynamically allocate and link nodes into a singly linked list
void create_linked_list(int num_nodes) {
    // Allocate memory for the arrays of strings, float values, and struct nodes
    char** string_array = malloc(num_nodes * sizeof(char*));
    float* float_array = malloc(num_nodes * sizeof(float));
    struct node** node_array = malloc(num_nodes * sizeof(struct node*));

    // Initialize the arrays with random lowercase alphabetic characters and unique string values
    for (int i = 0; i < num_nodes; i++) {
        string_array[i] = malloc(10 * sizeof(char));
        float_array[i] = rand() / (float)RAND_MAX;
        node_array[i] = malloc(sizeof(struct node));
        for (int j = 0; j < 10; j++) {
            string_array[i][j] = 'a' + (rand() % ('z' - 'a'));
        }
    }

    // Initialize the linked list with the unique string values
