// Define data structure for data items
typedef struct {
    long timestamp;
    int status_code;
    size_t payload_size;
} data_item;

// Define memory pool manager interface
struct mempool_manager {
    void* (*alloc)(size_t);
    void (*free)(void*);
};

// Define function to add new data item
int add_data_item(data_item* item) {
    // Check if memory pool is full
    if (mempool_manager.is_full()) {
        return -1;
    }

    // Allocate memory for data item
    void* mem = mempool_manager.alloc(sizeof(data_item));
    if (!mem) {
        return -2;
    }

    // Copy data item into allocated memory
    memcpy(mem, item, sizeof(data_item));

    // Add data item to collection
    data_items = realloc(data_items, (num_data_items + 1) * sizeof(data_item*));
    if (!data_items) {
        return -3;
    }
    data_items[num_data_items++] = mem;

    // Update memory usage statistics
    total_allocated_memory += sizeof(data_item);
    free_memory -= sizeof(data_item);
    mempool_utilization = (float)total_allocated_memory / (float)max_memory * 100;

    return 0;
}

// Define function to retrieve data item by identifier
data_item* get_data_item(int id) {
    // Check if data item exists in collection
    for (int i = 0; i < num_data_items; i++) {
        if (data_items[i]->id == id) {
            return data_items[i];
        }
    }

    // Return NULL if data item does not exist
    return NULL;
}

// Define function to clear all allocated resources and reset memory pool
void clear_resources() {
    // Free all allocated memory
    for (int i = 0; i < num_data_items; i++) {
        mempool_manager.free(data_items[i]);
    }
    free(data_items);
    data_items = NULL;
    num_data_items = 0;

    // Reset memory pool utilization and allocated memory statistics
    total_allocated_memory = 0;
    free_memory = max_memory;
    mempool_utilization = 0.0f;
}

// Define function to report memory usage statistics
void report_memory_usage() {
    printf("Total allocated memory: %zu\n", total_allocated_memory);
    printf("Free memory: %zu\n", free_memory);
    printf("Memory pool utilization: %.2f%%\n", mempool_utilization);
}
```
