static size_t num_profiles = 0;

// Define the maximum number of profiles allowed in the collection
#define MAX_PROFILES 1000

// Define a custom memory pool manager for profile allocation
static void* profile_alloc(size_t size) {
    // Allocate memory from an external memory pool manager
    void* mem = malloc(size);

    // Check if the allocation was successful
    if (mem == NULL) {
        printf("Error: Failed to allocate memory for a user profile\n");
        return NULL;
    }

    // Initialize the allocated memory with default values
    memset(mem, 0, size);

    return mem;
}

// Define a mechanism to report detailed memory usage statistics
static void print_memory_usage() {
    printf("Total allocated memory: %zu\n", num_profiles * sizeof(UserProfile));
    printf("Free memory: %zu\n", free(profile_collection) - num_profiles * sizeof(UserProfile));
    printf("Pool utilization: %d%%\n", (num_profiles / MAX_PROFILES) * 100);
}

// Define a thread-safe mechanism to manage the collection of user profiles
static void add_profile(const char* name, int age, const char* email, int* preference_list) {
    // Acquire a lock on the profile collection
    pthread_mutex_lock(&profile_collection_lock);

    // Check if the number of profiles exceeds the maximum allowed
    if (num_profiles >= MAX_PROFILES) {
        printf("Error: Maximum number of profiles reached\n");
        return;
    }

    // Allocate memory for a new user profile
    UserProfile* new_profile = profile_alloc(sizeof(UserProfile));

