    new_profile->age = age;
    new_profile->email = strdup(email);
    new_profile->preference_list = preference_list;

    // Add the new user profile to the collection
    profile_collection[num_profiles++] = new_profile;

    // Release the lock on the profile collection
    pthread_mutex_unlock(&profile_collection_lock);
}

// Define a mechanism to handle memory pressure by triggering alerts or fallback strategies when nearing capacity limits
static void handle_memory_pressure() {
    // Check if the number of profiles is nearing the maximum allowed
    if (num_profiles >= MAX_PROFILES - 10) {
        printf("Warning: Memory pressure detected, triggering alerts or fallback strategies\n");
    }
}

// Define a mechanism to report detailed memory usage statistics
static void print_memory_usage() {
    printf("Total allocated memory: %zu\n", num_profiles * sizeof(UserProfile));
    printf("Free memory: %zu\n", free(profile_collection) - num_profiles * sizeof(UserProfile));
    printf("Pool utilization: %d%%\n", (num_profiles / MAX_PROFILES) * 100);
}

// Define a mechanism to handle various failure scenarios, including resource exhaustion and allocation failures
