// Function to initialize an entry with a unique identifier and set its value
void init_entry(entry* e, const char* id) {
    // Allocate memory for the key
    e->key = malloc(strlen(id) + 1);
    if (e->key == NULL) {
        printf("Error: Failed to allocate memory for entry key\n");
        return;
    }
    strcpy(e->key, id);

    // Set the value to a random integer within the specified range
    e->value = rand() % 100 + 1;

    // Initialize the log structure with default values
    e->log = malloc(sizeof(log));
    if (e->log == NULL) {
        printf("Error: Failed to allocate memory for entry log\n");
        return;
    }
    e->log->level = 0;
    e->log->message = "Entry initialized";
}

// Function to manage a dynamic collection of entries
void manage_entries(entry** entries, int num_entries) {
    // Allocate memory for the array of entries
    *entries = malloc(num_entries * sizeof(entry));
    if (*entries == NULL) {
        printf("Error: Failed to allocate memory for entry array\n");
        return;
    }

    // Initialize each entry with a unique identifier and set its value
    for (int i = 0; i < num_entries; i++) {
        char id[16];
        sprintf(id, "entry%d", i);
        init_entry(&(*entries)[i], id);
    }

    // Free the memory allocated for the array of entries upon completion
    free(*entries);
}
