// Define a function to dynamically manage memory for the entries
void manage_memory(struct entry** entries, size_t num_entries) {
    // Allocate memory for an array of long integers representing offsets
    long* offsets = (long*)malloc(num_entries * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

