    // Populate the log structure with a default log level and message indicating the entry's index
    for (size_t i = 0; i < num_entries; i++) {
        entries[i]->log.level = 1;
        snprintf(entries[i]->log.message, sizeof(entries[i]->log.message), "entry%lu", i);
    }

    // Free the memory allocated for the offsets array
