#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a structure to store sensor readings
typedef struct {
    double timestamp;
    char description[256];
} data_point;

// Define a memory pool manager to optimize memory allocation and minimize fragmentation
struct mem_pool {
    void *mem;
    size_t size;
};

// Function to allocate and initialize memory for the dataset of sensor readings
data_point* alloc_dataset(size_t n) {
    // Allocate memory for the dataset using the external memory pool manager
    struct mem_pool *mem_pool = get_mem_pool();
    data_point *dataset = (data_point*) malloc(n * sizeof(data_point));
    if (!dataset) {
        fprintf(stderr, "Error: Failed to allocate memory for dataset\n");
        return NULL;
    }

    // Initialize the timestamp and description fields of each data point
    for (size_t i = 0; i < n; i++) {
        dataset[i].timestamp = get_random_double(1, 100);
        sprintf(dataset[i].description, "Sensor reading %zu", i + 1);
    }

    // Return the pointer to the allocated memory
    return dataset;
}

// Function to populate the dataset with random sensor readings
void populate_dataset(data_point *dataset, size_t n) {
    // Generate a random double value within a specified range
    double min = 1.0;
    double max = 100.0;
    srand(time(NULL));

    // Populate the dataset with random sensor readings
    for (size_t i = 0; i < n; i++) {
        dataset[i].timestamp = get_random_double(min, max);
    }
}

// Function to handle memory allocation failures gracefully
void handle_allocation_failure() {
    // Release any allocated resources before returning an error status
    free(dataset);
    fprintf(stderr, "Error: Failed to allocate memory for dataset\n");
}

// Function to report the current memory usage statistics
void report_memory_usage() {
    // Calculate the total allocated memory and free memory
    size_t total_allocated = 0;
    size_t free_memory = 0;
    for (size_t i = 0; i < n; i++) {
        total_allocated += sizeof(data_point);
        if (!dataset[i].description) {
            free_memory += sizeof(data_point);
        }
    }

    // Calculate the memory pool utilization
    size_t mem_pool_utilization = (total_allocated - free_memory) / total_allocated;

