function updateClinicStatus($clinicId, $status, $lastModifiedIpAddress, $lastModifiedDate) {
    // Validate clinic ID against whitelist
    if (!in_array($clinicId, $whitelistedClinicIds)) {
        return "Invalid clinic ID";
    }

    // Prepare statement for updating clinic status
    $stmt = $pdo->prepare("UPDATE clinics SET status = :status, last_modified_ip_address = :lastModifiedIpAddress, last_modified_date = :lastModifiedDate WHERE id = :clinicId");

    // Bind parameters to statement
    $stmt->bindParam(':status', $status);
    $stmt->bindParam(':lastModifiedIpAddress', $lastModifiedIpAddress);
    $stmt->bindParam(':lastModifiedDate', $lastModifiedDate);
    $stmt->bindParam(':clinicId', $clinicId);

    // Retry mechanism for updating clinic status
    $retries = 0;
    while ($retries < 3) {
        try {
            $stmt->execute();
            break;
        } catch (PDOException $e) {
            if ($retries == 2) {
                return "Failed to update clinic status after three retries";
            }
            sleep(1); // Wait for one second before retrying
            $retries++;
        }
    }

    // Log successful operation
    $logMessage = sprintf("Updated clinic status for clinic ID %s to %s", $clinicId, $status);
    logOperation($logMessage, "success");

    // Fetch latest status definitions from remote configuration service
    $statusDefinitions = fetchStatusDefinitions();

    // Check if the updated status is valid according to the remote configuration service
    if (!in_array($status, $statusDefinitions)) {
        return "Invalid status";
    }

    // Send notification to external API for successful update
