// Define the collection of modules
static module_t* modules = NULL;

// Define the lock for concurrent access
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize memory for a new module
module_t* create_module(char* name, int value) {
    // Allocate memory for the module structure
    module_t* new_module = malloc(sizeof(module_t));
    if (new_module == NULL) {
        printf("Error: Failed to allocate memory for new module\n");
        return NULL;
    }

    // Initialize the name and value of the module
    new_module->name = strdup(name);
    new_module->value = value;

    // Allocate memory for the dependencies list
    new_module->dependencies = malloc(sizeof(dependency_t*) * 10);
    if (new_module->dependencies == NULL) {
        printf("Error: Failed to allocate memory for module dependencies\n");
        free(new_module);
        return NULL;
    }

    // Initialize the list of dependencies
    new_module->num_dependencies = 0;

    return new_module;
}

// Function to add a dependency to a module
void add_dependency(module_t* module, char* name, int value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for the new dependency structure
    dependency_t* new_dependency = malloc(sizeof(dependency_t));
    if (new_dependency == NULL) {
        printf("Error: Failed to allocate memory for new dependency\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize the name and value of the dependency
    new_dependency->name = strdup(name);
    new_dependency->value = value;

    // Add the new dependency to the list of dependencies for the module
    module->dependencies[module->num_dependencies++] = new_dependency;

    pthread_mutex_unlock(&lock);
}

// Function to update the value of a module based on its dependencies
void update_value(module_t* module) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Iterate over the list of dependencies for the module
    for (int i = 0; i < module->num_dependencies; i++) {
        dependency_t* dependency = module->dependencies[i];

        // Update the value of the module based on its dependencies
        module->value += dependency->value;
    }

    pthread_mutex_unlock(&lock);
}

