// Define the function to dynamically allocate and manage memory for various data structures
int dynamicMemoryAllocation(struct MemoryPoolManager* poolManager, int keyArraySize, int recordCount) {
    // Validate the input sizes
    if (keyArraySize <= 0 || recordCount <= 0) {
        fprintf(stderr, "Invalid input size: %d, %d\n", keyArraySize, recordCount);
        return -1;
    }

    // Allocate memory for the key array
    int* keys = malloc(keyArraySize * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for key array: %s\n", strerror(errno));
        return -1;
    }

    // Allocate memory for the record array
    Record* records = malloc(recordCount * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array: %s\n", strerror(errno));
        free(keys);
        return -1;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < keyArraySize; i++) {
        keys[i] = rand() % INT_MAX;
    }

    // Initialize the record array with random values within a specified range
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % INT_MAX;
    }

    // Register the allocated memory blocks with the memory pool manager
    void* keyBlock = poolManager->alloc(keyArraySize * sizeof(int));
    if (keyBlock == NULL) {
        fprintf(stderr, "Failed to register key block: %s\n", strerror(errno));
        free(keys);
        free(records);
        return -1;
