    void* recordBlock = poolManager->alloc(recordCount * sizeof(Record));
    if (recordBlock == NULL) {
        fprintf(stderr, "Failed to register record block: %s\n", strerror(errno));
        free(keys);
        free(records);
        poolManager->dealloc(keyBlock);
        return -1;
