    printf("Total allocated memory: %zu\n", poolManager->totalAllocated());
    printf("Free memory: %zu\n", poolManager->freeMemory());
    printf("Memory pool utilization: %.2f%%\n", poolManager->utilization() * 100);

    // Clean up resources
    free(keys);
    free(records);
    poolManager->dealloc(keyBlock);
    poolManager->dealloc(recordBlock);

    return 0;
}

