        return NULL;
    }
    pool->totalAllocated = 0;
    pool->freeMemory = 0;
    pool->utilization = 0.0;
    return pool;
}

void destroyMemoryPoolManager(struct MemoryPoolManagerImpl* pool) {
    free(pool);
}

void* alloc(struct MemoryPoolManagerImpl* pool, size_t size) {
    // Check if the requested size is within the maximum allowed size
    if (size > MAX_ALLOCATION_SIZE) {
        fprintf(stderr, "Requested allocation size exceeds maximum allowed size: %zu\n", size);
        return NULL;
    }

    // Allocate a new block of memory from the pool
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory from pool: %s\n", strerror(errno));
        return NULL;
    }

    // Update the total allocated and free memory in the pool
    pool->totalAllocated += size;
    pool->freeMemory -= size;

    // Update the utilization of the pool
    pool->utilization = (double)pool->totalAllocated / MAX_ALLOCATION_SIZE;

    return ptr;
}

void dealloc(struct MemoryPoolManagerImpl* pool, void* ptr) {
    // Check if the pointer is NULL or not within the pool
