class OAuthRecordManager {
public:
    // Constructor
    OAuthRecordManager(int numRecords, int keyRangeMin, int keyRangeMax) :
        numRecords_(numRecords),
        keyRangeMin_(keyRangeMin),
        keyRangeMax_(keyRangeMax)
    {
        // Initialize memory for the two arrays
        offsetArray_ = new long[numRecords];
        keyArray_ = new int[numRecords];

        // Initialize each record's value to a random number within the user-defined range
        for (int i = 0; i < numRecords; ++i) {
            offsetArray_[i] = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
            keyArray_[i] = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        }
    }

    // Destructor
    ~OAuthRecordManager() {
        delete[] offsetArray_;
        delete[] keyArray_;
    }

    // Get the value of a record given its index
    int getValue(int index) {
        return keyArray_[index];
    }

    // Set the value of a record given its index and new value
    void setValue(int index, int newValue) {
        keyArray_[index] = newValue;
    }

    // Get the offset of a record given its index
    long getOffset(int index) {
        return offsetArray_[index];
    }

    // Set the offset of a record given its index and new offset
    void setOffset(int index, long newOffset) {
        offsetArray_[index] = newOffset;
    }

private:
    int numRecords_;
    int keyRangeMin_;
    int keyRangeMax_;
    long* offsetArray_;
    int* keyArray_;
};
