    // Check if the amount is non-negative and within range
    if (amount < 0 || amount > MAX_AMOUNT) {
        fprintf(stderr, "Invalid transaction amount: %f\n", amount);
        return -1;
    }

    // Process the transaction amount and update its status accordingly
