void init_records(size_t num_records, struct MemoryPool* pool) {
    // Allocate memory for the three arrays: offsets, keys, and records
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    struct Record* records = (struct Record*)malloc(num_records * sizeof(struct Record));

    // Initialize the status indicator for each record to false
    for (size_t i = 0; i < num_records; i++) {
        records[i].status = false;
    }

