    struct AuxiliaryStructure* aux = (struct AuxiliaryStructure*)malloc(sizeof(struct AuxiliaryStructure));
    aux->records = records;
    aux->num_records = num_records;

    // Set the memory pool for managing the records
    pool->buffer = aux;
    pool->capacity = num_records * sizeof(struct Record);
    pool->used = 0;
}

