    if (aux->records[index].key == 0) {
        aux->records[index].status = true;
    } else {
        aux->records[index].status = false;
    }
}

// Define a function to handle concurrent access and potential race conditions
void update_record(struct MemoryPool* pool, size_t index) {
    struct AuxiliaryStructure* aux = (struct AuxiliaryStructure*)pool->buffer;
    // Acquire a lock on the record to prevent race conditions
    pthread_mutex_lock(&aux->records[index].lock);
    // Update the status indicator based on certain conditions during execution
    update_status(pool, index);
    // Release the lock on the record
    pthread_mutex_unlock(&aux->records[index].lock);
}

// Define a function to handle dynamic memory allocation and deallocation
void free_records(struct MemoryPool* pool) {
    struct AuxiliaryStructure* aux = (struct AuxiliaryStructure*)pool->buffer;
    // Free the memory allocated for the three arrays: offsets, keys, and records
    free(aux->offsets);
    free(aux->keys);
    free(aux->records);
}
