// Define the structure for each vector
typedef struct {
    double *data;
    int size;
    int capacity;
    bool status;
} Vector;

// Define the structure for the auxiliary data structure
typedef struct {
    Vector **vectors;
    int num_vectors;
    pthread_mutex_t mutex;
} AuxiliaryData;

// Function to dynamically manage memory for vectors
void *manageMemory(void *args) {
    // Cast the arguments to the correct type
    AuxiliaryData *aux = (AuxiliaryData *) args;

    // Loop until a signal is received to stop
    while (1) {
        // Lock the mutex to access the vectors
        pthread_mutex_lock(&aux->mutex);

        // Check if there are any pending updates to the vectors
        for (int i = 0; i < aux->num_vectors; i++) {
            Vector *vector = aux->vectors[i];

            // If the vector is marked as updated, update its elements and reset the status indicator
            if (vector->status) {
                for (int j = 0; j < vector->size; j++) {
                    vector->data[j] = rand() % 100 + 1;
                }
                vector->status = false;
            }
        }

        // Unlock the mutex and wait for a signal to continue
        pthread_mutex_unlock(&aux->mutex);
        pthread_cond_wait(&aux->cond, &aux->mutex);
    }
}

// Function to create a new vector with random elements
Vector *createVector(int size) {
    // Allocate memory for the vector and its data
    Vector *vector = (Vector *) malloc(sizeof(Vector));
    vector->data = (double *) malloc(size * sizeof(double));

    // Initialize the vector's fields
    vector->size = size;
    vector->capacity = size;
    vector->status = false;

    // Fill the vector with random elements
    for (int i = 0; i < size; i++) {
        vector->data[i] = rand() % 100 + 1;
    }

    return vector;
}

// Function to update a vector's elements with new values
void updateVector(Vector *vector, int start, int end) {
    // Check if the vector is within bounds
    if (start < 0 || end > vector->size || start > end) {
        return;
    }

    // Update the vector's elements with new values
    for (int i = start; i <= end; i++) {
        vector->data[i] = rand() % 100 + 1;
    }
}

// Function to delete a vector and free its memory
void deleteVector(Vector *vector) {
    // Check if the vector is null
    if (vector == NULL) {
        return;
    }

    // Free the vector's data and the vector itself
    free(vector->data);
    free(vector);
}

// Function to add a new vector to the auxiliary data structure
void addVector(AuxiliaryData *aux, Vector *vector) {
    // Check if the auxiliary data structure is null or if the vector is null
    if (aux == NULL || vector == NULL) {
        return;
    }

    // Lock the mutex to access the vectors
    pthread_mutex_lock(&aux->mutex);

    // Increase the number of vectors and allocate memory for the new vector
    aux->num_vectors++;
    Vector **new_vectors = (Vector **) realloc(aux->vectors, aux->num_vectors * sizeof(Vector *));
    if (new_vectors == NULL) {
        pthread_mutex_unlock(&aux->mutex);
        return;
    }
    aux->vectors = new_vectors;
    aux->vectors[aux->num_vectors - 1] = vector;

    // Unlock the mutex and signal the condition variable to continue
    pthread_mutex_unlock(&aux->mutex);
    pthread_cond_signal(&aux->cond);
}

// Function to remove a vector from the auxiliary data structure
void removeVector(AuxiliaryData *aux, int index) {
    // Check if the auxiliary data structure is null or if the index is out of bounds
    if (aux == NULL || index < 0 || index >= aux->num_vectors) {
        return;
    }

    // Lock the mutex to access the vectors
    pthread_mutex_lock(&aux->mutex);

    // Decrease the number of vectors and free the memory for the removed vector
    aux->num_vectors--;
    Vector **new_vectors = (Vector **) realloc(aux->vectors, aux->num_vectors * sizeof(Vector *));
    if (new_vectors == NULL) {
        pthread_mutex_unlock(&aux->mutex);
        return;
    }
    aux->vectors = new_vectors;

    // Free the removed vector's data and the vector itself
    Vector *removed_vector = aux->vectors[index];
    free(removed_vector->data);
    free(removed_vector);

    // Unlock the mutex and signal the condition variable to continue
    pthread_mutex_unlock(&aux->mutex);
    pthread_cond_signal(&aux->cond);
}

// Function to update a vector's status indicator
void updateStatus(AuxiliaryData *aux, int index) {
    // Check if the auxiliary data structure is null or if the index is out of bounds
    if (aux == NULL || index < 0 || index >= aux->num_vectors) {
        return;
    }

    // Lock the mutex to access the vectors
    pthread_mutex_lock(&aux->mutex);

    // Update the vector's status indicator and signal the condition variable to continue
    aux->vectors[index]->status = true;
    pthread_cond_signal(&aux->cond);

    // Unlock the mutex
    pthread_mutex_unlock(&aux->mutex);
}
