// Custom DataPoint structure
typedef struct {
    time_t timestamp;
    bool status;
    double measurement;
} DataPoint;

// Function to manage memory for an array of DataPoints
void initializeDataPoints(DataPoint** data, int* num_data) {
    // Open file containing data
    FILE* fp = fopen("data.txt", "r");
    if (fp == NULL) {
        printf("Error: unable to open file\n");
        return;
    }

    // Initialize array of DataPoints and number of elements
    *data = malloc(sizeof(DataPoint) * 100);
    *num_data = 0;

    // Read data from file and store in array
    while (fscanf(fp, "%lu %d %lf", &((*data)[*num_data].timestamp), &((*data)[*num_data].status), &((*data)[*num_data].measurement)) == 3) {
        // Check for duplicate entries and corrupted lines
        if ((*data)[*num_data].status != 0 && (*data)[*num_data].status != 1) {
            printf("Error: invalid status flag\n");
            continue;
        } else if ((*data)[*num_data].measurement < 0) {
            printf("Error: negative measurement value\n");
            continue;
        }

        // Increment number of elements in array
        (*num_data)++;
    }

    // Sort DataPoint array based on measurement values in ascending order
    quicksort(*data, *num_data);

    // Close file
    fclose(fp);
}

// Custom sorting algorithm for DataPoints based on measurement value
void quicksort(DataPoint* data, int num_data) {
    if (num_data <= 1) return;

    int pivot = partition(data, num_data);
    quicksort(data, pivot - 1);
    quicksort(data + pivot + 1, num_data - pivot - 1);
}

// Partition function for quicksort algorithm
int partition(DataPoint* data, int num_data) {
    DataPoint pivot = data[num_data / 2];
    int i = 0;
    int j = num_data - 1;

    while (i < j) {
        while (data[i].measurement <= pivot.measurement && i < num_data) i++;
        while (data[j].measurement > pivot.measurement && j >= 0) j--;
        if (i < j) swap(&data[i], &data[j]);
    }

    return i;
}

// Swap function for quicksort algorithm
void swap(DataPoint* a, DataPoint* b) {
    DataPoint temp = *a;
    *a = *b;
    *b = temp;
}
```
