#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

// Define the DataPoint structure
typedef struct {
    time_t timestamp;
    bool status;
    double measurement;
} DataPoint;

// Function to initialize and sort a DataPoint array
DataPoint* initAndSort(int numSources, int *sourceUpdateFreqs, char **sourceFileNames) {
    // Allocate memory for the DataPoint array
    DataPoint *dataPoints = (DataPoint *)malloc(numSources * sizeof(DataPoint));
    assert(dataPoints != NULL);

    // Initialize each DataPoint with data from external sources
    for (int i = 0; i < numSources; i++) {
        // Read data from the current source file
        FILE *file = fopen(sourceFileNames[i], "r");
        assert(file != NULL);

        // Skip duplicate entries in the file
        int numDuplicates = 0;
        while (fscanf(file, "%d %d %lf", &dataPoints[i].timestamp, &dataPoints[i].status, &dataPoints[i].measurement) == 3) {
            if (numDuplicates > 0 && dataPoints[i - numDuplicates].timestamp == dataPoints[i].timestamp &&
                    dataPoints[i - numDuplicates].status == dataPoints[i].status &&
                    dataPoints[i - numDuplicates].measurement == dataPoints[i].measurement) {
                numDuplicates++;
            } else {
                break;
            }
        }

        // Update the number of duplicates in the current source file
        sourceUpdateFreqs[i] -= numDuplicates;

        // Close the current source file
        fclose(file);
    }

    // Sort the DataPoint array based on the measurement values in ascending order
    qsort(dataPoints, numSources - sourceUpdateFreqs[0], sizeof(DataPoint), compareDataPoints);

    return dataPoints;
}

// Comparison function for sorting DataPoint arrays
int compareDataPoints(const void *a, const void *b) {
    DataPoint *da = (DataPoint *)a;
    DataPoint *db = (DataPoint *)b;
    if (da->measurement < db->measurement) {
        return -1;
    } else if (da->measurement > db->measurement) {
        return 1;
    } else {
        return 0;
    }
}
