// Define the record structure
typedef struct {
    int value;
    char* text;
} record;

// Define the function to populate the records array with unique random values within a specified range
int populate_records(record** records, long budget) {
    // Initialize variables
    bool success = true;
    long total_memory = 0;
    int num_keys = 0;
    int* keys = NULL;
    record* new_record = NULL;

    // Allocate memory for the keys array
    keys = (int*)malloc(sizeof(int) * budget);
    if (!keys) {
        success = false;
        goto cleanup;
    }

    // Initialize the keys array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < budget; i++) {
        int key = rand() % 1000000;
        if (!contains_key(keys, num_keys, key)) {
            keys[num_keys++] = key;
        } else {
            // Retry the assignment until a unique key is found
            i--;
        }
    }

    // Allocate memory for the records array
    *records = (record*)malloc(sizeof(record) * num_keys);
    if (!*records) {
        success = false;
        goto cleanup;
    }

    // Populate the records array with random values and descriptive text
    for (int i = 0; i < num_keys; i++) {
        new_record = &(*records)[i];
        new_record->value = rand() % 1000000;
        new_record->text = (char*)malloc(256 * sizeof(char));
        if (!new_record->text) {
            success = false;
            goto cleanup;
        }
        sprintf(new_record->text, "Random text %d", i);
    }

cleanup:
    // Free any allocated memory
    free(keys);
    if (!success) {
        for (int i = 0; i < num_keys; i++) {
            record* current_record = &(*records)[i];
            free(current_record->text);
        }
        free(*records);
    }

    // Return the status and result structure
    return success ? 0 : -1;
}

// Check if a key is already present in an array of keys
bool contains_key(int* keys, int num_keys, int key) {
    for (int i = 0; i < num_keys; i++) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}
```
