#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a struct for data points
typedef struct {
    double value;
    char label;
    size_t index;
} data_point;

// Function to dynamically allocate memory for arrays of 'double', 'char', and 'data_point' elements
void* allocate_arrays(size_t num_doubles, size_t num_chars, size_t num_data_points) {
    // Calculate the total size of the arrays in bytes
    size_t total_size = (num_doubles * sizeof(double)) + (num_chars * sizeof(char)) + (num_data_points * sizeof(data_point));

    // Check if the total size exceeds the maximum allowed size
    if (total_size > MAX_ALLOCATION_SIZE) {
        fprintf(stderr, "Error: Total allocation size exceeds maximum allowed size\n");
        return NULL;
    }

    // Allocate memory for the arrays
    void* mem = malloc(total_size);
    if (!mem) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays\n");
        return NULL;
    }

    // Initialize the 'double' array
    double* doubles = (double*)mem;
    mem += num_doubles * sizeof(double);

    // Initialize the 'char' array
    char* chars = (char*)mem;
    mem += num_chars * sizeof(char);

    // Initialize the 'data_point' array
    data_point* data_points = (data_point*)mem;
    mem += num_data_points * sizeof(data_point);

    // Set the pointers to the beginning of each array
    double* doubles_ptr = doubles;
    char* chars_ptr = chars;
    data_point* data_points_ptr = data_points;

    // Initialize the arrays with default values
    for (size_t i = 0; i < num_doubles; i++) {
        *(doubles_ptr + i) = 0.0;
    }
    for (size_t i = 0; i < num_chars; i++) {
        *(chars_ptr + i) = '\0';
    }
    for (size_t i = 0; i < num_data_points; i++) {
        data_points_ptr[i].value = 0.0;
        data_points_ptr[i].label = '\0';
        data_points_ptr[i].index = 0;
    }

    // Return a pointer to the beginning of the allocated memory
    return mem;
}
```
