#define MAX_PATH_LENGTH 4096
#define MAX_FILE_COUNT 5000
#define CHECKSUM_ALGORITHM "sha256"

struct file_info {
    char* path;
    size_t size;
    struct checksum checksum;
};

struct directory_info {
    char* path;
    int file_count;
    int dir_count;
};

struct checksum {
    unsigned char hash[32];
    time_t timestamp;
};

void process_file(char* path, struct file_info* info) {
    // Open the file and calculate its size
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file size");
        close(fd);
        return;
    }

    info->size = st.st_size;

    // Calculate the checksum of the file
    unsigned char hash[32];
    if (hash_file(path, CHECKSUM_ALGORITHM, hash) == -1) {
        perror("Failed to calculate checksum");
        close(fd);
        return;
    }

    info->checksum.timestamp = time(NULL);
    memcpy(info->checksum.hash, hash, 32);

    // Close the file
    close(fd);
}

void process_directory(char* path, struct directory_info* info) {
    // Open the directory and get its contents
    DIR* dir = opendir(path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    int file_count = 0;
    int dir_count = 0;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (filename[0] == '.') continue; // Skip hidden files

        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, MAX_PATH_LENGTH, "%s/%s", path, filename);

        struct stat st;
        if (stat(full_path, &st) == -1) {
            perror("Failed to get file status");
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            dir_count++;
        } else {
            file_count++;
        }
    }

    info->file_count = file_count;
    info->dir_count = dir_count;

    // Close the directory
    closedir(dir);
}

void process_paths(char** paths, int path_count) {
    struct file_info* files = malloc(path_count * sizeof(struct file_info));
    if (files == NULL) {
        perror("Failed to allocate memory for file information");
        return;
    }

    struct directory_info* dirs = malloc(path_count * sizeof(struct directory_info));
    if (dirs == NULL) {
        perror("Failed to allocate memory for directory information");
        free(files);
        return;
    }

    // Process each path and store the results in the arrays
    for (int i = 0; i < path_count; i++) {
        char* path = paths[i];
        struct stat st;
        if (stat(path, &st) == -1) {
            perror("Failed to get file status");
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            process_directory(path, dirs + i);
        } else {
            process_file(path, files + i);
        }
    }

    // Log the results to a file for auditing purposes
    FILE* log = fopen("log.txt", "a");
    if (log == NULL) {
        perror("Failed to open log file");
        free(files);
        free(dirs);
        return;
    }

    // Write the results to the log file
    for (int i = 0; i < path_count; i++) {
        char* path = paths[i];
        struct stat st;
        if (stat(path, &st) == -1) {
            perror("Failed to get file status");
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            fprintf(log, "Directory: %s\n", path);
            struct directory_info* dir = dirs + i;
            fprintf(log, "\tFiles: %d\n", dir->file_count);
            fprintf(log, "\tDirectories: %d\n", dir->dir_count);
        } else {
            fprintf(log, "File: %s\n", path);
            struct file_info* file = files + i;
            fprintf(log, "\tSize: %lu\n", (unsigned long)file->size);
            fprintf(log, "\tChecksum: %s\n", hash_to_string(file->checksum.hash));
        }
    }

    // Close the log file
    fclose(log);

    free(files);
    free(dirs);
}

int main() {
    char** paths = NULL;
    int path_count = 0;

    while (1) {
        char* path = readline("Enter a file or directory path: ");
        if (path == NULL) break; // Exit the loop when no more input is available

        // Add the path to the array of paths
        paths = realloc(paths, (path_count + 1) * sizeof(char*));
        if (paths == NULL) {
            perror("Failed to allocate memory for file paths");
            return 1;
        }
        paths[path_count++] = path;
    }

    process_paths(paths, path_count);

    // Free the array of paths
    for (int i = 0; i < path_count; i++) {
        free(paths[i]);
    }
    free(paths);

    return 0;
}
