#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom SafeInt data type
typedef struct {
    int value;
} SafeInt;

// Record structure for storing key-value pairs
typedef struct record_t {
    SafeInt key;
    SafeInt value;
    struct record_t *next;
    struct record_t *prev;
} Record;

// Memory pool for allocating and deallocating nodes
static Record* memory_pool = NULL;

// Doubly linked list for storing records
static Record* head = NULL;
static Record* tail = NULL;

// Function to initialize the memory pool and doubly linked list
void init() {
    // Allocate memory for the memory pool
    memory_pool = (Record*) malloc(sizeof(Record) * 100);

    // Initialize the head and tail pointers
    head = NULL;
    tail = NULL;
}

// Function to insert a new record into the doubly linked list
void insert(SafeInt key, SafeInt value) {
    Record* node = (Record*) malloc(sizeof(Record));
    node->key = key;
    node->value = value;
    node->next = NULL;
    node->prev = NULL;

    // If the list is empty, set the head and tail pointers to the new node
    if (head == NULL) {
        head = node;
        tail = node;
    } else {
        // Insert the new node at the end of the list
        tail->next = node;
        node->prev = tail;
        tail = node;
    }
}

// Function to update a record in the doubly linked list
void update(SafeInt key, SafeInt value) {
    Record* node = find_node(key);
    if (node != NULL) {
        // Update the value of the existing node
        node->value += value;
    } else {
        // Insert a new node with the given key and value
        insert(key, value);
    }
}

// Function to find a record in the doubly linked list by its key
Record* find_node(SafeInt key) {
    Record* node = head;
    while (node != NULL) {
        if (node->key == key) {
            return node;
        }
        node = node->next;
    }
    return NULL;
}

// Function to traverse the doubly linked list and update records with duplicate keys
void update_duplicates(SafeInt* input, int size) {
    Record* node = head;
    while (node != NULL) {
        // Check if the current node has a duplicate key in the input array
        for (int i = 0; i < size; i++) {
            if (node->key == input[i]) {
                // Update the value of the existing node with the sum of the input value and the existing record value
                node->value += input[i];
                break;
            }
        }
        node = node->next;
    }
}

// Function to reverse the order of the doubly linked list in place without using additional data structures
void reverse() {
    Record* current = head;
    Record* previous = NULL;
    while (current != NULL) {
        Record* next = current->next;
        current->next = previous;
        if (previous == NULL) {
            tail = current;
        }
        previous = current;
        current = next;
    }
    head = previous;
}

// Function to free the memory allocated for the doubly linked list and the memory pool
void destroy() {
    Record* node = head;
    while (node != NULL) {
        Record* next = node->next;
        free(node);
        node = next;
    }
    free(memory_pool);
}
