#define MAX_VALUE INT_MAX

typedef struct {
    int *array;
    size_t capacity;
    size_t count;
} IntArray;

void handle_signal(int signum) {
    // Handle signal gracefully
}

IntArray* read_input() {
    IntArray *array = malloc(sizeof(IntArray));
    if (array == NULL) {
        perror("Failed to allocate memory for input array");
        return NULL;
    }
    array->capacity = 1024;
    array->count = 0;
    array->array = malloc(sizeof(int) * array->capacity);
    if (array->array == NULL) {
        perror("Failed to allocate memory for input array");
        free(array);
        return NULL;
    }
    char buffer[MAX_INPUT_SIZE];
    while (fgets(buffer, MAX_INPUT_SIZE, stdin)) {
        int value = atoi(buffer);
        if (value < MIN_VALUE || value > MAX_VALUE) {
            perror("Invalid input");
            continue;
        }
        if (array->count == array->capacity) {
            array->capacity *= 2;
            int *new_array = realloc(array->array, sizeof(int) * array->capacity);
            if (new_array == NULL) {
                perror("Failed to allocate memory for input array");
                free(array->array);
                free(array);
                return NULL;
            }
            array->array = new_array;
        }
        array->array[array->count++] = value;
    }
    return array;
}

int find_largest(IntArray *array) {
    int largest = INT_MIN;
    for (size_t i = 0; i < array->count; i++) {
        if (array->array[i] > largest) {
            largest = array->array[i];
        }
    }
    return largest;
}

void print_largest(IntArray *array) {
    printf("%d\n", find_largest(array));
}

int main() {
    signal(SIGINT, handle_signal);
    IntArray *array = read_input();
    if (array == NULL) {
        perror("Failed to read input");
        return 1;
    }
    print_largest(array);
    free(array->array);
    free(array);
    return 0;
}
