    double sum = 0.0;
    for (int i = 0; i < num_records; i++) {
        sum += values[i];
    }
    printf("Average value: %f\n", sum / num_records);

    // Free the dynamically allocated memory to avoid resource leaks
    free(records);
    free(keys);
    free(values);
}
