// Define the function to add nodes to the linked list
void add_node(struct node* head, struct node* tail, int value) {
    // Create a new node with the given value
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
