    new_node->value = value;
    new_node->next = NULL;

    // Lock the list before modifying it
    pthread_mutex_lock(&list_mutex);

    // Add the new node to the end of the list
    if (head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    // Unlock the list after modifying it
    pthread_mutex_unlock(&list_mutex);
}

// Define the function to distribute task entries across multiple worker threads
void distribute_tasks(struct task_entry* tasks, int num_tasks) {
    // Create a custom balancing algorithm that distributes task entries across multiple worker threads
    // This algorithm should optimize for load balancing and minimize idle time

    // Define the variables to keep track of the current task entry and the number of tasks assigned to each worker thread
    struct task_entry* current_task = tasks;
    int num_tasks_per_thread[num_threads];

    // Initialize the number of tasks assigned to each worker thread to 0
    for (int i = 0; i < num_threads; i++) {
        num_tasks_per_thread[i] = 0;
    }

    // Loop through all task entries and assign them to worker threads based on the current load balancing strategy
    while (current_task != NULL) {
        // Find the worker thread with the least number of tasks assigned to it
        int min_num_tasks = INT_MAX;
        int min_thread_index = -1;
        for (int i = 0; i < num_threads; i++) {
            if (num_tasks_per_thread[i] < min_num_tasks) {
                min_num_tasks = num_tasks_per_thread[i];
                min_thread_index = i;
            }
        }

        // Assign the current task entry to the worker thread with the least number of tasks assigned to it
        add_task(min_thread_index, current_task);
        num_tasks_per_thread[min_thread_index]++;

        // Move on to the next task entry
        current_task = current_task->next;
    }
}

