```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Custom memory pool manager
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used; // Amount of memory currently in use
    void* blocks[]; // Array of memory blocks
};

// Function to allocate a new memory block
void* allocate(size_t size) {
    struct MemoryPool* pool = get_pool();
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* block = malloc(size);
    if (!block) {
        return NULL;
    }
    pool->used += size;
    return block;
}

// Function to deallocate a memory block
void deallocate(void* block) {
    struct MemoryPool* pool = get_pool();
    if (block == NULL || pool->used == 0) {
        return;
    }
    size_t index = 0;
    while (index < pool->capacity && pool->blocks[index] != block) {
        index++;
    }
    if (index == pool->capacity) {
        return;
    }
    pool->used -= get_size(block);
}

// Function to coalesce adjacent free blocks
void coalesce() {
    struct MemoryPool* pool = get_pool();
    size_t index = 0;
    while (index < pool->capacity) {
        if (pool->blocks[index] == NULL) {
            // Skip over NULL blocks
            index++;
            continue;
        }
        size_t next_index = index + 1;
        while (next_index < pool->capacity && pool->blocks[next_index] == NULL) {
            next_index++;
        }
        if (next_index == pool->capacity) {
            // Reached the end of the array without finding a free block
            break;
        }
        size_t size = get_size(pool->blocks[index]);
        void* block = pool->blocks[index];
        pool->blocks[index] = NULL;
        pool->used -= size;
        index = next_index;
    }
}

// Function to register a memory block with the memory pool manager
void register_block(void* block) {
    struct MemoryPool* pool = get_pool();
    if (pool->used + get_size(block) > pool->capacity) {
        return;
    }
    size_t index = 0;
    while (index < pool->capacity && pool->blocks[index] != NULL) {
        index++;
    }
    if (index == pool->capacity) {
        return;
    }
    pool->blocks[index] = block;
    pool->used += get_size(block);
}

// Function to unregister a memory block from the memory pool manager
void unregister_block(void* block) {
    struct MemoryPool* pool = get_pool();
    size_t index = 0;
    while (index < pool->capacity && pool->blocks[index] != block) {
        index++;
    }
    if (index == pool->capacity) {
        return;
    }
    pool->blocks[index] = NULL;
    pool->used -= get_size(block);
}

// Function to initialize the memory pool manager
void init_pool() {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return;
    }
    pool->capacity = 1024 * 1024; // 1 MB
    pool->used = 0;
    pool->blocks = malloc(pool->capacity * sizeof(void*));
    if (!pool->blocks) {
        free(pool);
        return;
    }
}

// Function to get the memory pool manager
struct MemoryPool* get_pool() {
    static struct MemoryPool* pool = NULL;
    if (pool == NULL) {
        init_pool();
    }
    return pool;
}

// Function to set the value of each record's int field to a random value within a specified range
void populate_records(int lower, int upper) {
    struct MemoryPool* pool = get_pool();
    size_t index = 0;
    while (index < pool->capacity) {
        if (pool->blocks[index] == NULL) {
            // Skip over NULL blocks
            index++;
            continue;
        }
        struct record* record = pool->blocks[index];
        record->int_field = rand() % (upper - lower + 1) + lower;
        index++;
    }
}
