        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    // Initialize the record with the allocated data and offset
    record->offset = (long)data - (long)pool->data;
    record->key = current_time;

    // Unlock the mutex to allow other threads to access the memory pools
    pthread_mutex_unlock(&manager->mutex);

    return data;
}

// Define the function to deallocate a record and free its allocated memory
void deallocate_record(Record* record) {
    // Get the current time in milliseconds
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long current_time = (long)tv.tv_sec * 1000 + (long)tv.tv_usec / 1000;

    // Get the memory pool manager instance
    MemoryPoolManager* manager = get_memory_pool_manager();

    // Lock the mutex to prevent concurrent access to the memory pools
    pthread_mutex_lock(&manager->mutex);

    // Find the memory pool that contains the record's allocated data
    MemoryPool* pool = find_pool(record, manager);

    // Free the record's allocated data and update the pool's statistics
    free((void*)((long)pool->data + record->offset));
    pool->size -= size;

    // Unlock the mutex to allow other threads to access the memory pools
    pthread_mutex_unlock(&manager->mutex);
}

// Define the function to find the best memory pool for a new record based on current workload patterns
MemoryPool* find_best_pool(Record* record, size_t size, MemoryPoolManager* manager) {
    // Iterate over all memory pools and find the one with the lowest utilization
    MemoryPool* best_pool = NULL;
    for (int i = 0; i < manager->num_pools; i++) {
        if (best_pool == NULL || manager->pools[i]->size < best_pool->size) {
            best_pool = manager->pools[i];
        }
    }

    // If no pool is found, create a new one with the specified size
    if (best_pool == NULL) {
        MemoryPool* new_pool = malloc(sizeof(MemoryPool));
        new_pool->size = size;
        new_pool->data = malloc(new_pool->size);
        new_pool->mutex = PTHREAD_MUTEX_INITIALIZER;
        manager->pools[manager->num_pools++] = new_pool;
        best_pool = new_pool;
    }

    return best_pool;
}

// Define the function to find the memory pool that contains a record's allocated data
MemoryPool* find_pool(Record* record, MemoryPoolManager* manager) {
    // Iterate over all memory pools and find the one that contains the record's allocated data
    for (int i = 0; i < manager->num_pools; i++) {
        if ((long)manager->pools[i]->data <= record->offset &&
            (long)manager->pools[i]->data + manager->pools[i]->size > record->offset) {
            return manager->pools[i];
        }
    }

    // If no pool is found, return NULL
    return NULL;
}

// Define the function to get the memory pool manager instance
MemoryPoolManager* get_memory_pool_manager() {
    static MemoryPoolManager manager = {NULL, 0};
    if (manager.pools == NULL) {
        manager.pools = malloc(sizeof(MemoryPool*) * INITIAL_NUM_POOLS);
        manager.num_pools = 0;
    }
    return &manager;
}
