#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define the task structure
typedef struct {
    char *name;
    double priority;
    int deadline;
} Task;

// Define the task collection data structure
typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} TaskCollection;

// Initialize a new task collection with a given capacity
TaskCollection *task_collection_init(size_t capacity) {
    TaskCollection *tc = malloc(sizeof(TaskCollection));
    tc->tasks = calloc(capacity, sizeof(Task *));
    tc->capacity = capacity;
    tc->count = 0;
    pthread_mutex_init(&tc->mutex, NULL);
    return tc;
}

// Add a new task to the collection
void task_collection_add(TaskCollection *tc, Task *task) {
    // Acquire lock on mutex
    pthread_mutex_lock(&tc->mutex);

    // Check if there is enough capacity for the new task
    if (tc->count >= tc->capacity) {
        // Reallocate memory for tasks array to double its size
        tc->tasks = realloc(tc->tasks, 2 * tc->capacity * sizeof(Task *));
        tc->capacity *= 2;
    }

    // Add the new task to the end of the tasks array
    tc->tasks[tc->count++] = task;

    // Release lock on mutex
    pthread_mutex_unlock(&tc->mutex);
}

// Remove a task from the collection by its index
void task_collection_remove(TaskCollection *tc, size_t index) {
    // Acquire lock on mutex
    pthread_mutex_lock(&tc->mutex);

    // Check if the index is valid
    if (index >= tc->count) {
        printf("Error: Index %zu out of bounds\n", index);
        return;
    }

    // Shift tasks after the removed task to fill the gap
    for (size_t i = index + 1; i < tc->count; i++) {
        tc->tasks[i - 1] = tc->tasks[i];
    }

    // Decrement the count of tasks
    tc->count--;

    // Release lock on mutex
    pthread_mutex_unlock(&tc->mutex);
}

// Adjust the priority of a task in the collection by its index
void task_collection_adjust_priority(TaskCollection *tc, size_t index, double new_priority) {
    // Acquire lock on mutex
    pthread_mutex_lock(&tc->mutex);

    // Check if the index is valid
    if (index >= tc->count) {
        printf("Error: Index %zu out of bounds\n", index);
        return;
    }

    // Update the priority of the task at the given index
    tc->tasks[index]->priority = new_priority;

    // Release lock on mutex
    pthread_mutex_unlock(&tc->mutex);
}

// Free the memory allocated for a task collection
void task_collection_free(TaskCollection *tc) {
    // Acquire lock on mutex
    pthread_mutex_lock(&tc->mutex);

    // Release memory for tasks array
    free(tc->tasks);

    // Release memory for the task collection struct
    free(tc);

    // Release lock on mutex
    pthread_mutex_unlock(&tc->mutex);
}
```
