    for (int i = 0; i < size; i++) {
        data_points[i].value = MIN_FLOATING_POINT_VALUE + ((double)rand() / RAND_MAX) * (MAX_FLOATING_POINT_VALUE - MIN_FLOATING_POINT_VALUE);
    }
    // Implement a custom hash function to efficiently map data points to memory blocks within the memory pool
    for (int i = 0; i < size; i++) {
        void* block = allocate_memory(pool, sizeof(struct DataPoint));
        if (!block) {
            printf("Failed to allocate memory for data point %d\n", i);
            return;
        }
        memcpy(block, &data_points[i], sizeof(struct DataPoint));
    }
    // Implement a mechanism to track the age of each data point and automatically remove the oldest data point if the memory pool exceeds a specified maximum size
    int max_age = 0;
    for (int i = 0; i < size; i++) {
