        if (data_point->value > MAX_FLOATING_POINT_VALUE) {
            max_age++;
        } else {
            max_age = 0;
        }
        if (max_age > MAX_AGE) {
            deallocate_memory(pool, block);
            break;
        }
    }
    // Implement robust error handling for all memory allocations and deallocations
    if (!data_points || !pool) {
        printf("Failed to allocate memory for data points or create memory pool\n");
        return;
    }
    // Optimize the function for performance by minimizing the number of memory allocations and deallocations
    coalesce_free_blocks(pool);
    // Ensure thread safety by implementing synchronization mechanisms that minimize contention, focusing on scalability under high concurrency
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    for (int i = 0; i < size; i++) {
        struct DataPoint* data_point = (struct DataPoint*)block;
        if (data_point->value > MAX_FLOATING_POINT_VALUE) {
            pthread_mutex_lock(&mutex);
            while (!pthread_cond_wait(&cond, &mutex)) {
                deallocate_memory(pool, block);
                break;
            }
            pthread_mutex_unlock(&mutex);
        }
    }
    // Provide a mechanism to report comprehensive memory usage statistics, including total allocated memory, free memory, and memory pool utilization
    printf("Total allocated memory: %zu\n", size * sizeof(struct DataPoint));
