    Task* tasks;
    size_t capacity;
    size_t count;
} TaskList;

// Initialize the list with a specified number of tasks and default priority
TaskList* init_task_list(size_t num_tasks) {
    TaskList* list = malloc(sizeof(TaskList));
    if (!list) {
        return NULL;
    }
    list->tasks = malloc(num_tasks * sizeof(Task));
    if (!list->tasks) {
        free(list);
        return NULL;
    }
    list->capacity = num_tasks;
    list->count = 0;
    for (size_t i = 0; i < num_tasks; i++) {
        list->tasks[i].priority = DEFAULT_PRIORITY;
        list->tasks[i].status = malloc(MAX_STATUS_LENGTH);
        if (!list->tasks[i].status) {
            free(list->tasks);
            free(list);
            return NULL;
        }
    }
    return list;
}

// Add a new task to the list with specified priority and status
void add_task(TaskList* list, int priority, const char* status) {
    if (list->count == list->capacity) {
        // Dynamically resize the list if necessary
        size_t new_capacity = list->capacity * 2;
        Task* new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) {
            return;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
    list->tasks[list->count].priority = priority;
    strncpy(list->tasks[list->count].status, status, MAX_STATUS_LENGTH);
    list->count++;
}

// Remove a task from the list by its index
void remove_task(TaskList* list, size_t index) {
    if (index >= list->count) {
        return;
    }
    Task* tasks = list->tasks;
    for (size_t i = index + 1; i < list->count; i++) {
        tasks[i - 1] = tasks[i];
    }
    list->count--;
}

// Free the memory allocated to the list
void free_task_list(TaskList* list) {
    if (!list) {
        return;
    }
    for (size_t i = 0; i < list->count; i++) {
        free(list->tasks[i].status);
    }
    free(list->tasks);
    free(list);
}
