// Define the memory allocation function for records
void* record_alloc(size_t size) {
    struct record_pool_manager* manager = get_record_pool_manager();
    struct record_pool* pool = manager->pools[0];
    pthread_mutex_lock(&manager->lock);
    if (pool->count < pool->capacity) {
        void* data = &pool->data[pool->count++];
        pthread_mutex_unlock(&manager->lock);
        return data;
    } else {
        // If the pool is full, allocate a new pool and add it to the manager
        struct record_pool* new_pool = malloc(sizeof(struct record_pool));
        new_pool->capacity = size;
        new_pool->count = 0;
        new_pool->data = malloc(size * sizeof(record_t));
        manager->pools = realloc(manager->pools, (manager->num_pools + 1) * sizeof(struct record_pool*));
        manager->pools[manager->num_pools++] = new_pool;
        pthread_mutex_unlock(&manager->lock);
        return &new_pool->data[0];
    }
}

