void* nfapi_crc_indication_pdu_alloc(size_t size) {
    struct nfapi_crc_indication_pdu_pool_manager* manager = get_nfapi_crc_indication_pdu_pool_manager();
    struct nfapi_crc_indication_pdu_pool* pool = manager->pools[0];
