// Define the memory deallocation function for records
void record_free(void* data) {
    struct record_pool_manager* manager = get_record_pool_manager();
    pthread_mutex_lock(&manager->lock);
    // Find the pool that contains the given data and decrement its count
    size_t i;
    for (i = 0; i < manager->num_pools; ++i) {
        struct record_pool* pool = manager->pools[i];
        if (data >= pool->data && data < &pool->data[pool->capacity]) {
            --pool->count;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    // If the data is not found in any pool, free it and remove it from the manager
    free(data);
    for (i = 0; i < manager->num_pools; ++i) {
        struct record_pool* pool = manager->pools[i];
        if (pool->data == data) {
            --manager->num_pools;
            free(pool);
            break;
