#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define a structure to hold project information
typedef struct {
    int priority;
    char *status;
    Owner owner;
} Project;

// Define a structure to hold owner information
typedef struct {
    char *name;
    char *email;
} Owner;

// Define a function to initialize the list of projects
void init_projects(int num_projects, int default_priority) {
    // Allocate memory for the list of projects
    Project **projects = malloc(num_projects * sizeof(Project*));
    assert(projects != NULL);

    // Initialize each project with a default priority and allocate space for status strings
    for (int i = 0; i < num_projects; i++) {
        projects[i] = malloc(sizeof(Project));
        assert(projects[i] != NULL);
        projects[i]->priority = default_priority;
        projects[i]->status = malloc(1024 * sizeof(char)); // 1024 is the maximum length of a status string
        assert(projects[i]->status != NULL);
    }

    // Set the number of projects to the specified value
    num_projects = num_projects;
}

// Define a function to add a new project to the list
void add_project(Project *new_project) {
    // Check if the list is empty and initialize it if necessary
    if (num_projects == 0) {
        init_projects(1, new_project->priority);
    } else {
        // Allocate memory for the new project and add it to the end of the list
        Project **new_projects = realloc(projects, (num_projects + 1) * sizeof(Project*));
        assert(new_projects != NULL);
        projects = new_projects;
        projects[num_projects] = malloc(sizeof(Project));
        assert(projects[num_projects] != NULL);
        num_projects++;
    }

    // Copy the new project's information to the end of the list
    memcpy(projects[num_projects - 1], new_project, sizeof(Project));
}

// Define a function to update an existing project in the list
void update_project(int index, Project *updated_project) {
    // Check if the index is valid and the updated project has a priority
    if (index >= 0 && index < num_projects && updated_project->priority != -1) {
        // Update the project's priority and status
        projects[index]->priority = updated_project->priority;
        strcpy(projects[index]->status, updated_project->status);
    }
}

// Define a function to remove an existing project from the list
void remove_project(int index) {
    // Check if the index is valid and there are still projects left in the list
    if (index >= 0 && num_projects > 1) {
        // Remove the project at the specified index
        Project *removed_project = projects[index];
        memmove(projects + index, projects + index + 1, (num_projects - index - 1) * sizeof(Project*));
        num_projects--;

        // Free the memory used by the removed project
        free(removed_project);
    }
}

// Define a function to handle updates from an external data source
void update_from_external_source() {
    // Check if there are any projects in the list
    if (num_projects > 0) {
        // Update each project with information from the external data source
        for (int i = 0; i < num_projects; i++) {
            Project *project = projects[i];
            update_project(i, project);
        }
    }
}
