// Custom hash function for mapping data points to memory blocks within a memory pool
unsigned long customHash(void* data) {
    // Implement a custom hash function that takes into account the size of the memory pool and the number of data points
    unsigned long hash = 0;
    char* data_ptr = (char*)data;
