    manager->memory_blocks = (void**)calloc(memory_pool_size, sizeof(void*));
    manager->num_free_blocks = memory_pool_size;
    manager->memory_pool_size = memory_pool_size;
}

// Allocate a new memory block for a data point and return its address
void* allocateMemoryBlock(struct MemoryPoolManager* manager) {
    // Check if there are any free memory blocks available
    if (manager->num_free_blocks == 0) {
        // If not, expand the memory pool by a certain percentage to make room for more data points
        size_t new_memory_pool_size = manager->memory_pool_size * 1.2;
        void** new_memory_blocks = (void**)realloc(manager->memory_blocks, new_memory_pool_size);
        if (new_memory_blocks == NULL) {
            // If reallocation fails, return NULL to indicate allocation failure
            return NULL;
        }
        manager->memory_blocks = new_memory_blocks;
        manager->num_free_blocks += new_memory_pool_size - manager->memory_pool_size;
        manager->memory_pool_size = new_memory_pool_size;
    }
    // Return the address of the first free memory block
    return manager->memory_blocks[--manager->num_free_blocks];
}

// Deallocate a memory block for a data point and mark it as free
void deallocateMemoryBlock(struct MemoryPoolManager* manager, void* memory_block) {
    // Check if the given memory block is within the memory pool
    if (memory_block < manager->memory_blocks || memory_block >= manager->memory_blocks + manager->memory_pool_size) {
        // If not, return to indicate deallocation failure
        return;
    }
    // Mark the given memory block as free and update the number of free blocks
    manager->num_free_blocks++;
}

