        struct data_point** new_memory_blocks = (struct data_point**)realloc(manager->memory_blocks, new_memory_pool_size);
        if (new_memory_blocks == NULL) {
            // If reallocation fails, return NULL to indicate allocation failure
            return NULL;
        }
        manager->memory_blocks = new_memory_blocks;
        manager->num_free_blocks += new_memory_pool_size - manager->memory_pool_size;
        manager->memory_pool_size = new_memory_pool_size;
    }
    // Return the address of the first free memory block
    return manager->memory_blocks[--manager->num_free_blocks];
}

// Deallocate a memory block for a data point and mark it as free
void deallocateMemoryBlock(struct MemoryPoolManager* manager, void* memory_block) {
    // Check if the given memory block is within the memory pool
    if (memory_block < manager->memory_blocks || memory_block >= manager->memory_blocks + manager->memory_pool_size) {
        // If not, return to indicate deallocation failure
        return;
    }
    // Mark the given memory block as free and update the number of free blocks
    manager->num_free_blocks++;
}

// Coalesce adjacent free blocks for improved memory efficiency
void coalesceFreeBlocks(struct MemoryPoolManager* manager) {
    // Iterate over all memory blocks in the pool and check if they are free
    for (int i = 0; i < manager->memory_pool_size; i++) {
        struct data_point* memory_block = manager->memory_blocks[i];
        if (memory_block == NULL) {
            // If the memory block is free, check if it is adjacent to another free block
            int j = i + 1;
            while (j < manager->memory_pool_size && manager->memory_blocks[j] == NULL) {
                j++;
            }
            // If it is, coalesce the two blocks and update the number of free blocks accordingly
            if (j < manager->memory_pool_size) {
                manager->num_free_blocks += 2;
                manager->memory_blocks[i] = (struct data_point*)realloc(manager->memory_blocks[i], sizeof(struct data_point) + j - i);
            }
        }
    }
}

