void init_event_hierarchy(int max_depth, int event_limit, event_t **events) {
    // Check if the maximum depth is valid
    if (max_depth <= 0) {
        printf("Error: Maximum depth must be greater than zero\n");
        return;
    }

    // Check if the event limit per level is valid
    if (event_limit <= 0) {
        printf("Error: Event limit per level must be greater than zero\n");
        return;
    }

    // Allocate memory for the events array
    *events = malloc(sizeof(event_t *) * max_depth);
    if (*events == NULL) {
        printf("Error: Failed to allocate memory for events array\n");
        return;
    }

    // Initialize each event in the events array
    for (int i = 0; i < max_depth; i++) {
        (*events)[i] = malloc(sizeof(event_t));
        if ((*events)[i] == NULL) {
            printf("Error: Failed to allocate memory for event %d\n", i);
            return;
        }
        (*events)[i]->type = 0;
        (*events)[i]->message[0] = '\0';
        (*events)[i]->next = NULL;
    }

    // Recursively populate the events array with events
