        if (i == 0) {
            // If this is the first level, create a new event and set its type and message
            (*events)[i]->type = 1;
            strcpy((*events)[i]->message, "Root event");
        } else {
            // If this is not the first level, create a new event and set its type and message
            (*events)[i]->type = i + 1;
            sprintf((*events)[i]->message, "Event %d", i);
        }

        // If this is not the last level, create a new event and set its type and message
        if (i < max_depth - 1) {
            (*events)[i]->next = malloc(sizeof(event_t));
            if ((*events)[i]->next == NULL) {
                printf("Error: Failed to allocate memory for next event\n");
                return;
            }
            (*events)[i]->next->type = i + 2;
            sprintf((*events)[i]->next->message, "Next event %d", i);
        }
    }

    // Serialize the events hierarchy to a file in a specified format
    FILE *file = fopen("events.txt", "w");
    if (file == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
    }
    for (int i = 0; i < max_depth; i++) {
        fprintf(file, "%d %s", (*events)[i]->type, (*events)[i]->message);
        if ((*events)[i]->next != NULL) {
            fprintf(file, " %d %s", (*events)[i]->next->type, (*events)[i]->next->message);
        }
        fprintf(file, "\n");
    }
    fclose(file);
}

// Define the function to free memory for a hierarchical event structure
void cleanup_event_hierarchy(int max_depth, event_t **events) {
    // Check if the maximum depth is valid
    if (max_depth <= 0) {
        printf("Error: Maximum depth must be greater than zero\n");
        return;
    }

    // Free memory for each event in the events array
    for (int i = 0; i < max_depth; i++) {
        free((*events)[i]);
    }

    // Free memory for the events array
    free(*events);
}
