// Define the node structure
typedef struct {
    int key;
    long value;
} node_t;

// Define the list structure
typedef struct {
    node_t *nodes;
    size_t count;
    pthread_mutex_t mutex;
} list_t;

// Initialize a new list
list_t* init_list() {
    list_t *list = malloc(sizeof(list_t));
    if (list == NULL) {
        return NULL;
    }
    list->nodes = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Insert a new node into the list
void insert_node(list_t *list, int key, long value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Find the position where the new node should be inserted
    size_t i = 0;
    while (i < list->count && key > list->nodes[i].key) {
        i++;
    }

    // If a node with the same key already exists, update its value and return
    if (i < list->count && key == list->nodes[i].key) {
        list->nodes[i].value = value;
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Allocate memory for the new node
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Insert the new node into the list
    new_node->key = key;
    new_node->value = value;
    if (i == 0) {
        // Insert at the head of the list
        new_node->next = list->nodes;
        list->nodes = new_node;
    } else if (i == list->count) {
        // Insert at the tail of the list
        list->nodes[list->count - 1].next = new_node;
        new_node->prev = list->nodes[list->count - 1];
        new_node->next = NULL;
    } else {
        // Insert in the middle of the list
        node_t *prev_node = list->nodes + i - 1;
        node_t *next_node = list->nodes + i;
        prev_node->next = new_node;
        new_node->prev = prev_node;
        new_node->next = next_node;
        next_node->prev = new_node;
    }

    // Update the count of nodes in the list
    list->count++;

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Traverse the list and print each node's key and value
void traverse_list(list_t *list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Print each node's key and value
    for (size_t i = 0; i < list->count; i++) {
        printf("%d: %ld\n", list->nodes[i].key, list->nodes[i].value);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}
```
