void insertNode(List* list, int key, long value) {
    // Create a new node with the given key and value
    Node* newNode = malloc(sizeof(Node));
    newNode->key = key;
    newNode->value = value;

    // If the list is empty, set the head and tail to the new node
    if (list->size == 0) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        // Otherwise, insert the new node at the end of the list
        Node* current = list->tail;
        current->next = newNode;
        newNode->prev = current;
        list->tail = newNode;
    }

    // Increment the size of the list
    list->size++;
}

// Function to update an existing node's value if the key already exists
void updateNode(List* list, int key, long value) {
    // Find the node with the given key
    Node* current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    // If the node was found, update its value and return
    if (current != NULL) {
        current->value = value;
        return;
    }

    // Otherwise, insert a new node with the given key and value
    insertNode(list, key, value);
}

// Function to traverse the list in both forward and backward directions
