    // Traverse the list in backward direction
    current = list->tail;
    while (current != NULL) {
        printf("Key: %d, Value: %ld\n", current->key, current->value);
        current = current->prev;
    }
}

// Function to dynamically resize the underlying array
void resizeList(List* list, size_t newSize) {
    // If the new size is smaller than the current size, do nothing
    if (newSize < list->size) {
        return;
    }

    // Otherwise, allocate a new array with the new size and copy over the nodes
    Node** newArray = malloc(sizeof(Node*) * newSize);
    for (int i = 0; i < list->size; i++) {
