    }

    // Free the old array and set the new array as the head of the list
    free(list->head);
    list->head = newArray;
}

// Function to handle edge cases such as inserting at the head, tail, or middle of the list
void insertAtEdge(List* list, int key, long value) {
    // If the list is empty, set the head and tail to the new node
