            Node* current = list->head;
            while (current != NULL && current->key != key) {
                current = current->next;
            }
            if (current != NULL) {
                current->value = value;
                return;
            }
        }
    }

    // Increment the size of the list
    list->size++;
}

// Function to handle edge cases such as handling empty lists, lists with a single element, and invalid inputs
void updateAtEdge(List* list, int key, long value) {
    // If the list is empty or has only one node, do nothing
    if (list->size == 0 || list->size == 1) {
        return;
    }

    // Otherwise, find the node with the given key and update its value
    Node* current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current != NULL) {
        current->value = value;
    } else {
        // If the key is not present, insert a new node with the given key and value
        Node* newNode = malloc(sizeof(Node));
        newNode->key = key;
        newNode->value = value;
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
}

// Function to handle edge cases such as handling empty lists, lists with a single element, and invalid inputs
void deleteAtEdge(List* list, int key) {
    // If the list is empty or has only one node, do nothing
    if (list->size == 0 || list->size == 1) {
        return;
    }

    // Otherwise, find the node with the given key and delete it
    Node* current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current != NULL) {
        // If the node is at the head, set its next node as the new head and free it
        if (current == list->head) {
            Node* newHead = current->next;
            newHead->prev = NULL;
            free(current);
            list->head = newHead;
        } else if (current == list->tail) {
            // If the node is at the tail, set its previous node as the new tail and free it
            Node* newTail = current->prev;
            newTail->next = NULL;
            free(current);
            list->tail = newTail;
        } else {
            // If the node is in the middle, set its previous and next nodes as the new neighbors and free it
            Node* prevNode = current->prev;
            Node* nextNode = current->next;
            prevNode->next = nextNode;
            nextNode->prev = prevNode;
            free(current);
        }
    } else {
        // If the key is not present, do nothing
        return;
    }
}
