        void** new_blocks = realloc(pool->blocks, sizeof(void*) * num_records);
        if (!new_blocks) {
            fprintf(stderr, "Error: Failed to resize memory pool\n");
            free(records);
            free(pool);
            return;
        }
        pool->blocks = new_blocks;
