typedef struct {
    memory_block_t* blocks;
    size_t num_blocks;
    size_t block_size;
    pthread_mutex_t mutex;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (!pool) {
        return NULL;
    }
    pool->blocks = calloc(num_blocks, sizeof(memory_block_t));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }
    pool->num_blocks = num_blocks;
    pool->block_size = block_size;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool_t* pool) {
    if (!pool) {
        return;
    }
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        free(pool->blocks[i].data);
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool->blocks);
    free(pool);
}

void* allocate_memory(memory_pool_t* pool, size_t size) {
    if (!pool || !size) {
        return NULL;
    }
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        memory_block_t* block = &pool->blocks[i];
        if (block->size >= size) {
            void* data = malloc(size);
            if (!data) {
                pthread_mutex_unlock(&pool->mutex);
                return NULL;
            }
            block->data = data;
            block->size -= size;
            pthread_mutex_unlock(&pool->mutex);
            return data;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

void deallocate_memory(memory_pool_t* pool, void* data) {
    if (!pool || !data) {
        return;
    }
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        memory_block_t* block = &pool->blocks[i];
        if (block->data == data) {
            free(data);
            block->data = NULL;
            pthread_mutex_unlock(&pool->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

