// Define a function to process the input data and calculate the median
void processInput(struct InputData* data, int num_data) {
    // Sort the input data in ascending order
    qsort(data, num_data, sizeof(struct InputData), compare);

    // Calculate the median of the input data
    float median = (data[num_data / 2].value + data[(num_data / 2) - 1].value) / 2;

    // Print the smallest number in the array and the median
    printf("Smallest number: %f\n", data[0].value);
    printf("Median: %f\n", median);
}

// Define a function to calculate the linear interpolation between two points
void linearInterpolation(float x1, float y1, float x2, float y2, float x) {
    // Calculate the slope and intercept of the line passing through the two points
    float m = (y2 - y1) / (x2 - x1);
    float b = y1 - m * x1;

    // Calculate the y-value of the point on the line corresponding to the given x-value
    float y = m * x + b;

    printf("Linear interpolation: %f\n", y);
}

