void reportMemoryUsage() {
    // Calculate the total amount of memory allocated by the program
    size_t total_allocated = 0;
    for (int i = 0; i < num_data; i++) {
        total_allocated += sizeof(struct InputData);
    }

    // Calculate the free memory available in the system
    size_t free_memory = 0;
    FILE* file = fopen("/proc/meminfo", "r");
    if (file != NULL) {
        char line[128];
        while (fgets(line, sizeof(line), file) != NULL) {
            if (strstr(line, "MemFree:") != NULL) {
                sscanf(line, "%*s %zu", &free_memory);
                break;
            }
        }
    }

    // Calculate the memory pool utilization
    size_t memory_pool_utilization = total_allocated / free_memory;

    printf("Memory usage statistics:\n");
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Free memory available: %zu\n", free_memory);
    printf("Memory pool utilization: %zu\n", memory_pool_utilization);
}

