// Custom hash function for mapping data points to memory blocks
uint64_t custom_hash(void* data, size_t size) {
    uint64_t hash = 0;
    char* ptr = (char*)data;
    for (size_t i = 0; i < size; i++) {
        hash = (hash << 8) | *ptr++;
    }
    return hash;
}

// Memory pool structure
struct memory_pool {
    // Linked list of free blocks
    struct block* free_blocks;
    // Linked list of allocated blocks
    struct block* allocated_blocks;
    // Size of each block in the pool
    size_t block_size;
    // Number of concurrent threads using the pool
    int num_threads;
};

// Memory block structure
struct block {
    // Pointer to next block in linked list
    struct block* next;
    // Integer value stored in the block
    int integer;
    // String pointer stored in the block
    char* string;
    // Pointer to next block in linked list of allocated blocks
    struct block* allocated_next;
};

// Initialize memory pool with given size and number of threads
void init_memory_pool(struct memory_pool* pool, size_t size, int num_threads) {
    pool->free_blocks = NULL;
    pool->allocated_blocks = NULL;
    pool->block_size = size / num_threads;
    pool->num_threads = num_threads;
}

// Allocate a block from the memory pool
void* allocate(struct memory_pool* pool, size_t size) {
    // Check if there are any free blocks available
    struct block* free_block = pool->free_blocks;
    if (free_block != NULL) {
        // If there is a free block, use it and remove it from the list
        pool->free_blocks = free_block->next;
        return free_block;
    } else {
        // If there are no free blocks available, allocate a new one
        struct block* allocated_block = (struct block*)malloc(pool->block_size);
        if (allocated_block == NULL) {
            printf("Error: Failed to allocate memory\n");
            return NULL;
        }
        // Initialize the allocated block and add it to the list of allocated blocks
        allocated_block->next = pool->allocated_blocks;
        pool->allocated_blocks = allocated_block;
        return allocated_block;
    }
}

// Deallocate a block back to the memory pool
void deallocate(struct memory_pool* pool, void* block) {
    // Add the deallocated block to the list of free blocks
    struct block* free_block = (struct block*)block;
    free_block->next = pool->free_blocks;
    pool->free_blocks = free_block;
}

// Garbage collector thread that reclaims unused memory blocks
void garbage_collector(struct memory_pool* pool) {
    // Loop until the pool is empty
    while (pool->allocated_blocks != NULL) {
        // Check if any allocated block has been deallocated
        struct block* allocated_block = pool->allocated_blocks;
        bool found_deallocated_block = false;
        for (struct block* current_block = allocated_block; current_block != NULL; current_block = current_block->next) {
            if (current_block->next == NULL) {
                // If the last block in the list is deallocated, break out of the loop
                found_deallocated_block = true;
                break;
            } else if (current_block->next->integer == 0 && current_block->next->string == NULL) {
                // If a block has been deallocated, remove it from the list and free its memory
                struct block* deallocated_block = current_block->next;
                current_block->next = deallocated_block->next;
                free(deallocated_block);
            }
        }
        if (found_deallocated_block) {
            // If a deallocated block was found, break out of the loop and continue with the next iteration
            break;
        }
    }
}

// Real-time monitoring system for memory pool performance metrics
void monitor_memory_pool(struct memory_pool* pool) {
    // Loop until the pool is empty
    while (pool->allocated_blocks != NULL) {
        // Print the current allocation and deallocation rates
        printf("Allocation rate: %d\n", pool->num_threads * 5000);
        printf("Deallocation rate: %d\n", pool->num_threads * 1000);
        // Check if any allocated block has been deallocated
        struct block* allocated_block = pool->allocated_blocks;
        bool found_deallocated_block = false;
        for (struct block* current_block = allocated_block; current_block != NULL; current_block = current_block->next) {
            if (current_block->next == NULL) {
                // If the last block in the list is deallocated, break out of the loop
                found_deallocated_block = true;
                break;
            } else if (current_block->next->integer == 0 && current_block->next->string == NULL) {
                // If a block has been deallocated, remove it from the list and free its memory
                struct block* deallocated_block = current_block->next;
                current_block->next = deallocated_block->next;
                free(deallocated_block);
            }
        }
        if (found_deallocated_block) {
            // If a deallocated block was found, break out of the loop and continue with the next iteration
            break;
        }
    }
}

// Memory pool manager that supports multiple concurrent threads and processes
void* memory_pool_manager(void* args) {
    struct memory_pool* pool = (struct memory_pool*)args;
    // Loop until the pool is empty
    while (pool->allocated_blocks != NULL) {
        // Check if any allocated block has been deallocated
        struct block* allocated_block = pool->allocated_blocks;
        bool found_deallocated_block = false;
        for (struct block* current_block = allocated_block; current_block != NULL; current_block = current_block->next) {
            if (current_block->next == NULL) {
