                struct block* deallocated_block = current_block->next;
                current_block->next = deallocated_block->next;
                free(deallocated_block);
            }
        }
        if (found_deallocated_block) {
            // If a deallocated block was found, break out of the loop and continue with the next iteration
            break;
        }
    }
