#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define a structure to represent a state in the FSA
typedef struct State {
    int id; // unique identifier for the state
    int ref_count; // reference count for the state
    char *label; // transition label for the state
    struct State *next; // pointer to the next state in the list
} State;

// Define a structure to represent the state list
typedef struct StateList {
    State *head; // head of the state list
    int size; // number of states in the list
    int max_size; // maximum size of the state list
    bool sorted; // whether the state list is sorted
} StateList;

// Define a function to create a new state list
StateList *create_state_list(int num_states, FSA *fsa, int last_state) {
    // Check for invalid inputs
    if (num_states < 0 || fsa == NULL || last_state < 0) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the state list
    StateList *list = malloc(sizeof(StateList));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for the state list\n");
        return NULL;
    }

    // Initialize the state list
    list->head = NULL;
    list->size = 0;
    list->max_size = 10000;
    list->sorted = false;

    // Iterate over the states in the FSA and add them to the state list
    for (int i = 0; i < num_states; i++) {
        State *state = &fsa->states[i];
        if (state->id == last_state) {
            // Add the last state to the end of the list
            list->head = add_state(list, state);
        } else {
            // Add other states to the beginning of the list
            list->head = add_state(list, state);
        }
    }

    return list;
}

// Define a function to add a state to the state list
State *add_state(StateList *list, State *state) {
    // Check for invalid inputs
    if (list == NULL || state == NULL) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Increment the reference count of the state
    state->ref_count++;

    // Create a new node to hold the state
    State *node = malloc(sizeof(State));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for the state\n");
        return NULL;
    }

    // Copy the state information into the new node
    memcpy(node, state, sizeof(State));

    // Add the node to the end of the list
    if (list->head == NULL) {
        list->head = node;
    } else {
        node->next = list->head;
        list->head = node;
    }

    // Update the size of the state list
    list->size++;

    return node;
}

// Define a function to merge metadata for duplicate states
void merge_metadata(State *state1, State *state2) {
    // Check for invalid inputs
    if (state1 == NULL || state2 == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Merge the transition labels of the two states
    char *label = malloc(strlen(state1->label) + strlen(state2->label) + 1);
    if (label == NULL) {
        printf("Error: Failed to allocate memory for the merged label\n");
        return;
    }
    sprintf(label, "%s%s", state1->label, state2->label);
    free(state1->label);
    state1->label = label;

    // Merge the reference counts of the two states
    state1->ref_count += state2->ref_count;
}

// Define a function to handle duplicate states gracefully
State *handle_duplicate(StateList *list, State *state) {
    // Check for invalid inputs
    if (list == NULL || state == NULL) {
        printf("Error: Invalid input parameters\n");
        return NULL;
    }

    // Iterate over the states in the list to find a duplicate
    for (State *node = list->head; node != NULL; node = node->next) {
        if (node->id == state->id) {
            // Merge the metadata of the two states
            merge_metadata(node, state);
            return node;
        }
    }

    // Add the new state to the list
    State *new_state = add_state(list, state);
    if (new_state == NULL) {
        printf("Error: Failed to add the new state\n");
        return NULL;
    }

    return new_state;
}

// Define a function to update the 'next' pointers of the last state in the list
void update_next(StateList *list, State *last_state) {
    // Check for invalid inputs
    if (list == NULL || last_state == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Update the 'next' pointer of the last state in the list
    State *node = list->head;
    while (node != NULL && node->id != last_state->id) {
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: Failed to find the last state\n");
        return;
    }
    node->next = list->head;
}

// Define a function to sort the state list in ascending order based on state identifiers
void sort_state_list(StateList *list) {
    // Check for invalid inputs
    if (list == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Sort the state list using a stable sorting algorithm
    State *node = list->head;
    while (node != NULL) {
        State *next_node = node->next;
        while (next_node != NULL && next_node->id < node->id) {
            swap(node, next_node);
            next_node = node->next;
        }
        node = node->next;
    }
}

// Define a function to handle memory allocation failures
void handle_memory_allocation_failure() {
    // Log an error message and return an error code
    printf("Error: Failed to allocate memory\n");
    return -1;
}

// Define a function to log changes to the state list for debugging and auditing purposes
void log_state_list(StateList *list) {
    // Check for invalid inputs
    if (list == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Log the changes to the state list
    State *node = list->head;
    while (node != NULL) {
        printf("State %d: label=%s, ref_count=%d\n", node->id, node->label, node->ref_count);
        node = node->next;
    }
}
