// Define the record structure
typedef struct {
    int key;
    int value;
    struct timeval timestamp;
} Record;

// Define the linked list node structure
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Define the hash table structure
typedef struct {
    Node **buckets;
    int num_buckets;
    pthread_mutex_t mutex;
} HashTable;

// Define the garbage collector structure
typedef struct {
    HashTable *htable;
    pthread_mutex_t mutex;
} GarbageCollector;

// Define the function to generate random integer values within a specified range
int generateRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Define the custom hash function
unsigned long hash(Record *record) {
    unsigned long hash = 0;
    hash += record->key;
    hash += record->value;
    hash += record->timestamp.tv_sec;
    hash += record->timestamp.tv_usec;
    return hash % num_buckets;
}

// Define the function to add a new record
void addRecord(HashTable *htable, Record *record) {
    pthread_mutex_lock(&htable->mutex);
    Node *node = malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    unsigned long index = hash(record);
    if (htable->buckets[index] == NULL) {
        htable->buckets[index] = node;
    } else {
        Node *curr = htable->buckets[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = node;
    }
    pthread_mutex_unlock(&htable->mutex);
}

// Define the function to update an existing record
void updateRecord(HashTable *htable, Record *record) {
    pthread_mutex_lock(&htable->mutex);
    unsigned long index = hash(record);
    Node *curr = htable->buckets[index];
    while (curr != NULL && curr->record->key != record->key) {
        curr = curr->next;
    }
    if (curr == NULL) {
        addRecord(htable, record);
    } else {
        curr->record = record;
    }
    pthread_mutex_unlock(&htable->mutex);
}

// Define the function to delete a record based on its key
void deleteRecordByKey(HashTable *htable, int key) {
    pthread_mutex_lock(&htable->mutex);
    unsigned long index = hash(key);
    Node *curr = htable->buckets[index];
    while (curr != NULL && curr->record->key != key) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&htable->mutex);
        return;
    }
    Node *prev = curr;
    while (curr->next != NULL && curr->next->record->key != key) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&htable->mutex);
        return;
    }
    prev->next = curr->next;
    free(curr);
    pthread_mutex_unlock(&htable->mutex);
}

// Define the function to delete a record based on its timestamp
void deleteRecordByTimestamp(HashTable *htable, struct timeval timestamp) {
    pthread_mutex_lock(&htable->mutex);
    unsigned long index = hash(timestamp);
    Node *curr = htable->buckets[index];
    while (curr != NULL && curr->record->timestamp.tv_sec != timestamp.tv_sec) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&htable->mutex);
        return;
    }
    Node *prev = curr;
    while (curr->next != NULL && curr->next->record->timestamp.tv_sec != timestamp.tv_sec) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&htable->mutex);
        return;
    }
    prev->next = curr->next;
    free(curr);
    pthread_mutex_unlock(&htable->mutex);
}

// Define the function to garbage collect the hash table
void garbageCollect(HashTable *htable) {
    pthread_mutex_lock(&htable->mutex);
    int num_active = 0;
    for (int i = 0; i < htable->num_buckets; i++) {
        Node *curr = htable->buckets[i];
        while (curr != NULL) {
            if (curr->record->timestamp.tv_sec > time(NULL)) {
                num_active++;
            }
            curr = curr->next;
        }
    }
    if (num_active < 500000) {
        for (int i = 0; i < htable->num_buckets; i++) {
            Node *curr = htable->buckets[i];
            while (curr != NULL) {
                if (curr->record->timestamp.tv_sec <= time(NULL)) {
                    Node *prev = curr;
                    curr = curr->next;
                    free(prev);
                } else {
                    break;
                }
            }
        }
    }
    pthread_mutex_unlock(&htable->mutex);
}

// Define the main function
int main() {
    // Initialize the hash table with a fixed number of buckets
    HashTable *htable = malloc(sizeof(HashTable));
    htable->num_buckets = 1000000;
    htable->buckets = malloc(sizeof(Node *) * htable->num_buckets);
    for (int i = 0; i < htable->num_buckets; i++) {
        htable->buckets[i] = NULL;
    }
    pthread_mutex_init(&htable->mutex, NULL);

    // Initialize the garbage collector with a fixed interval
    GarbageCollector *gc = malloc(sizeof(GarbageCollector));
    gc->htable = htable;
    pthread_mutex_init(&gc->mutex, NULL);

    // Start the garbage collection thread
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, &garbageCollect, (void *)gc);

    // Add new records to the hash table
    Record *record = malloc(sizeof(Record));
    record->key = generateRandomInt(1, 1000000);
    record->value = generateRandomInt(1, 1000000);
    record->timestamp.tv_sec = time(NULL) + 3600;
    addRecord(htable, record);

    // Update existing records in the hash table
    record->key = generateRandomInt(1, 1000000);
    record->value = generateRandomInt(1, 1000000);
    record->timestamp.tv_sec = time(NULL) + 3600;
    updateRecord(htable, record);

    // Delete records from the hash table based on their keys
    deleteRecordByKey(htable, generateRandomInt(1, 1000000));

    // Delete records from the hash table based on their timestamps
    deleteRecordByTimestamp(htable, time(NULL) + 3600);

    // Stop the garbage collection thread
    pthread_cancel(&gc_thread);

    return 0;
}
