    // Implement a custom sorting algorithm with O(n log n) complexity to sort the history list in descending order based on timestamps
    if (loggingSystem->isSortingEnabled()) {
        loggingSystem->logInfo("Sorting history list in descending order...");
        HistoryListEntry* current = historyList->head;
        while (current != NULL && current->next != NULL) {
            if (current->metadata->timestamp > current->next->metadata->timestamp) {
                loggingSystem->logWarning("Swapping log entries %s and %s", current->metadata->id, current->next->metadata->id);
                LogEntryMetadata* temp = current->metadata;
                current->metadata = current->next->metadata;
                current->next->metadata = temp;
            }
            current = current->next;
        }
    }

    // Ensure thread safety by implementing locks or mutexes to protect shared resources when multiple threads attempt to modify the history list simultaneously
    pthread_mutex_lock(&loggingSystem->historyListMutex);
    loggingSystem->setHistoryList(historyList);
    pthread_mutex_unlock(&loggingSystem->historyListMutex);

