    if (!keys) {
        // Log an error message if the memory allocation fails
        ERR_print_errors_fp(stderr);
        return 0;
    }

    // Initialize the record array
    Record* records = (Record*)malloc(sizeof(Record) * 3);
    if (!records) {
        // Log an error message if the memory allocation fails
        ERR_print_errors_fp(stderr);
        return 0;
    }

