    EVP_MD_CTX_free(md5_ctx);

    // Disable and free the SHA1 digest context
    EVP_MD_CTX_free(sha1_ctx);

    // Disable and free the RSA with SHA1 signature context
    EVP_PKEY_CTX_free(rsa_ctx);
}
