// Custom allocator for managing memory in a concurrent environment
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used; // Used memory in the pool
    void* data; // Pointer to the start of the pool
    pthread_mutex_t mutex; // Mutex for synchronizing access to the pool
};

// Function to allocate memory from the pool
void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (size > 0 && size <= pool->capacity - pool->used) {
        // Lock the mutex before accessing the pool
        pthread_mutex_lock(&pool->mutex);
        // Allocate memory from the pool
        ptr = pool->data + pool->used;
        pool->used += size;
        // Unlock the mutex after accessing the pool
        pthread_mutex_unlock(&pool->mutex);
    } else {
        printf("Error: Out of memory in mempool_alloc\n");
    }
    return ptr;
}

// Function to free memory from the pool
void mempool_free(struct MemoryPool* pool, void* ptr) {
    // Lock the mutex before accessing the pool
    pthread_mutex_lock(&pool->mutex);
    // Free the memory back to the pool
    size_t size = (char*)ptr - (char*)pool->data;
    pool->used -= size;
    // Unlock the mutex after accessing the pool
    pthread_mutex_unlock(&pool->mutex);
}

// Function to initialize a memory pool with a given capacity
struct MemoryPool* mempool_init(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (pool != NULL) {
        // Initialize the mutex for synchronizing access to the pool
        pthread_mutex_init(&pool->mutex, NULL);
        // Allocate memory for the pool
        pool->data = malloc(capacity);
        if (pool->data == NULL) {
            printf("Error: Out of memory in mempool_init\n");
            free(pool);
            return NULL;
        }
        pool->capacity = capacity;
        pool->used = 0;
    } else {
        printf("Error: Out of memory in mempool_init\n");
    }
    return pool;
}

// Function to destroy a memory pool and free its resources
void mempool_destroy(struct MemoryPool* pool) {
    // Lock the mutex before accessing the pool
    pthread_mutex_lock(&pool->mutex);
    // Free the memory allocated to the pool
    free(pool->data);
    // Destroy the mutex for synchronizing access to the pool
    pthread_mutex_destroy(&pool->mutex);
    // Free the memory allocated to the pool structure
    free(pool);
}

