public class MemoryPool {
    private static final int MAX_RECORDS = 10000; // maximum number of records in the pool
    private static final int MIN_RECORD_SIZE = 4; // minimum size of a record in bytes
    private static final int MAX_RECORD_SIZE = 1024; // maximum size of a record in bytes

    private ConcurrentHashMap<Integer, byte[]> records; // map of record IDs to their corresponding data
    private AtomicInteger nextRecordId; // atomic integer for generating unique record IDs

    public MemoryPool() {
        this.records = new ConcurrentHashMap<>();
        this.nextRecordId = new AtomicInteger(0);
    }

    public int allocateRecord(int size) {
        if (size < MIN_RECORD_SIZE || size > MAX_RECORD_SIZE) {
            throw new IllegalArgumentException("Invalid record size: " + size);
        }

        // generate a unique record ID and allocate the memory for the record
        int recordId = nextRecordId.getAndIncrement();
        byte[] data = new byte[size];
        records.put(recordId, data);

        return recordId;
    }

    public void deallocateRecord(int recordId) {
        if (!records.containsKey(recordId)) {
            throw new IllegalArgumentException("Invalid record ID: " + recordId);
        }

        // remove the record from the map and release its memory
        records.remove(recordId);
    }

    public byte[] getRecordData(int recordId) {
        if (!records.containsKey(recordId)) {
            throw new IllegalArgumentException("Invalid record ID: " + recordId);
        }

        return records.get(recordId);
    }

    public void setRecordData(int recordId, byte[] data) {
        if (!records.containsKey(recordId)) {
            throw new IllegalArgumentException("Invalid record ID: " + recordId);
        }

        records.put(recordId, data);
    }

    public int getPeakMemoryConsumption() {
        return records.size();
    }

    public int getCurrentAvailableMemory() {
        return MAX_RECORDS - records.size();
    }
}
