#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define a struct for a node in the linked list
struct node {
    char* str;
    double value;
    struct node* next;
};

// Define a function to allocate memory for a new node
struct node* alloc_node(char* str, double value) {
    // Allocate memory for the node
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for a new node\n");
        return NULL;
    }

    // Initialize the fields of the node
    new_node->str = strdup(str);
    new_node->value = value;
    new_node->next = NULL;

    return new_node;
}

// Define a function to create a linked list from an array of strings and values
struct node* create_list(char** arr, int num_strings, double* values) {
    // Check if the input arrays are valid
    assert(arr != NULL && values != NULL);

    // Initialize the head pointer of the linked list to NULL
    struct node* head = NULL;

    // Iterate over the array of strings and values
    for (int i = 0; i < num_strings; i++) {
        // Allocate memory for a new node
        struct node* new_node = alloc_node(arr[i], values[i]);
        if (new_node == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for a new node\n");
            return NULL;
        }

        // Add the new node to the linked list
        if (head == NULL) {
            head = new_node;
        } else {
            struct node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    return head;
}

// Define a function to populate the string field of each node with a unique identifier
void populate_strings(struct node* head) {
    // Check if the input linked list is valid
    assert(head != NULL);

    // Initialize a counter for the unique identifiers
    int id = 0;

    // Iterate over the nodes in the linked list
    struct node* current = head;
    while (current != NULL) {
        // Generate a unique identifier for the current node
        char* id_str = malloc(sizeof(char) * 16);
        sprintf(id_str, "%d", id++);

        // Set the string field of the current node to the generated identifier
        free(current->str);
        current->str = strdup(id_str);
    }
}

// Define a function to clear all allocated resources and reset the memory pool
void clear_resources() {
    // Check if the memory pool manager is initialized
    assert(mempool != NULL);

    // Clear the memory pool
    mempool_clear();

    // Reset the head pointer of the linked list to NULL
    head = NULL;
}

// Define a function to handle edge cases, such as empty lists and lists with only one node
void handle_edge_cases(struct node* head) {
    // Check if the input linked list is valid
    assert(head != NULL);

    // Handle the case of an empty list
    if (head == NULL) {
        printf("The linked list is empty\n");
        return;
    }

    // Handle the case of a list with only one node
    struct node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    if (current == head) {
        printf("The linked list has only one node\n");
        return;
    }
}

// Define a function to traverse the linked list and print concatenated strings from each node
void traverse_list(struct node* head) {
    // Check if the input linked list is valid
    assert(head != NULL);

    // Initialize a string buffer for storing the concatenated strings
    char* str = malloc(sizeof(char) * 1024);
    str[0] = '\0';

    // Iterate over the nodes in the linked list
    struct node* current = head;
    while (current != NULL) {
        // Concatenate the string field of the current node with the buffer
        strcat(str, current->str);

        // Print the concatenated string
        printf("%s\n", str);

        // Move to the next node in the linked list
        current = current->next;
    }
}

// Define a function to optimize memory usage by minimizing the number of allocations and leveraging an external memory pool manager for efficient resource management
void optimize_memory(struct node* head) {
    // Check if the input linked list is valid
    assert(head != NULL);

    // Initialize a memory pool manager
    mempool = malloc(sizeof(mempool));
    if (mempool == NULL) {
        fprintf(stderr, "Error: failed to initialize the memory pool manager\n");
        return;
    }

    // Register each allocated block of memory with the memory pool manager
    struct node* current = head;
    while (current != NULL) {
        mempool_register(current);
        current = current->next;
    }
}

// Define a function to ensure thread safety by using appropriate synchronization mechanisms when interacting with the external memory pool manager, particularly during node creation and insertion into the linked list
void ensure_thread_safety() {
    // Check if the memory pool manager is initialized
    assert(mempool != NULL);

    // Use a mutex to synchronize access to the memory pool manager
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for a mutex\n");
        return;
    }
    pthread_mutex_init(mutex, NULL);

    // Use the mutex to synchronize access to the memory pool manager during node creation and insertion into the linked list
    struct node* current = head;
    while (current != NULL) {
        pthread_mutex_lock(mutex);
        mempool_register(current);
        pthread_mutex_unlock(mutex);
        current = current->next;
    }
}

// Define a function to report memory usage statistics, including total allocated memory, free memory, and memory pool utilization
void report_memory_usage() {
    // Check if the memory pool manager is initialized
    assert(mempool != NULL);

    // Print the total allocated memory
    printf("Total allocated memory: %lu\n", mempool->total_allocated);

    // Print the free memory
    printf("Free memory: %lu\n", mempool->free_memory);

    // Print the memory pool utilization
    printf("Memory pool utilization: %.2f%%\n", (mempool->used_memory / mempool->total_allocated) * 100.0);
}

// Define a function to clear all allocated resources and reset the memory pool, enabling effective reuse of memory in subsequent executions
void clear_resources() {
    // Check if the memory pool manager is initialized
    assert(mempool != NULL);

    // Clear the memory pool
    mempool_clear();

    // Reset the head pointer of the linked list to NULL
    head = NULL;
}
