memory_pool* init_memory_pool(size_t capacity) {
    // Allocate a new array of void pointers to store the allocated memory blocks
    void** blocks = malloc(capacity * sizeof(void*));
    if (!blocks) {
        printf("Error: Failed to allocate memory pool\n");
        exit(1);
    }
    // Initialize the memory pool with an initial capacity of NUM_DATA_POINTS
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (!pool) {
        printf("Error: Failed to allocate memory pool\n");
        exit(1);
    }
    pool->blocks = blocks;
    pool->num_blocks = 0;
    return pool;
}

// Add a new memory block to the memory pool
void add_memory_block(memory_pool* pool, void* block) {
    // Check if the memory pool is full
    if (pool->num_blocks == capacity) {
        printf("Error: Memory pool is full\n");
        exit(1);
    }
    // Add the new memory block to the end of the array
    pool->blocks[pool->num_blocks++] = block;
}

// Remove a memory block from the memory pool
void remove_memory_block(memory_pool* pool, void* block) {
    // Find the index of the memory block in the array
    size_t i = 0;
    while (i < pool->num_blocks && pool->blocks[i] != block) {
        i++;
    }
    // Check if the memory block was found
    if (i == pool->num_blocks) {
        printf("Error: Memory block not found\n");
        exit(1);
    }
    // Remove the memory block from the array by shifting all subsequent blocks back one index
    for (size_t j = i; j < pool->num_blocks - 1; j++) {
        pool->blocks[j] = pool->blocks[j + 1];
    }
    // Decrement the number of memory blocks in the pool
    pool->num_blocks--;
}

