// Define the function to allocate and initialize arrays
void allocateAndInitializeArrays(size_t keySize, size_t offsetSize) {
    // Validate the input sizes
    if (keySize > MAX_KEY_SIZE || offsetSize > MAX_OFFSET_SIZE) {
        printf("Invalid input sizes. Maximum allowed sizes are %d and %d respectively.\n", MAX_KEY_SIZE, MAX_OFFSET_SIZE);
        return;
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(keySize * sizeof(int));
    if (!keys) {
        printf("Failed to allocate memory for the key array.\n");
        return;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < keySize; i++) {
        keys[i] = rand() % MAX_RANGE + MIN_RANGE;
    }

    // Allocate memory for the offset array
    long *offsets = (long *)malloc(offsetSize * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for the offset array.\n");
        free(keys);
        return;
    }

    // Initialize the offset array with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % MAX_RANGE + MIN_RANGE;
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(keySize * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for the record array.\n");
        free(keys);
        free(offsets);
        return;
    }

    // Initialize each record with a random value within a specified range
    srand(time(NULL));
