    unsigned char *pixels; // Pointer to the pixel values
    int index; // Index of the frame
    struct frame *next; // Pointer to the next frame
};

// Define the video processing function
void process_video(int num_frames, int fps) {
    // Initialize the memory pool manager
    struct mem_pool *mem_pool = malloc(sizeof(struct mem_pool));
    if (mem_pool == NULL) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        return;
    }
    mem_pool->mem = malloc(1024 * 1024); // Allocate a 1 MB memory pool
    if (mem_pool->mem == NULL) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        free(mem_pool);
        return;
    }
    mem_pool->size = 1024 * 1024; // Set the size of the memory pool to 1 MB
    mem_pool->num_blocks = 0; // Initialize the number of blocks in the memory pool to 0
    mem_pool->block_size = 0; // Initialize the size of each block in the memory pool to 0

    // Allocate memory for the pixel values, frame indices, and frame pointers arrays
    unsigned char *pixels = malloc(num_frames * sizeof(unsigned char));
    if (pixels == NULL) {
        printf("Error: Failed to allocate memory for the pixel values array\n");
        free(mem_pool->mem);
        free(mem_pool);
        return;
    }
    int *frame_indices = malloc(num_frames * sizeof(int));
    if (frame_indices == NULL) {
        printf("Error: Failed to allocate memory for the frame indices array\n");
        free(pixels);
        free(mem_pool->mem);
        free(mem_pool);
        return;
    }
    struct frame *frames = malloc(num_frames * sizeof(struct frame));
    if (frames == NULL) {
        printf("Error: Failed to allocate memory for the frames array\n");
        free(pixels);
        free(frame_indices);
        free(mem_pool->mem);
        free(mem_pool);
        return;
    }

    // Initialize the pixel values, frame indices, and frame pointers arrays
    for (int i = 0; i < num_frames; i++) {
        pixels[i] = 0;
        frame_indices[i] = i;
        frames[i].pixels = &pixels[i];
        frames[i].index = i;
        frames[i].next = NULL;
    }

    // Populate the memory pool with compressed video frame data
    for (int i = 0; i < num_frames; i++) {
        struct frame *frame = &frames[i];
        int block_size = 1024; // Set the size of each block to 1 KB
        void *block = mem_pool->mem + (i * block_size);
        if (block == NULL) {
            printf("Error: Failed to allocate memory for the frame %d\n", i);
            free(pixels);
            free(frame_indices);
            free(frames);
            return;
        }
        memcpy(block, &frame->pixels[0], block_size);
    }

    // Periodically report memory usage statistics
    printf("Memory usage: %lu bytes allocated, %lu bytes free, %d blocks in the memory pool\n", mem_pool->size, mem_pool->size - (mem_pool->num_blocks * mem_pool->block_size), mem_pool->num_blocks);

    // Clear all allocated resources and reset the memory pool
    for (int i = 0; i < num_frames; i++) {
        struct frame *frame = &frames[i];
        free(frame->pixels);
        frame->pixels = NULL;
        frame->index = -1;
        frame->next = NULL;
    }
    free(pixels);
    pixels = NULL;
    free(frame_indices);
    frame_indices = NULL;
    free(frames);
    frames = NULL;
    mem_pool->num_blocks = 0;
    mem_pool->size = 1024 * 1024;
    mem_pool->block_size = 0;

    // Free the memory pool manager and its associated resources
    free(mem_pool->mem);
    free(mem_pool);
}
