    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->id = id;
    pool->blockSize = blockSize;
    pool->maxCapacity = maxCapacity;
    pool->currentSize = 0;
    return pool;
}

void destroyMemoryPool(MemoryPool* pool) {
    free(pool);
}

void lockMemoryPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
}

void unlockMemoryPool(MemoryPool* pool) {
    pthread_mutex_unlock(&pool->lock);
}

// Define the memory request functions
MemoryRequest* createMemoryRequest(int id, size_t blockSize) {
    MemoryRequest* request = (MemoryRequest*)malloc(sizeof(MemoryRequest));
    request->id = id;
    request->blockSize = blockSize;
    return request;
}

void destroyMemoryRequest(MemoryRequest* request) {
    free(request);
}

// Define the memory allocation and deallocation functions
void* allocateMemory(MemoryPoolManager* manager, MemoryRequest* request) {
    lockMemoryPoolManager(manager);
    for (int i = 0; i < manager->numPools; i++) {
        MemoryPool* pool = manager->pools[i];
        if (pool->currentSize < pool->maxCapacity) {
            void* block = malloc(request->blockSize);
            if (block != NULL) {
                lockMemoryPool(pool);
                pool->blocks[pool->currentSize] = block;
                pool->currentSize++;
                unlockMemoryPool(pool);
                destroyMemoryRequest(request);
                return block;
            } else {
                // Memory allocation failed, log the error and continue
                printf("Error: Failed to allocate memory for request %d\n", request->id);
            }
        }
    }
    unlockMemoryPoolManager(manager);
    destroyMemoryRequest(request);
    return NULL;
}

void deallocateMemory(MemoryPoolManager* manager, MemoryRequest* request) {
    lockMemoryPoolManager(manager);
    for (int i = 0; i < manager->numPools; i++) {
        MemoryPool* pool = manager->pools[i];
        if (pool->currentSize > 0) {
            void* block = request->block;
            lockMemoryPool(pool);
            for (int j = 0; j < pool->currentSize; j++) {
                if (pool->blocks[j] == block) {
                    free(block);
                    pool->blocks[j] = NULL;
                    pool->currentSize--;
                    unlockMemoryPool(pool);
                    destroyMemoryRequest(request);
                    return;
                }
            }
            unlockMemoryPool(pool);
        }
    }
    unlockMemoryPoolManager(manager);
    destroyMemoryRequest(request);
}

