    free(manager->pools);
}

void* allocate_block_threadsafe(struct memory_pool_manager* manager, int size) {
    // Allocate a new block of memory within the memory pool manager in a thread-safe manner
    pthread_mutex_lock(&manager->mutex);
    struct memory_pool* pool = manager->pools;
    while (pool) {
        void* block = allocate_block(pool, size);
        if (block) {
            pthread_mutex_unlock(&manager->mutex);
            return block;
        }
        pool = pool->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void deallocate_block_threadsafe(struct memory_pool_manager* manager, void* block) {
    // Deallocate a block of memory within the memory pool manager in a thread-safe manner
    pthread_mutex_lock(&manager->mutex);
    struct memory_pool* pool = manager->pools;
    while (pool) {
