// Define the logging function
void log(MemoryPoolManager* memory_pool_manager, LoggingService* logging_service, ConfigManager* config_manager, const char* message, size_t message_length) {
    // Get the current time
    time_t timestamp = time(NULL);

    // Allocate memory for the log entry
    LogEntry* log_entry = (LogEntry*)memory_pool_manager->alloc(sizeof(LogEntry));
    if (!log_entry) {
        // Handle allocation failure gracefully by releasing partially allocated resources and returning an appropriate error status
        return;
    }

    // Initialize the log entry fields
    log_entry->timestamp = timestamp;
    log_entry->level = LOG_LEVEL_INFO;
    log_entry->message_length = message_length;
    log_entry->message = (char*)memory_pool_manager->alloc(message_length + 1);
    if (!log_entry->message) {
        // Handle allocation failure gracefully by releasing partially allocated resources and returning an appropriate error status
        memory_pool_manager->free(log_entry);
        return;
    }

    // Copy the message into the log entry
    strncpy(log_entry->message, message, message_length + 1);

    // Log the entry using the logging service
    logging_service->log(LOG_LEVEL_INFO, log_entry->message, log_entry->message_length);

    // Release the memory for the log entry
    memory_pool_manager->free(log_entry->message);
    memory_pool_manager->free(log_entry);
