    // Allocate memory for the memory pool
    void* pool = malloc(record_size * 10000);
    if (pool == NULL) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        exit(1);
    }
    // Initialize the memory pool manager with the allocated memory
    manager->pool_start = pool;
    manager->pool_end = pool + record_size * 10000;
    manager->record_size = record_size;
    manager->num_records = 0;
}

// Define a function to allocate memory for a new record in the memory pool
void* alloc_memory(struct MemoryPoolManager* manager, size_t record_size) {
    // Check if there is enough space in the memory pool to allocate a new record
    if (manager->pool_end - manager->pool_start < record_size) {
        printf("Error: Not enough space in the memory pool to allocate a new record\n");
        exit(1);
    }
    // Allocate memory for the new record and update the memory pool manager
    void* record = manager->pool_start;
    manager->pool_start += record_size;
    manager->num_records++;
    return record;
}

