#include <string.h>
#include <pthread.h>

// Define data structures for different types of data
typedef struct {
    int value;
} int_data;

typedef struct {
    long value;
} long_data;

typedef struct {
    int value;
    char* string;
} record_data;

// Define memory pool structure
struct memory_pool {
    // Array of data structures for different types of data
    union {
        int_data* int_array;
        long_data* long_array;
        record_data* record_array;
    } data;

    // Size of the memory pool in bytes
    size_t size;

    // Number of elements in the memory pool
    size_t num_elements;

    // Mutex for synchronizing access to the memory pool
    pthread_mutex_t mutex;
};

// Function to initialize the memory pool
void init_memory_pool(struct memory_pool* pool, size_t size) {
    // Allocate memory for the data structures
    pool->data.int_array = (int_data*)malloc(size * sizeof(int_data));
    pool->data.long_array = (long_data*)malloc(size * sizeof(long_data));
    pool->data.record_array = (record_data*)malloc(size * sizeof(record_data));

    // Initialize the mutex for synchronizing access to the memory pool
    pthread_mutex_init(&pool->mutex, NULL);

    // Set the size and number of elements in the memory pool
    pool->size = size;
    pool->num_elements = 0;
}

// Function to allocate memory from the memory pool
void* alloc_memory(struct memory_pool* pool, size_t size) {
    // Lock the mutex for synchronizing access to the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Check if there is enough space in the memory pool to allocate the requested amount of memory
    if (pool->size - pool->num_elements * sizeof(int) < size) {
        // If not, dynamically resize the memory pool
        pool->data.int_array = realloc(pool->data.int_array, pool->size + size);
        pool->data.long_array = realloc(pool->data.long_array, pool->size + size);
        pool->data.record_array = realloc(pool->data.record_array, pool->size + size);
        pool->size += size;
    }

    // Allocate memory for the requested data structure
    void* ptr = NULL;
    switch (size) {
        case sizeof(int):
            ptr = &pool->data.int_array[pool->num_elements];
            break;
        case sizeof(long):
            ptr = &pool->data.long_array[pool->num_elements];
            break;
        case sizeof(record_data):
            ptr = &pool->data.record_array[pool->num_elements];
            break;
    }

    // Increment the number of elements in the memory pool
    pool->num_elements++;

    // Unlock the mutex for synchronizing access to the memory pool
    pthread_mutex_unlock(&pool->mutex);

    return ptr;
}

// Function to deallocate memory from the memory pool
void free_memory(struct memory_pool* pool, void* ptr) {
    // Lock the mutex for synchronizing access to the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Decrement the number of elements in the memory pool
    pool->num_elements--;

    // Free the requested data structure
    switch (ptr) {
        case &pool->data.int_array[pool->num_elements]:
            free(ptr);
            break;
        case &pool->data.long_array[pool->num_elements]:
            free(ptr);
            break;
        case &pool->data.record_array[pool->num_elements]:
            free(ptr);
            break;
    }

    // Unlock the mutex for synchronizing access to the memory pool
    pthread_mutex_unlock(&pool->mutex);
}

// Function to retrieve a data structure from the memory pool
void* get_data(struct memory_pool* pool, size_t index) {
    // Lock the mutex for synchronizing access to the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Retrieve the requested data structure
    void* ptr = NULL;
    switch (index) {
        case 0:
            ptr = &pool->data.int_array[index];
            break;
        case 1:
            ptr = &pool->data.long_array[index];
            break;
        case 2:
            ptr = &pool->data.record_array[index];
            break;
    }

    // Unlock the mutex for synchronizing access to the memory pool
    pthread_mutex_unlock(&pool->mutex);

    return ptr;
}

// Function to set a data structure in the memory pool
void set_data(struct memory_pool* pool, size_t index, void* data) {
    // Lock the mutex for synchronizing access to the memory pool
    pthread_mutex_lock(&pool->mutex);

    // Set the requested data structure
    switch (index) {
        case 0:
            pool->data.int_array[index] = *(int*)data;
            break;
        case 1:
            pool->data.long_array[index] = *(long*)data;
            break;
        case 2:
            pool->data.record_array[index] = *(record_data*)data;
            break;
    }

    // Unlock the mutex for synchronizing access to the memory pool
    pthread_mutex_unlock(&pool->mutex);
}
