    int key_index = 1;
    for (int i = 0; i < data_size; i++) {
        while (key_index <= data_size) {
            if (!(key[i] == offset[i])) {
                key[i] = key_index++;
                break;
            } else {
                key_index++;
            }
        }
    }

    // Initialize each record's value as the average of the corresponding offset and key values, rounding down to the nearest integer
    for (int i = 0; i < data_size; i++) {
