#define MAX_SIZE 1000000
#define MAX_RECORDS 100000
#define SCALE_FACTOR 10

typedef struct {
    int key;
    long offset;
} record;

void init_arrays(record** records, long** offsets, int** keys, float** scaling_factors) {
    // Allocate memory for the arrays with a maximum size of MAX_SIZE elements
    *records = (record*)malloc(sizeof(record) * MAX_RECORDS);
    *offsets = (long*)malloc(sizeof(long) * MAX_SIZE);
    *keys = (int*)malloc(sizeof(int) * MAX_SIZE);
    *scaling_factors = (float*)malloc(sizeof(float) * MAX_RECORDS);

    // Initialize each element in the 'offset' array with a random value between 0 and 1000
    srand(time(NULL));
    for (int i = 0; i < MAX_SIZE; i++) {
        (*offsets)[i] = rand() % 1000;
    }

    // Initialize each element in the 'key' array with a unique integer value from 1 to MAX_SIZE
    for (int i = 0; i < MAX_SIZE; i++) {
        (*keys)[i] = i + 1;
    }

    // Initialize each 'record' structure with a value that is the average of the corresponding 'offset' and 'key' values
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*records)[i].key = (*keys)[i];
        (*records)[i].offset = (*offsets)[i];
    }

    // Apply a configurable scaling factor from the 'scaling factor' array for compatibility with legacy systems
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*records)[i].offset *= SCALE_FACTOR;
    }

    // Ensure that the scaling factor is applied consistently across all records, even if the scaling factors change dynamically
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*scaling_factors)[i] = SCALE_FACTOR;
    }
}
