// Define the data structure for a single item in the collection
typedef struct {
    time_t timestamp;
    int status_code;
    char *description;
} data_item;

// Define the dynamic array to store the items
typedef struct {
    data_item **items;
    size_t capacity;
    size_t count;
} item_collection;

// Function to add a new item to the collection
void add_item(item_collection *coll, time_t timestamp, int status_code, char *description) {
    // Check if the array needs to be resized
    if (coll->count == coll->capacity) {
        // Double the capacity of the array
        coll->capacity *= 2;
        coll->items = realloc(coll->items, coll->capacity * sizeof(data_item));
    }

    // Add the new item to the end of the array
    coll->items[coll->count] = malloc(sizeof(data_item));
    coll->items[coll->count]->timestamp = timestamp;
    coll->items[coll->count]->status_code = status_code;
    coll->items[coll->count]->description = strdup(description);
    coll->count++;
}

// Function to retrieve an item from the collection by its index
data_item *get_item(item_collection *coll, size_t index) {
    if (index >= coll->count) {
        return NULL;
    }
    return coll->items[index];
}

// Function to remove an item from the collection by its index
void remove_item(item_collection *coll, size_t index) {
    if (index >= coll->count) {
        return;
    }
    free(coll->items[index]);
    coll->count--;
}

// Function to write the collection of items to a rotating log file system
void write_log(item_collection *coll, char *filename) {
    // Open the log file for writing
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        return;
    }

    // Write each item in the collection to the log file
    for (size_t i = 0; i < coll->count; i++) {
        data_item *item = get_item(coll, i);
        fprintf(file, "%lu %d %s\n", item->timestamp, item->status_code, item->description);
    }

    // Close the log file
    fclose(file);
}

// Function to rotate the log files daily
void rotate_logs(char *filename) {
    // Get the current date and time
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    // Create a new filename for the log file based on the current date
    char new_filename[256];
    strftime(new_filename, sizeof(new_filename), "%Y-%m-%d.log", timeinfo);

    // Rename the existing log file to the new filename
    rename(filename, new_filename);
}
