// Custom memory allocator for managing memory pools
struct MemoryPool {
    void* pool; // Pointer to the start of the memory pool
    size_t size; // Size of the memory pool in bytes
    size_t used; // Amount of memory currently in use
};

// Function to allocate memory from a memory pool
void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    if (size > pool->size - pool->used) {
        return NULL;
    }
    void* ptr = pool->pool + pool->used;
    pool->used += size;
    return ptr;
}

// Function to free memory from a memory pool
void mempool_free(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->pool || ptr >= pool->pool + pool->size) {
        return;
    }
    size_t offset = ptr - pool->pool;
    pool->used -= offset;
}

// Function to initialize an array of long offsets and int keys
