    pool->registered_blocks = realloc(pool->registered_blocks, sizeof(struct MemoryBlock*) * (pool->num_registered + 1));
    if (!pool->registered_blocks) {
        free(block);
        return;
    }
    pool->registered_blocks[pool->num_registered++] = block;
}

// Function to unregister an allocated block of memory with a memory pool manager
void unregister_memory(struct MemoryPool* pool, void* ptr) {
    // Find the registered block that matches the given pointer
    for (int i = 0; i < pool->num_registered; i++) {
        if (pool->registered_blocks[i]->ptr == ptr) {
            free(pool->registered_blocks[i]);
            pool->registered_blocks[i] = NULL;
            return;
        }
    }
}

