// Define function to dynamically allocate memory for arrays
void init_arrays(int num_files, const char* file_names[], int** offset_arr, int** key1_arr, int** key2_arr, record*** rec_arr, enum status_type** status_arr) {
    // Initialize variables to store file sizes and record counts
    long file_size = 0;
    int num_records = 0;

    // Loop through each file and read data into arrays
    for (int i = 0; i < num_files; i++) {
        // Open file and check for errors
        FILE* fp = fopen(file_names[i], "r");
        if (fp == NULL) {
            printf("Error opening file %s: %s\n", file_names[i], strerror(errno));
            continue;
        }

        // Get file size and record count
        fseek(fp, 0, SEEK_END);
        file_size = ftell(fp);
        rewind(fp);
        num_records = file_size / sizeof(record);

        // Allocate memory for arrays
        *offset_arr = (int*)malloc(num_records * sizeof(int));
        *key1_arr = (int*)malloc(num_records * sizeof(int));
        *key2_arr = (int*)malloc(num_records * sizeof(int));
        *rec_arr = (record**)malloc(num_records * sizeof(record*));
        *status_arr = (enum status_type*)malloc(num_records * sizeof(enum status_type));

        // Read data from file into arrays
        for (int j = 0; j < num_records; j++) {
            record rec;
            fread(&rec, sizeof(record), 1, fp);
            (*offset_arr)[j] = rec.offset;
            (*key1_arr)[j] = rec.key1;
            (*key2_arr)[j] = rec.key2;
            (*rec_arr)[j] = &rec;
            (*status_arr)[j] = rec.status_enum;
        }

        // Close file and check for errors
        if (fclose(fp) == EOF) {
            printf("Error closing file %s: %s\n", file_names[i], strerror(errno));
        }
    }
}

// Define function to free memory allocated by init_arrays()
void free_arrays(int** offset_arr, int** key1_arr, int** key2_arr, record*** rec_arr, enum status_type** status_arr) {
    // Free memory for arrays
    free(*offset_arr);
    free(*key1_arr);
    free(*key2_arr);
    free(*rec_arr);
    free(*status_arr);
}
