['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Custom memory pool for managing memory allocations
struct MemoryPool {
    size_t capacity; // Total capacity of the pool
    size_t used;     // Used memory in the pool
    void* buffer;    // Pointer to the start of the buffer
};

// Function to initialize a new memory pool with a given capacity
struct MemoryPool* initMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    if (pool->buffer == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to allocate memory from the memory pool
void* allocMemory(struct MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (size > 0 && pool->used + size <= pool->capacity) {
        ptr = pool->buffer + pool->used;
        pool->used += size;
    }
    return ptr;
}

// Function to free memory from the memory pool
void freeMemory(struct MemoryPool* pool, void* ptr) {
    if (ptr != NULL && pool->used > 0) {
        size_t offset = (char*)ptr - (char*)pool->buffer;
        assert(offset < pool->capacity);
        pool->used -= offset;
    }
}

// Function to reset the memory pool for reuse in subsequent calls
void resetMemoryPool(struct MemoryPool* pool) {
    pool->used = 0;
}

// Custom data structure for storing records with unique keys and offsets
struct Record {
    int key;
    long offset;
};

// Function to generate a random integer within a given range
int randInt(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random long integer within a given range
long randLong(long min, long max) {
    return min + (rand() % (max - min + 1));
}

// Function to populate the records with unique values within specified ranges
void populateRecords(struct Record* records, int numRecords, int keyMin, int keyMax, long offsetMin, long offsetMax) {
    for (int i = 0; i < numRecords; i++) {
        records[i].key = randInt(keyMin, keyMax);
        records[i].offset = randLong(offsetMin, offsetMax);
    }
}

// Function to allocate memory for the two arrays and populate them with unique values
