void serializeData(struct Record* records, int numRecords, char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        return;
    }
    for (int i = 0; i < numRecords; i++) {
        fprintf(fp, "{\"key\": %d, \"offset\": %ld}\n", records[i].key, records[i].offset);
    }
    fclose(fp);
}

// Function to deserialize the data structures from a file in JSON format
struct Record* deserializeData(int numRecords, char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
