    for (int i = 0; i < numRecords; i++) {
        char line[1024];
        fgets(line, sizeof(line), fp);
        sscanf(line, "{\"key\": %d, \"offset\": %ld}", &records[i].key, &records[i].offset);
    }
    fclose(fp);
    return records;
}

