Here is an example implementation of the C data structure and associated functions to manage a dynamic collection of records, each containing a `long` offset, an `int` key, and a `float` value:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define the structure to hold the record data
typedef struct {
    long offset;
    int key;
    float value;
} Record;

// Define a hash table to store the records
typedef struct {
    size_t capacity; // The current capacity of the hash table
    size_t size; // The number of records stored in the hash table
    Record* records; // An array of records
} HashTable;

// Define a function to create a new hash table with a given capacity
HashTable* create_hash_table(size_t capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    if (!ht) {
        return NULL;
    }
    ht->capacity = capacity;
    ht->size = 0;
    ht->records = calloc(capacity, sizeof(Record));
    if (!ht->records) {
        free(ht);
        return NULL;
    }
    return ht;
}

// Define a function to insert a new record into the hash table
int insert_record(HashTable* ht, long offset, int key, float value) {
    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        return -1;
    }
    // Find an empty slot in the hash table
    size_t index = 0;
    while (index < ht->capacity && ht->records[index].key != 0) {
        index++;
    }
    if (index == ht->capacity) {
        return -1;
    }
    // Insert the new record into the hash table
    ht->records[index].offset = offset;
    ht->records[index].key = key;
    ht->records[index].value = value;
    ht->size++;
    return 0;
}

// Define a function to delete a record from the hash table by key
int delete_record(HashTable* ht, int key) {
    // Find the index of the record with the given key
    size_t index = 0;
    while (index < ht->capacity && ht->records[index].key != key) {
        index++;
    }
    if (index == ht->capacity) {
        return -1;
    }
    // Remove the record from the hash table
    ht->size--;
    for (size_t i = index; i < ht->capacity - 1; i++) {
        ht->records[i] = ht->records[i + 1];
    }
    return 0;
}

// Define a function to retrieve a record from the hash table by key
Record* get_record(HashTable* ht, int key) {
    // Find the index of the record with the given key
    size_t index = 0;
    while (index < ht->capacity && ht->records[index].key != key) {
        index++;
    }
    if (index == ht->capacity) {
        return NULL;
    }
    // Return the record at the found index
    return &ht->records[index];
}

// Define a function to iterate over all records in the hash table and print their contents
void print_all_records(HashTable* ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i].key != 0) {
            printf("Record %lu: offset=%ld, key=%d, value=%.2f\n", i, ht->records[i].offset, ht->records[i].key, ht->records[i].value);
        }
    }
}
