```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
} Record;

// Define the memory pool manager
struct MemoryPoolManager {
    // The size of the memory pool in bytes
    size_t poolSize;

    // The number of free blocks in the pool
    size_t numFreeBlocks;

    // The list of free blocks in the pool
    struct FreeBlock *freeBlocks;
};

// Define a free block structure
struct FreeBlock {
    // The address of the free block
    void *address;

    // The size of the free block
    size_t size;

    // The next free block in the list
    struct FreeBlock *next;
};

// Define a custom memory allocator that handles fragmentation by dynamically coalescing adjacent free blocks
void *customAlloc(size_t size) {
    // Check if the requested size is within the maximum allowable size
    if (size > 10000) {
        return NULL;
    }

    // Allocate memory for the record array
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        return NULL;
    }

    // Initialize the record array
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % 100 + 1;
    }

    // Return the pointer to the allocated memory
    return records;
}

// Define a function that registers each allocated block of memory with the memory pool manager
void registerBlock(void *address, size_t size) {
    // Check if the address is NULL or the size is 0
    if (!address || !size) {
        return;
    }

    // Allocate memory for the free block structure
    struct FreeBlock *freeBlock = malloc(sizeof(struct FreeBlock));
    if (!freeBlock) {
        return;
    }

    // Initialize the free block structure
    freeBlock->address = address;
    freeBlock->size = size;
    freeBlock->next = NULL;

    // Add the free block to the list of free blocks in the pool
    struct MemoryPoolManager *pool = getMemoryPool();
    if (!pool) {
        return;
    }

    // Check if there are any existing free blocks in the pool
    if (pool->numFreeBlocks > 0) {
        // Find the last free block in the list
        struct FreeBlock *lastFreeBlock = pool->freeBlocks;
        while (lastFreeBlock->next != NULL) {
            lastFreeBlock = lastFreeBlock->next;
        }

        // Add the new free block to the end of the list
        lastFreeBlock->next = freeBlock;
    } else {
        // The pool is empty, so add the first free block
        pool->freeBlocks = freeBlock;
    }

    // Increment the number of free blocks in the pool
    pool->numFreeBlocks++;
}

// Define a function that unregisters each allocated block of memory with the memory pool manager
void unregisterBlock(void *address) {
    // Check if the address is NULL
    if (!address) {
        return;
    }

    // Find the free block in the list that matches the address
    struct MemoryPoolManager *pool = getMemoryPool();
    if (!pool) {
        return;
    }

    struct FreeBlock *freeBlock = pool->freeBlocks;
    while (freeBlock != NULL) {
        if (freeBlock->address == address) {
            // Remove the free block from the list
            struct FreeBlock *prevFreeBlock = freeBlock->next;
            free(freeBlock);

            // Decrement the number of free blocks in the pool
            pool->numFreeBlocks--;

            return;
        }

        prevFreeBlock = freeBlock;
        freeBlock = freeBlock->next;
    }
}

// Define a function that handles memory allocation and deallocation for the record array
void *allocateRecords(size_t size) {
    // Check if the requested size is within the maximum allowable size
