#include <stdlib.h>
#include <string.h>

// Define a custom memory pool for efficient allocation of record structures
struct MemoryPool {
    size_t capacity; // Maximum number of records that can be stored in the pool
    size_t count; // Current number of records stored in the pool
    struct Record *records[]; // Array of record structures
};

// Define a record structure to store key, offset, and dynamically allocated value
struct Record {
    int *key; // Pointer to an integer key
    long offset; // Long integer offset value
    int *value; // Dynamically allocated integer value
};

// Function to manage memory for an array of 'record' structures
void manage_memory(size_t num_records, size_t max_records) {
    // Validate the configuration parameters to prevent buffer overflows
    if (num_records > max_records) {
        return;
    }

    // Create a custom memory pool for efficient allocation of record structures
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->capacity = max_records;
    pool->count = num_records;
    pool->records = malloc(num_records * sizeof(struct Record));

    // Initialize each record structure with a key, offset, and dynamically allocated value
    for (size_t i = 0; i < num_records; i++) {
        struct Record *record = &pool->records[i];
        record->key = malloc(sizeof(int));
        record->offset = 0;
        record->value = malloc(sizeof(int));
    }

    // Release all allocated memory when the function is no longer in use
    atexit(free_memory);
}

// Function to free all allocated memory for a given memory pool
void free_memory(struct MemoryPool *pool) {
    if (pool == NULL) {
        return;
    }

    // Free each record structure and its dynamically allocated value
    for (size_t i = 0; i < pool->count; i++) {
        struct Record *record = &pool->records[i];
        free(record->key);
        free(record->value);
    }

    // Free the memory pool itself
    free(pool);
}
```
