```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

// Define a custom memory pool manager
struct MemoryPoolManager {
    // Pointer to the start of the memory pool
    void* pool;
    // Size of the memory pool in bytes
    size_t poolSize;
    // Number of free blocks in the memory pool
    int numFreeBlocks;
    // Array of free block pointers
    void** freeBlocks;
};

// Define a custom hash function for mapping data points to memory blocks within the memory pool
unsigned long hash(void* key) {
    unsigned long hash = 0;
    char* c = (char*)key;
    while (*c != '\0') {
        hash = *c + (hash << 6) + (hash << 16) - hash;
        c++;
    }
    return hash;
}

// Define a custom memory pool manager for managing the memory pool
struct MemoryPoolManager* createMemoryPoolManager(size_t poolSize) {
    struct MemoryPoolManager* manager = (struct MemoryPoolManager*)malloc(sizeof(struct MemoryPoolManager));
    if (!manager) {
        return NULL;
    }
    manager->pool = malloc(poolSize);
    if (!manager->pool) {
        free(manager);
        return NULL;
    }
    manager->poolSize = poolSize;
    manager->numFreeBlocks = 0;
    manager->freeBlocks = (void**)malloc(sizeof(void*) * poolSize);
    if (!manager->freeBlocks) {
        free(manager->pool);
        free(manager);
        return NULL;
    }
    return manager;
}

// Define a function for allocating memory within the memory pool
void* allocateMemory(struct MemoryPoolManager* manager, size_t size) {
    // Check if there are any free blocks in the memory pool
    if (manager->numFreeBlocks == 0) {
        return NULL;
    }
    // Find a suitable free block within the memory pool
    void** freeBlock = manager->freeBlocks[hash(size)];
    while (*freeBlock != NULL && *freeBlock < size) {
        freeBlock++;
    }
    if (*freeBlock == NULL) {
        return NULL;
    }
    // Allocate the memory block and update the free block list
    void* allocatedMemory = (void*)((char*)manager->pool + *freeBlock);
    manager->numFreeBlocks--;
    manager->freeBlocks[hash(size)] = NULL;
    return allocatedMemory;
}

// Define a function for deallocating memory within the memory pool
void deallocateMemory(struct MemoryPoolManager* manager, void* memory) {
    // Check if the memory block is within the memory pool
    if ((char*)memory < (char*)manager->pool || (char*)memory >= (char*)manager->pool + manager->poolSize) {
        return;
    }
    // Find the free block list index for the memory block
    size_t index = hash((char*)memory - (char*)manager->pool);
    // Add the memory block to the free block list
    manager->freeBlocks[index] = (void*)((char*)memory - (char*)manager->pool);
    manager->numFreeBlocks++;
}

// Define a function for coalescing adjacent free blocks within the memory pool
void coalesceMemory(struct MemoryPoolManager* manager) {
    // Iterate over all free block lists
    for (int i = 0; i < manager->poolSize; i++) {
        // Check if there are any adjacent free blocks in the list
        void** currentBlock = manager->freeBlocks[i];
        while (*currentBlock != NULL) {
            // Find the next free block in the list
            void** nextBlock = (void**)((char*)currentBlock + *currentBlock);
            // Check if the next block is adjacent to the current block
            if ((char*)nextBlock >= (char*)manager->pool && (char*)nextBlock < (char*)manager->pool + manager->poolSize) {
                // Coalesce the two blocks and update the free block list
                *currentBlock += *nextBlock;
                manager->freeBlocks[i] = nextBlock;
            } else {
                currentBlock++;
            }
        }
    }
}

// Define a function for managing memory allocation and deallocation within the memory pool
void* manageMemory(struct MemoryPoolManager* manager, size_t size) {
    // Check if there is enough free memory in the memory pool to allocate the requested block
    if (manager->numFreeBlocks * size > manager->poolSize - manager->poolSize / 10) {
        return NULL;
    }
    // Allocate the memory block within the memory pool
    void* allocatedMemory = allocateMemory(manager, size);
    if (!allocatedMemory) {
        coalesceMemory(manager);
        allocatedMemory = allocateMemory(manager, size);
        if (!allocatedMemory) {
            return NULL;
        }
    }
    // Update the memory usage statistics
    manager->numFreeBlocks--;
    manager->poolSize -= size;
    return allocatedMemory;
}

// Define a function for reporting the current memory usage statistics within the memory pool
void reportMemoryUsage(struct MemoryPoolManager* manager) {
    printf("Total allocated memory: %zu\n", manager->poolSize);
    printf("Free memory: %zu\n", manager->numFreeBlocks * sizeof(void*));
    printf("Memory pool utilization: %.2f%%\n", (double)(manager->poolSize - manager->numFreeBlocks * sizeof(void*)) / manager->poolSize * 100);
}

// Define a function for managing memory allocation and deallocation within the memory pool in a thread-safe manner
void* manageMemoryThreadSafe(struct MemoryPoolManager* manager, size_t size) {
    // Lock the memory pool manager to ensure thread safety
    pthread_mutex_lock(&manager->mutex);
    void* allocatedMemory = manageMemory(manager, size);
    if (!allocatedMemory) {
        coalesceMemory(manager);
        allocatedMemory = manageMemory(manager, size);
        if (!allocatedMemory) {
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
    }
    // Unlock the memory pool manager to release the lock
    pthread_mutex_unlock(&manager->mutex);
    return allocatedMemory;
}
