int allocate_and_initialize(int N, int M, int P) {
    // Allocate an array of long integers with N elements
    long* arr = my_alloc(N * sizeof(long));
    if (!arr) {
        return -1;
    }

    // Initialize each element in the array to a random value between 0 and MAX_OFFSET
    for (int i = 0; i < N; i++) {
        arr[i] = rand() % MAX_OFFSET;
    }

    // Allocate an array of int integers with M unique elements
    int* keys = my_alloc(M * sizeof(int));
    if (!keys) {
        my_free(arr);
        return -1;
    }

    // Initialize each element in the array to a random value between 0 and MAX_KEY
    for (int i = 0; i < M; i++) {
        keys[i] = rand() % MAX_KEY;
    }

    // Allocate an array of record structures with P elements
    record* records = my_alloc(P * sizeof(record));
    if (!records) {
        my_free(arr);
        my_free(keys);
        return -1;
    }

    // Initialize each element in the array to a valid key and corresponding offset
    for (int i = 0; i < P; i++) {
        records[i].key = keys[rand() % M];
        records[i].offset = arr[rand() % N];
        records[i].value = rand() % MAX_VALUE + MIN_VALUE;
    }

    // Serialize and deserialize the record structures using a custom allocator
    char* serialized = serialize(records, P);
    if (!serialized) {
        my_free(arr);
        my_free(keys);
        my_free(records);
        return -1;
    }
    record* deserialized = deserialize(serialized);
    if (!deserialized) {
        my_free(arr);
        my_free(keys);
        my_free(records);
        my_free(serialized);
        return -1;
    }

    // Free all allocated resources
    my_free(arr);
    my_free(keys);
    my_free(records);
    my_free(serialized);

    return 0;
}

// Serialize the record structures using a custom allocator
char* serialize(record* records, int count) {
    // Calculate the size of the serialized data
    int size = count * sizeof(record);

    // Allocate memory for the serialized data
    char* serialized = my_alloc(size);
    if (!serialized) {
        return NULL;
    }

    // Serialize the record structures into the allocated memory
    memcpy(serialized, records, size);

    return serialized;
}

// Deserialize the record structures using a custom allocator
record* deserialize(char* serialized) {
    // Calculate the size of the deserialized data
    int size = strlen(serialized) / sizeof(record);

    // Allocate memory for the deserialized data
    record* deserialized = my_alloc(size * sizeof(record));
    if (!deserialized) {
        return NULL;
    }

    // Deserialize the serialized data into the allocated memory
    memcpy(deserialized, serialized, size);

    return deserialized;
}
