import os
import json
import time
from datetime import datetime
from docker import APIClient
from docker.errors import DockerException, ImageNotFound
from requests import RequestException
from requests.exceptions import HTTPError

class ContainerManager:
    def __init__(self, config):
        self.config = config
        self.client = APIClient(base_url='unix://var/run/docker.sock')

    def build_image(self, env):
        try:
            image_name = f'{env["name"]}-{env["version"]}'
            dockerfile_path = os.path.join('./', 'Dockerfile')
            self.client.images.build(path=dockerfile_path, tag=image_name)
            return True
        except (DockerException, ImageNotFound) as e:
            print(f'Error building image {image_name}: {e}')
            return False

    def push_image(self, env):
        try:
            image_name = f'{env["name"]}-{env["version"]}'
            self.client.images.push(image_name)
            return True
        except (DockerException, ImageNotFound) as e:
            print(f'Error pushing image {image_name}: {e}')
            return False

    def update_stack(self, env):
        try:
            stack_name = f'{env["name"]}-{env["version"]}'
            stack_data = self.client.stacks.inspect(stack_name)
            stack_data['Spec']['Env'] = env['env']
            stack_data['Spec']['Resources'] = env['resources']
            stack_data['Spec']['Services'] = env['services']
            stack_data['Spec']['Networks'] = env['networks']
            self.client.stacks.update(stack_name, stack_data)
            return True
        except (DockerException, ImageNotFound) as e:
            print(f'Error updating stack {stack_name}: {e}')
            return False

    def teardown_stack(self, env):
        try:
            stack_name = f'{env["name"]}-{env["version"]}'
            self.client.stacks.remove(stack_name)
            return True
        except (DockerException, ImageNotFound) as e:
            print(f'Error tearing down stack {stack_name}: {e}')
            return False

    def handle_exception(self, env):
        try:
            if self.build_image(env):
                if self.push_image(env):
                    if self.update_stack(env):
                        print(f'Successfully updated stack {env["name"]}-{env["version"]}')
                    else:
                        print(f'Error updating stack {env["name"]}-{env["version"]}')
                else:
                    print(f'Error pushing image {env["name"]}-{env["version"]}')
            else:
                print(f'Error building image {env["name"]}-{env["version"]}')
        except (DockerException, ImageNotFound) as e:
            print(f'Error handling exception for stack {env["name"]}-{env["version"]}: {e}')

def main():
    config = {
        'environments': [
            {
                'name': 'production',
                'version': '1.0',
                'env': {'FOO': 'bar'},
                'resources': {'limits': {'cpu': 2, 'memory': 4}},
                'services': {'service1': {'image': 'my-image:latest'}},
                'networks': {'default': {'aliases': ['my-app']}}
            },
            {
                'name': 'staging',
                'version': '2.0',
                'env': {'FOO': 'baz'},
                'resources': {'limits': {'cpu': 1, 'memory': 2}},
                'services': {'service1': {'image': 'my-image:latest'}},
                'networks': {'default': {'aliases': ['my-app']}}
            }
        ]
    }

    manager = ContainerManager(config)

    for env in config['environments']:
        try:
            if not manager.update_stack(env):
                manager.handle_exception(env)
        except (DockerException, ImageNotFound) as e:
            print(f'Error updating stack {env["name"]}-{env["version"]}: {e}')

if __name__ == '__main__':
    main()
