#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>

typedef struct {
    char* path;
    int index;
    double size;
} FileInfo;

FileInfo* getFilesInDirectory(const char* directoryPath) {
    // Check if the directory exists and is a directory
    struct stat dirStat;
    if (stat(directoryPath, &dirStat) == -1 || !S_ISDIR(dirStat.st_mode)) {
        fprintf(stderr, "Error: %s is not a valid directory\n", directoryPath);
        return NULL;
    }

    // Open the directory and get its file count
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        fprintf(stderr, "Error: could not open directory %s\n", directoryPath);
        return NULL;
    }
    int fileCount = 0;
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        fileCount++;
    }
    closedir(dir);

    // Allocate memory for the array of FileInfo structures
    FileInfo* files = malloc(fileCount * sizeof(FileInfo));
    if (files == NULL) {
        fprintf(stderr, "Error: could not allocate memory for file list\n");
        return NULL;
    }

    // Populate the array with the absolute paths of files in the directory
    int i = 0;
    dir = opendir(directoryPath);
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char* filePath = malloc((strlen(directoryPath) + strlen(entry->d_name) + 2) * sizeof(char));
        if (filePath == NULL) {
            fprintf(stderr, "Error: could not allocate memory for file path\n");
            return NULL;
        }
        sprintf(filePath, "%s/%s", directoryPath, entry->d_name);
        struct stat fileStat;
        if (stat(filePath, &fileStat) == -1 || !S_ISREG(fileStat.st_mode)) {
            fprintf(stderr, "Error: could not get information for file %s\n", filePath);
            return NULL;
        }
        files[i].path = filePath;
        files[i].index = i + 1;
        files[i].size = (double)fileStat.st_size / 1024.0;
        i++;
    }
    closedir(dir);

    return files;
}
