Here's an example implementation of the doubly linked list data structure using C:
```c
#include <stdlib.h>
#include <stdio.h>

// Node structure for the list
typedef struct node {
    int key;
    struct node *next, *prev;
} node_t;

// Function to dynamically allocate memory for a new node and initialize it with a given key
node_t* create_node(int key) {
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return NULL;
    }
    new_node->key = key;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

// Function to insert a new node at a specified position in the list, maintaining sorted order based on the int key
void insert_node(node_t **head, int key, int pos) {
    // Check if the position is valid
    if (pos < 0 || pos > count_nodes(*head)) {
        printf("Error: Invalid position for node insertion\n");
        return;
    }

    // Create a new node with the given key
    node_t *new_node = create_node(key);
    if (new_node == NULL) {
        printf("Error: Failed to create new node\n");
        return;
    }

    // If the position is 0, insert at the beginning of the list
    if (pos == 0) {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    } else {
        // Find the node before which to insert the new node
        node_t *cur_node = *head;
        for (int i = 0; i < pos - 1; i++) {
            cur_node = cur_node->next;
        }

        // Insert the new node after the current node
        new_node->prev = cur_node;
        new_node->next = cur_node->next;
        cur_node->next->prev = new_node;
        cur_node->next = new_node;
    }
}

// Function to traverse the list and print the keys of all nodes in ascending order
void traverse_list(node_t *head) {
    node_t *cur_node = head;
    while (cur_node != NULL) {
        printf("%d ", cur_node->key);
        cur_node = cur_node->next;
    }
}

// Function to count the number of nodes in the list
int count_nodes(node_t *head) {
    int count = 0;
    node_t *cur_node = head;
    while (cur_node != NULL) {
        count++;
        cur_node = cur_node->next;
    }
    return count;
}

// Function to remove a node from the list at a specified position, maintaining sorted order based on the int key
void remove_node(node_t **head, int pos) {
    // Check if the position is valid
    if (pos < 0 || pos >= count_nodes(*head)) {
        printf("Error: Invalid position for node removal\n");
        return;
    }

    // Find the node to remove
    node_t *cur_node = *head;
    for (int i = 0; i < pos - 1; i++) {
        cur_node = cur_node->next;
    }

    // Remove the node from the list
    if (pos == 0) {
        *head = (*head)->next;
        (*head)->prev = NULL;
    } else {
        cur_node->prev->next = cur_node->next;
        cur_node->next->prev = cur_node->prev;
    }

    // Free the memory allocated for the node
    free(cur_node);
}
```
