// Function to populate an array of FileInfo structures with strings representing the absolute paths of files within a specified directory, categorized by MIME type, and include metadata such as file permissions, modification timestamps, and ownership details.
int populate_file_info_array(const char* dir_path, size_t max_files, FileInfo** file_info_array) {
    // Check if the directory path is valid
    if (!dir_path || !strlen(dir_path)) {
        fprintf(stderr, "Error: Invalid directory path\n");
        return -1;
    }

    // Open the directory stream for reading
    DIR* dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Error: Failed to open directory %s\n", dir_path);
        return -1;
    }

    // Initialize the file counter and the array index
    size_t file_count = 0;
    size_t index = 0;

    // Read each entry in the directory stream
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over hidden files and directories
        if (strncmp(entry->d_name, ".", 2) == 0 || strncmp(entry->d_name, "..", 3) == 0) {
            continue;
        }

        // Get the absolute path of the file
        char* file_path = (char*)malloc(strlen(dir_path) + strlen(entry->d_name) + 2);
        if (!file_path) {
            fprintf(stderr, "Error: Failed to allocate memory for file path\n");
            closedir(dir);
            return -1;
        }
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);

        // Get the MIME type of the file
        struct stat file_stat;
        if (lstat(file_path, &file_stat) == -1) {
            fprintf(stderr, "Error: Failed to get file status for %s\n", file_path);
            free(file_path);
            closedir(dir);
            return -1;
        }
        char* mime_type = (char*)malloc(strlen(entry->d_name) + 20);
        if (!mime_type) {
            fprintf(stderr, "Error: Failed to allocate memory for MIME type\n");
            free(file_path);
            closedir(dir);
            return -1;
        }
        sprintf(mime_type, "%s/%s", entry->d_name + strlen(entry->d_name) - 3, entry->d_name + strlen(entry->d_name) - 2);

        // Get the file size in kilobytes
        double file_size = (double)file_stat.st_size / 1024;

        // Add the FileInfo structure to the array
        if (index >= max_files) {
            fprintf(stderr, "Error: Maximum number of files exceeded\n");
            free(file_path);
            free(mime_type);
            closedir(dir);
            return -1;
        }
        FileInfo* file_info = (FileInfo*)malloc(sizeof(FileInfo));
        if (!file_info) {
            fprintf(stderr, "Error: Failed to allocate memory for file info\n");
            free(file_path);
            free(mime_type);
            closedir(dir);
            return -1;
        }
        file_info->path = file_path;
        file_info->index = index++;
        file_info->size = file_size;
        file_info_array[file_count++] = file_info;
    }

    // Close the directory stream
    closedir(dir);

    return file_count;
}

