// Define a struct for the nodes in the BST
struct node {
    double value;
    char* string;
    int count;
    struct node* left;
    struct node* right;
};

// Define a configuration file to specify default sizes and limits for the arrays
#define DEFAULT_ARRAY_SIZE 100
#define MAX_ARRAY_SIZE 1000

// Function to allocate and initialize memory for the three primary data structures
void init_memory(int array_size, int string_array_size, int node_array_size) {
    // Allocate memory for the arrays
    double* array = (double*)malloc(sizeof(double) * array_size);
    char** string_array = (char**)malloc(sizeof(char*) * string_array_size);
    struct node** node_array = (struct node**)malloc(sizeof(struct node*) * node_array_size);

    // Initialize the arrays
    for (int i = 0; i < array_size; i++) {
        array[i] = 0.0;
    }
    for (int i = 0; i < string_array_size; i++) {
        string_array[i] = NULL;
    }
    for (int i = 0; i < node_array_size; i++) {
        node_array[i] = NULL;
    }
}

// Function to insert a new value into the BST while maintaining balance and ensuring that the tree remains sorted
void insert(struct node* root, double value) {
    // If the root is null, create a new node with the given value
    if (root == NULL) {
        struct node* new_node = (struct node*)malloc(sizeof(struct node));
        new_node->value = value;
        new_node->left = NULL;
        new_node->right = NULL;
        return new_node;
    }

    // If the value is less than the root's value, insert it in the left subtree
    if (value < root->value) {
        root->left = insert(root->left, value);
    } else {
        root->right = insert(root->right, value);
    }

    // Balance the tree by rotating nodes as needed
    balance_tree(root);
}

// Function to balance the BST after insertions to minimize search times and improve performance
void balance_tree(struct node* root) {
    // If the root is null, return
    if (root == NULL) {
        return;
    }

    // If the left subtree is unbalanced, rotate it
    if (unbalanced(root->left)) {
        root = rotate_left(root);
    }

    // If the right subtree is unbalanced, rotate it
    if (unbalanced(root->right)) {
        root = rotate_right(root);
    }
}

// Function to check if a node is unbalanced and needs to be rotated
int unbalanced(struct node* node) {
    // If the node is null, return false
    if (node == NULL) {
        return 0;
    }

    // If the left subtree is too large, return true
    if (height(node->left) - height(node->right) > 1) {
        return 1;
    }

    // If the right subtree is too large, return true
    if (height(node->right) - height(node->left) > 1) {
        return 1;
    }

    // Otherwise, return false
    return 0;
}

// Function to rotate a node left
struct node* rotate_left(struct node* root) {
    struct node* new_root = root->right;
    root->right = new_root->left;
    new_root->left = root;
    return new_root;
}

// Function to rotate a node right
struct node* rotate_right(struct node* root) {
    struct node* new_root = root->left;
    root->left = new_root->right;
    new_root->right = root;
    return new_root;
}

// Function to delete a node from the BST and balance the tree
void delete(struct node* root, double value) {
    // If the root is null, return
    if (root == NULL) {
        return;
    }

    // If the value is less than the root's value, delete it in the left subtree
    if (value < root->value) {
        root->left = delete(root->left, value);
    } else {
        root->right = delete(root->right, value);
    }

    // If the node is null, return
    if (root == NULL) {
        return;
    }

    // If the left subtree is empty and the right subtree is not, make the right child the new root
    if (root->left == NULL && root->right != NULL) {
        struct node* temp = root->right;
        free(root);
        return temp;
    }

    // If the right subtree is empty and the left subtree is not, make the left child the new root
    if (root->right == NULL && root->left != NULL) {
        struct node* temp = root->left;
        free(root);
        return temp;
    }

    // If both subtrees are not empty, find the minimum value in the right subtree and make it the new root
    if (root->right != NULL && root->left != NULL) {
        struct node* min = find_min(root->right);
        root->value = min->value;
        root->right = delete(root->right, min->value);
    }
}

// Function to find the minimum value in a subtree
struct node* find_min(struct node* root) {
    // If the root is null, return null
    if (root == NULL) {
        return NULL;
    }

    // If the left subtree is empty, return the current node
    if (root->left == NULL) {
        return root;
    }

    // Otherwise, recurse down the left subtree to find the minimum value
    struct node* min = find_min(root->left);
    return min;
}

// Function to traverse the BST in-order and pre-order
void traverse(struct node* root) {
    // If the root is null, return
    if (root == NULL) {
        return;
    }

    // Traverse the left subtree
    traverse(root->left);

    // Visit the current node
    visit(root);

    // Traverse the right subtree
    traverse(root->right);
}

// Function to visit a node during traversal
void visit(struct node* root) {
    // Print the value of the node
    printf("%f\n", root->value);
}

// Function to test the BST with stress conditions
void test_bst() {
    struct node* root = NULL;
    int array_size = 1000;
    double* array = (double*)malloc(sizeof(double) * array_size);
    for (int i = 0; i < array_size; i++) {
        array[i] = i + 1.0;
    }
    for (int i = 0; i < array_size; i++) {
        root = insert(root, array[i]);
    }
    traverse(root);
}

// Function to clean up the BST and release all allocated resources
void cleanup() {
    // Release the memory for the arrays
    free(array);
    free(string_array);
    free(node_array);
}
