    // Allocate memory for the vector of doubles
    double* doubles = (double*)malloc(numDoubles * sizeof(double));
    if (!doubles) {
        printf("Error: Failed to allocate memory for the vector of doubles\n");
        return;
    }

    // Allocate memory for the vector of strings
