    if (!strings) {
        printf("Error: Failed to allocate memory for the vector of strings\n");
        free(doubles);
        return;
    }

    // Allocate memory for the vector of points
    Point* points = (Point*)malloc(numPoints * sizeof(Point));
    if (!points) {
        printf("Error: Failed to allocate memory for the vector of points\n");
        free(doubles);
        free(strings);
        return;
    }

