// Define a function to handle thread safety by using appropriate synchronization mechanisms when interacting with the external memory pool manager
void handleThreadSafety(int numDoubles, int numStrings, int numPoints) {
    // Use a mutex to ensure that only one thread can access the memory pool manager at a time
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
