        vec1[i] = rand_num / 10.0;
    }

    // Integrate the function with an external memory pool manager and data structure manager to optimize memory usage and reduce fragmentation
    int mem_pool_size = num_vectors * sizeof(double) + num_points * sizeof(point);
    char* mem_pool = (char*)malloc(mem_pool_size);
    if (!mem_pool) {
        printf("Error: Failed to allocate memory for memory pool\n");
        return;
