#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <float.h>
#include <limits.h>
#include <errno.h>
#include <assert.h>

// Define the maximum memory usage limit
#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1 GB
#define MEMORY_BUDGET 1024 * 1024 * 512 // 512 MB

// Define the range of random floating-point numbers to generate
#define RANDOM_MIN -100.0
#define RANDOM_MAX 100.0

// Define the maximum length of a string
#define MAX_STRING_LENGTH 1024

// Define the memory pool manager
struct MemoryPoolManager {
    // The total amount of memory allocated in bytes
    size_t totalAllocatedMemory;

    // The free memory available in bytes
    size_t freeMemory;

    // The utilization of the memory pool as a percentage
    double memoryUtilization;

    // The maximum memory usage limit in bytes
    size_t maxMemoryUsage;

    // The memory budget in bytes
    size_t memoryBudget;
};

// Define the data point structure
struct DataPoint {
    // The double value of the data point
    double value;

    // The string pointer of the data point
    char* string;
};

// Define the function to manage and operate on a dynamic collection of data points
void dynamicDataManager(struct MemoryPoolManager* memoryPoolManager, struct DataPoint** dataPoints, int numDataPoints) {
    // Allocate memory for the double precision floating-point numbers array
    double* values = (double*)malloc(numDataPoints * sizeof(double));
    if (!values) {
        fprintf(stderr, "Error: Failed to allocate memory for the double precision floating-point numbers array\n");
        return;
    }

    // Allocate memory for the char string pointers array
    char** strings = (char**)malloc(numDataPoints * sizeof(char*));
    if (!strings) {
        fprintf(stderr, "Error: Failed to allocate memory for the char string pointers array\n");
        free(values);
        return;
    }

    // Initialize the double precision floating-point numbers array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < numDataPoints; ++i) {
        values[i] = RANDOM_MIN + ((double)rand() / (RAND_MAX)) * (RANDOM_MAX - RANDOM_MIN);
    }

    // Initialize the char string pointers array with random strings within a specified range
    for (int i = 0; i < numDataPoints; ++i) {
        int length = rand() % MAX_STRING_LENGTH + 1;
        strings[i] = (char*)malloc(length * sizeof(char));
        if (!strings[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for the char string pointers array\n");
            free(values);
            free(strings);
            return;
        }
        for (int j = 0; j < length; ++j) {
            strings[i][j] = 'a' + rand() % ('z' - 'a');
        }
    }

    // Allocate memory for the data points array
    struct DataPoint* dataPointsArray = (struct DataPoint*)malloc(numDataPoints * sizeof(struct DataPoint));
    if (!dataPointsArray) {
        fprintf(stderr, "Error: Failed to allocate memory for the data points array\n");
        free(values);
        free(strings);
        return;
    }

    // Initialize the data points array with the double precision floating-point numbers and char string pointers arrays
    for (int i = 0; i < numDataPoints; ++i) {
        dataPointsArray[i].value = values[i];
        dataPointsArray[i].string = strings[i];
    }

    // Register the allocated memory blocks with the memory pool manager
    for (int i = 0; i < numDataPoints; ++i) {
        memoryPoolManager->totalAllocatedMemory += sizeof(struct DataPoint);
        memoryPoolManager->freeMemory -= sizeof(struct DataPoint);
        memoryPoolManager->memoryUtilization = (double)memoryPoolManager->totalAllocatedMemory / (double)memoryPoolManager->maxMemoryUsage;
    }

    // Return the data points array
    *dataPoints = dataPointsArray;
}

// Define the function to report current memory usage statistics
void reportMemoryUsage(struct MemoryPoolManager* memoryPoolManager) {
    printf("Total allocated memory: %zu bytes\n", memoryPoolManager->totalAllocatedMemory);
    printf("Free memory: %zu bytes\n", memoryPoolManager->freeMemory);
    printf("Memory pool utilization: %.2f%%\n", memoryPoolManager->memoryUtilization * 100.0);
}

// Define the function to clear all allocated resources and reset the memory pool
void clearResources(struct MemoryPoolManager* memoryPoolManager) {
    // Free the data points array
    free(*dataPoints);

    // Reset the memory pool manager
    memoryPoolManager->totalAllocatedMemory = 0;
    memoryPoolManager->freeMemory = MEMORY_BUDGET;
    memoryPoolManager->memoryUtilization = 0.0;
}

// Define the function to find and print the largest floating-point number in the data points array
void findLargestFloatingPointNumber(struct DataPoint* dataPoints, int numDataPoints) {
    double largestValue = -DBL_MAX;
    for (int i = 0; i < numDataPoints; ++i) {
        if (dataPoints[i].value > largestValue) {
            largestValue = dataPoints[i].value;
        }
    }
    printf("The largest floating-point number is: %f\n", largestValue);
}

// Define the function to find and print the longest string in the data points array
void findLongestString(struct DataPoint* dataPoints, int numDataPoints) {
    int longestLength = 0;
    for (int i = 0; i < numDataPoints; ++i) {
        if (strlen(dataPoints[i].string) > longestLength) {
            longestLength = strlen(dataPoints[i].string);
        }
    }
    printf("The longest string is: %s\n", dataPoints[longestLength].string);
}

int main() {
    // Initialize the memory pool manager
    struct MemoryPoolManager memoryPoolManager;
    memoryPoolManager.totalAllocatedMemory = 0;
    memoryPoolManager.freeMemory = MEMORY_BUDGET;
    memoryPoolManager.memoryUtilization = 0.0;
    memoryPoolManager.maxMemoryUsage = MAX_MEMORY_USAGE;
    memoryPoolManager.memoryBudget = MEMORY_BUDGET;

    // Read the number of data points from standard input
    int numDataPoints;
    scanf("%d", &numDataPoints);

    // Allocate memory for the data points array
    struct DataPoint* dataPoints;
    dynamicDataManager(&memoryPoolManager, &dataPoints, numDataPoints);

    // Find and print the largest floating-point number in the data points array
    findLargestFloatingPointNumber(dataPoints, numDataPoints);

    // Find and print the longest string in the data points array
    findLongestString(dataPoints, numDataPoints);

    // Report current memory usage statistics
    reportMemoryUsage(&memoryPoolManager);

    // Clear all allocated resources and reset the memory pool
    clearResources(&memoryPoolManager);

    return 0;
}']

