// Initialize a memory pool with a given number of blocks and block size
struct memory_pool *memory_pool_init(size_t num_blocks, size_t block_size) {
    struct memory_pool *pool = malloc(sizeof(struct memory_pool));
    if (!pool) {
        return NULL;
    }
    pool->num_blocks = num_blocks;
    pool->block_size = block_size;
    pool->blocks = calloc(num_blocks, sizeof(void*));
    if (!pool->blocks) {
