        // Register the allocated memory block with the memory pool manager
        manager->update(ptr, sizeof(data_point));
        // Update the reporting mechanism to monitor memory usage statistics
        stats->total_allocated += sizeof(data_point);
    }

    // Ensure thread safety and proper synchronization when interacting with the external memory pool manager
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Design a thread-safe mechanism for concurrent access to the memory pool, employing fine-grained locking to minimize contention and protect critical sections
    void* (*lock)(void* mutex) = &pthread_mutex_lock;
    void (*unlock)(void* mutex) = &pthread_mutex_unlock;
    void (*wait)(void* cond, void* mutex) = &pthread_cond_wait;
