    // Implement the caching strategy to enhance performance by reusing frequently accessed memory blocks
    for (int i = 0; i < num_points; ++i) {
        data[i].string = cache->cache[cache->count++];
        if (cache->count == cache->capacity) {
            cache->count = 0;
        }
    }

    // Ensure efficient handling of memory deallocations and resource cleanup, allowing for effective reuse of memory across multiple calls
    void (*dealloc)(void* ptr) = &manager->free;
    void (*cleanup)(void* ptr) = &pthread_mutex_destroy;

