```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
} Record;

// Define the memory pool manager
struct MemoryPoolManager {
    // The total amount of memory allocated in the pool
    size_t total_memory;

    // The number of free blocks in the pool
    size_t num_free_blocks;

    // The list of free blocks in the pool
    struct FreeBlock *free_blocks;
};

// Define a free block structure
struct FreeBlock {
    // The address of the free block
    void *address;

    // The size of the free block
    size_t size;

    // The next free block in the list
    struct FreeBlock *next;
};

// Define a memory pool structure
struct MemoryPool {
    // The total amount of memory allocated in the pool
    size_t total_memory;

    // The number of free blocks in the pool
    size_t num_free_blocks;

    // The list of free blocks in the pool
    struct FreeBlock *free_blocks;
};

// Define a function to allocate memory from the pool
void *allocate_memory(struct MemoryPoolManager *manager, size_t size) {
    // Check if there are any free blocks available
    if (manager->num_free_blocks == 0) {
        // If not, add a new block to the list of free blocks
        struct FreeBlock *new_block = malloc(size);
        manager->free_blocks = new_block;
        manager->num_free_blocks++;
    }

    // Get the first free block from the list
    struct FreeBlock *free_block = manager->free_blocks;

    // Remove the free block from the list
    manager->free_blocks = free_block->next;
    manager->num_free_blocks--;

    // Return the address of the free block
    return free_block->address;
}

// Define a function to deallocate memory back to the pool
void deallocate_memory(struct MemoryPoolManager *manager, void *address) {
    // Check if the address is in the list of free blocks
    struct FreeBlock *free_block = manager->free_blocks;
    while (free_block != NULL) {
        if (free_block->address == address) {
            // If it is, add it back to the list of free blocks
            free_block->next = manager->free_blocks;
            manager->free_blocks = free_block;
            manager->num_free_blocks++;
            return;
        }
        free_block = free_block->next;
    }

    // If the address is not in the list of free blocks, add it to a new block
    struct FreeBlock *new_block = malloc(size);
    new_block->address = address;
    new_block->size = size;
    new_block->next = manager->free_blocks;
    manager->free_blocks = new_block;
