void initializeArrays(size_t offsetSize, size_t keySize, size_t recordSize) {
    // Initialize random seed with current time
    srand(time(NULL));

    // Allocate memory for the three arrays
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(keySize * sizeof(int));
    Record* records = (Record*)malloc(recordSize * sizeof(Record));

    // Initialize memory pool for dynamic allocation
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->size = 1024; // Fixed size of the memory pool in bytes
    pool->data = malloc(pool->size);

    // Generate random values for offsets and keys within specified ranges
    for (int i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % 1000;
    }
    for (int i = 0; i < keySize; i++) {
        keys[i] = rand() % 1000;
    }

    // Initialize records with random values and unique keys
    for (int i = 0; i < recordSize; i++) {
        Record* record = &records[i];
        record->key = keys[i];
        record->identifier = malloc(8 * sizeof(char));
        for (int j = 0; j < 8; j++) {
            record->identifier[j] = rand() % 26 + 'a';
        }
    }

    // Sort records based on their 'int' values in ascending order
    qsort(records, recordSize, sizeof(Record), compareRecords);

    // Log skipped keys and metrics to a separate file
    FILE* logFile = fopen("log.txt", "w");
    for (int i = 0; i < recordSize; i++) {
        Record* record = &records[i];
        if (record->key == -1) {
            fprintf(logFile, "%d\n", record->key);
        }
    }
    fclose(logFile);
}

// Comparison function for sorting records based on their 'int' values
int compareRecords(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    return recordA->key - recordB->key;
}

// Custom memory pool for dynamic allocation
struct MemoryPool* createMemoryPool(size_t size) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->size = size;
    pool->data = malloc(pool->size);
    return pool;
}

// Dynamic allocation function using custom memory pool
void* allocateMemory(struct MemoryPool* pool, size_t size) {
    if (pool->size < size) {
        // Reallocate memory pool with a larger size if necessary
        pool->data = realloc(pool->data, pool->size * 2);
        pool->size *= 2;
    }
    void* data = malloc(size);
    memcpy(data, pool->data, size);
    return data;
}

// Dynamic deallocation function using custom memory pool
void freeMemory(struct MemoryPool* pool, void* data) {
    // Free the memory block and update the memory pool size
    free(data);
    pool->size -= sizeof(data);
}
