// Custom memory pool for dynamic allocation
struct MemoryPool {
    size_t size; // Size of the pool in bytes
    void* data;  // Pointer to the start of the pool
};

// Function to initialize a memory pool with a fixed size
void initMemoryPool(struct MemoryPool* pool, size_t size) {
    assert(pool != NULL);
    pool->size = size;
    pool->data = malloc(size);
}

// Function to allocate memory from the memory pool
void* allocFromPool(struct MemoryPool* pool, size_t size) {
    assert(pool != NULL && size > 0);
    if (pool->size < size) {
        return NULL;
    }
    void* ptr = pool->data;
    pool->data += size;
    pool->size -= size;
    return ptr;
}

