#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
} Record;

// Define the memory pool manager
struct MemoryPoolManager {
    // Pointer to the head of the linked list of allocated blocks
    void* head;
    // Pointer to the tail of the linked list of allocated blocks
    void* tail;
    // Number of allocated blocks
    size_t num_blocks;
};

// Define the memory pool manager functions
void initMemoryPoolManager(struct MemoryPoolManager* manager) {
    manager->head = NULL;
    manager->tail = NULL;
    manager->num_blocks = 0;
}

void registerBlock(struct MemoryPoolManager* manager, void* block) {
    // Add the new block to the end of the linked list
    if (manager->tail == NULL) {
        manager->head = block;
        manager->tail = block;
    } else {
        ((void**)manager->tail)[0] = block;
        manager->tail = block;
    }
    // Increment the number of allocated blocks
    manager->num_blocks++;
}

void deregisterBlock(struct MemoryPoolManager* manager, void* block) {
    // Remove the block from the linked list
    if (manager->head == block) {
        manager->head = ((void**)block)[0];
    } else if (manager->tail == block) {
        manager->tail = ((void**)block)[0];
    }
    // Decrement the number of allocated blocks
    manager->num_blocks--;
}

// Define the function to allocate memory for the arrays
void* allocateMemory(size_t size, struct MemoryPoolManager* manager) {
    void* block = malloc(size);
    if (block == NULL) {
        // Handle allocation failure gracefully
        return NULL;
    }
    registerBlock(manager, block);
    return block;
}

// Define the function to deallocate memory for the arrays
void deallocateMemory(void* block, struct MemoryPoolManager* manager) {
    deregisterBlock(manager, block);
    free(block);
}

// Define the function to initialize the arrays
void initArrays(int** keys, long** offsets, size_t num_keys, struct MemoryPoolManager* manager) {
    // Allocate memory for the key and offset arrays
    *keys = allocateMemory(num_keys * sizeof(int), manager);
    *offsets = allocateMemory(num_keys * sizeof(long), manager);
    if (*keys == NULL || *offsets == NULL) {
        // Handle allocation failure gracefully
        deallocateMemory(*keys, manager);
        deallocateMemory(*offsets, manager);
        return;
    }
    // Initialize the key and offset arrays
    for (size_t i = 0; i < num_keys; i++) {
        (*keys)[i] = 0;
        (*offsets)[i] = 0;
    }
}

// Define the function to set the value of each record's int field to a random value within a specified range
void setRandomValues(Record* records, size_t num_records, int lower_bound, int upper_bound) {
    // Generate a random number within the specified range for each record
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = lower_bound + rand() % (upper_bound - lower_bound);
    }
}

// Define the function to report memory usage statistics
void reportMemoryUsage(struct MemoryPoolManager* manager) {
    // Calculate the total allocated memory
    size_t total_allocated = 0;
    for (size_t i = 0; i < manager->num_blocks; i++) {
        total_allocated += ((void**)manager->head)[i];
    }
    // Calculate the free memory
    size_t free_memory = 0;
    for (size_t i = 0; i < manager->num_blocks; i++) {
        free_memory += ((void**)manager->tail)[i];
    }
    // Calculate the memory pool utilization
    size_t memory_pool_utilization = total_allocated / (total_allocated + free_memory);
    // Log the memory usage statistics
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Free memory: %zu\n", free_memory);
    printf("Memory pool utilization: %.2f%%\n", memory_pool_utilization * 100);
}

// Define the function to clear all allocated resources and reset the memory pool
void clearResources(struct MemoryPoolManager* manager) {
    // Free all allocated blocks
    for (size_t i = 0; i < manager->num_blocks; i++) {
        free(((void**)manager->head)[i]);
    }
    // Reset the memory pool manager
    initMemoryPoolManager(manager);
}

// Define the function to support multiple concurrent invocations
void* concurrentAllocateMemory(size_t size, struct MemoryPoolManager* manager) {
    void* block = malloc(size);
    if (block == NULL) {
        // Handle allocation failure gracefully
        return NULL;
    }
    registerBlock(manager, block);
    return block;
}

// Define the function to support multiple concurrent invocations
void concurrentDeallocateMemory(void* block, struct MemoryPoolManager* manager) {
    deregisterBlock(manager, block);
    free(block);
}
