#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the struct to store data
struct record {
    double value;
    char *str;
};

// Define the memory pool manager
struct mem_pool {
    void **blocks;
    size_t num_blocks;
    size_t block_size;
    pthread_mutex_t lock;
};

// Function to allocate and initialize memory for an array of struct record objects
int alloc_records(struct mem_pool *mem_pool, size_t num_records, double min_value, double max_value) {
    // Check if the input parameters are valid
    if (num_records == 0 || min_value >= max_value) {
        return -1;
    }

    // Calculate the size of each record and the total memory required
    size_t record_size = sizeof(struct record);
    size_t total_memory = num_records * record_size;

    // Allocate memory for the array of struct record objects
    void **blocks = malloc(total_memory);
    if (blocks == NULL) {
        return -1;
    }

    // Initialize each struct with a unique random double and string
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        blocks[i] = malloc(record_size);
        if (blocks[i] == NULL) {
            return -1;
        }
        struct record *record = blocks[i];
        record->value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
        char str[8];
        for (size_t j = 0; j < 7; j++) {
            str[j] = 'a' + rand() % 26;
        }
        str[7] = '\0';
        record->str = strdup(str);
    }

    // Register each allocated block with the memory pool manager
    pthread_mutex_lock(&mem_pool->lock);
    mem_pool->blocks = blocks;
    mem_pool->num_blocks = num_records;
    mem_pool->block_size = record_size;
    pthread_mutex_unlock(&mem_pool->lock);

    return 0;
}

// Function to deallocate memory for an array of struct record objects
void free_records(struct mem_pool *mem_pool) {
    // Check if the input parameters are valid
    if (mem_pool == NULL || mem_pool->blocks == NULL) {
        return;
    }

    // Deallocate each block of memory and clear the memory pool manager
    for (size_t i = 0; i < mem_pool->num_blocks; i++) {
        free(mem_pool->blocks[i]);
    }
    free(mem_pool->blocks);
    mem_pool->blocks = NULL;
    mem_pool->num_blocks = 0;
    mem_pool->block_size = 0;
}

// Function to process a list of floating-point numbers and strings read from standard input, storing them in separate arrays
void process_input(struct record *records, size_t num_records) {
    // Check if the input parameters are valid
    if (records == NULL || num_records == 0) {
        return;
    }

    // Initialize variables to store the average and most frequent string
    double sum = 0.0;
    size_t max_count = 0;
    char *most_frequent_str = NULL;

    // Read input from standard input and process each line
    while (fgets(line, sizeof(line), stdin) != NULL) {
        // Parse the line into a floating-point number and string
        double value;
        char str[8];
        if (sscanf(line, "%lf %7s", &value, str) == 2) {
            // Store the parsed values in the appropriate arrays
            records[i].value = value;
            records[i].str = strdup(str);
            i++;
        }
    }

    // Calculate the average of all valid floating-point numbers and identify the most frequent string
    for (size_t i = 0; i < num_records; i++) {
        if (!isnan(records[i].value)) {
            sum += records[i].value;
            size_t count = 1;
            for (size_t j = i + 1; j < num_records; j++) {
                if (strcmp(records[i].str, records[j].str) == 0) {
                    count++;
                }
            }
            if (count > max_count) {
                most_frequent_str = strdup(records[i].str);
                max_count = count;
            }
        }
    }

    // Print the average and most frequent string
    printf("Average: %f\n", sum / num_records);
    if (most_frequent_str != NULL) {
        printf("Most frequent string: %s\n", most_frequent_str);
    } else {
        printf("No strings found.\n");
    }
}

// Function to clear all allocated resources and reset the memory pool, enabling effective reuse of memory for subsequent operations
void reset_mem_pool(struct mem_pool *mem_pool) {
    // Check if the input parameters are valid
    if (mem_pool == NULL || mem_pool->blocks == NULL) {
        return;
    }

    // Deallocate each block of memory and clear the memory pool manager
    for (size_t i = 0; i < mem_pool->num_blocks; i++) {
        free(mem_pool->blocks[i]);
    }
    free(mem_pool->blocks);
    mem_pool->blocks = NULL;
    mem_pool->num_blocks = 0;
    mem_pool->block_size = 0;
}
