#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
#include <time.h>

// Define a complex structure with double and string fields
typedef struct {
    double value;
    char *str;
} complex_t;

// Define a point structure with x, y coordinates
typedef struct {
    int x;
    int y;
} point_t;

// Define a memory pool management system
struct mempool {
    size_t initial_size; // Initial size of the memory pool
    size_t current_size; // Current size of the memory pool
    void *memory; // Pointer to the memory pool
    pthread_mutex_t lock; // Mutex for synchronizing access to the memory pool
};

// Function to allocate and initialize arrays for double, char, and complex structures
void allocate_arrays(size_t num_doubles, size_t num_chars, size_t num_complexes) {
    // Check for integer overflow during calculation of array sizes
    if (num_doubles > SIZE_MAX / sizeof(double) ||
        num_chars > SIZE_MAX / sizeof(char) ||
        num_complexes > SIZE_MAX / sizeof(complex_t)) {
        fprintf(stderr, "Integer overflow during array size calculation\n");
        return;
    }

    // Calculate the total memory requirement for all arrays
    size_t total_size = (num_doubles * sizeof(double) + num_chars * sizeof(char) + num_complexes * sizeof(complex_t));

    // Check if the total memory requirement exceeds system limits
    struct sysinfo info;
    sysinfo(&info);
    size_t max_memory = info.totalram * info.mem_unit;
    if (total_size > max_memory) {
        fprintf(stderr, "Total memory requirement exceeds system limits\n");
        return;
    }

    // Allocate memory for the arrays
    double *doubles = malloc(num_doubles * sizeof(double));
    char **chars = malloc(num_chars * sizeof(char*));
    complex_t *complexes = malloc(num_complexes * sizeof(complex_t));

    // Initialize the arrays with random values
    for (size_t i = 0; i < num_doubles; i++) {
        doubles[i] = drand48();
    }
    for (size_t i = 0; i < num_chars; i++) {
        chars[i] = malloc(10 * sizeof(char));
        sprintf(chars[i], "%d", rand() % 10);
    }
    for (size_t i = 0; i < num_complexes; i++) {
        complexes[i].value = drand48();
        complexes[i].str = malloc(10 * sizeof(char));
        sprintf(complexes[i].str, "%d", rand() % 10);
    }

    // Initialize the memory pool with the total size of all arrays
    struct mempool pool;
    pool.initial_size = total_size;
    pool.current_size = total_size;
    pool.memory = malloc(total_size);
    pthread_mutex_init(&pool.lock, NULL);

    // Populate the memory pool with random values
    for (size_t i = 0; i < num_doubles; i++) {
        double *ptr = (double*)pool.memory + i * sizeof(double);
        *ptr = drand48();
    }
    for (size_t i = 0; i < num_chars; i++) {
        char **ptr = (char**)pool.memory + i * sizeof(char*);
        ptr[i] = malloc(10 * sizeof(char));
        sprintf(ptr[i], "%d", rand() % 10);
    }
    for (size_t i = 0; i < num_complexes; i++) {
        complex_t *ptr = (complex_t*)pool.memory + i * sizeof(complex_t);
        ptr->value = drand48();
        ptr->str = malloc(10 * sizeof(char));
        sprintf(ptr->str, "%d", rand() % 10);
    }
}

// Function to populate each complex structure's double value with a random number generated within a specified range
void populate_complexes(double lower_bound, double upper_bound) {
    // Check if the input parameters are valid
    if (lower_bound > upper_bound || lower_bound < 0 || upper_bound < 0) {
        fprintf(stderr, "Invalid input range\n");
        return;
    }

    // Populate each complex structure's double value with a random number within the specified range
    for (size_t i = 0; i < num_complexes; i++) {
        complexes[i].value = lower_bound + drand48() * (upper_bound - lower_bound);
    }
}

// Function to clear all allocated resources and reset the memory pool
void clear_resources() {
    // Free all dynamically allocated memory
    free(doubles);
    for (size_t i = 0; i < num_chars; i++) {
        free(chars[i]);
    }
    free(complexes);

    // Reset the memory pool for new allocations
    pthread_mutex_destroy(&pool.lock);
    free(pool.memory);
}

// Function to display memory usage statistics
void report_usage() {
    // Calculate total allocated memory and free memory
    size_t total_allocated = num_doubles * sizeof(double) + num_chars * sizeof(char*) + num_complexes * sizeof(complex_t);
    size_t total_free = 0;
    for (size_t i = 0; i < num_chars; i++) {
        total_free += strlen(chars[i]);
    }

    // Calculate memory pool utilization
    size_t pool_utilized = pool.current_size - total_free;

    // Print the memory usage statistics
    printf("Total allocated memory: %zu\n", total_allocated);
    printf("Total free memory: %zu\n", total_free);
    printf("Memory pool utilization: %zu\n", pool_utilized);
}
