void init_sensors(int num_sensors, float min_voltage, float max_voltage) {
    // Allocate memory for the arrays
    int *sensor_indices = malloc(num_sensors * sizeof(int));
    float *voltage_readings = malloc(num_sensors * sizeof(float));
    char *sensor_types = malloc(num_sensors * sizeof(char) * 10);
    struct sensor_info *sensor_infos = malloc(num_sensors * sizeof(struct sensor_info));

    // Check for memory allocation failures
    if (sensor_indices == NULL || voltage_readings == NULL || sensor_types == NULL || sensor_infos == NULL) {
        printf("Error: Failed to allocate memory for arrays\n");
        return;
    }

    // Set the initial values of the arrays
    for (int i = 0; i < num_sensors; i++) {
        // Generate a random voltage reading within the specified range
        float voltage = min_voltage + ((float)rand() / RAND_MAX) * (max_voltage - min_voltage);
        // Assign a unique sensor type to each sensor
        char type[10];
        sprintf(type, "Sensor %d", i);
        // Populate the index with a sequential number
        int index = i;

        // Store the values in the arrays
        sensor_indices[i] = index;
        voltage_readings[i] = voltage;
        strcpy(sensor_types[i], type);
        sensor_infos[i].voltage = voltage;
        sensor_infos[i].type = type;
        sensor_infos[i].index = index;
    }

    // Free the memory allocated for the arrays
    free(sensor_indices);
    free(voltage_readings);
    free(sensor_types);
    free(sensor_infos);
}
