    // Increment each value by a reproducibly generated random number within a specified range
    for (size_t i = 0; i < n; i++) {
        records[i].value += rand() % 10 + 1;
    }

    // Register the arrays with the memory pool manager, promoting efficient memory management
    mp->data = offsets;
    mp->used += sizeof(long) * n;
    mp->data = keys;
    mp->used += sizeof(int) * n;
    mp->data = records;
    mp->used += sizeof(record_t) * n;

    // Return the memory pool manager and the arrays of long integers, integers, and records
    return mp;
}

// Function to free all allocated resources and reset the memory pool for subsequent calls
void free_flexible_data_structure(void* data) {
