        struct mempool* mp = data;
        printf("Total allocated memory: %zu\n", mp->capacity);
        printf("Free memory: %zu\n", mp->capacity - mp->used);
        printf("Memory pool utilization: %.2f%%\n", (double)mp->used / mp->capacity * 100);
    }
}

// Function to clear all allocated resources and reset the memory pool for subsequent calls
void clear_flexible_data_structure(void* data) {
    if (data) {
        struct mempool* mp = data;
        free(mp->data); // Free the memory pool
        mp->used = 0; // Reset the used memory to zero
        mp->data = malloc(mp->capacity); // Allocate a new memory pool
    }
}
