#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/mman.h>
#include <pthread.h>

// Define the structs for records and metadata
struct record {
    float value;
    char label;
    struct metadata *metadata;
};

struct metadata {
    int origin; // 0 for file1, 1 for file2
    int ref_count;
};

// Define the memory pool parameters
#define POOL_SIZE (1 << 20) // 1 MB
#define MIN_FREE_BLOCKS 5
#define MAX_FREE_BLOCKS 10

// Define the file names and their sizes
const char *file1 = "file1.txt";
const char *file2 = "file2.txt";
size_t file1_size, file2_size;

// Define the memory pool and its management functions
void *pool;
int free_blocks;
pthread_mutex_t pool_lock;

// Initialize the memory pool and allocate memory for the arrays
void init_memory_pool() {
    // Allocate a large block of memory for the pool
    pool = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Initialize the free block count and lock
    free_blocks = MAX_FREE_BLOCKS;
    pthread_mutex_init(&pool_lock, NULL);
}

// Allocate memory from the pool
void *allocate(size_t size) {
    // Lock the pool to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Check if there are enough free blocks available
    if (free_blocks < MIN_FREE_BLOCKS) {
        // If not, try to compact the pool and allocate again
        compact_pool();
        if (free_blocks < MIN_FREE_BLOCKS) {
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
    }

    // Allocate a block from the pool and update the free block count
    void *ptr = pool + sizeof(struct metadata) * free_blocks++;
    pthread_mutex_unlock(&pool_lock);

    // Return the allocated memory
    return ptr;
}

// Deallocate memory back to the pool
void deallocate(void *ptr) {
    // Lock the pool to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Find the corresponding metadata structure and decrement its reference count
    struct metadata *metadata = (struct metadata *)((char *)ptr - sizeof(struct metadata));
    if (--metadata->ref_count == 0) {
        // If the reference count is zero, add the block back to the free list
        free_blocks++;
    }

    pthread_mutex_unlock(&pool_lock);
}

// Compact the pool by merging adjacent free blocks
void compact_pool() {
    // Lock the pool to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Merge adjacent free blocks and update the free block count
    size_t i, j;
    for (i = 0, j = 1; j < free_blocks; j++) {
        if (((char *)pool + sizeof(struct metadata) * i) == ((char *)pool + sizeof(struct metadata) * j)) {
            // If the blocks are adjacent, merge them and update the reference count
            struct metadata *metadata = (struct metadata *)((char *)pool + sizeof(struct metadata) * i);
            metadata->ref_count += 1;
        } else {
            // If the blocks are not adjacent, copy the block to a new location and update the reference count
            memcpy((char *)pool + sizeof(struct metadata) * i, (char *)pool + sizeof(struct metadata) * j, sizeof(struct metadata));
            struct metadata *metadata = (struct metadata *)((char *)pool + sizeof(struct metadata) * i);
            metadata->ref_count = 1;
        }
    }
    free_blocks = j;

    pthread_mutex_unlock(&pool_lock);
}

// Read the input files and populate the arrays
void read_files(const char *file1, const char *file2) {
    // Open the files for reading
    FILE *fp1 = fopen(file1, "r");
    if (fp1 == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    FILE *fp2 = fopen(file2, "r");
    if (fp2 == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Get the file sizes
    fseek(fp1, 0, SEEK_END);
    file1_size = ftell(fp1);
    rewind(fp1);
    fseek(fp2, 0, SEEK_END);
    file2_size = ftell(fp2);
    rewind(fp2);

    // Allocate memory for the arrays
    float *values1 = (float *)allocate(file1_size * sizeof(float));
    char *labels1 = (char *)allocate(file1_size * sizeof(char));
    struct record *records1 = (struct record *)allocate(file1_size * sizeof(struct record));
    float *values2 = (float *)allocate(file2_size * sizeof(float));
    char *labels2 = (char *)allocate(file2_size * sizeof(char));
    struct record *records2 = (struct record *)allocate(file2_size * sizeof(struct record));

    // Read the files and populate the arrays
    size_t i, j;
    for (i = 0; i < file1_size; i++) {
        fscanf(fp1, "%f %c", &values1[i], &labels1[i]);
        records1[i].value = values1[i];
        records1[i].label = labels1[i];
        records1[i].metadata = (struct metadata *)allocate(sizeof(struct metadata));
        records1[i].metadata->origin = 0;
        records1[i].metadata->ref_count = 1;
    }
    for (j = 0; j < file2_size; j++) {
        fscanf(fp2, "%f %c", &values2[j], &labels2[j]);
        records2[j].value = values2[j];
        records2[j].label = labels2[j];
        records2[j].metadata = (struct metadata *)allocate(sizeof(struct metadata));
        records2[j].metadata->origin = 1;
        records2[j].metadata->ref_count = 1;
    }

    // Close the files and return the arrays
    fclose(fp1);
    fclose(fp2);
}

// Process the data in parallel using multiple threads
void process_data() {
    // Create a thread pool for processing the data
    pthread_t *threads = (pthread_t *)allocate(sizeof(pthread_t) * 4);
    size_t i;
    for (i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, process_data_thread, NULL);
    }

    // Wait for all threads to complete and clean up
    for (i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    deallocate(threads);
}

// Process the data in a single thread
void process_data_thread() {
    // Allocate memory for the arrays
    float *values1 = (float *)allocate(file1_size * sizeof(float));
    char *labels1 = (char *)allocate(file1_size * sizeof(char));
    struct record *records1 = (struct record *)allocate(file1_size * sizeof(struct record));
    float *values2 = (float *)allocate(file2_size * sizeof(float));
    char *labels2 = (char *)allocate(file2_size * sizeof(char));
    struct record *records2 = (struct record *)allocate(file2_size * sizeof(struct record));

    // Read the files and populate the arrays
    read_files(file1, file2);

    // Process the data in parallel using multiple threads
    size_t i;
    for (i = 0; i < file1_size; i++) {
        // Perform any necessary processing on the records
        records1[i].value = process_record(records1[i]);
        records2[i].value = process_record(records2[i]);
    }

    // Clean up the memory and return
    deallocate(values1);
    deallocate(labels1);
    deallocate(records1);
    deallocate(values2);
    deallocate(labels2);
    deallocate(records2);
}

// Process a single record and return the processed value
float process_record(struct record *record) {
    // Perform any necessary processing on the record
    float processed_value = record->value;
    return processed_value;
}

int main() {
    init_memory_pool();
    read_files(file1, file2);
    process_data();
    return 0;
}
