    void **blocks;
    // Number of allocated blocks
    int num_blocks;
    // Size of each block in bytes
    size_t block_size;
};

// Define a function to initialize the memory pool manager
void init_mempool(struct mempool_manager *mgr, size_t block_size) {
    mgr->blocks = NULL;
    mgr->num_blocks = 0;
    mgr->block_size = block_size;
}

// Define a function to allocate memory from the memory pool manager
void *allocate(struct mempool_manager *mgr, size_t size) {
    // Check if there is enough space in the current block
    if (mgr->blocks[mgr->num_blocks - 1] + mgr->block_size >= size) {
        return mgr->blocks[mgr->num_blocks - 1];
    }

    // Allocate a new block if necessary
    void *new_block = malloc(size);
    if (new_block == NULL) {
        return NULL;
    }

    // Register the new block with the memory pool manager
    mgr->blocks[mgr->num_blocks] = new_block;
    mgr->num_blocks++;

    return new_block;
}

// Define a function to deallocate memory from the memory pool manager
void deallocate(struct mempool_manager *mgr, void *ptr) {
    // Find the index of the block containing the given pointer
    int i = 0;
    while (i < mgr->num_blocks && mgr->blocks[i] != ptr) {
        i++;
    }

    // If the pointer is not found, return
    if (i == mgr->num_blocks) {
        return;
    }

    // Deallocate the block and update the memory pool manager
