// Define the struct for the buckets
typedef struct bucket {
    int *count;
    float *weight;
    size_t size;
    double average;
} bucket_t;

bucket_t* create_buckets(int *counts, float *weights, size_t threshold) {
    // Get the number of buckets to allocate
    int num_buckets = 0;
    while (num_buckets < counts && *(counts + num_buckets) <= threshold) {
        num_buckets++;
    }

    // Allocate memory for the bucket array and initialize it
    bucket_t *buckets = malloc(sizeof(bucket_t) * num_buckets);
    if (!buckets) {
        return NULL;
    }
    memset(buckets, 0, sizeof(bucket_t) * num_buckets);

    // Allocate memory for the count and weight arrays in each bucket
    int i = 0;
    while (i < num_buckets) {
        buckets[i].count = malloc(sizeof(int) * (*(counts + i)));
        if (!buckets[i].count) {
            free_buckets(buckets, i);
            return NULL;
        }
        memcpy(buckets[i].count, counts + i, sizeof(int) * (*(counts + i)));

        buckets[i].weight = malloc(sizeof(float) * (*(weights + i)));
        if (!buckets[i].weight) {
            free_buckets(buckets, i);
            return NULL;
        }
        memcpy(buckets[i].weight, weights + i, sizeof(float) * (*(weights + i)));

        buckets[i].size = sizeof(int) * (*(counts + i)) + sizeof(float) * (*(weights + i));

        // Compute the average for each bucket
        int j = 0;
        double sum = 0.0;
        while (j < *(counts + i)) {
            sum += weights[i + j];
            j++;
        }
        buckets[i].average = sum / (*(counts + i));

        i++;
    }

    return buckets;
}

void free_buckets(bucket_t *buckets, int num_buckets) {
    // Free the memory for each bucket
    int i = 0;
    while (i < num_buckets) {
        free(buckets[i].count);
        free(buckets[i].weight);
        i++;
    }
    // Free the memory for the bucket array
    free(buckets);
}
