    if (!strings) {
        printf("Error: Failed to allocate memory for strings\n");
        exit(1);
    }

    // Allocate memory for the binary search tree nodes
    struct node *nodes = malloc(num_nodes * sizeof(struct node));
    if (!nodes) {
        printf("Error: Failed to allocate memory for nodes\n");
        exit(1);
    }

    // Initialize the arrays with default values
