            printf("Error: Failed to allocate memory for string %zu\n", i);
            exit(1);
        }
        memset(strings[i], 0, 256 * sizeof(char));
    }
    for (size_t i = 0; i < num_nodes; i++) {
        nodes[i].value = 0.0;
        nodes[i].key = NULL;
        nodes[i].left = NULL;
        nodes[i].right = NULL;
    }
}

// Define the function to insert a new node into the binary search tree
void insert_node(struct node *root, struct node *new_node) {
    // If the root is NULL, set it to the new node and return
    if (!root) {
        root = new_node;
        return;
    }

    // If the new node's value is less than the root's value, insert it as the left child
    if (new_node->value < root->value) {
        if (root->left) {
            insert_node(root->left, new_node);
        } else {
            root->left = new_node;
        }
    // If the new node's value is greater than the root's value, insert it as the right child
    } else if (new_node->value > root->value) {
        if (root->right) {
            insert_node(root->right, new_node);
        } else {
            root->right = new_node;
        }
    // If the new node's value is equal to the root's value, set it as a duplicate and return
    } else {
        printf("Error: Duplicate value %f\n", new_node->value);
        exit(1);
    }
}

// Define the function to register memory with the memory pool
void register_memory(struct mem_pool *pool, void *data) {
    // If the data is NULL, return
    if (!data) {
        return;
    }

    // Allocate memory for the new block in the memory pool
    struct mem_block *new_block = malloc(sizeof(struct mem_block));
    if (!new_block) {
        printf("Error: Failed to allocate memory for new block\n");
        exit(1);
    }

    // Set the data pointer and size of the new block
    new_block->data = data;
    new_block->size = pool->size;

    // Add the new block to the end of the memory pool's linked list
    struct mem_block *last_block = pool->head;
    while (last_block->next) {
        last_block = last_block->next;
    }
    last_block->next = new_block;
}

// Define the function to handle memory registration and tracking automatically
void auto_register(struct mem_pool *pool, void *data, size_t size) {
    // If the data is NULL or the size is 0, return
    if (!data || !size) {
        return;
    }

    // Allocate memory for the new block in the memory pool
    struct mem_block *new_block = malloc(sizeof(struct mem_block));
    if (!new_block) {
        printf("Error: Failed to allocate memory for new block\n");
        exit(1);
    }

    // Set the data pointer and size of the new block
    new_block->data = data;
    new_block->size = size;

    // Add the new block to the end of the memory pool's linked list
    struct mem_block *last_block = pool->head;
    while (last_block->next) {
        last_block = last_block->next;
    }
    last_block->next = new_block;
}

// Define the function to handle memory cleanup and resetting of the memory pool
void cleanup(struct mem_pool *pool) {
    // If the pool is NULL, return
    if (!pool) {
        return;
    }

    // Free all blocks in the linked list
    struct mem_block *current_block = pool->head;
    while (current_block) {
        free(current_block->data);
        current_block = current_block->next;
    }

    // Reset the memory pool's head pointer to NULL
    pool->head = NULL;
}

// Define the function to handle logging of memory usage and operations
void log_memory(struct mem_pool *pool, char *message) {
    // If the pool is NULL or the message is NULL, return
    if (!pool || !message) {
        return;
    }

    // Print the message to the console
    printf("%s\n", message);
}
