};

// Define a function to insert new nodes into the linked list
void insert_node(struct node **head, int key) {
    // Allocate memory for the new node
    struct node *new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Error: failed to allocate memory for new node\n");
        return;
    }

    // Set the key and string fields of the new node
    new_node->key = key;
    new_node->string = malloc(sizeof(char) * 10);
    if (new_node->string == NULL) {
        printf("Error: failed to allocate memory for string\n");
        free(new_node);
        return;
    }
    sprintf(new_node->string, "Node %d", key);

    // Insert the new node into the linked list
    new_node->next = *head;
    *head = new_node;
}

// Define a function to set the value of each node's integer key and double value to a random value within a specified range
void set_random_values(struct node **head, int lower_bound, int upper_bound) {
    // Set the seed for the random number generator
    srand(time(NULL));

    // Loop through each node in the linked list and set its key and value to a random value within the specified range
    struct node *current = *head;
    while (current != NULL) {
        current->key = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        current->value = (double)rand() / RAND_MAX;
        current = current->next;
    }
}

// Define a function to allocate memory for and initialize an array of 'record' structures, where each record contains a single 'int' value
struct record *allocate_records(int num_records) {
    // Allocate memory for the array of records
    struct record *records = malloc(sizeof(struct record) * num_records);
    if (records == NULL) {
        printf("Error: failed to allocate memory for records\n");
        return NULL;
    }

    // Set the value of each record's int field to a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    return records;
}

// Define a function to integrate the function with an external data structure manager that handles memory pooling to optimize memory usage and reduce fragmentation
void integrate_with_manager(struct node **head, struct record *records) {
    // Register each allocated block of memory with the manager
    struct node *current = *head;
    while (current != NULL) {
        current->string = malloc(sizeof(char) * 10);
        if (current->string == NULL) {
            printf("Error: failed to allocate memory for string\n");
            return;
        }
        sprintf(current->string, "Node %d", current->key);
        current = current->next;
    }

    // Register each allocated block of memory with the manager
    struct record *record_current = records;
    while (record_current != NULL) {
        record_current->value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        record_current = record_current->next;
    }
}
