        // Remove the allocated block from the free list and add it to the used list
        struct MemoryBlock* new_used_list = this->used_list;
        while (new_used_list != NULL && new_used_list->next != block) {
            new_used_list = new_used_list->next;
        }
        if (new_used_list == NULL) {
            this->used_list = block;
        } else {
            new_used_list->next = block->next;
        }
        block->next = NULL;
