#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Node structure for the linked list
typedef struct node {
    int key;
    long value;
    struct node* next;
} node_t;

// Linked list structure
typedef struct linked_list {
    node_t* head;
    size_t size;
} linked_list_t;

// Function to insert a new node into the list at a specified position
void insert_node(linked_list_t* list, int key, long value, size_t pos) {
    // Check if the list is empty or if the position is valid
    if (list->head == NULL || pos > list->size) {
        return;
    }

    // Allocate memory for the new node
    node_t* new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node with the given key and value
    new_node->key = key;
    new_node->value = value;

    // If the position is 0, insert at the head of the list
    if (pos == 0) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        // Find the node before the specified position and insert after it
        node_t* prev_node = find_node(list, pos - 1);
        if (prev_node == NULL) {
            free(new_node);
            return;
        }
        new_node->next = prev_node->next;
        prev_node->next = new_node;
    }

    // Update the size of the list
    list->size++;
}

// Function to find a node in the list by its position
node_t* find_node(linked_list_t* list, size_t pos) {
    if (pos >= list->size) {
        return NULL;
    }

    // Start from the head of the list and iterate until we reach the specified position
    node_t* current = list->head;
    for (size_t i = 0; i < pos; i++) {
        current = current->next;
    }

    return current;
}

// Function to delete a node from the list by its key
void delete_node(linked_list_t* list, int key) {
    // Find the node with the given key and remove it from the list
    node_t* node = find_node(list, key);
    if (node == NULL) {
        return;
    }

    // Update the next pointer of the previous node to skip over the deleted node
    node_t* prev_node = find_node(list, key - 1);
    if (prev_node != NULL) {
        prev_node->next = node->next;
    } else {
        list->head = node->next;
    }

    // Free the memory of the deleted node
    free(node);

    // Update the size of the list
    list->size--;
}

// Function to print all nodes in the list
void print_list(linked_list_t* list) {
    if (list->head == NULL) {
        printf("List is empty\n");
        return;
    }

    // Start from the head of the list and iterate until we reach the end
    node_t* current = list->head;
    while (current != NULL) {
        printf("%d: %ld\n", current->key, current->value);
        current = current->next;
    }
}

int main() {
    // Create a new linked list
    linked_list_t* list = malloc(sizeof(linked_list_t));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }
    list->head = NULL;
    list->size = 0;

    // Insert nodes into the list at various positions
    insert_node(list, 1, 100, 0);
    insert_node(list, 2, 200, 1);
    insert_node(list, 3, 300, 2);
    insert_node(list, 4, 400, 3);
    insert_node(list, 5, 500, 4);

    // Print all nodes in the list
    print_list(list);

    // Delete a node from the list by its key
    delete_node(list, 2);

    // Print all nodes in the list again
    print_list(list);

    // Free the memory of the linked list
    free(list);

    return 0;
}
