// Custom memory pool manager for thread-safe allocation and deallocation of records
struct MemoryPool {
    size_t capacity; // Total capacity of the memory pool
    size_t used; // Used memory in the pool
    pthread_mutex_t mutex; // Mutex to protect concurrent access
    void* data; // Pointer to the start of the memory pool
};

// Record structure for storing integer values
struct Record {
    int value;
};

// Function to allocate and initialize an array of records
struct Record* allocate_records(size_t num_records, size_t record_size) {
