    for (size_t i = 0; i < num_records; i++) {
        struct Record* record = data + i * record_size;
        record->value = rand() % MAX_VALUE;
    }

    // Return the allocated records
    return data;
}

// Function to deallocate and clear all allocated resources
void clear_resources(struct MemoryPool* pool) {
    // Check if the memory pool is valid
    if (pool == NULL) {
        return;
    }

    // Lock the mutex to protect concurrent access
    pthread_mutex_lock(&pool->mutex);

    // Deallocate the memory pool
    free(pool->data);

    // Reset the used memory and capacity
    pool->used = 0;
    pool->capacity = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&pool->mutex);
}

// Function to report the current memory usage statistics
void report_memory_usage(struct MemoryPool* pool) {
    // Check if the memory pool is valid
    if (pool == NULL) {
        return;
    }

    // Lock the mutex to protect concurrent access
    pthread_mutex_lock(&pool->mutex);

    // Print the current memory usage statistics
    printf("Total allocated memory: %zu\n", pool->used);
    printf("Free memory: %zu\n", pool->capacity - pool->used);
    printf("Memory pool utilization: %.2f%%\n", (float)pool->used / pool->capacity * 100);

    // Unlock the mutex
    pthread_mutex_unlock(&pool->mutex);
}

// Function to handle potential race conditions and deadlocks effectively
