#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define a structure to represent a record
typedef struct {
    long offset;
    int key;
} Record;

// Define a structure to represent a dataset
typedef struct {
    int num_records;
    int size_limit;
    int random_seed;
    Record* records;
} Dataset;

// Define a memory pool manager
struct MemoryPoolManager {
    // Array of allocated memory blocks
    void** blocks;
    // Number of allocated blocks
    int num_blocks;
    // Size of each block
    size_t block_size;
    // Mutex for synchronizing access to the pool
    pthread_mutex_t mutex;
};

// Define a function to allocate memory from the pool
void* allocate(struct MemoryPoolManager* manager, size_t size) {
    void* ptr = NULL;
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);
    // Check if there are any available blocks in the pool
    if (manager->num_blocks > 0) {
        // Find the first available block and allocate memory from it
        ptr = manager->blocks[0];
        manager->blocks[0] = NULL;
        --manager->num_blocks;
    } else {
        // Allocate a new block if there are no available blocks in the pool
        ptr = malloc(size);
    }
    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&manager->mutex);
    return ptr;
}

// Define a function to deallocate memory back to the pool
void deallocate(struct MemoryPoolManager* manager, void* ptr) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);
    // Add the deallocated block to the available blocks in the pool
    manager->blocks[manager->num_blocks++] = ptr;
    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&manager->mutex);
}

// Define a function to initialize the memory pool manager
void init_memory_pool(struct MemoryPoolManager* manager, size_t block_size) {
    // Initialize the mutex for synchronizing access to the pool
    pthread_mutex_init(&manager->mutex, NULL);
    // Allocate an array of pointers to hold the available blocks in the pool
    manager->blocks = malloc(sizeof(void*) * 1024);
    // Set the number of allocated blocks to zero
    manager->num_blocks = 0;
    // Set the size of each block
    manager->block_size = block_size;
}

// Define a function to destroy the memory pool manager
void destroy_memory_pool(struct MemoryPoolManager* manager) {
    // Free the array of pointers holding the available blocks in the pool
    free(manager->blocks);
    // Destroy the mutex for synchronizing access to the pool
    pthread_mutex_destroy(&manager->mutex);
}

// Define a function to manage memory for multiple datasets
void manage_memory(struct MemoryPoolManager* manager, int num_datasets, size_t dataset_size, int random_seed) {
    // Allocate an array of pointers to hold the allocated datasets
    Dataset** datasets = malloc(sizeof(Dataset*) * num_datasets);
    // Initialize each dataset with a random seed and size limit
    for (int i = 0; i < num_datasets; ++i) {
        datasets[i] = malloc(sizeof(Dataset));
        datasets[i]->random_seed = random_seed + i;
        datasets[i]->size_limit = dataset_size;
    }
    // Allocate memory for each dataset's record array
    for (int i = 0; i < num_datasets; ++i) {
        datasets[i]->records = allocate(manager, sizeof(Record) * datasets[i]->size_limit);
    }
    // Populate each record with a random integer within the specified range
    for (int i = 0; i < num_datasets; ++i) {
        for (int j = 0; j < datasets[i]->size_limit; ++j) {
            datasets[i]->records[j].offset = rand_r(&datasets[i]->random_seed);
            datasets[i]->records[j].key = rand_r(&datasets[i]->random_seed);
        }
    }
    // Integrate with the external memory pool manager
    for (int i = 0; i < num_datasets; ++i) {
        register_memory(manager, datasets[i]->records, sizeof(Record) * datasets[i]->size_limit);
    }
    // Minimize memory allocations and deallocations by reusing available memory within the pool
    for (int i = 0; i < num_datasets; ++i) {
        for (int j = 0; j < datasets[i]->size_limit; ++j) {
            if (datasets[i]->records[j].offset == NULL) {
                datasets[i]->records[j].offset = allocate(manager, sizeof(Record));
            }
        }
    }
    // Ensure thread safety when accessing the memory pool and updating shared resources
    for (int i = 0; i < num_datasets; ++i) {
        pthread_mutex_lock(&manager->mutex);
        datasets[i]->records = realloc(datasets[i]->records, sizeof(Record) * datasets[i]->size_limit);
        pthread_mutex_unlock(&manager->mutex);
    }
    // Provide detailed memory usage statistics after function execution
    printf("Total allocated memory: %zu\n", manager->num_blocks * manager->block_size);
    printf("Free memory: %zu\n", manager->num_blocks * manager->block_size - (manager->num_blocks - 1) * sizeof(void*));
    printf("Memory pool utilization: %.2f%%\n", (float)(manager->num_blocks * manager->block_size) / (float)(manager->num_blocks * manager->block_size + num_datasets * dataset_size) * 100);
    // Iterate over each allocated block and print its allocation time, lifetime, and last accessed timestamp
    for (int i = 0; i < manager->num_blocks; ++i) {
        printf("Block %d: Allocation time: %ld, Lifetime: %ld, Last accessed: %ld\n", i, manager->blocks[i]->allocation_time, manager->blocks[i]->lifetime, manager->blocks[i]->last_accessed);
    }
    // Clear all allocated resources and reset the memory pool for concurrent data set processing
    destroy_memory_pool(manager);
    init_memory_pool(manager, block_size);
}

// Define a function to clear all allocated resources and reset the memory pool for concurrent data set processing
void reset_memory_pool(struct MemoryPoolManager* manager) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&manager->mutex);
    // Free all allocated blocks in the pool
    for (int i = 0; i < manager->num_blocks; ++i) {
        free(manager->blocks[i]);
    }
    // Reset the number of allocated blocks to zero
    manager->num_blocks = 0;
    // Unlock the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&manager->mutex);
}

