int allocate_memory(size_t num_readings, size_t num_timestamps, size_t num_sensor_states) {
    // Validate input parameters
    if (num_readings == 0 || num_timestamps == 0 || num_sensor_states == 0) {
        return -1;
    }

    // Allocate memory for the arrays
    double* readings = malloc(sizeof(double) * num_readings);
    time_t* timestamps = malloc(sizeof(time_t) * num_timestamps);
    struct sensor_state* sensor_states = malloc(sizeof(struct sensor_state) * num_sensor_states);

    // Check for memory allocation failures
    if (readings == NULL || timestamps == NULL || sensor_states == NULL) {
        free(readings);
        free(timestamps);
        free(sensor_states);
        return -1;
    }

    // Initialize the arrays with default values
