        sensor_states[i].sensor3 = 0;
        sensor_states[i].sensor4 = 0;
        sensor_states[i].sensor5 = 0;
    }

    // Initialize the custom memory pool manager
    struct MemoryPool* mempool = malloc(sizeof(struct MemoryPool));
    if (mempool == NULL) {
        free(readings);
        free(timestamps);
        free(sensor_states);
        return -1;
    }
    mempool->capacity = num_readings + num_timestamps + num_sensor_states;
    mempool->used = 0;
    mempool->buffer = malloc(mempool->capacity * sizeof(void*));
    if (mempool->buffer == NULL) {
        free(mempool);
        free(readings);
        free(timestamps);
        free(sensor_states);
        return -1;
    }

    // Allocate memory for the arrays within the custom memory pool manager
