    readings = (double*)mempool->buffer + mempool_index;
    mempool_index += num_readings * sizeof(double);
    timestamps = (time_t*)mempool->buffer + mempool_index;
    mempool_index += num_timestamps * sizeof(time_t);
    sensor_states = (struct sensor_state*)mempool->buffer + mempool_index;
    mempool->used += num_readings + num_timestamps + num_sensor_states;

    // Return the allocated memory and custom memory pool manager
    return 0;
}

// Function to deallocate memory for arrays of double values, timestamps, and sensor states
void deallocate_memory(double* readings, time_t* timestamps, struct sensor_state* sensor_states) {
