using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public static class RecordManager
{
    public static void AllocateAndInitializeRecords(int numRecords, long minOffset, long maxOffset, int keyRange, string dataSource)
    {
        // Validate input parameters
        if (numRecords < 1 || minOffset < 0 || maxOffset < 0 || keyRange < 1 || dataSource == null)
        {
            throw new ArgumentException("Invalid input parameter");
        }

        // Create a random seed based on the current time
        Random rand = new Random(DateTime.Now.Millisecond);

        // Allocate memory for records and initialize them
        Record[] records = new Record[numRecords];
        for (int i = 0; i < numRecords; i++)
        {
            long offset = rand.NextLong(minOffset, maxOffset);
            int key = rand.NextInt(keyRange);
            records[i] = new Record(offset, key);
        }

        // Parse the XML document and find the first element matching the specified name
        XmlDocument doc = new XmlDocument();
        doc.Load(dataSource);
        XPathNavigator nav = doc.CreateNavigator();
        XPathExpression expr = nav.Compile("//" + "record");
        XPathNodeIterator iter = nav.Select(expr);
        if (iter.Count == 0)
        {
            throw new Exception("No element found in the XML document");
        }
        else if (iter.Count > 1)
        {
            throw new Exception("Multiple elements found in the XML document");
        }

        // Create a new directory with the given name and set an environment variable to its path
        string dirName = "records";
        DirectoryInfo dir = Directory.CreateDirectory(dirName);
        Environment.SetEnvironmentVariable("RECORDS_DIR", dir.FullName);

        // Write records to file
        foreach (Record record in records)
        {
            File.WriteAllText(Path.Combine(dir.FullName, $"{record.Key}.txt"), record.Offset.ToString());
        }
    }
}

public class Record
{
    public long Offset { get; set; }
    public int Key { get; set; }

    public Record(long offset, int key)
    {
        this.Offset = offset;
        this.Key = key;
    }
}
