#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <mysql/mysql.h>

// Define the configuration file path and connection pool size limits
#define CONFIG_FILE_PATH "/path/to/config.ini"
#define MIN_CONN_POOL_SIZE 5
#define MAX_CONN_POOL_SIZE 100

// Define the connection health check interval (in seconds)
#define HEALTH_CHECK_INTERVAL 30

// Define the logging level (0 - none, 1 - error, 2 - warning, 3 - info, 4 - debug)
#define LOGGING_LEVEL 3

// Define the connection pool structure
typedef struct {
    int size; // Current size of the connection pool
    int min_size; // Minimum size of the connection pool
    int max_size; // Maximum size of the connection pool
    int active_connections; // Number of active connections in the pool
    int idle_connections; // Number of idle connections in the pool
    pthread_mutex_t mutex; // Mutex for protecting the connection pool
} conn_pool_t;

// Define the connection structure
typedef struct {
    MYSQL *conn; // MySQL connection handle
    int active; // Whether the connection is active or not
} conn_t;

// Initialize the connection pool
void init_conn_pool(conn_pool_t *pool) {
    // Read the configuration file and set the minimum and maximum connection pool sizes
    FILE *config = fopen(CONFIG_FILE_PATH, "r");
    if (config == NULL) {
        printf("Error: unable to open configuration file\n");
        exit(1);
    }
    char line[256];
    while (fgets(line, sizeof(line), config)) {
        if (strncmp(line, "min_conn_pool_size", 17) == 0) {
            pool->min_size = atoi(line + 18);
        } else if (strncmp(line, "max_conn_pool_size", 17) == 0) {
            pool->max_size = atoi(line + 18);
        }
    }
    fclose(config);

    // Initialize the connection pool with the minimum size
    pool->size = pool->min_size;
    pool->active_connections = 0;
    pool->idle_connections = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    // Create the initial connections in the pool
    for (int i = 0; i < pool->size; i++) {
        conn_t *conn = malloc(sizeof(conn_t));
        conn->active = 1;
        conn->conn = mysql_init(NULL);
        if (mysql_real_connect(conn->conn, "localhost", "username", "password", "database", 0, NULL, 0) == NULL) {
            printf("Error: unable to connect to database\n");
            exit(1);
        }
        pthread_mutex_lock(&pool->mutex);
        pool->active_connections++;
        pool->idle_connections++;
        pthread_mutex_unlock(&pool->mutex);
    }
}

// Get a connection from the pool
conn_t *get_connection(conn_pool_t *pool) {
    // Check if there are any idle connections in the pool
    pthread_mutex_lock(&pool->mutex);
    if (pool->idle_connections > 0) {
        conn_t *conn = malloc(sizeof(conn_t));
        conn->active = 1;
        conn->conn = pool->connections[--pool->idle_connections];
        pthread_mutex_unlock(&pool->mutex);
        return conn;
    } else {
        // If there are no idle connections, check if the maximum size has been reached
        if (pool->size == pool->max_size) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }

        // Create a new connection and add it to the pool
        conn_t *conn = malloc(sizeof(conn_t));
        conn->active = 1;
        conn->conn = mysql_init(NULL);
        if (mysql_real_connect(conn->conn, "localhost", "username", "password", "database", 0, NULL, 0) == NULL) {
            printf("Error: unable to connect to database\n");
            exit(1);
        }
        pthread_mutex_lock(&pool->mutex);
        pool->connections[pool->size++] = conn;
        pool->active_connections++;
        pthread_mutex_unlock(&pool->mutex);
        return conn;
    }
}

// Release a connection back to the pool
void release_connection(conn_t *conn) {
    // Check if the connection is active and not already in the pool
    if (conn->active && !in_pool(conn)) {
        pthread_mutex_lock(&pool->mutex);
        conn->active = 0;
        pool->idle_connections++;
        pthread_mutex_unlock(&pool->mutex);
    }
}

// Check if a connection is already in the pool
int in_pool(conn_t *conn) {
    // Iterate through the connections in the pool and check for a match
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i] == conn) {
            return 1;
        }
    }
    return 0;
}

// Close all connections in the pool and free the memory
void close_pool(conn_pool_t *pool) {
    // Iterate through the connections in the pool and close them
    for (int i = 0; i < pool->size; i++) {
        mysql_close(pool->connections[i]->conn);
        free(pool->connections[i]);
    }
    pthread_mutex_destroy(&pool->mutex);
}

// Perform a health check on the connection pool and remove dead connections
void health_check(conn_pool_t *pool) {
    // Iterate through the connections in the pool and check for dead connections
    for (int i = 0; i < pool->size; i++) {
        if (!mysql_ping(pool->connections[i]->conn)) {
            printf("Error: connection %d is dead\n", i);
            mysql_close(pool->connections[i]->conn);
            free(pool->connections[i]);
            pool->size--;
            pool->active_connections--;
        }
    }
}

// Main function for the connection pool
int main() {
    // Initialize the connection pool with the minimum size
    conn_pool_t *pool = malloc(sizeof(conn_pool_t));
    init_conn_pool(pool);

    // Perform a health check on the connection pool every 30 seconds
    while (1) {
        sleep(HEALTH_CHECK_INTERVAL);
        health_check(pool);
    }
}
```
