using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class MessageHandler
{
    private readonly SymmetricAlgorithm _algorithm;
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly int _blockSize;
    private readonly int _paddingMode;
    private readonly bool _useStreamingDecryption;
    private readonly ILogger _logger;

    public MessageHandler(SymmetricAlgorithm algorithm, byte[] key, byte[] iv, int blockSize = 128, int paddingMode = PaddingMode.PKCS7, bool useStreamingDecryption = false)
    {
        _algorithm = algorithm;
        _key = key;
        _iv = iv;
        _blockSize = blockSize;
        _paddingMode = paddingMode;
        _useStreamingDecryption = useStreamingDecryption;
        _logger = new Logger();
    }

    public async Task<string> DecryptMessageAsync(string encryptedMessage, byte[] authenticationTag)
    {
        try
        {
            var decryptedMessage = await DecryptMessageInternalAsync(encryptedMessage, authenticationTag);
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            _logger.LogWarning($"Failed to decrypt message: {ex.Message}");
            return null;
        }
    }

    private async Task<string> DecryptMessageInternalAsync(string encryptedMessage, byte[] authenticationTag)
    {
        var cipherText = Convert.FromBase64String(encryptedMessage);
        var tag = new byte[authenticationTag.Length];
        Array.Copy(cipherText, cipherText.Length - tag.Length, tag, 0, tag.Length);
        if (!VerifyAuthenticationTag(tag))
        {
            _logger.LogWarning($"Invalid authentication tag");
            return null;
        }
        var plainText = await DecryptAsync(cipherText);
        return Encoding.UTF8.GetString(plainText);
    }

    private async Task<byte[]> DecryptAsync(byte[] cipherText)
    {
        using (var memoryStream = new MemoryStream())
        {
            var decryptor = _algorithm.CreateDecryptor(_key, _iv);
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
            {
                await cryptoStream.WriteAsync(cipherText, 0, cipherText.Length);
                cryptoStream.FlushFinalBlock();
                return memoryStream.ToArray();
            }
        }
    }

    private bool VerifyAuthenticationTag(byte[] tag)
    {
        var computedTag = _algorithm.ComputeHash(tag);
        for (int i = 0; i < tag.Length; i++)
        {
            if (computedTag[i] != tag[i])
            {
                return false;
            }
        }
        return true;
    }
}
