using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Xml.Serialization;

namespace CompressionLibrary
{
    public class Compressor
    {
        private readonly string _settingsFilePath;
        private readonly XmlSerializer _serializer = new XmlSerializer(typeof(CompressionSettings));

        public Compressor(string settingsFilePath)
        {
            _settingsFilePath = settingsFilePath;
        }

        public async Task<byte[]> CompressAsync(byte[] data, string fileType)
        {
            var settings = await LoadSettingsAsync();
            var compressionLevel = GetCompressionLevel(fileType);
            return await CompressAsync(data, compressionLevel, settings.LogVerbosity);
        }

        public async Task<byte[]> DecompressAsync(byte[] data)
        {
            var settings = await LoadSettingsAsync();
            return await DecompressAsync(data, settings.CompressionAlgorithm, settings.LogVerbosity);
        }

        private async Task<CompressionSettings> LoadSettingsAsync()
        {
            using (var stream = new FileStream(_settingsFilePath, FileMode.Open))
            {
                return await _serializer.DeserializeAsync(stream) as CompressionSettings;
            }
        }

        private async Task<byte[]> CompressAsync(byte[] data, int compressionLevel, LogVerbosity logVerbosity)
        {
            var algorithm = GetCompressionAlgorithm(compressionLevel);
            using (var stream = new MemoryStream())
            {
                await algorithm.CompressAsync(data, stream, logVerbosity);
                return stream.ToArray();
            }
        }

        private async Task<byte[]> DecompressAsync(byte[] data, CompressionAlgorithm algorithm, LogVerbosity logVerbosity)
        {
            using (var stream = new MemoryStream())
            {
                await algorithm.DecompressAsync(data, stream, logVerbosity);
                return stream.ToArray();
            }
        }

        private int GetCompressionLevel(string fileType)
        {
            var settings = LoadSettings();
            if (settings.FileTypes.Contains(fileType))
            {
                return settings.CompressionLevel;
            }
            else
            {
                return 0;
            }
        }

        private CompressionAlgorithm GetCompressionAlgorithm(int compressionLevel)
        {
            switch (compressionLevel)
            {
                case 1:
                    return new GzipCompression();
                case 2:
                    return new ZipCompression();
                default:
                    return new NoCompression();
            }
        }

        private CompressionSettings LoadSettings()
        {
            using (var stream = new FileStream(_settingsFilePath, FileMode.Open))
            {
                return _serializer.Deserialize(stream) as CompressionSettings;
            }
        }
    }

    public class CompressionSettings
    {
        [XmlElement("CompressionAlgorithm")]
        public string CompressionAlgorithm { get; set; }

        [XmlArray("FileTypes")]
        [XmlArrayItem("string")]
        public List<string> FileTypes { get; set; }

        [XmlElement("LogVerbosity")]
        public LogVerbosity LogVerbosity { get; set; }
    }

    public enum CompressionAlgorithm
    {
        Gzip,
        Zip,
        NoCompression
    }

    public enum LogVerbosity
    {
        Minimal,
        Normal,
        Verbose
    }
}
