        if adapter_name in self.network_adapters:
            raise ValueError("Adapter already exists")
        self.network_adapters[adapter_name] = adapter_type
        if config is not None:
            self.configure_adapter(adapter_name, config)

    def update_adapter(self, adapter_name, new_config):
        if adapter_name not in self.network_adapters:
            raise ValueError("Adapter does not exist")
        self.network_configs[adapter_name] = new_config
        self.apply_config(adapter_name)

