#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the task structure
typedef struct {
    char* name;
    int priority;
    enum status { pending, in_progress, completed } status;
} task;

// Define a thread-safe list data structure
struct list {
    pthread_mutex_t mutex;
    task** tasks;
    size_t capacity;
};

// Initialize the list with a given capacity
void init_list(struct list* list, size_t capacity) {
    list->capacity = capacity;
    list->tasks = malloc(sizeof(task*) * capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new task to the list
void add_task(struct list* list, const char* name, int priority) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->capacity == 0) {
        // If the list is full, double its capacity
        list->capacity *= 2;
        list->tasks = realloc(list->tasks, sizeof(task*) * list->capacity);
    }

    // Create a new task structure
    task* new_task = malloc(sizeof(task));
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->status = pending;

    // Add the new task to the list
    list->tasks[list->size++] = new_task;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Get a task from the list by its index
task* get_task(struct list* list, size_t index) {
    return list->tasks[index];
}

// Update the status of a task in the list
void update_status(struct list* list, size_t index, enum status new_status) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Get the task at the given index
    task* task = get_task(list, index);

    // Update the status of the task
    task->status = new_status;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Free the memory allocated for the list
void free_list(struct list* list) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Free the memory allocated for each task in the list
    for (size_t i = 0; i < list->size; i++) {
        free(list->tasks[i]);
    }

    // Free the memory allocated for the tasks array
    free(list->tasks);

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}
```
