// Define the structure for a project
typedef struct {
    char *title;
    float budget;
    int status;
    char **assigned_team;
} project;

// Define the function to dynamically manage the list of projects
void manage_projects(project **projects, size_t num_projects) {
    // Initialize the mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define the function to add a new project
    void add_project(project *new_project) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if there is enough space for the new project
        if (num_projects >= 500) {
            printf("Error: Maximum number of projects reached\n");
            return;
        }

        // Allocate memory for the new project
        project *new_project = malloc(sizeof(project));
        if (!new_project) {
            printf("Error: Failed to allocate memory for new project\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Copy the title, budget, and status of the new project
        strcpy(new_project->title, new_project->title);
        new_project->budget = new_project->budget;
        new_project->status = new_project->status;

        // Add the new project to the list of projects
        projects[num_projects++] = new_project;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to update the budget and status of an existing project
    void update_project(int index, float new_budget, int new_status) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if the index is valid
        if (index < 0 || index >= num_projects) {
            printf("Error: Invalid project index\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Update the budget and status of the project
        projects[index]->budget = new_budget;
        projects[index]->status = new_status;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to retrieve the assigned team for a specific project
    char **get_assigned_team(int index) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if the index is valid
        if (index < 0 || index >= num_projects) {
            printf("Error: Invalid project index\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        // Return the assigned team for the specified project
        char **assigned_team = projects[index]->assigned_team;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);

        return assigned_team;
    }

    // Define the function to clean up all allocated resources when the application terminates
    void cleanup() {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Free the memory for each project in the list
        for (int i = 0; i < num_projects; i++) {
            free(projects[i]);
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }
}
