// Function to initialize the arrays and binary search tree
void init_data(int num_nodes, int num_doubles, int num_strings) {
    // Allocate memory for the arrays
    struct node* nodes = malloc(num_nodes * sizeof(struct node));
    double* doubles = malloc(num_doubles * sizeof(double));
    char** strings = malloc(num_strings * sizeof(char*));

    // Initialize the arrays with default values
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].name[0] = '\0';
        nodes[i].value = 0.0;
    }
    for (int i = 0; i < num_doubles; i++) {
        doubles[i] = 0.0;
    }
    for (int i = 0; i < num_strings; i++) {
        strings[i] = malloc(256 * sizeof(char));
        strings[i][0] = '\0';
    }

    // Initialize the binary search tree with the nodes
    struct binary_tree* tree = malloc(num_nodes * sizeof(struct binary_tree));
    for (int i = 0; i < num_nodes; i++) {
        tree[i].data = &nodes[i];
        tree[i].left = 0.0;
        tree[i].right = 0.0;
    }
}

// Function to insert a new node into the binary search tree
void insert_node(struct binary_tree* tree, struct node* data) {
    // Find the appropriate position for the new node in the tree
    int pos = 0;
    while (pos < num_nodes && tree[pos].data->value <= data->value) {
        pos++;
    }

    // Insert the new node into the tree
    if (pos == num_nodes) {
        // If the new node is greater than all existing nodes, add it to the end of the tree
        tree[num_nodes].data = data;
        tree[num_nodes].left = 0.0;
        tree[num_nodes].right = 0.0;
    } else {
        // If the new node is less than or equal to an existing node, insert it before that node
        for (int i = num_nodes - 1; i >= pos; i--) {
            tree[i + 1].data = tree[i].data;
            tree[i + 1].left = tree[i].left;
            tree[i + 1].right = tree[i].right;
        }
        tree[pos].data = data;
    }
}

