        if (doubles[i] == 0.0) {
            total_free += sizeof(double);
        }
    }
    for (int i = 0; i < num_strings; i++) {
        total_allocated += sizeof(char*);
        if (strings[i][0] == '\0') {
            total_free += sizeof(char*);
        }
    }

    // Calculate the memory pool utilization for each data type
    int pool_utilization = 0;
    for (int i = 0; i < num_nodes; i++) {
        if (nodes[i].name[0] != '\0') {
            pool_utilization++;
        }
    }
    for (int i = 0; i < num_doubles; i++) {
        if (doubles[i] != 0.0) {
