// Define the function to manage memory and perform data initialization
void initializeData(int num_keys, int num_offsets) {
    // Validate user input
    if (num_keys < 0 || num_offsets < 0) {
        printf("Invalid input: num_keys = %d, num_offsets = %d\n", num_keys, num_offsets);
        return;
    }

