// Define the register_memory_blocks function to register each allocated memory block with the external memory pool manager
void register_memory_blocks(struct mempool *mempool, void *ptr, size_t size) {
    // Allocate a new block from the memory pool
    struct block *new_block = malloc(sizeof(struct block));
    if (new_block == NULL) {
        return;
    }
    // Set the size of the block in bytes
    new_block->size = size;
    // Set the pointer to the next free block
    new_block->next = mempool->free_head;
    // Set the pointer to the previous free block
    new_block->prev = NULL;
    // Add the new block to the linked list of free blocks
    if (mempool->free_head != NULL) {
        mempool->free_head->prev = new_block;
    }
    mempool->free_head = new_block;
    // Update the number of free blocks in the pool
    mempool->num_free_blocks++;
}

// Define the free_memory_blocks function to free all previously allocated resources before returning an error status
void free_memory_blocks(struct mempool *mempool) {
    // Free each block in the linked list of free blocks
    while (mempool->free_head != NULL) {
        struct block *current = mempool->free_head;
        mempool->free_head = current->next;
        if (current->prev != NULL) {
            current->prev->next = NULL;
        }
        free(current);
    }
