    while (current != NULL) {
        // Check if the block is unused
        if (current->next == NULL && current->prev == NULL) {
            // Free the block
            free(current);
            // Update the number of free blocks in the pool
            mempool->num_free_blocks--;
        } else {
            // Move to the next block
            current = current->next;
        }
    }
}

