void resize_key_array(struct data_stream *stream, size_t new_size) {
    // Check if the new size is greater than the current size
    if (new_size > stream->array_size) {
        // Allocate a new array of integers with the new size
        int *new_key_array = malloc(sizeof(int) * new_size);
        if (new_key_array == NULL) {
