// Define constants for logging levels and maximum history list size
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2
#define LOG_LEVEL_ERROR 3
#define MAX_HISTORY_LIST_SIZE 10000

// Define a struct to represent a log entry
typedef struct {
    char* timestamp;
    int level;
    char* message;
} LogEntry;

// Define a struct to represent the history list
typedef struct {
    LogEntry** entries;
    size_t count;
    size_t capacity;
} HistoryList;

// Define a function to create a new history list
HistoryList* createHistoryList(LogEntry** logEntries, int numLogEntries) {
    // Check for null pointers and negative log entry counts
    if (logEntries == NULL || numLogEntries < 0) {
        return NULL;
    }

    // Allocate memory for the history list
    HistoryList* historyList = malloc(sizeof(HistoryList));
    if (historyList == NULL) {
        return NULL;
    }

    // Initialize the history list with the given log entries
    historyList->entries = logEntries;
    historyList->count = numLogEntries;
    historyList->capacity = numLogEntries;

    // Increment the reference count of each log entry added to the new list
    for (int i = 0; i < numLogEntries; i++) {
        LogEntry* entry = logEntries[i];
        entry->refCount++;
    }

    return historyList;
}

// Define a function to add a log entry to the history list
void addLogEntry(HistoryList* historyList, LogEntry* logEntry) {
    // Check for null pointers and insufficient memory
    if (historyList == NULL || logEntry == NULL) {
        return;
    }

    // Increment the reference count of the new log entry
    logEntry->refCount++;

    // Add the new log entry to the history list
    historyList->entries[historyList->count++] = logEntry;

    // Check if the history list exceeds the maximum size and reset the count if necessary
    if (historyList->count > MAX_HISTORY_LIST_SIZE) {
        historyList->count = MAX_HISTORY_LIST_SIZE;
        printf("History list exceeded maximum size, resetting to %d\n", MAX_HISTORY_LIST_SIZE);
    }
}

// Define a function to sort the history list in descending order based on timestamps
void sortHistoryList(HistoryList* historyList) {
    // Check for null pointers and insufficient memory
    if (historyList == NULL || historyList->count < 2) {
        return;
    }

    // Implement a custom sorting algorithm with O(n log n) complexity
    for (int i = 0; i < historyList->count - 1; i++) {
        for (int j = i + 1; j < historyList->count; j++) {
            if (strcmp(historyList->entries[i]->timestamp, historyList->entries[j]->timestamp) > 0) {
                LogEntry* temp = historyList->entries[i];
                historyList->entries[i] = historyList->entries[j];
                historyList->entries[j] = temp;
            }
        }
    }
}

// Define a function to handle duplicate log entries gracefully
void handleDuplicateLogEntry(HistoryList* historyList, LogEntry* logEntry) {
    // Check for null pointers and insufficient memory
    if (historyList == NULL || logEntry == NULL) {
        return;
    }

    // Check if the given log entry is already present in the history list
    for (int i = 0; i < historyList->count; i++) {
        LogEntry* entry = historyList->entries[i];
        if (strcmp(entry->message, logEntry->message) == 0 && strcmp(entry->timestamp, logEntry->timestamp) == 0) {
            printf("Duplicate log entry found, ignoring\n");
            return;
        }
    }

    // Add the new log entry to the history list
    addLogEntry(historyList, logEntry);
}

// Define a function to manage the size of the history list efficiently
void manageHistoryListSize(HistoryList* historyList) {
    // Check for null pointers and insufficient memory
    if (historyList == NULL || historyList->count < 0) {
        return;
    }

    // Implement a sliding window mechanism to manage the size of the history list
    while (historyList->count > MAX_HISTORY_LIST_SIZE) {
        LogEntry* entry = historyList->entries[0];
        entry->refCount--;
        if (entry->refCount <= 0) {
            free(entry);
            for (int i = 1; i < historyList->count; i++) {
                historyList->entries[i - 1] = historyList->entries[i];
            }
            historyList->count--;
        } else {
            break;
        }
    }
}

