        }

        public double GenerateRandomDouble()
        {
            if (_distributionModel == "gaussian")
            {
                return GenerateGaussianRandomValue();
            }
            else if (_distributionModel == "uniform")
            {
                return GenerateUniformRandomValue();
            }
            else
            {
                throw new Exception("Invalid distribution model");
            }
        }

        public string ProcessString(string input)
        {
            if (input.Length > _sizeLimit)
            {
                return "LIMIT_EXCEEDED";
            }
            else
            {
                return input + "/";
            }
        }

        private int GenerateUniformRandomValue()
        {
            Random random = new Random();
            return random.Next(_minInt, _maxInt);
        }

        private double GenerateGaussianRandomValue()
        {
            Random random = new Random();
            return random.NextDouble() * (_maxDouble - _minDouble) + _minDouble;
        }

