// Define function to initialize semaphore
int init_semaphore(char* name, int value) {
    // Create semaphore with specified name and initial value
    sem_t* sem = sem_open(name, O_CREAT | O_EXCL, 0644, value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return SEM_INIT_FAILURE;
    }
    // Return success
    return 0;
}

// Define function to manipulate semaphore
int manipulate_semaphore(char* name, int operation) {
    // Open semaphore with specified name
    sem_t* sem = sem_open(name, 0);
    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        return -1;
    }
    // Perform operation on semaphore
    switch (operation) {
        case SEM_INCREMENT:
            sem_post(sem);
            break;
        case SEM_DECREMENT:
            sem_wait(sem);
            break;
        default:
            fprintf(stderr, "Invalid operation for semaphore\n");
            return -1;
    }
    // Close semaphore
    sem_close(sem);
    // Return success
    return 0;
}

// Define function to delete semaphore
int delete_semaphore(char* name) {
    // Open semaphore with specified name
    sem_t* sem = sem_open(name, 0);
    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        return -1;
    }
    // Delete semaphore
    sem_unlink(sem);
    // Return success
    return 0;
}

