    int shm_fd = shm_open("mem_pool", O_CREAT | O_EXCL, 0644);
    if (shm_fd == -1) {
        perror("Failed to create shared memory segment");
        return -1;
    }
    // Set size of shared memory segment
    int shm_size = MEM_POOL_SIZE;
    // Map shared memory segment into process address space
    void* mem_pool = mmap(NULL, shm_size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (mem_pool == MAP_FAILED) {
        perror("Failed to map shared memory segment");
        return -1;
    }
    // Initialize memory pool manager with shared memory segment
    mem_pool_manager = init_memory_pool_manager(mem_pool, shm_size);
    if (mem_pool_manager == NULL) {
        perror("Failed to initialize memory pool manager");
        return -1;
    }
    // Return success
    return 0;
}

// Define function to allocate memory from memory pool manager
void* allocate_memory(size_t size) {
    // Allocate memory block from memory pool manager
    void* mem = mem_pool_manager_allocate(mem_pool_manager, size);
    if (mem == NULL) {
