#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a struct to represent a node in the linked list
struct node {
    char *str;
    int key;
    struct node *next;
};

// Define a function to insert a new node into the linked list
void insert_node(struct node **head, int key) {
    // Allocate memory for the new node
    struct node *new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("Error: failed to allocate memory for new node\n");
        return;
    }

    // Set the key and next pointer of the new node
    new_node->key = key;
    new_node->next = *head;

    // Update the head pointer to point to the new node
    *head = new_node;
}

// Define a function to maintain order based on the key values
void maintain_order(struct node **head) {
    struct node *current = *head;
    while (current != NULL && current->next != NULL) {
        if (current->key > current->next->key) {
            // Swap the nodes
            struct node *temp = current->next;
            current->next = temp->next;
            temp->next = current;
            current = temp;
        } else {
            current = current->next;
        }
    }
}

// Define a function to handle duplicates by appending them to the end of the list
void handle_duplicates(struct node **head) {
    struct node *current = *head;
    while (current != NULL && current->next != NULL) {
        if (current->key == current->next->key) {
            // Append the duplicate to the end of the list
            struct node *duplicate = current->next;
            current->next = duplicate->next;
            duplicate->next = NULL;
            insert_node(head, duplicate->key);
        } else {
            current = current->next;
        }
    }
}

// Define a function to report the memory usage statistics
void report_memory_usage(struct node **head) {
    struct node *current = *head;
    int total_allocated_memory = 0;
    int free_memory = 0;
    int memory_pool_utilization = 0;

    // Calculate the total allocated memory and free memory
    while (current != NULL) {
        total_allocated_memory += sizeof(struct node);
        if (current->next == NULL) {
            free_memory += sizeof(struct node);
        }
        current = current->next;
    }

    // Calculate the memory pool utilization
    memory_pool_utilization = total_allocated_memory - free_memory;

    printf("Total allocated memory: %d\n", total_allocated_memory);
    printf("Free memory: %d\n", free_memory);
    printf("Memory pool utilization: %d\n", memory_pool_utilization);
}
```
