// Define a struct to represent a record in the linked list
typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

// Define a struct to represent the hash map for fast lookup by key
typedef struct HashMap {
    int size;
    Record** buckets;
} HashMap;

// Define a function to create a new record with the given key and offset
Record* create_record(int key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (record == NULL) {
        return NULL;
    }
    record->key = key;
    record->offset = offset;
    record->next = NULL;
    return record;
}

// Define a function to insert a new record into the linked list
void insert_record(Record** head, Record* record) {
    if (*head == NULL) {
        *head = record;
    } else {
        Record* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Define a function to delete a record from the linked list by its key
void delete_record(Record** head, int key) {
    if (*head == NULL) {
        return;
    } else if ((*head)->key == key) {
        Record* temp = *head;
        *head = (*head)->next;
        free(temp);
    } else {
        Record* current = *head;
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            return;
        }
        Record* temp = current->next;
        current->next = temp->next;
        free(temp);
    }
}

// Define a function to retrieve a record from the linked list by its key
Record* get_record(Record** head, int key) {
    if (*head == NULL) {
        return NULL;
    } else if ((*head)->key == key) {
        return *head;
    } else {
        Record* current = *head;
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            return NULL;
        }
        return current->next;
    }
}

// Define a function to traverse the linked list and print each record's contents
void traverse_list(Record** head) {
    Record* current = *head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
}

// Define a function to create a new hash map with the given size
HashMap* create_hashmap(int size) {
    HashMap* map = malloc(sizeof(HashMap));
    if (map == NULL) {
        return NULL;
    }
    map->size = size;
    map->buckets = calloc(size, sizeof(Record*));
    if (map->buckets == NULL) {
        free(map);
        return NULL;
    }
    return map;
}

// Define a function to insert a record into the hash map by its key
void insert_into_hashmap(HashMap* map, Record* record) {
    int index = record->key % map->size;
    if (map->buckets[index] == NULL) {
        map->buckets[index] = record;
    } else {
        Record* current = map->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
}

// Define a function to delete a record from the hash map by its key
void delete_from_hashmap(HashMap* map, int key) {
    if (map == NULL) {
        return;
    }
    int index = key % map->size;
    Record* current = map->buckets[index];
    if (current == NULL) {
        return;
    } else if (current->key == key) {
        map->buckets[index] = current->next;
        free(current);
    } else {
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            return;
        }
        Record* temp = current->next;
        current->next = temp->next;
        free(temp);
    }
}

// Define a function to retrieve a record from the hash map by its key
Record* get_from_hashmap(HashMap* map, int key) {
    if (map == NULL) {
        return NULL;
    }
    int index = key % map->size;
    Record* current = map->buckets[index];
    if (current == NULL) {
        return NULL;
    } else if (current->key == key) {
        return current;
    } else {
        while (current->next != NULL && current->next->key != key) {
            current = current->next;
        }
        if (current->next == NULL) {
            return NULL;
        }
        return current->next;
    }
}

// Define a function to traverse the hash map and print each record's contents
void traverse_hashmap(HashMap* map) {
    for (int i = 0; i < map->size; i++) {
        Record* current = map->buckets[i];
        while (current != NULL) {
            printf("Key: %d, Offset: %ld\n", current->key, current->offset);
            current = current->next;
        }
    }
}

// Define a function to free the memory allocated for the linked list and hash map
void free_memory(Record** head, HashMap* map) {
    Record* current = *head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    for (int i = 0; i < map->size; i++) {
        Record* current = map->buckets[i];
        while (current != NULL) {
            Record* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(map->buckets);
    free(map);
}
