#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    double value;
} Record;

// Define the hash table for efficient key-based lookups
typedef struct {
    Record* records[1024]; // 1024 is a good size for a small to medium-sized dataset
    int num_records;
} HashTable;

// Define the linked list for maintaining insertion order
typedef struct {
    Record* head;
    Record* tail;
} LinkedList;

// Define the data structure for storing records
typedef struct {
    HashTable* hash_table;
    LinkedList* linked_list;
} DataStructure;

// Define the mutex for synchronizing access to the data structure
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a record into the data structure
void insert(DataStructure* ds, int key, long offset, double value) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if the hash table needs to be resized
    if (ds->hash_table->num_records >= 1024) {
        resize_hash_table(ds);
    }

    // Insert the record into the hash table and linked list
    Record* new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
    ds->hash_table->records[key % 1024] = new_record;
    if (ds->linked_list->head == NULL) {
        ds->linked_list->head = new_record;
        ds->linked_list->tail = new_record;
    } else {
        ds->linked_list->tail->next = new_record;
        ds->linked_list->tail = new_record;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to delete a record from the data structure
void delete(DataStructure* ds, int key) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if the hash table needs to be resized
    if (ds->hash_table->num_records <= 128) {
        resize_hash_table(ds);
    }

    // Delete the record from the hash table and linked list
    Record* deleted_record = ds->hash_table->records[key % 1024];
    if (deleted_record == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    ds->hash_table->num_records--;
    if (ds->linked_list->head == deleted_record) {
        ds->linked_list->head = deleted_record->next;
    } else {
        Record* prev_record = NULL;
        for (Record* record = ds->linked_list->head; record != NULL; record = record->next) {
            if (record == deleted_record) {
                break;
            }
            prev_record = record;
        }
        if (prev_record == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        prev_record->next = deleted_record->next;
    }
    free(deleted_record);

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record from the data structure
Record* get(DataStructure* ds, int key) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Retrieve the record from the hash table
    Record* record = ds->hash_table->records[key % 1024];
    if (record == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);

    return record;
}

// Function to serialize the data structure to a file
void serialize(DataStructure* ds, FILE* fp) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Write the number of records in the hash table to the file
    int num_records = ds->hash_table->num_records;
    fwrite(&num_records, sizeof(int), 1, fp);

    // Write each record in the linked list to the file
    for (Record* record = ds->linked_list->head; record != NULL; record = record->next) {
        fwrite(&record->key, sizeof(int), 1, fp);
        fwrite(&record->offset, sizeof(long), 1, fp);
        fwrite(&record->value, sizeof(double), 1, fp);
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to deserialize the data structure from a file
void deserialize(DataStructure* ds, FILE* fp) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Read the number of records in the hash table from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, fp);

    // Resize the hash table if necessary
    if (ds->hash_table->num_records < num_records) {
        resize_hash_table(ds);
    }

    // Read each record from the file and insert it into the linked list
    for (int i = 0; i < num_records; i++) {
        int key;
        long offset;
        double value;
        fread(&key, sizeof(int), 1, fp);
        fread(&offset, sizeof(long), 1, fp);
        fread(&value, sizeof(double), 1, fp);
        insert(ds, key, offset, value);
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to resize the hash table if necessary
void resize_hash_table(DataStructure* ds) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Resize the hash table if necessary
    if (ds->hash_table->num_records < 1024) {
        Record** new_records = malloc(sizeof(Record*) * 2048);
        memset(new_records, 0, sizeof(Record*) * 2048);
        for (int i = 0; i < ds->hash_table->num_records; i++) {
            new_records[i] = ds->hash_table->records[i];
        }
        free(ds->hash_table->records);
        ds->hash_table->records = new_records;
    }

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure(DataStructure* ds) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Handle memory allocation failure by flushing changes to disk and exiting the program
    fprintf(stderr, "Memory allocation failed. Flushing changes to disk...\n");
    serialize(ds, stdout);
    exit(EXIT_FAILURE);

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}
