        with self.lock:
            del self.records[key]

    def serialize(self):
        with self.lock:
            return json.dumps(self.records)

    def deserialize(self, data):
        with self.lock:
            self.records = json.loads(data)

class RecordCapacityManager:
    def __init__(self):
        self.capacities = collections.defaultdict(int)
        self.lock = threading.Lock()

    def set_capacity(self, key, capacity):
        with self.lock:
            self.capacities[key] = capacity

    def get_capacity(self, key):
        with self.lock:
            return self.capacities[key]

class CompressedRecord:
