def manage_config(payload: dict) -> dict:
    # Validate input payload
    if not all(key in payload for key in ["section", "setting", "value", "action"]):
        return {"message": "Invalid payload"}

    # Initialize database connection and transaction
    db = DatabaseConnection()
    txn = db.begin_transaction()

    try:
        # Extract relevant information from payload
        section = payload["section"]
        setting = payload["setting"]
        value = payload["value"]
        action = payload["action"]
        config_id = payload.get("config_id")
        version = payload.get("version")
        dry_run = payload.get("dry_run", False)
        monitoring_service_key = payload["monitoring_service_key"]

        # Validate section and setting names
        if not re.match(r"^[a-zA-Z0-9_]+$", section):
            return {"message": "Invalid section name"}
        if not re.match(r"^[a-zA-Z0-9_]+$", setting):
            return {"message": "Invalid setting name"}

        # Validate value data type
        if not isinstance(value, (str, int, float)):
            return {"message": "Invalid value data type"}

        # Perform action based on payload
        if action == "create":
            # Create new configuration setting
            config_id = db.insert("configs", {
                "section": section,
                "setting": setting,
                "value": value,
                "version": version
            })

            # Log operation and notify monitoring service
            log_operation(action, config_id)
            notify_monitoring_service(config_id, action)

        elif action == "update":
            # Update existing configuration setting
            if not config_id:
                return {"message": "Missing 'config_id'"}

            # Validate current version
            current_version = db.get("configs", config_id, "version")
            if current_version != version:
                return {"message": f"Invalid version ({current_version} instead of {version})"}

            # Update configuration setting
            db.update("configs", config_id, {
                "value": value,
                "version": version + 1
            })

            # Log operation and notify monitoring service
            log_operation(action, config_id)
            notify_monitoring_service(config_id, action)

        elif action == "delete":
            # Soft delete configuration setting
            if not config_id:
                return {"message": "Missing 'config_id'"}

            # Validate current version
            current_version = db.get("configs", config_id, "version")
            if current_version != version:
                return {"message": f"Invalid version ({current_version} instead of {version})"}

            # Soft delete configuration setting
            db.update("configs", config_id, {
                "deleted": True,
                "version": version + 1
            })

            # Log operation and notify monitoring service
            log_operation(action, config_id)
            notify_monitoring_service(config_id, action)

        elif action == "bulk_delete":
            # Validate 'config_ids' list
            if not isinstance(config_ids, List):
                return {"message": "Invalid 'config_ids'"}

            # Validate total number of deletions
            if len(config_ids) > MAX_BULK_DELETE:
                return {"message": f"Maximum bulk delete limit exceeded ({len(config_ids)} instead of {MAX_BULK_DELETE})"}

            # Soft delete configuration settings
            for config_id in config_ids:
                # Validate current version
                current_version = db.get("configs", config_id, "version")
                if current_version != version:
                    return {"message": f"Invalid version ({current_version} instead of {version})"}

                # Soft delete configuration setting
                db.update("configs", config_id, {
                    "deleted": True,
                    "version": version + 1
                })

            # Log operation and notify monitoring service
            log_operation(action, config_ids)
            notify_monitoring_service(config_ids, action)

        else:
            return {"message": f"Invalid 'action' ({action})"}

        # Commit transaction
        txn.commit()

        # Return response
        return {
            "message": "success",
            "data": [{"id": config_id, "status": "created" if action == "create" else "updated"}]
        }

    except Exception as e:
        # Rollback transaction on error
        txn.rollback()

        # Log error and return response
        log_error(e)
        return {"message": f"Error occurred ({str(e)})"}
