using namespace std;

struct Section {
    int id;
    string elementId;
    string htmlContent;
};

class CmsApiClient {
public:
    virtual string getHtmlContent(const string& elementId) = 0;
};

class MemoryPoolManager {
private:
    unordered_map<string, shared_ptr<char>> memoryPool_;
    mutex poolMutex_;

public:
    void allocateMemory(size_t size) {
        lock_guard<mutex> lock(poolMutex_);
        memoryPool_.emplace(make_pair("", make_shared<char>(size)));
    }

    shared_ptr<char> getMemory(const string& elementId) {
        lock_guard<mutex> lock(poolMutex_);
        return memoryPool_[elementId];
    }
};

class UpdateContentInSections {
private:
    forward_list<Section> sections_;
    CmsApiClient* cmsApiClient_;
    MemoryPoolManager* memoryPoolManager_;
    mutex updateMutex_;
    condition_variable updateCondVar_;
    bool isUpdating_;

public:
    UpdateContentInSections(forward_list<Section> sections, CmsApiClient* cmsApiClient, MemoryPoolManager* memoryPoolManager) :
        sections_(sections), cmsApiClient_(cmsApiClient), memoryPoolManager_(memoryPoolManager), isUpdating_(false) {}

    void updateContent() {
        lock_guard<mutex> lock(updateMutex_);
        if (isUpdating_) {
            return;
        }
        isUpdating_ = true;

        for (auto& section : sections_) {
            string htmlContent = cmsApiClient_->getHtmlContent(section.elementId);
            shared_ptr<char> memory = memoryPoolManager_->getMemory(section.elementId);
            strcpy(memory.get(), htmlContent.c_str());
        }

        isUpdating_ = false;
        updateCondVar_.notify_all();
    }

    void waitForUpdate() {
        unique_lock<mutex> lock(updateMutex_);
        while (isUpdating_) {
            updateCondVar_.wait(lock);
        }
    }
};
