    // Constructor
    ProcessAndGenerateUtil() {}

    // Destructor
    ~ProcessAndGenerateUtil() {}

    // Start the process and generate utilities
    void start(const std::string& command, const std::string& output_dir) {
        // Initialize variables
        this->command = command;
        this->output_dir = output_dir;
        this->paused = false;
        this->running = true;
        this->status = "started";

