        pid = fork();

        // Check if the fork was successful
        if (pid == 0) {
            // Execute the command in the child process
            execl("/bin/sh", "sh", "-c", this->command.c_str(), NULL);

            // Handle error
            std::cout << "Error executing command: " << strerror(errno) << std::endl;
        } else if (pid > 0) {
            // Wait for the child process to finish
            wait(&status);

