                  "Host: monitoring-system.com\r\n"
                  "Content-Type: application/json\r\n"
                  "Content-Length: " + std::to_string(status_update.size()) + "\r\n"
                  "\r\n"
                  + status_update;

        // Send the HTTP request to the external monitoring system
        response = sendHttpRequest(request);

        // Check if the request was successful
        if (response != "") {
            // Parse the HTTP response code
            status_code = parseHttpResponseCode(response);

            // Handle the HTTP response code
            if (status_code == 200) {
                // Update the status update
                this->status_update = status_update;
            } else {
                // Handle error
                std::cout << "Error sending status update: " << strerror(errno) << std::endl;
            }
        } else {
            // Handle error
            std::cout << "Error sending status update: " << strerror(errno) << std::endl;
        }
    }

    // Send an HTTP request to the external monitoring system
    std::string sendHttpRequest(const std::string& request) {
        // Initialize variables
        std::string response;
        int sock = 0;
        struct addrinfo hints, *res;
        char buffer[1024];
        ssize_t bytes_read;

        // Get the address information for the external monitoring system
        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo("monitoring-system.com", "80", &hints, &res) != 0) {
            // Handle error
            std::cout << "Error getting address information: " << strerror(errno) << std::endl;
        }

        // Create a socket for the HTTP request
        sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
        if (sock == -1) {
            // Handle error
            std::cout << "Error creating socket: " << strerror(errno) << std::endl;
        }

        // Connect to the external monitoring system
        if (connect(sock, res->ai_addr, res->ai_addrlen) == -1) {
            // Handle error
            std::cout << "Error connecting to server: " << strerror(errno) << std::endl;
        }

        // Send the HTTP request to the external monitoring system
        if (send(sock, request.c_str(), request.size(), 0) == -1) {
            // Handle error
            std::cout << "Error sending request: " << strerror(errno) << std::endl;
        }

        // Read the HTTP response from the external monitoring system
        while ((bytes_read = recv(sock, buffer, 1024, 0)) > 0) {
            // Append the received data to the response
            response += std::string(buffer, bytes_read);
        }

        // Close the socket
        close(sock);

        return response;
    }

    // Parse an HTTP response code from a string
    int parseHttpResponseCode(const std::string& response) {
        // Initialize variables
        int status_code = 0;
        size_t pos = 0;

        // Find the first occurrence of "HTTP/" in the response
        pos = response.find("HTTP/");

        // Check if the string was found
        if (pos != std::string::npos) {
            // Get the status code from the response
            status_code = std::stoi(response.substr(pos + 5, 3));
        } else {
            // Handle error
            std::cout << "Error parsing HTTP response: " << strerror(errno) << std::endl;
        }

        return status_code;
    }
};
