    printf("Error: Failed to allocate memory for weather records from the memory pool\n");
    return;
  }

  // Initialize the weather records array
  for (int i = 0; i < num_weather_records; i++) {
    weather_records[i].temperature = generate_random_temperature();
    strcpy(weather_records[i].city, "");
    weather_records[i].identifier = -1;
