// Define the URL and file path for uploading
const char* url = "https://example.com/upload";
const char* file_path = "/path/to/file.txt";

// Function to upload a file using cURL
char* upload_file(const char* url, const char* file_path) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/octet-stream");
    headers = curl_slist_append(headers, "Expect: 100-continue");
    headers = curl_slist_append(headers, "Connection: Keep-Alive");

    // Initialize cURL handle
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
        curl_easy_setopt(curl, CURLOPT_INFILESIZE, (long)file_size);
        curl_easy_setopt(curl, CURLOPT_READDATA, file_path);
        curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);

        // Perform the upload
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "cURL failed: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        // Get the URL of the uploaded file
        char* uploaded_url = curl_easy_getinfo(curl, CURLINFO_EASY_RESPONSE);
        if (uploaded_url) {
            return uploaded_url;
        } else {
            fprintf(stderr, "Failed to get uploaded URL\n");
            return NULL;
        }
    } else {
        fprintf(stderr, "Failed to initialize cURL handle\n");
        return NULL;
    }
}
