// Define the function to manage memory for the three data structures
void manageMemory(OffsetArray* offset_array, StringArray* string_array, ObjectArray* object_array) {
    // Initialize the memory pool with a fixed size of 1024 blocks
    MemoryPool pool = {NULL, 1024 * sizeof(void*), 0};

    // Allocate memory for the offset array
    offset_array->capacity = 10;
    offset_array->count = 0;
    offset_array->offsets = malloc(offset_array->capacity * sizeof(int));

    // Allocate memory for the string array
    string_array->capacity = 10;
    string_array->count = 0;
    string_array->keys = malloc(string_array->capacity * sizeof(char*));
    string_array->values = malloc(string_array->capacity * sizeof(int));
    string_array->timestamps = malloc(string_array->capacity * sizeof(time_t));

    // Allocate memory for the object array
    object_array->capacity = 10;
    object_array->count = 0;
    object_array->items = malloc(object_array->capacity * sizeof(ItemObject));

    // Initialize the locks for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Define a function to add an item to the array
    void addItem(OffsetArray* offset_array, StringArray* string_array, ObjectArray* object_array, ItemObject item) {
        // Acquire the lock for thread safety
        pthread_mutex_lock(&lock);

        // Validate the input key and value
        if (strlen(item.key) > 10 || strchr(item.key, '!') != NULL) {
            printf("Invalid input: Key must be less than 10 characters and cannot contain the character '!'");
            return;
        }

        // Allocate memory for the new item object
        ItemObject* new_item = malloc(sizeof(ItemObject));
        if (new_item == NULL) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            return;
        }

        // Copy the input key and value to the new item object
        new_item->key = malloc(strlen(item.key) + 1);
        if (new_item->key == NULL) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            free(new_item);
            return;
        }
        strcpy(new_item->key, item.key);
        new_item->value = item.value;
        new_item->timestamp = time(NULL);

        // Add the new item object to the array
        if (object_array->count == object_array->capacity) {
            // Reallocate memory for the array if necessary
            object_array->capacity *= 2;
            object_array->items = realloc(object_array->items, object_array->capacity * sizeof(ItemObject));
        }
        object_array->items[object_array->count++] = new_item;

        // Release the lock for thread safety
        pthread_mutex_unlock(&lock);
    }

    // Define a function to save the current state of the arrays to a binary file
    void saveState(OffsetArray* offset_array, StringArray* string_array, ObjectArray* object_array) {
        // Open the binary file for writing
        FILE* fp = fopen("items.bin", "wb");
        if (fp == NULL) {
            printf("Error opening file: %s\n", strerror(errno));
            return;
        }

        // Write the offset array to the binary file
        fwrite(offset_array->offsets, sizeof(int), offset_array->count, fp);

        // Write the string array to the binary file
        for (size_t i = 0; i < string_array->count; i++) {
            fwrite(string_array->keys[i], strlen(string_array->keys[i]) + 1, 1, fp);
            fwrite(&string_array->values[i], sizeof(int), 1, fp);
            fwrite(&string_array->timestamps[i], sizeof(time_t), 1, fp);
        }

        // Write the object array to the binary file
        for (size_t i = 0; i < object_array->count; i++) {
            fwrite(&object_array->items[i]->key, sizeof(char*), 1, fp);
            fwrite(&object_array->items[i]->value, sizeof(int), 1, fp);
            fwrite(&object_array->items[i]->timestamp, sizeof(time_t), 1, fp);
        }

        // Close the binary file
        fclose(fp);
    }

    // Define a function to load the current state of the arrays from a binary file
    void loadState(OffsetArray* offset_array, StringArray* string_array, ObjectArray* object_array) {
        // Open the binary file for reading
        FILE* fp = fopen("items.bin", "rb");
        if (fp == NULL) {
            printf("Error opening file: %s\n", strerror(errno));
            return;
        }

        // Read the offset array from the binary file
        fread(offset_array->offsets, sizeof(int), offset_array->count, fp);

        // Read the string array from the binary file
        for (size_t i = 0; i < string_array->count; i++) {
            string_array->keys[i] = malloc(strlen(string_array->keys[i]) + 1);
            fread(string_array->keys[i], strlen(string_array->keys[i]) + 1, 1, fp);
            fread(&string_array->values[i], sizeof(int), 1, fp);
            fread(&string_array->timestamps[i], sizeof(time_t), 1, fp);
        }

        // Read the object array from the binary file
        for (size_t i = 0; i < object_array->count; i++) {
            object_array->items[i]->key = malloc(strlen(object_array->items[i]->key) + 1);
            fread(&object_array->items[i]->key, sizeof(char*), 1, fp);
            fread(&object_array->items[i]->value, sizeof(int), 1, fp);
            fread(&object_array->items[i]->timestamp, sizeof(time_t), 1, fp);
        }

        // Close the binary file
        fclose(fp);
    }
}
